#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NETWORKS 1000
#define MEMORY_BUDGET 1048576 // 1 MB for connection lists memory budget
#define GROWTH_FACTOR 2

// Custom allocator function
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && MEMORY_BUDGET > 0) {
        MEMORY_BUDGET -= size;
        printf("Memory budget: %d bytes\n", MEMORY_BUDGET);
        ptr = malloc(size);
    }
    return ptr;
}

// Custom free function
void custom_free(void* ptr) {
    if (ptr) {
        free(ptr);
        MEMORY_BUDGET += sizeof(*ptr);
        printf("Memory budget: %d bytes\n", MEMORY_BUDGET);
    }
}

// Network statistics record struct
