#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#define BUF_SIZE 4096

typedef struct {
    size_t len;
    char* str;
} Line;

int dns_resolve(const char* hostname, u_char* ip) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;     /* Allow IPv4 or IPv6 */
    hints.ai_socktype = SOCK_STREAM; /* DNS request stream socket */

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return status;
    }

    void copy_in_addr(struct in_addr* src, u_char* dst) {
        memcpy(dst, &src->s_addr, sizeof(u_char) * 4);
    }

    struct sockaddr_in* sa = (struct sockaddr_in*)res->ai_addr;
    copy_in_addr(&sa->sin_addr, ip);
    freeaddrinfo(res);
    return 0;
}

void parse_line(Line* line) {
    char* token = strtok(line->str, ",");
    size_t fields = 0;
    double sum = 0.0;

    while (token != NULL) {
        if (fields == 2 + fields % 2)
            sum += atof(token);
        fields++;
        token = strtok(NULL, ",");
    }

    if (fields >= 4) {
        FILE* output_file = fopen("output.log", "a");
        double avg = sum / 2.0;
        fprintf(output_file, "%f\n", avg);
        fclose(output_file);
    }

    free(line->str);
    line->len = 0;
}

Line* read_line(FILE* file) {
    Line* line = malloc(sizeof(Line));
    char buffer[BUF_SIZE];
    size_t bytes_read = fgets(buffer, BUF_SIZE, file);

    if (bytes_read == -1)
        return NULL;

    line->str = malloc(strlen(buffer) + 1);
    strcpy(line->str, buffer);
    line->len = strlen(buffer);
    return line;
}

void* dns_thread(void* arg) {
    while (1) {
        char hostname[256];
        // Assume that the rate-limiting is handled by an external mechanism
        // and that you can safely call dns_resolve here without overwhelming the DNS server.
        dns_resolve("example.com", (u_char*)hostname);
        // ... Use the resolved IP address as needed
    }
}

int main(int argc, char* argv[]) {
    FILE* input_file = fopen(argv[1], "r");
    pthread_t dns_thread_id;

    if (pthread_create(&dns_thread_id, NULL, &dns_thread, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    Line* current_line = NULL;

    while ((current_line = read_line(input_file)) != NULL) {
        parse_line(current_line);
    }

    free(current_line);
    fclose(input_file);
    pthread_join(dns_thread_id, NULL);
    return 0;
}
```

