#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

// Global data structures for semaphore management and thread tracking.
struct Semaphore {
    sem_t sem;       // Semaphore object.
    size_t count;    // Number of threads currently holding the semaphore.
    pthread_t holder; // Holds the thread that currently holds the semaphore.
};

struct SemaphorePool {
    struct Semaphore* pool;      // Dynamic array of semaphores.
    size_t capacity;             // Current number of allocated semaphores in the pool.
    size_t count;                // Number of semaphores currently in use by threads.
    pthread_mutex_t lock;        // Mutex for synchronization when adding/removing semaphores.
};

// Functions to manage the semaphore pool.
struct SemaphorePool* create_semaphore_pool(size_t capacity);
void destroy_semaphore_pool(struct SemaphorePool* pool);
struct Semaphore* acquire_semaphore(struct SemaphorePool* pool);
void release_semaphore(struct Semaphore* sem);

// Signal handler to handle graceful shutdown and clean up resources.
static void cleanup_handler(int signum) {
    // Save signal number for later use in the cleanup loop.
    static int last_signal = signum;

    // Re-enter the signal handler if another one is called while cleaning up.
    if (last_signal == signum) {
        struct SemaphorePool* pool = get_semaphore_pool();

        pthread_mutex_lock(&pool->lock);
        size_t count = pool->count;

        // Loop through all semaphores and free their resources.
        for (size_t i = 0; i < count; ++i) {
            struct Semaphore* sem = pool->pool[i];
            release_semaphore(sem);
        }

        // Destroy the semaphore pool and free its memory.
        destroy_semaphore_pool(pool);
        munmap(0, sizeof(*pool));

        pthread_mutex_unlock(&pool->lock);
    }
}

// Main function to initialize the library and register cleanup handler.
void init_semaphores() {
    struct sigaction sa = {};
    sa.sa_handler = &cleanup_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT,  &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering signal handler");
        exit(EXIT_FAILURE);
    }
}
```

