#include <iostream>
#include <mutex>
#include <atomic>

std::mutex mtx;
std::atomic<bool> isLogging{false};

void insertAfterUniqueElement(std::vector<int>& vec, int targetValue, int newValue, bool verbose) {
    std::unique_ptr<bool> log(new bool(isLogging));
    if (log && *log) {
        std::lock_guard<std::mutex> lock(mtx);
        isLogging = false;
        std::cout << "Vector size before insertion: " << vec.size() << '\n';
    }

    auto it = std::find(vec.begin(), vec.end(), targetValue);
    if (it != vec.end()) {
        if ((it + 1) != vec.end() && *(it + 1) == newValue) return; // Avoid duplicate insertions

        vec.insert(++it, 1, newValue);

        if (log && *log) {
            std::lock_guard<std::mutex> lock(mtx);
            isLogging = false;
            std::cout << "Inserted " << newValue << " after " << targetValue << " at index: " << it - vec.begin() + 1 << '\n';
        }
    } else {
        vec.push_back(newValue);

        if (log && *log) {
            std::lock_guard<std::mutex> lock(mtx);
            isLogging = false;
            std::cout << "Appended " << newValue << " to the vector\n";
        }
    }
}
```

