#include <mutex>
#include <random>

namespace mylib {

class ThreadSafeMersenneTwister {
public:
    explicit ThreadSafeMersenneTwister(uint64_t seed = std::random_device{}());
    ThreadSafeMersenneTwister(const ThreadSafeMersenneTwister&) = delete;
    ThreadSafeMersenneTwister(ThreadSafeMersenneTwister&&) noexcept;
    ~ThreadSafeMersenneTwister();

    ThreadSafeMersenneTwister& operator=(const ThreadSafeMersenneTwister&) = delete;
    ThreadSafeMersenneTwister& operator=(ThreadSafeMersenneTwister&&) noexcept;

    void seed(uint64_t seed);
    uint32_t getRandomNumber(uint32_t min, uint32_t max);

private:
    std::mt19937 mersenneEngine;
    std::mutex mutex;
};

inline ThreadSafeMersenneTwister::ThreadSafeMersenneTwister(uint64_t seed)
    : mersenneEngine(static_cast<uint32_t>(seed)), engineVector() {
    engineVector.emplace_back(mersenneEngine);
}

inline ThreadSafeMersenneTwister::ThreadSafeMersenneTwister(ThreadSafeMersenneTwister&& other) noexcept
    : mersenneEngine(other.mersenneEngine), engineVector(std::move(other.engineVector)) {}

inline ThreadSafeMersenneTwister& ThreadSafeMersenneTwister::operator=(ThreadSafeMersenneTwister&& other) noexcept {
    if (this != &other) {
        mersenneEngine = other.mersenneEngine;
        engineVector = std::move(other.engineVector);
    }
    return *this;
}

inline ThreadSafeMersenneTwister::~ThreadSafeMersenneTwister() {}

inline void ThreadSafeMersenneTwister::seed(uint64_t seed) {
    std::unique_lock<std::mutex> lock(mutex);
    mersenneEngine.seed(static_cast<uint32_t>(seed));
}

inline uint32_t ThreadSafeMersenneTwister::getRandomNumber(uint32_t min, uint32_t max) {
    std::unique_lock<std::mutex> lock(mutex);
    auto engineIndex = std::hash<std::thread::id>()(std::this_thread::get_id()) % engineVector.size();
    return engineVector[engineIndex].minstd_rand01() * (max - min) + min;
}

}  // namespace mylib
```
