public class UpdateService : IHubCaller
{
    private const int MaxContentLength = 10000;
    private readonly IDatabase cache;
    private readonly IHubContext<UpdateHub> hubContext;
    private readonly IConnectionManager connectionManager;

    public UpdateService(IDatabase cache, IHubContext<UpdateHub> hubContext, IConnectionManager connectionManager)
    {
        this.cache = cache;
        this.hubContext = hubContext;
        this.connectionManager = connectionManager;
    }

    public async Task UpdateElementAsync(Guid pageSectionId, Guid elementId, string content)
    {
        if (content.Length > MaxContentLength)
            throw new ArgumentException("Content exceeds maximum length");

        // Validate HTML content against predefined schema
        Regex schemaValidator = new Regex("REGEX_SCHEMA", RegexOptions.Compiled);
        if (!schemaValidator.IsMatch(content))
            throw new ArgumentException("Invalid HTML content");

        var lockKey = GetLockKey(pageSectionId, elementId);
        IDatabase redisDb = RedisDatabase.Default;
        using (redisDb.LockTake(lockKey, TimeSpan.FromSeconds(10))) // 10 seconds lock timeout
        {
            if (!redisDb.StringExists(lockKey)) // Handle race conditions
            {
                await UpdateAndPropagateContentAsync(pageSectionId, elementId, content);
            }
        }
    }

    private async Task UpdateAndPropagateContentAsync(Guid pageSectionId, Guid elementId, string content)
    {
        await UpdateElementInDatabaseAsync(pageSectionId, elementId, content); // Update the element in your database

        await hubContext.Clients.Group(pageSectionId.ToString()).SendAsync("UpdateElement", new { PageSectionId = pageSectionId, ElementId = elementId, Content = content }); // Send updates to clients

        // Cache the updated element for better performance and reduce load on main server
        await cache.HashSetAsync($"ElementCache:{pageSectionId}", elementId, content);
    }

    private async Task UpdateElementInDatabaseAsync(Guid pageSectionId, Guid elementId, string content)
    {
        // Implement your database update logic here
    }

    // Helper methods for getting lock keys and group names for SignalR
    private string GetLockKey(Guid pageSectionId, Guid elementId) => $"{pageSectionId}:{elementId}";
    private string GetGroupKey(Guid pageSectionId) => pageSectionId.ToString();
}
