use reqwest::Client;
use reqwest::header::{HeaderMap, UserAgent};
use reqwest::transport::h1::H1Connector;
use reqwest_native_tls::NativeTlsTrust;
use serde_json::{Map, Value};
use std::collections::HashMap;
use std::sync::{Arc, Mutex, RwLock};
use std::time::{Duration, Instant};

pub struct CustomHttpClient {
    client: Arc<RwLock<Client>>,
    max_connections_per_host: u16,
    retry_attempts: u32,
    backoff_factor: f32,
    log_level: LogLevel,
    auth_service: Box<dyn AuthService>,
}

impl CustomHttpClient {
    pub fn new(
        max_connections_per_host: u16,
        retry_attempts: u32,
        backoff_factor: f32,
        log_level: LogLevel,
        auth_service: Box<dyn AuthService>,
    ) -> Self {
        let client = Arc::new(RwLock::new(Client::builder()
            .connector(H1Connector::new())
            .max_connections_per_host(max_connections_per_host)
            .build()));

        CustomHttpClient {
            client,
            max_connections_per_host,
            retry_attempts,
            backoff_factor,
            log_level,
            auth_service,
        }
    }

    pub async fn request_builder(&self, url: &str) -> reqwest::blocking::RequestBuilder {
        let client = self.client.read().await;
        let mut request_builder = client.get(url);

        // Disable certificate validation if required
        if !self.should_validate_certificate() {
            request_builder = request_builder.dont_verify_trusted_certificate();
        }

        self.set_user_agent(&mut request_builder);
        self.set_headers(&mut request_builder);
        self.set_timeout(&mut request_builder);
        self.handle_retries(request_builder.clone());
        self.apply_auth(&mut request_builder);

        request_builder
    }

    fn should_validate_certificate(&self) -> bool {
        // Implement your logic for deciding whether to validate the certificate or not
        true
    }

    fn set_user_agent(&self, req_builder: &mut reqwest::blocking::RequestBuilder) {
        let user_agent = format!("MyApp/{}", env!("CARGO_PKG_VERSION"));
        req_builder.header(Header::USER_AGENT, user_agent);
    }

    fn set_headers(&self, req_builder: &mut reqwest::blocking::RequestBuilder) {
        // Set any custom headers required for your specific use case
    }

    fn set_timeout(&self, req_builder: &mut reqwest::blocking::RequestBuilder) {
        // Set a timeout if required
    }

    fn handle_retries(&self, mut request_builder: reqwest::blocking::RequestBuilder) {
        let retry_delay = Duration::from_secs(1);
        let max_retry_delay = Duration::from_secs(60);

        request_builder.retries(self.retry_attempts, |req, resp| {
            if is_transient_error(&resp) {
                self.backoff_delay(retry_delay.mul(self.backoff_factor.pow(u32::from(req.retries())))).as_secs_f32() as u64
            } else {
                std::u64::MAX
            }
        });
    }

    fn backoff_delay(&self, delay: Duration) -> Duration {
        if delay > max_retry_delay {
            max_retry_delay
        } else {
            delay
        }
    }

    fn is_transient_error(resp: &Response) -> bool {
        // Implement your logic for deciding whether the error is transient or not based on response status code, etc.
        false
    }

    fn apply_auth(&self, req_builder: &mut reqwest::blocking::RequestBuilder) {
        self.auth_service.apply_auth(req_builder);
    }
}

pub trait AuthService {
    fn apply_auth(&self, req_builder: &mut reqwest::blocking::RequestBuilder);
}
```

