use std::env;
use std::fs::{self, File};
use std::io::{BufWriter, Write};
use std::path::PathBuf;
use std::process::Command;
use rustc_driver::{DiagnosticHandler, Driver};
use sync_runtime::SyncLazy;

static RUSTC: SyncLazy<Box<fn(Vec<String>) -> i32>> = SyncLazy::new(|| {
    Box::new(|args| {
        let output = Command::new("rustc")
            .args(&args)
            .output()
            .expect("failed to execute process");

        if !output.status.success() {
            return output.status.code().unwrap_or(1);
        }

        // Here you can add your ice hook to catch and report errors with `rustc_driver::catch_with_exit_code`

        0
    })
});

fn run_compile(crate_dir: &PathBuf, features: Vec<&str>, output_file: Option<&PathBuf>) -> (u64, i32) {
    let current_rss = std::process::memory_usage().resident_set_size;

    let mut args = vec!["--crate-name".to_owned(), crate_dir.file_name().unwrap().to_str().unwrap()];
    args.extend(features);

    let output_arg = if let Some(output_path) = output_file {
        format!("--out-dir={}", output_path.display())
    } else {
        String::new()
    };
    args.push(output_arg);

    let mut handler = DiagnosticHandler::default();
    let driver = Driver::new(&args, &handler);
    let status = driver.run();

    let elapsed_time = std::process::duration_since(driver.start_time).as_millis() as u64;
    (elapsed_time, status.code().unwrap_or(1))
}

fn log_to_file(message: &str, level: &str, log_file: &PathBuf) {
    let file = File::create(log_file).expect("failed to create log file");
    let mut writer = BufWriter::new(file);

    writeln!(writer, "[{}] {}", level, message).unwrap();
}
```

