function generateAndHashPassword($length, $characterSet, $filePath) {
    if (!is_array($characterSet)) {
        throw new InvalidArgumentException("Character set must be an array.");
    }

    $config = json_decode(file_get_contents($filePath), true);
    if (!$config || !is_array($config) || empty($config['characters'])) {
        throw new InvalidArgumentException("Invalid or missing configuration file.");
    }

    $characters = array_merge($characterSet, $config['characters']);
    shuffle($characters);

    $password = substr(implode('', $characters), 0, $length);
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    return [$password, $hashedPassword];
}
```

