["Here's a basic implementation of the function using Node.js `fs`, `crypto` and Stream modules, following the guidelines provided:

```javascript
const fs = require('fs');
const crypto = require('crypto');
const { PassThrough } = require('stream');

// Load environment variable for directory path
const dirPath = process.env.CERT_DIR_PATH;

async function generatePEMCertificate(oauthRequest) {
  try {
    // Read private key and certificate files from the specified directory
    const privateKeyPath = `${dirPath}/${oauthRequest.privateKeyFile}`;
    const certPath = `${dirPath}/${oauthRequest.certificateFile}`;

    let privateKeyData = [];
    let certificateData = [];

    // Create pass-through streams for the private key and certificate files
    const privateKeyStream = fs.createReadStream(privateKeyPath);
    const certStream = fs.createReadStream(certPath);

    // Pipe the streams into arrays, handling pause/resume operations
    privateKeyStream.on('data', (chunk) => {
      privateKeyData.push(chunk);
    });

    certStream.on('data', (chunk) => {
      certificateData.push(chunk);
    });

    // Collect all data when the streams end
    privateKeyStream.on('end', () => {
      privateKeyData = Buffer.concat(privateKeyData);
    });

    certStream.on('end', () => {
      certificateData = Buffer.concat(certificateData);
    });

    // Generate the PEM certificate from the concatenated data
    const pemPrivateKey = privateKeyData.toString('utf8');
    const pemCertificate = certificateData.toString('utf8');

    // Extract the key and certificate objects
    const key = crypto.privateKeys.keyFromPem(pemPrivateKey);
    const cert = crypto.createCredentials({ key, cert: pemCertificate });

    return { key, cert };
  } catch (error) {
    console.error(`Error fetching certificate and private key: ${error}`);
    throw error;
  }
}
```

This function will read the specified files asynchronously using streams to handle large data streams efficiently. It uses environment variables for directory path configuration, making it easy to change the location of certificates without modifying the function itself. Error handling is incorporated to manage potential failures during file access and retrieval processes.

Note that this implementation does not include caching strategies or any modifications to accommodate changes in directory structures or data formats. Those improvements could be added by using a library such as `js-yaml` or `jsonfile` for loading configuration files, along with setting up a cache system like Redis or Memcached."]

