template<typename T>
class OctreeNode {
public:
    std::vector<std::unique_ptr<OctreeNode<T>>> children;
    T data;

    OctreeNode(T data) : data(data) {}
};

class Octree {
public:
    Octree(float featureSize, size_t numLeafNodes, size_t dataCapacity) {
        if (numLeafNodes > (1ULL << 28)) throw std::invalid_argument("Too many leaf nodes exceeding maximum supported number.");

        // Calculate the maximum depth of the octree and allocate root node.
        uint32_t depth = static_cast<uint32_t>(log2(numLeafNodes));
        rootNode = std::make_unique<OctreeNode<T>>(T{});
        nodesPerLevel = (1ULL << depth);
        memoryPool.reserve(nodesPerLevel * sizeof(OctreeNode<T>));

        // Allocate memory pool for optimal performance and scalability.
        void* memoryBlock = malloc(memoryPool.capacity());
        char* memoryStart = static_cast<char*>(memoryBlock);
        for (size_t i = 0; i < nodesPerLevel; ++i) {
            new (memoryStart) OctreeNode<T>();
            memoryStart += sizeof(OctreeNode<T>);
        }

        // Initialize root node data and recursively build octree structure.
        initializeNode(rootNode.get(), 0, depth);
    }

private:
    std::vector<OctreeNode<T>*> memoryPool;
    std::unique_ptr<OctreeNode<T>> rootNode;
    uint64_t nodesPerLevel;

    void initializeNode(OctreeNode<T>* node, size_t level, uint32_t depth) {
        if (level == depth) {
            // Allocate leaf node and populate with data.
            auto leafNode = memoryPool.empty() ? new OctreeNode<T>(T{}) : memoryPool.back();
            memoryPool.pop_back();
            node->children.push_back(std::unique_ptr<OctreeNode<T>>(leafNode));
            return;
        }

        float featureSizeHalf = featureSize / 2.f;
        size_t childrenCount = static_cast<size_t>(std::pow(2, level + 1));
        for (size_t i = 0; i < childrenCount; ++i) {
            uint64_t indexInMemoryPool = node->children.size() + i;
            if (indexInMemoryPool >= memoryPool.size()) initializeNode(memoryPool[indexInMemoryPool], level + 1, depth);
        }
    }

    // Implement insertion, traversal, and destruction functions here...
};
```

