class Character {
public:
    std::vector<std::pair<int, int>> attackHistory; // (type, timestamp)

    void attack() {
        auto now = std::chrono::system_clock::now();
        int currentType = getRandomAttackType(); // Implement a method to get a random attack type

        std::pair<int, int> newAttack = {currentType, static_cast<int>(std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count())};

        if (attackHistory.size() >= 10)
            attackHistory.erase(attackHistory.begin());

        attackHistory.push_back(newAttack);

        std::this_thread::sleep_for(std::chrono::milliseconds(9 + getRandomDelay())); // Implement a method to get a random delay between 0 and 2 seconds

        auto it = std::chrono::system_clock::now();
        time_t nowTime = std::chrono::system_clock::to_time_t(it);
        if (nowTime == prevMinute + 60) {
            printAttackFrequency();
            prevMinute = nowTime;
        }
    }

private:
    int getRandomAttackType() {
        // Implement a method to generate a random attack type
        static std::mt19937 randEngine(static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count()));
        static std::uniform_int_distribution<> distrib(0, 2); // Define the range for possible attack types
        return distrib(randEngine);
    }

    int getRandomDelay() {
        // Implement a method to generate a random delay between 0 and 2 seconds
        static std::uniform_int_distribution<> distrib(0, 2000); // Define the range for possible delays in milliseconds
        return distrib(std::mt19937{static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count())});
    }

    void printAttackFrequency() {
        std::unordered_map<int, int> freq;
        for (auto& attack : attackHistory)
            ++freq[attack.first];

        for (const auto& element : freq)
            std::cout << "Attack type: " << element.first << ", count: " << element.second << std::endl;
    }

    time_t prevMinute = 0; // Store the timestamp of the previous minute to avoid printing frequency every second
};
```
