using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Aforge.Imaging;
using AForge.Imaging.FileFormats;

namespace ImageMetadataExtractor
{
    public class ImageReport
    {
        public string FileName { get; set; }
        public int BitsPerSample { get; set; }
        public int SamplesPerPixel { get; set; }
        public int[] ExtraSamples { get; set; }
        public ulong Md5Hash { get; set; }
    }

    public class TiffImageProcessor
    {
        private readonly Dictionary<string, ImageReport> _reportCache = new Dictionary<string, ImageReport>();

        public async Task ProcessDirectoryAsync(string directory)
        {
            var files = Directory.GetFiles(directory, "*.tif", SearchOption.AllDirectories);
            await Task.WhenAll(files.Select(ProcessImageFileAsync));
        }

        private ImageReport GetReport(string filePath)
        {
            if (_reportCache.TryGetValue(filePath, out var report))
                return report;

            using (var reader = new TiffReader(filePath))
            {
                if (!reader.IsValid)
                    throw new InvalidDataException($"Invalid TIFF file: {filePath}");

                var bitsPerSample = GetBitsPerSample(reader);
                var samplesPerPixel = reader.PhotometricInterpretation == PhotometricInterpretation.MinIsWhite
                    ? reader.SamplesPerPixel - 1
                    : reader.SamplesPerPixel;
                var extraSamples = GetExtraSamples(reader);
                var md5Hash = GetMd5Hash(filePath);

                report = new ImageReport
                {
                    FileName = filePath,
                    BitsPerSample = bitsPerSample,
                    SamplesPerPixel = samplesPerPixel,
                    ExtraSamples = extraSamples,
                    Md5Hash = md5Hash
                };

                _reportCache[filePath] = report;
            }

            return report;
        }

        private int[] GetExtraSamples(TiffReader reader)
        {
            if (reader.SamplesPerPixel <= 3 || reader.PhotometricInterpretation != PhotometricInterpretation.MinIsWhite)
                return Array.Empty<int>();

            return Enumerable.Range(0, reader.SamplesPerPixel - 1)
                .Where(i => i > 2)
                .Select(i => (int)(reader.GetTagValue<double>("SampleFormat", i) * 8))
                .ToArray();
        }

        private static int GetBitsPerSample(TiffReader reader)
        {
            if (reader.PhotometricInterpretation == PhotometricInterpretation.MinIsWhite && reader.SamplesPerPixel == 1)
                return 8;

            var bits = Enumerable.Range(0, reader.SamplesPerPixel).Select(GetBitsPerSampleForSample).ToList();
            return Math.Max(bits.Min(), bits.Max());
        }

        private static int GetBitsPerSampleForSample(int sampleIndex)
        {
            var tag = (sampleIndex * 2 + 3) % 4;
            return reader => reader.GetTagValue<ushort>($"BitsPerSample{tag}", 0) switch
            {
                1 => 1,
                2 => 2,
                4 => 4,
                8 => 8,
                16 => 16,
                _ => throw new InvalidDataException($"Invalid bits per sample for TIFF file: {reader.FileName}")
            };
        }

        private static ulong GetMd5Hash(string filePath)
        {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(filePath))
                return BitConverter.ToUInt64(md5.ComputeHash(stream), 0);
        }

        private async Task ProcessImageFileAsync(string filePath)
        {
            try
            {
                var report = await Task.Run(() => GetReport(filePath));
                Console.WriteLine(report);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing {filePath}: {ex.Message}");
            }
        }
    }
}
