            !session_data.contains("expiration_time") ||
            !session_data.contains("user_id")) {
            return false;
        }

        string session_id = session_data["session_id"].get<string>();
        auto it = active_sessions.find(session_id);
        if (it != active_sessions.end() && it->second != chrono::system_clock::now()) {
            return false;
        }

        if (!storage->isValidUser(session_data["user_id"].get<string>())) {
            return false;
        }

        time_point<system_clock> expiration_time = session_data["expiration_time"].get<chrono::time_point<system_clock>>();
        if (expiration_time <= chrono::system_clock::now()) {
            return false;
        }

        unique_lock<mutex> lock(sessions_mutex);
        if (active_sessions.find(session_id) != active_sessions.end() && it->second == chrono::system_clock::now()) {
            return false; // race condition, session already being updated by another thread
        }

        lock.unlock();
        Session session(session_id, session_data["user_id"].get<string>(), session_data["refresh_token"].get<string>(), expiration_time);
        active_sessions.insert(make_pair(session_id, chrono::system_clock::now()));
        lock.lock();

        // Cache the user record locally for faster access in future sessions
        // ... (implement this part)

        lock.unlock();
        return true;
    }
};
