        {
            LogError("Network timeout: " + ex.Message);
            await Task.Delay(TimeSpan.FromSeconds(_configuration.GetValue<int>("RetriesDelay")));
            ProcessData(data); // Retry the operation
        }
        catch (HttpRequestException ex) when (IsTransientError(ex))
        {
            LogError("API rate limit exceeded: " + ex.Message);
            await Task.Delay(TimeSpan.FromSeconds(_configuration.GetValue<int>("RetriesDelay")));
            ProcessData(data); // Retry the operation
        }
        catch (SqlException ex) when (IsTransientError(ex))
        {
            LogError("Database connection error: " + ex.Message);
            await Task.Delay(TimeSpan.FromSeconds(_configuration.GetValue<int>("RetriesDelay")));
            ProcessData(data); // Retry the operation
        }
        catch (Exception ex) when (IsTransientError(ex))
        {
            LogError("Unexpected error: " + ex.Message);
            await Task.Delay(TimeSpan.FromSeconds(_configuration.GetValue<int>("RetriesDelay")));
            ProcessData(data); // Retry the operation
