using System;
using System.Collections.Generic;
using System.Text;
using System.Diagnostics;
using Newtonsoft.Json;

public class NormalizedString
{
    public string Value { get; set; }
}

public class Logger
{
    private readonly ILoggerAdapter _logger;
    private const int MaxIdentifierLength = 32;

    public Logger(ILoggerAdapter logger)
    {
        _logger = logger;
    }

    public string ProcessLogEntry(string logEntry)
    {
        Stopwatch stopWatch = new Stopwatch();
        stopWatch.Start();

        var normalizedString = NormalizeInput(logEntry);
        var hash = CalculateHash(normalizedString.Value);
        var identifier = FormatIdentifier(hash);

        if (identifier.Length > MaxIdentifierLength)
        {
            _logger.LogError($"Processing log entry ({logEntry}) failed: Identifier length exceeded maximum allowed ({MaxIdentifierLength}).");
            throw new Exception("Identifier is too long.");
        }

        stopWatch.Stop();

        _logger.LogInformation($"Processed log entry {logEntry} in {stopWatch.ElapsedMilliseconds} ms, generated unique identifier: {identifier}");

        return identifier;
    }

    private NormalizedString NormalizeInput(string input)
    {
        var result = new StringBuilder();
        foreach (var c in input)
            if (char.IsLetterOrDigit(c))
                result.Append(char.ToLowerInvariant(c));

        return new NormalizedString { Value = result.ToString().Trim() };
    }

    private string CalculateHash(string normalizedInput)
    {
        using (var sha256 = SHA256.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(normalizedInput);
            return BitConverter.ToString(sha256.ComputeHash(bytes)).Replace("-", "").Substring(0, MaxIdentifierLength);
        }
    }

    private string FormatIdentifier(string hash)
    {
        if (hash.Length < MaxIdentifierLength)
        {
            var padding = MaxIdentifierLength - hash.Length;
            return hash.PadLeft(padding, '0');
        }

        return hash;
    }
}

public interface ILoggerAdapter
{
    void LogInformation(string message);
    void LogError(string message);
}
```
