import java.io.*;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class CustomObjectDeserializer {
    private static final int MAX_RETRIES = 3;
    private static final ConcurrentHashMap<String, Class<?>> CLASS_CACHE = new ConcurrentHashMap<>();
    private static final AtomicInteger RETTRY_COUNT = new AtomicInteger(0);

    public static <T> T deserialize(byte[] data) {
        try (ObjectInputStream ois = new CustomClassLoaderObjectInputStream(getClass().getClassLoader())) {
            ois.reset();
            ois.readFully(data);

            Class<?> clazz = CLASS_CACHE.computeIfAbsent("root", CustomClassLoader::new);
            return (T) ois.readObject();
        } catch (IOException | ClassNotFoundException | IllegalArgumentException e) {
            if (RETTRY_COUNT.getAndIncrement() < MAX_RETRIES) {
                throw new RuntimeException("Deserialization failed, retrying...", e);
            } else {
                throw new RuntimeException("Failed to deserialize data after " + MAX_RETRIES + " retries.", e);
            }
        }
    }

    static class CustomClassLoader extends ClassLoader {
        private final String baseDir;

        CustomClassLoader(ClassLoader parent) {
            super(parent);
            this.baseDir = "path/to/your/classes";
        }

        @Override
        protected Class<?> findClass(String name) throws ClassNotFoundException {
            try (URL url = new URL("file", "", baseDir + "/" + name.replaceAll("\\.", "/") + ".class")) {
                byte[] classData = IOUtils.toByteArray(url.openStream());
                return defineClass(name, classData, 0, classData.length);
            } catch (IOException e) {
                throw new ClassNotFoundException("Failed to load class: " + name, e);
            }
        }
    }

    // CustomObjectInputStream implementation omitted for brevity...
}
