const cloudStorageService = require('cloud-storage-service'); // Third-party API
const { v4: uuidv4 } = require('uuid'); // For unique ID generation
const config = require('./config'); // Application configuration
const logger = require('./logger'); // Existing logging system

let activeUploads = new Set(); // Track concurrent uploads

function validateFile(file) {
  const { mimeType, size } = file;
  if (!mimeType || !size) return false;

  const allowedMimes = config.get('allowedMimes');
  const maxSize = config.get('maxFileSize');

  // Check MIME type and size against configured limits
  return allowedMimes.includes(mimeType) && size <= maxSize;
}

async function uploadFile(file, onProgress, onError, onComplete) {
  if (!validateFile(file)) {
    logger.error(`Invalid file: ${file.name}. MIME type is not allowed or the file size exceeds the limit.`);
    onError('Invalid file');
    return;
  }

  const uploadId = uuidv4();
  activeUploads.add(uploadId);

  try {
    const result = await cloudStorageService.upload({
      id: uploadId,
      file,
      onProgress: progress => onProgress(progress),
      onError: error => {
        // Handle transient errors by retrying based on your application's policy
        // Log the error for monitoring and debugging purposes
        logger.error(`Upload failed for file ${file.name}: ${error}`);
        activeUploads.delete(uploadId);
      },
      onComplete: response => {
        activeUploads.delete(uploadId);
        onComplete(response);
      }
    });

    logger.info(`File ${file.name} uploaded successfully.`);
  } catch (error) {
    // Handle non-transient errors appropriately and log for monitoring and debugging
    logger.error(`Unexpected error occurred while uploading file ${file.name}: ${error}`);
    activeUploads.delete(uploadId);
  }
}

module.exports = { uploadFile };
```

