    public class Program
    {
        public static void Main(string[] args)
        {
            if (args.Length < 1)
            {
                WriteLine("Please provide an XML file as input.");
                return;
            }

            var xmlFile = args[0];
            var intList = GetValidIntListFromConsole();

            var largestNumber = FindLargestNumber(xmlFile);

            if (largestNumber.HasValue)
            {
                WriteLine($"The largest number in the XML file is: {largestNumber.Value}");
                foreach (var num in intList)
                    WriteLine($"User input: {num}");
            }
        }

        private static List<int> GetValidIntListFromConsole()
        {
            var intList = new List<int>();

            while (true)
            {
                if (!int.TryParse(Console.ReadLine(), out int input))
                    WriteLine("Invalid input, please enter an integer.");
                else
                    intList.Add(input);

                if (Console.ReadKey().Key == ConsoleKey.D) // D for done
                    break;
            }

            return intList;
        }

        private static int? FindLargestNumber(string xmlFilePath)
        {
            var largest = default(int?);

            using (var reader = XmlReader.Create(xmlFilePath))
            {
                if (!reader.MoveToContent()) return null;

                while (reader.Read())
                {
                    switch (reader.NodeType)
                    {
                        case XmlNodeType.Element:
                            var elementName = reader.LocalName!;
                            if (elementName == "desiredTagName")
                            {
                                largest = int.Parse(reader.GetAttribute("attributeYouNeed"));
                                break;
                            }
                            continue;

                        case XmlNodeType.EndElement:
                            if (largest.HasValue) return largest;
                            break;
                    }
                }
            }

            return null;
        }
    }

