using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.Crypto;

namespace TripleDesBase64DecryptionLibrary
{
    public interface ICryptoAlgorithm
    {
        KeyParameters GetKey(string key);
        byte[] Encrypt(byte[] data, KeyParameters key);
        byte[] Decrypt(byte[] data, KeyParameters key);
    }

    public abstract class BaseCryptoAlgorithm : ICryptoAlgorithm
    {
        protected virtual KeyParameters GetKey(string key) => throw new NotImplementedException();
        protected virtual byte[] Encrypt(byte[] data, KeyParameters key) => throw new NotImplementedException();
        protected virtual byte[] Decrypt(byte[] data, KeyParameters key) => throw new NotImplementedException();
    }

    public class TripleDesAlgorithm : BaseCryptoAlgorithm
    {
        private const string AlgorithmName = "TripleDES";

        protected override KeyParameters GetKey(string key)
        {
            var tripleDESKeySpec = new TripleDESCryptoServiceProvider().KeyGenerator.KeySpec;
            tripleDESKeySpec.SetKeyEncoding(TripleDESCryptoServiceProvider.TripleDES_3KEY);
            tripleDESKeySpec.SetPassword(Encoding.ASCII.GetBytes(key));
            return new ParametersWithIV(new KeyParameter(tripleDESKeySpec), new byte[8]);
        }

        protected override byte[] Encrypt(byte[] data, KeyParameters key)
        {
            using (var encryptor = TripleDESCryptoServiceProvider.Create())
            {
                encryptor.Init(false, key.Key);
                return encryptor.TransformFinalBlock(data, 0, data.Length);
            }
        }

        protected override byte[] Decrypt(byte[] data, KeyParameters key)
        {
            using (var decryptor = TripleDESCryptoServiceProvider.Create())
            {
                decryptor.Init(true, key.Key);
                return decryptor.TransformFinalBlock(data, 0, data.Length);
            }
        }
    }

    public class DecryptionService
    {
        private readonly ICryptoAlgorithm _algorithm;

        public DecryptionService(ICryptoAlgorithm algorithm) => _algorithm = algorithm;

        public string DecryptBase64(string base64EncodedMessage, string key, string iv)
        {
            var data = Convert.FromBase64String(base64EncodedMessage);
            var keyParameters = _algorithm.GetKey(key);
            var ivBytes = TextEncodings.Hex.Decode(iv);

            if (data.Length < ivBytes.Length)
                throw new ArgumentException("Invalid IV length.");

            var decryptedData = _algorithm.Decrypt(CombineArrays(data, 0, ivBytes.Length, data, ivBytes.Length), keyParameters);
            return Encoding.UTF8.GetString(decryptedData);
        }

        private static byte[] CombineArrays(params byte[][] arrays) => arrays.SelectMany(b => b).ToArray();
    }
}
```

