#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

// Maximum number of concurrent connections
#define MAX_CONNECTIONS 16

// Semaphore for managing max connections
sem_t connection_mutex;

struct connection_info {
    struct sockaddr_in addr;
    int socket;
    bool connected;
};

int establishNetworkService(const char *hostname, int port) {
    struct hostent *he = gethostbyname(hostname);
    if (!he) {
        perror("gethostbyname");
        return -1;
    }

    // Initialize connection info for the resolved IP address
    struct connection_info conn_info;
    memcpy(&conn_info.addr, he->h_addr, sizeof(struct sockaddr_in));
    conn_info.addr.sin_port = htons(port);
    conn_info.socket = -1;
    conn_info.connected = false;

    // Try to acquire the semaphore to manage a connection attempt
    if (sem_trywait(&connection_mutex) != 0) {
        return -1; // Max connections reached
    }

    // Create and connect socket
    int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock == -1) {
        perror("socket");
        sem_post(&connection_mutex);
        return -1;
    }

    int retries = 3;
    bool connected = false;
    while (!connected && retries > 0) {
        if (connect(sock, (struct sockaddr *)&conn_info.addr, sizeof(struct sockaddr)) == 0) {
            connected = true;
        } else {
            usleep(100000); // Sleep for 100ms before retrying
            retries--;
        }
    }

    if (!connected) {
        close(sock);
        sem_post(&connection_mutex);
        return -1;
    }

    conn_info.socket = sock;
    conn_info.connected = true;

    // Log connection success
    printf("Connected to %s:%d\n", inet_ntoa(conn_info.addr.sin_addr), port);

    sem_post(&connection_mutex);
    return sock;
}
```

