#ifndef LOGGING_HPP
#define LOGGING_HPP

#include <stdarg.h>
#include <stdexcept>
#include <sstream>
#include <atomic>
#include <mutex>
#include <curl/curl.h>

namespace my_project {

class ErrorLogger {
public:
    ErrorLogger(const std::string& apiKey) : apiKey_(apiKey) {}

    void logError(const char* format, ...) {
        if (!initialized_) {
            initialize();
        }

        std::stringstream ss;
        va_list args;
        va_start(args, format);
        ss << fmt::format(format, args);
        va_end(args);

        CURL* curl = curl_easy_init();
        if (curl) {
            std::string url = "https://logging-api.com/log?key=" + apiKey_ + "&message=" + ss.str();
            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_perform(curl);
            curl_easy_cleanup(curl);
        }
    }

private:
    void initialize() {
        // Handle system dependencies such as network communication and authentication tokens here.
        initialized_ = true;
    }

    std::string apiKey_;
    std::atomic<bool> initialized_{false};
};

