// Union-Find structure using Disjoint Set Forest (DF U) data representation
typedef struct {
    uint32_t *parent;
    uint32_t *rank;
} uf_set;

void init_uf(uf_set* set, int size) {
    set->parent = calloc(size, sizeof(uint32_t));
    set->rank = calloc(size, sizeof(uint32_t));
    for (int i = 0; i < size; ++i) {
        set->parent[i] = i;
        set->rank[i] = 1;
    }
}

int find_set(uf_set* set, int x) {
    if (x != set->parent[x])
        set->parent[x] = find_set(set, set->parent[x]);
    return set->parent[x];
}

void union_sets(uf_set* set, int x, int y) {
    int rootX = find_set(set, x);
    int rootY = find_set(set, y);

    if (rootX == rootY) return;

    if (set->rank[rootX] < set->rank[rootY]) {
        set->parent[rootX] = rootY;
        set->rank[rootY] += set->rank[rootX];
    } else {
        set->parent[rootY] = rootX;
        set->rank[rootX] += set->rank[rootY];
    }
}

void destroy_uf(uf_set* set) {
    free(set->parent);
    free(set->rank);
}

struct config {
    const char *extension_map; // JSON string mapping file extensions to types
};

typedef struct processFileMetadata_params {
    char filename[257];
    int array[];
    struct config config;
} processFileMetadata_params;

// Function to derive a unique identifier for the filename by hashing it
char *hash_filename(const char *filename) {
    size_t len = strlen(filename);
    uint64_t hash = 1234567890123456789;
    for (size_t i = 0; i < len; ++i) {
        hash ^= filename[i];
        hash *= 1234567890;
    }
    char *unique_id = malloc(32);
    snprintf(unique_id, 32, "%llu", (unsigned long long)hash);
    return unique_id;
}

char* processFileMetadata(const char* filename, int size, const struct config* cfg, int* array) {
    // Validate and sanitize the filename
    if (strlen(filename) > 256) {
        char trimmed[257];
        strncpy(trimmed, filename, 256);
        trimmed[256] = '\0';
        warn("Filename exceeds maximum length of 256 characters. Trimming to %lu.", strlen(trimmed));
    }

    // Derive a unique identifier for the filename by hashing it, and append this identifier to the original filename
    char *hashed = hash_filename(filename);
    size_t full_length = strlen(filename) + strlen(hashed) + 1; // 1 for delimiter
    char *unique_filename = malloc(full_length);
    snprintf(unique_filename, full_length, "%s-%s", filename, hashed);

    free(hashed); // Free hashed memory since it's no longer needed

    // Determine the file type by identifying specific character sequences within the filename and mapping them to predefined types
    const char *extension_map = json_string_value(json_object_get(cfg->extension_map));
    int file_type = -1;
    char *ext = strrchr(unique_filename, '.');
    if (ext) {
        size_t extension_len = strlen(ext);
        for (int i = 0; i < extension_len; ++i) {
            char extension[extension_len + 1];
            snprintf(extension, extension_len+1, "%c", ext[i]);
            if (fnmatch(extension, extension_map, 0) == 0) {
                file_type = json_int_value(json_object_get(json_object_get(cfg->extension_map, extension)));
                break;
            }
        }
    }

    // Initialize and construct Union-Find data structure to manage the integer array
    uf_set sets;
    init_uf(&sets, size);

    // Measure and log the processing time for filename modification
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Process the integer array with Union-Find operations
    for (int i = 0; i < size; ++i) {
        int root = find_set(&sets, i);
        for (int j = i+1; j < size; ++j) {
            if (array[j] == array[i]) {
                union_sets(&sets, i, j);
            }
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    long filename_modification_time = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
    log("Filename modification time: %ld ms", filename_modification_time);

    // Destroy Union-Find data structure and measure the processing time for Union-Find operations
    destroy_uf(&sets);
    clock_gettime(CLOCK_MONOTONIC, &end);
    long union_find_time = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
    log("Union-Find time: %ld ms", union_find_time);

    // Create the final metadata string
    json_t *metadata = json_pack ("{s, i, s}", "file_type", file_type, "filename", unique_filename);
    char *final_metadata = json_dumps(metadata, JSON_FORMAT_EXTENDED | JSON_INCLUDE_EMPTY_ENTRY_ARRAYS | JSON_DISABLE_UTF8_CHECK);

    // Clean up and return the metadata string
    free(unique_filename);
    json_decref(metadata);
    return final_metadata;
}']

