using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Text.Json;
using Microsoft.AspNetCore.Caching.Memory;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace UserProfileService
{
    public class UserProfileService
    {
        private readonly ILogger<UserProfileService> _logger;
        private readonly MemoryCache _cache;
        private readonly string _jsonFilePath;

        public UserProfileService(ILogger<UserProfileService> logger, IMemoryCache cache, string jsonFilePath)
        {
            _logger = logger;
            _cache = cache;
            _jsonFilePath = jsonFilePath;
        }

        public IEnumerable<UserProfile> GetActiveUsers()
        {
            var userProfiles = LoadFromCache();
            if (userProfiles == null)
            {
                userProfiles = LoadFromFile();
                CacheData();
            }

            return userProfiles.Where(u => u.IsActive);
        }

        private UserProfile[] LoadFromFile()
        {
            try
            {
                using var reader = File.OpenText(_jsonFilePath);
                var jsonString = reader.ReadToEnd();
                return JsonConvert.DeserializeObject<UserProfile[]>(jsonString);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error loading JSON file.");
                throw new Exception("Failed to load JSON file.", ex);
            }
        }

        private void CacheData()
        {
            var userProfiles = LoadFromFile();
            if (userProfiles != null)
                _cache.Set(nameof(UserProfile), userProfiles, new MemoryCacheEntryOptions().RegisterPostEvictionCallback((_, evictedValue) =>
                {
                    _logger.LogInformation("Cached User Profiles expired; reloading data...");
                    LoadFromFile();
                }));
        }

        private UserProfile[] LoadFromCache()
        {
            return (UserProfile[])_cache.Get(nameof(UserProfile));
        }

        public class UserProfile
        {
            public bool IsActive { get; set; }
            // Other properties for user profile
        }
    }
}
```

