public class BackgroundCommandHandler
{
    private readonly ILogger<BackgroundCommandHandler> _logger;
    private readonly IMemoryCache _memoryCache;
    private readonly int _maxConcurrentTasks;
    private readonly TimeSpan _cacheExpiration;

    public BackgroundCommandHandler(ILogger<BackgroundCommandHandler> logger,
                                     IOptionsMonitor<BackgroundCommandHandlerOptions> options,
                                     IMemoryCache memoryCache)
    {
        _logger = logger;
        _memoryCache = memoryCache;
        var opts = options.CurrentValue;
        _maxConcurrentTasks = Math.Min(opts.MaxConcurrentTasks, 1024);
        _cacheExpiration = opts.CacheExpiration;
    }

    public async Task ExecuteAsync(string command)
    {
        var cacheItem = _memoryCache.GetOrCreate(command, options => HandleCommandExecution(options));
        await ExecuteCommandAsync((string)cacheItem.Value).ConfigureAwait(false);
    }

    private object HandleCommandExecution(ExecuteOptions options)
    {
        var result = Task.Run(() => PerformCommandExecution(options)).Result;
        _memoryCache.Set(new CacheItemEntry { Key = options.Command, Value = result }, _cacheExpiration);
        return result;
    }

    private async Task ExecuteCommandAsync(string command)
    {
        var semaphoreSlim = new SemaphoreSlim(_maxConcurrentTasks, _maxConcurrentTasks);
        await semaphoreSlim.WaitAsync();

        try
        {
            await PerformCommandExecution(new ExecuteOptions { Command = command }).ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while executing command: {Command}", command);
        }
        finally
        {
            semaphoreSlim.Release();
        }
    }

    private async Task PerformCommandExecution(ExecuteOptions options)
    {
        // Implement your service dependencies and external data sources here
    }
}

public class CacheItemEntry
