    SandeshClient(const string& configFile) {
        ptree pt;
        read_xml(fs::path(configFile), pt);
        host_ = pt.get<string>("server.host");
        port_ = stoi(pt.get<string>("server.port"));
        retryCount_ = stoi(pt.get<string>("request.retryCount"));
        timeoutMs_ = stod(pt.get<string>("request.timeoutMs"));
    }

    void sendGetRequest() {
        try {
            io_.reset(new tcp::iostream(host_, port_));
            if (!io_->is_open()) {
                cerr << "Failed to connect, retrying..." << endl;
                for (size_t i = 1; i <= retryCount_; ++i) {
                    try {
                        io_->connect();
                        break;
                    } catch (const system_error& e) {
                        if (i == retryCount_) {
                            cerr << "Failed to connect after " << retryCount_ << " attempts." << endl;
                            return;
                        }
                        steady_timer timer(io_->get_io_service());
                        timer.expires_from_now(boost::posix_time::seconds(timeoutMs_ / 1000));
                        timer.async_wait([this](const system_error& e) {
                            if (!e) {
                                io_->connect();
                            }
                        });
                    }
                }
            }

            // Send GET request and read response
