const char *log_file = "error_log.txt";
int log_level = 2; // Error (1), Warning (2), Info (3)

// Function prototypes
void* process_file(const char* filepath);
regex_t filter_pattern;
size_t buffer_size = 4096;

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [file1, file2, ...] --filter=regex\n", argv[0]);
        return 1;
    }

    regcomp(&filter_pattern, argv[argc-1], REG_EXTENDED | REG_NEWLINE); // Compile user-defined filtering regular expression
    argc--;

    for (int i = 0; i < argc; ++i) {
        if (!process_file(argv[i])) return 1;
    }

    printf("Total lines: %zu\n", total_lines);
    return 0;
}

void* process_file(const char *filepath) {
    FILE *fp = NULL;
    int fd = -1;
    size_t lines = 0;
    char *line = NULL;
    ssize_t read;

    if (strchr(filepath, '/') == NULL && getcwd(line, buffer_size) != NULL) {
        // Use absolute path if not provided or current working directory is not the root
        snprintf(filepath, buffer_size, "%s/%s", line, filepath);
    }

    fp = fopen(filepath, "r");
    if (!fp) {
        // Log error and return if unable to open the file
        fprintf(stderr, "Error opening file: %s\n", filepath);
        pthread_mutex_lock(&progress_lock);
        processed_files++;
        pthread_mutex_unlock(&progress_lock);
        return 1;
    }

    fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        // Log error and return if unable to open the file using open()
        fprintf(stderr, "Error opening file: %s\n", filepath);
        pthread_mutex_lock(&progress_lock);
        processed_files++;
        pthread_mutex_unlock(&progress_lock);
        fclose(fp);
        return 1;
    }

    while ((read = readline_chunked(fd, &line, buffer_size)) > 0) {
        if (regexec(&filter_pattern, line, 0, NULL, REG_NEWLINE | REG_NOTEOL) != 0) {
            total_lines++;
        }
        free(line);
    }

    if (read == -1 && errno != EOF) {
        // Log error and return if reading file encounters an error other than EOF
        fprintf(stderr, "Error reading file: %s\n", filepath);
        pthread_mutex_lock(&progress_lock);
        processed_files++;
        pthread_mutex_unlock(&progress_lock);
    }

    if (read == -1 && errno == EOF) {
        free(line);
    }

    fclose(fp);
    close(fd);

    pthread_mutex_lock(&progress_lock);
    processed_files++;
    if ((processed_files % 5) == 0) {
        printf("%.2f%% processed\n", (float)processed_files/argc*100);
    }
    pthread_mutex_unlock(&progress_lock);

    return 0;
}

// Function to read chunked lines from a file descriptor, handling memory allocation and deallocation
ssize_t readline_chunked(int fd, char **lineptr, size_t bufsize) {
    ssize_t n = 0;
    char *line = NULL;

    if (bufsize <= 0 || lineptr == NULL) return -1;

    while ((n = read(fd, line + strlen(*line), bufsize - strlen(*line) - 1)) > 0) {
        if (n < (ssize_t)(bufsize - strlen(*line) - 1)) break;
        (*line)[strlen(*line)] = '\n';
        (*line)[strlen(*line) + 1] = '\0';
    }

    if (n > 0) {
        *line = realloc(*line, strlen(*line) + n + 1);
        memmove(line + strlen(*line), line, n + 1);
    }

    return n;
}
