// Custom memory pool for connection lists
typedef struct connection_pool {
    void* connections; // Array of dynamically allocated memory blocks
    size_t capacity;
    size_t count;
} connection_pool;

connection_pool connection_pools[CONNECTION_POOL_SIZE];

void init_memory_pool() {
    for (int i = 0; i < CONNECTION_POOL_SIZE; ++i) {
        connection_pools[i].capacity = MEMORY_BUDGET / CONNECTION_POOL_SIZE;
        connection_pools[i].count = 0;
        connection_pools[i].connections = malloc(connection_pools[i].capacity * sizeof(int));
    }
}

void* get_memory_block() {
    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < CONNECTION_POOL_SIZE; ++i) {
        if (connection_pools[i].count < connection_pools[i].capacity) {
            connection_pools[i].count++;
            pthread_mutex_unlock(&memory_lock);
            return connection_pools[i].connections + connection_pools[i].count - 1;
        }
    }
    pthread_mutex_unlock(&memory_lock);
    return NULL;
}

void free_memory_block(void* block) {
    if (block == NULL) return;
    int index = (int)((char*)block - (char*)connection_pools[0].connections) / sizeof(int);
    pthread_mutex_lock(&memory_lock);
    connection_pools[index / CONNECTION_POOL_SIZE].count--;
    total_connections -= 1;
    if (connection_pools[index / CONNECTION_POOL_SIZE].count <= 0) {
        free(connection_pools[index / CONNECTION_POOL_SIZE].connections);
        memset(&connection_pools[index / CONNECTION_POOL_SIZE], 0, sizeof(connection_pool));
    }
    pthread_mutex_unlock(&memory_lock);
}

