#define MAX_RNTIS 1024

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _LIST_NODE *next;
    sem_t rnti_sem; // Semaphore for RNTI locking
} LIST_NODE;

static LIST_NODE* head = NULL;
static int max_list_size = 0;
static int num_duplicates = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static sem_t list_sem = SEM_INITIALIZE(&head, 1);

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    LIST_NODE *new_node = malloc(sizeof(LIST_NODE));
    if (!new_node) return; // Handle out of memory error

    sem_init(&new_node->rnti_sem, 0, 1);
    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = new_node;
        max_list_size++;
    } else {
        LIST_NODE *temp = head;
        while (temp->next != NULL) temp = temp->next;
        temp->next = new_node;
        max_list_size++;
    }
    pthread_mutex_unlock(&list_mutex);
}

bool remove_from_list(uint32_t rnti) {
    bool found = false;
    LIST_NODE *temp = head;
    LIST_NODE *prev = NULL;

    sem_wait(&temp->rnti_sem);
    while (temp != NULL && temp->data.RNTI == rnti) {
        found = true;
        if (prev == NULL) {
            head = temp->next;
            free(temp);
            max_list_size--;
        } else {
            prev->next = temp->next;
            free(temp);
            max_list_size--;
        }
        if (!head) break;
        prev = temp;
        sem_wait(&temp->rnti_sem);
        temp = temp->next;
    }
    sem_post(&temp->rnti_sem);

    return found;
}

void list_cleanup() {
    LIST_NODE *temp = head;
    while (head != NULL) {
        LIST_NODE *next_node = head->next;
        free(head);
        head = next_node;
    }
    head = NULL;
    max_list_size = 0;
}

int main() {
    // Initialize and manage the list here, handling error cases for invalid sizes.
    // Implement multi-threaded access to the list using pthread_mutex_lock() and semaphores.
    // Test under stress and implement recovery mechanisms.
    // ...
}
