class NetworkConnection {
public:
    virtual ~NetworkConnection() {}
    virtual void connect(const string& host, int port) = 0;
    virtual int read(char* buffer, size_t length) = 0;
    virtual void write(const char* data, size_t length) = 0;
    virtual bool is_connected() const = 0;
};

class TcpConnection : public NetworkConnection {
public:
    explicit TcpConnection(b::io_service& io_service)
        : socket_(io_service), work_(io_service) {}

    void connect(const string& host, int port) override {
        tcp::endpoint endpoint(tcp::v4(), port);
        socket_.connect(boost::asio::ip::make_address(host), endpoint);
    }

    int read(char* buffer, size_t length) override {
        return socket_.read_some(b::buffer(buffer, length));
    }

    void write(const char* data, size_t length) override {
        socket_.write_some(b::buffer(data, length));
    }

    bool is_connected() const override { return socket_.is_open(); }

private:
    b::ip::tcp::socket socket_;
    b::io_service& io_service_;
    b::io_service::work work_;
};

