        unique_ptr<NetworkConnection> connection = make_unique<TcpConnection>(io_service);

        // Connect to the network source using the configuration settings
        connection->connect(config.host, config.port);

        // Start an ASIO thread pool for concurrent requests
        unsigned int num_threads = system_properties::get_num_processors();
        b::io_service thread_pool(b::io_service::work_guard<b::shared_mutex>());
        for (unsigned int i = 0; i < num_threads; ++i) {
            thread pool_thread(&boost::asio::io_service::run, &thread_pool);
        }

        // Create a DataAnalyzer instance and start processing the network data
        DataAnalyzer analyzer;
