// Custom dynamic array implementation
DynamicList* create_dynamic_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->capacity = 0;
    list->length = 0;
    list->elements = NULL;
    return list;
}

void resize_dynamic_list(DynamicList* list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) {
        perror("Failed to allocate memory for expanded array");
        free(list);
        return;
    }

    list->elements = new_elements;
    list->capacity = new_capacity;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list || !list->elements) return;
    free(list->elements);
    free(list);
}

// Function to manage a dynamically resizable list of NFAPI_CRC_INDICATION_PDU_T structures
void push_back(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->length == list->capacity) resize_dynamic_list(list, list->capacity * 2);
    list->elements[list->length] = element;
    list->length++;
}

