#include <semaphore.h>
#include <fcntl.h>
#include <sys/stat.h>

typedef enum { TEXT, IMAGE, SCRIPT } JobType;

struct Job {
    const char *input_path;
    JobType type;
    union {
        struct { int lines, words, chars; }, // for text processing
                img_data;                     // for image processing
        char *script;                         // for custom script execution
    } u;
};

sem_t semaphore;

void text_process(struct Job *job) {
    int fd = open(job->input_path, O_RDONLY);
    if (fd < 0) return;

    char buffer[4096];
    size_t chunk_size = 1024; // Adjust dynamically based on memory usage and CPU load

    job->u.lines = 0;
    job->u.words = 0;
    job->u.chars = 0;

    while (read(fd, buffer, sizeof(buffer)) > 0) {
        size_t i, length = strlen(buffer);
        for (i = 0; i < length; ++i)
            if (buffer[i] == '\n') ++job->u.lines;
        job->u.chars += length;
        for (i = 0; buffer[i]; ++i) {
            if (!isspace(buffer[i])) ++job->u.words;
        }
    }

    close(fd);
}

void image_process(struct Job *job) {
    // Implement image processing here, applying specified transformation or filter to job->img_data
}

void script_process(struct Job *job) {
    pid_t pid = fork();
    if (pid == 0) {
        execl("/bin/bash", "/bin/bash", "-c", job->script, NULL);
        exit(1);
    }

    int status;
    waitpid(pid, &status, 0);

    // Capture output and further process it as needed
}

void clean_up(struct Job *job) {
    if (job->type == TEXT && job->input_path) free(job->input_path);
    if (job->type == SCRIPT && job->script) free(job->script);
}

int main(int argc, char **argv) {
    if (argc < 2) return -1; // Invalid argument count

    int config_fd = open(argv[1], O_RDONLY);
    if (config_fd < 0) return -1; // Invalid configuration file path

    struct Job jobs[256];
    size_t job_count = 0;

    char buffer[4096];
    while (read(config_fd, buffer, sizeof(buffer)) > 0) {
        const char *start = buffer;
        const char *end = strchr(start, '\n');
        if (!end) break; // Reached end of file

        size_t job_len = end - start + 1;
        struct Job tmp = { .input_path = mmap(NULL, job_len, PROT_READ, MAP_PRIVATE, config_fd, start), };

        sscanf(start, "JOB_TYPE %c", &tmp.type);
        switch (tmp.type) {
            case 't': tmp.u.script = NULL; break;
            case 'i': tmp.u.lines = 0; tmp.u.words = 0; tmp.u.chars = 0; break;
            case 's': tmp.u.img_data = NULL; tmp.u.lines = 0; tmp.u.words = 0; tmp.script = start + strlen("JOB_TYPE s"); break;
        }

        if (tmp.type == SCRIPT) {
            char *script_start = tmp.script;
            while (*(tmp.script++)); // Find script end, ignoring whitespace
            ++tmp.script; // Move to next character after end of script
            tmp.script -= strlen(script_start); // Backtrack to start of script
        }

        jobs[job_count++] = tmp;
    }

    sem_init(&semaphore, 0, 4); // Initialize semaphore with 4 as initial value

    for (size_t i = 0; i < job_count; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, (void*(*)(void*)) process_job, &jobs[i]);
    }

    for (size_t i = 0; i < job_count; ++i) {
        pthread_join(thread, NULL);
    }

    sem_destroy(&seaphore); // Destroy the semaphore

    return 0;
}

void* process_job(void *arg) {
    struct Job *job = arg;

    sem_wait(&semaphore);

    if (job->type == TEXT) text_process(job);
    else if (job->type == IMAGE) image_process(job);
    else script_process(job);

    clean_up(job);

    sem_post(&semaphore);
    return NULL;
}
```

This code provides a basic structure for the given task. The main function reads a configuration file and creates an array of jobs. It initializes a semaphore with an initial value of 4, representing the maximum number of concurrent jobs. The `process_job` function is responsible for executing each job based on its type and handles resource cleanup after job execution. Concurrency is managed using pthreads and a semaphore to prevent race conditions during file access and resource sharing.

The text processing and image processing functions are placeholders, as they require specific implementations depending on the desired functionality. The script processing function executes an external script using fork() and exec().']

