NFAPI_CRC_INDICATION_PDU_T* create_PDU(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid array size. Aborting.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pduArray = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        fprintf(stderr, "Memory allocation failed. Aborting.\n");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pduArray[i].ueTag = (RX_UE_INFORMATION_TAG)i + 1; // Assign a unique UE tag for each PDU
        pduArray[i].rnti = i % 5 + 1;                    // Set RNTI based on the index modulo 5 and adding 1
        pduArray[i].crcIndication.CRCFLAG = (LOG_VERBOSE > 2) ? rand() % 2 : 0; // Randomly set CRCFLAG if logging level is high, or always set to 0 for less verbose logs
