        printf("\nUE Tag: %d\nRNTI: %d\nCRCFLAG: %d", pduArray[i].ueTag, pduArray[i].rnti, pduArray[i].crcIndication.CRCFLAG);
    }
#endif

    return pduArray;
}

void free_PDU(NFAPI_CRC_INDICATION_PDU_T *pduArray, size_t N) {
