#define MAX_FILES 1000
#define MAX_PATH_LENGTH 500
#define MAX_CHARACTERS 500000

size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t remaing = *(size_t*)userp;
    size_t total = remaing + size * nmemb;

    if (total > MAX_CHARACTERS) {
        fprintf(stderr, "Error: Exceeded maximum character limit.\n");
        return 0;
    }

    memcpy(((char*)userp) + remaing, contents, size * nmemb);
    *(size_t*)userp = total;

    return size * nmemb;
}

int read_config(const char *filename, char **paths, int *num_files) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error: Unable to open the configuration file.");
        return 1;
    }

    size_t num_allocated = 0;
    size_t current_length = 0;
    char *line = NULL;
    ssize_t len;
    int line_count = 0;

    while ((len = getline(&line, &current_length, file)) != -1) {
        if (++line_count > MAX_FILES || current_length >= MAX_PATH_LENGTH) {
            free(line);
            fprintf(stderr, "Error: Invalid configuration format.\n");
            fclose(file);
            return 1;
        }

        if (num_allocated == line_count) {
            paths = realloc(paths, sizeof(char*) * (num_allocated * 2));
            if (!paths) {
                free(line);
                fclose(file);
                perror("Error: Failed to allocate memory.");
                return 1;
            }
            num_allocated *= 2;
        }

        paths[line_count - 1] = line;
    }

    if (feof(file)) {
        free(line);
        fclose(file);
    } else {
        perror("Error: Unexpected end of file.");
        return 1;
    }

    *num_files = line_count;

    return 0;
}

static size_t write_metadata(void *contents, size_t size, size_t nmemb, void *userp) {
    // Implement API call to fetch metadata here.
    // For simplicity, we'll just ignore the contents and continue processing.
    return size * nmemb;
}

int process_files(char **paths, int num_files) {
    CURL *curl;
    struct curl_slist *header = NULL;
    CURLcode res;
    int executable_count = 0;

    for (int i = 0; i < num_files; ++i) {
        if (!paths[i]) continue;

        // Initialize the curl session.
        curl = curl_easy_init();
        if (!curl) {
            fprintf(stderr, "Error: Failed to initialize curl.\n");
            return 1;
        }

        header = curl_slist_append(header, ":");
        // Add other headers as needed.

        // Set URL and callback functions for the API call.
        res = curl_easy_setopt(curl, CURLOPT_URL, paths[i]);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: Failed to set URL.\n");
            curl_easy_cleanup(curl);
            continue;
        }

        res = curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_metadata);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: Failed to set write callback.\n");
            curl_easy_cleanup(curl);
            continue;
        }

        // Perform the API call.
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: Failed to fetch metadata.\n");
        }

        // Check for executable files.
        struct stat file_info;
        if (stat(paths[i], &file_info) == 0 && S_ISREG(file_info.st_mode)) {
            if ((file_info.st_mode & S_IXUSR) || (file_info.st_mode & S_IXGRP) || (file_info.st_mode & S_IXOTH)) {
                ++executable_count;
            }
        }

        // Clean up and move to the next file.
        curl_easy_cleanup(curl);
        curl_slist_free_all(header);
    }

    printf("Executable files count: %d\n", executable_count);

    for (int i = 0; i < num_files; ++i) {
        free(paths[i]);
    }
    free(paths);

    curl_slist_free_all(header);

    return 0;
}
