#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void handleConfigError(const char* msg) {
    fprintf(stderr, "Configuration error: %s\n", msg);
    exit(1);
}

int getLineCount(FILE *file) {
    int lineCount = 0;
    char c;
    while ((c = fgetc(file)) != EOF) {
        if (c == '\n')
            lineCount++;
    }
    return --lineCount;
}

NFAPI_CRC_INDICATION_PDU_T* createPDUs(FILE *config, int *pN) {
    int N = 0;
    char rntiRange[2][11];
    if (fscanf(config, "%d", &N) != 1 || N <= 0)
        handleConfigError("Invalid number of elements");
    fgets(rntiRange[0], sizeof(rntiRange[0]), config);
    sscanf(rntiRange[0], "%s %s", rntiRange[0], rntiRange[1]);
    if (getLineCount(config) != 2 || N + 3 != getLineCount(config))
        handleConfigError("Malformed configuration file");

    int minRNTI = atoi(rntiRange[0]);
    int maxRNTI = atoi(rntiRange[1]);
    if (maxRNTI < minRNTI)
        handleConfigError("Invalid RNTI range");

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!pdus)
        handleConfigError("Out of memory");

    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = rand() % (maxRNTI - minRNTI + 1) + minRNTI;
        pdus[i].CRC_INDICATION_REL8_TAG = i + 1;
        pdus[i].CRCFLAG = rand() % 2 == 0;
    }
    *pN = N;
    return pdus;
}
