void destroy_list(list_node **head) {
    if (!*head) return;

    list_node *current = *head, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
    *head = NULL;
}

list_node* create_new_node(NFAPI_CRC_INDICATION_PDU_T data) {
    list_node *new_node = (list_node*) malloc(sizeof(list_node));
    if (!new_node) return NULL;

    new_node->data = data;
    pthread_mutex_init(&(new_node->mutex), NULL);
    new_node->next = NULL;
    return new_node;
}

void insert_node(list_node **head, list_node *new_node) {
    pthread_mutex_lock(&head_lock);

    if (!*head || (*head)->rnti != new_node->rnti) {
        new_node->next = *head;
        *head = new_node;
    } else {
        list_node *current = *head;
        while (current->next && current->next->rnti == new_node->rnti) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    if (pthread_mutex_unlock(&head_lock)) {
        perror("pthread_mutex_unlock");
        destroy_list(head);
    }
}

void remove_least_recently_added(list_node **head) {
    if (!*head) return;

    list_node *current = *head, *previous = NULL;
    time_t now = time(NULL);
    list_node *temp;

    pthread_mutex_lock(&head_lock);
    while (current->next && current->next->rnti != current->rnti) { // Move to the least recently added node.
        previous = current;
        current = current->next;
    }

    if (!current->next) { // If this is the last entry, remove it and set head to NULL.
        temp = current;
        *head = NULL;
    } else {               // Otherwise, remove the least recently added node and update head.
        temp = current->next;
        previous->next = temp->next;
    }

    free(current);
    pthread_mutex_unlock(&head_lock);
}

list_node* get_node_by_rnti(uint32_t rnti) {
    list_node *current = head;

    while (current != NULL && current->rnti != rnti) {
        current = current->next;
    }

    return current;
}

void manage_data(NFAPI_CRC_INDICATION_PDU_T data) {
    if (head == NULL || get_node_by_rnti(data.rnti) == NULL) { // If the list is empty or the RNTI doesn't exist, create a new node.
        list_node *new_node = create_new_data(data);
        if (!new_node) return;
        insert_node(&head, new_node);
    } else { // If the RNTI already exists, overwrite its data with the new one.
        list_node *existing_node = get_node_by_rnti(data.rnti);
        existing_node->data = data;
    }

    if (head->next && head->next->rnti == data.rnti) { // If the list exceeds the maximum size, remove the least recently added entry.
        remove_least_recently_added(&head);
    }
