typedef struct _node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _node *prev, *next;
    pthread_mutex_t node_lock;
} node_t;

typedef struct {
    size_t size;
    node_t *head;
    node_t *tail;
    size_t max_size;
    pthread_mutex_t list_lock;
} dl_list_t;

void init_dl_list(dl_list_t* list, size_t max_size) {
    list->max_size = max_size;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->list_lock, NULL);
}

void destroy_dl_list(dl_list_t* list) {
    node_t *cur, *next;
    pthread_mutex_destroy(&list->list_lock);
    pthread_mutex_init(&list->node_lock, NULL);

    cur = list->head;
    while (cur != NULL) {
        next = cur->next;
        free(cur);
        cur = next;
    }
}

static inline bool is_empty(const dl_list_t* list) {
    return list->size == 0;
}

static inline node_t* get_node(dl_list_t* list) {
    node_t *new_node = (node_t *) malloc(sizeof(node_t));
    if (!new_node) return NULL;

    pthread_mutex_init(&new_node->node_lock, NULL);
    new_node->prev = NULL;
    new_node->next = NULL;

    return new_node;
}

void add_to_list(dl_list_t* list, NFAPI_CRC_INDICATION_PDU_T data) {
    node_t *new_node, *cur;

    pthread_mutex_lock(&list->list_lock);

    if (is_empty(list)) {
        list->head = new_node = get_node();
        if (!new_node) {
            pthread_mutex_unlock(&list->list_lock);
            return;
        }
        list->head->data = data;
        list->tail = new_node;
    } else {
        cur = list->tail;
        new_node = get_node();
        if (!new_node) {
            pthread_mutex_unlock(&list->list_lock);
            return;
        }
        new_node->data = data;
        cur->next = new_node;
        new_node->prev = cur;
        list->tail = new_node;
    }

    if (++list->size > list->max_size) {
        node_t *tmp = list->head;
        pthread_mutex_lock(&tmp->node_lock);
        while (list->size > list->max_size && tmp != NULL) {
            pthread_mutex_unlock(&tmp->node_lock);
            tmp = tmp->next;
            if (tmp == NULL) break;
            pthread_mutex_lock(&tmp->node_lock);
        }
        if (tmp != NULL) {
            list_remove(list, tmp);
            pthread_mutex_unlock(&tmp->node_lock);
        }
    }

    pthread_mutex_unlock(&list->list_lock);
}

void list_remove(dl_list_t* list, node_t *node) {
    if (node == list->head) {
        list->head = node->next;
    } else if (node == list->tail) {
        list->tail = node->prev;
        list->tail->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    free(node);
    --list->size;
}
