    if (N == 0 || max_size < sizeof(NFAPI_CRC_INDICATION_PDU_T))
        return NULL;

    size_t allocated_bytes = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (allocated_bytes > max_size) {
