        N = max_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(allocated_bytes);

