```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
    pthread_mutex_t node_mutex;
} Node_t;

Node_t* head = NULL;
Node_t* tail = NULL;
size_t max_size = 0;
pthread_mutex_t list_mutex;
pthread_cond_t not_full_cond;
pthread_cond_t not_empty_cond;

void init() {
    pthread_mutex_init(&list_mutex, NULL);
    pthread_cond_init(&not_full_cond, NULL);
    pthread_cond_init(&not_empty_cond, NULL);
}

void cleanup() {
    Node_t* current = head;
    while (head) {
        head = head->next;
        free(current);
        current = head;
    }
    pthread_mutex_destroy(&list_mutex);
    pthread_cond_destroy(&not_full_cond);
    pthread_cond_destroy(&not_empty_cond);
}

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    // Insert the new node into the list
    Node_t* newNode = (Node_t*)malloc(sizeof(Node_t));
    if (!newNode) return;

    pthread_mutex_init(&newNode->node_mutex, NULL);
    newNode->data = data;
    newNode->next = NULL;

    // Acquire the list mutex to ensure thread safety
    pthread_mutex_lock(&list_mutex);

    if (head == NULL) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }

    // If the list exceeds the maximum size, remove the least recently added entry
    if (tail >= &head[max_size]) {
        Node_t* temp = head;
        while (temp->next && temp != tail) {
            temp = temp->next;
        }
        free(temp->next);
        if (temp == tail) {
            tail = temp;
        }
    }

    pthread_mutex_unlock(&list_mutex);

    // Signal that the list is not empty
    pthread_cond_signal(&not_empty_cond);
}

Node_t* find(uint32_t tag) {
    // Find a node with the given RX_UE_INFORMATION_TAG in the list
    Node_t* current = head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void update(uint32_t tag, NFAPI_CRC_INDICATION_PDU_T newData) {
    Node_t* node = find(tag);
    if (!node) return;

    pthread_mutex_lock(&node->node_mutex);

    // Update the node's data without changing its RNTI or CRCFLAG values
    memcpy(&node->data, &newData, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&node->node_mutex);
}

void merge() {
    // Merge adjacent nodes with identical RX_UE_INFORMATION_TAG values
    Node_t* current = head;
    while (current && current->next) {
        if (current->data.RX_UE_INFORMATION_TAG == current->next->data.RX_UE_INFORMATION_TAG) {
            // Combine adjacent nodes with identical RX_UE_INFORMATION_TAG values
            NFAPI_CRC_INDICATION_PDU_T mergedData = current->data;
            free(current->next);
            current->next = current->next->next;

            pthread_mutex_lock(&current->node_mutex);
            memcpy(&current->data, &mergedData, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&current->node_mutex);
        } else {
            current = current->next;
        }
    }
}
```

