struct memory_pool {
    void* buffer;
    size_t capacity;
    size_t allocated;
};

void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->buffer = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->capacity = capacity;
    pool->allocated = 0;
}

void* pool_allocate(struct memory_pool* pool, size_t size) {
    if (pool->allocated + size > pool->capacity)
        return NULL; // Out of memory
    void* result = (char*)pool->buffer + pool->allocated;
    pool->allocated += size;
    return result;
}

void pool_free(struct memory_pool* pool, void* ptr) {
    if (!ptr)
        return;

    char* p = (char*)ptr - pool->allocated;
    pool->allocated -= ((char*)ptr - (char*)pool->buffer);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t count) {
    static struct memory_pool pdu_pool = {0};
    init_memory_pool(&pdu_pool, count);
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        free(pdu_pool.buffer);
        return NULL; // Out of memory
    }

    for (size_t i = 0; i < count; ++i) {
        void* pdu_ptr = pool_allocate(&pdu_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_ptr) { // Out of memory in the pool
            free(pdus);
            return NULL;
        }
        pdus[i] = *(NFAPI_CRC_INDICATION_PDU_T*)pdu_ptr;
    }

    return pdus;
}

