#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_UE_ID 1024
#define LOG_BUFFER_SIZE 4096

sem_t sem_ue_id_map, sem_log;
int ue_id_count = 0;
int* processed_ue_ids = NULL;
int* duplicates = NULL;
int num_duplicates = 0;

void log(const char* message) {
    char log_buffer[LOG_BUFFER_SIZE];
    snprintf(log_buffer, sizeof(log_buffer), "%s", message);
    write(2, log_buffer, strlen(log_buffer));
}

int get_next_ue_id() {
    if (ue_id_count >= MAX_UE_ID) return -1; // out of range
    int id = ue_id_count++;
    processed_ue_ids[id] = 1;
    return id;
}

bool is_duplicate(int ue_id, NFAPI_CRC_INDICATION_PDU_T** pdu) {
    for (int i = 0; i < ue_id_count; ++i) {
        if (processed_ue_ids[i] && processed_ue_ids[i] == processed_ue_ids[ue_id]) {
            duplicates[num_duplicates++] = i;
            return true;
        }
    }
    return false;
}

void* allocate_pdus(int ue_id, void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**) arg;
    int idx = ue_id - 1; // array index starts at 0

    sem_wait(&sem_ue_id_map);
    if (processed_ue_ids[idx] || idx >= MAX_UE_ID) { // out of range or already processed
        sem_post(&sem_ue_id_map);
        return NULL;
    }
    processed_ue_ids[idx] = 1;
    sem_post(&sem_ue_id_map);

    pdus[idx] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus[idx]) {
        log("Memory allocation error for PDU");
        return NULL;
    }

    pdus[idx]->tag = RX_UE_INFORMATION_TAG_FROM_ID(idx + 1);
    pdus[idx]->rnti = RNTI_FROM_ID(idx + 1);
    pdus[idx]->crc_indication.crcflag = (rand() % 2) ? 0 : 1; // randomly set CRCFLAG

    if (is_duplicate(idx + 1, pdus)) {
        log("Duplicate UE ID encountered:");
        log(pdus[idx]->tag);
    }

    return pdus[idx];
}

NFAPI_CRC_INDICATION_PDU_T** create_pdus(int N) {
    if (N <= 0) {
        log("Invalid input: N must be greater than zero");
        return NULL;
    }

    int* ids = calloc(N, sizeof(int));
    if (!ids) {
        log("Memory allocation error for UE IDs array");
        return NULL;
    }

    duplicates = calloc(ue_id_count, sizeof(int));
    processed_ue_ids = calloc(MAX_UE_ID, sizeof(int));
    if (!duplicates || !processed_ue_ids) {
        log("Memory allocation error for arrays");
        free(ids);
        return NULL;
    }

    pthread_t threads[N];
    NFAPI_CRC_INDICATION_PDU_T** pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    sem_init(&sem_ue_id_map, 0, ue_id_count);
    sem_init(&sem_log, 0, 1);

    for (int i = 0; i < N; ++i) {
        int ret = pthread_create(&threads[i], NULL, allocate_pdus, &pdus[i]);
        if (ret != 0) {
            log("Error creating thread:");
            perror("");
            cleanup(pdus, threads, ids);
            return NULL;
        }
    }

    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], (void**) &pdus[i]);
        if (!pdus[i]) {
            cleanup(pdus, threads, ids);
            return NULL;
        }
    }

    log("Total unique UEs processed:");
    log(ue_id_count - num_duplicates);
    log("Number of duplicate UEs encountered:");
    log(num_duplicates);

    free(ids);
    free(duplicates);
    sem_destroy(&sem_ue_id_map);
    sem_destroy(&sem_log);

    return pdus;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T** pdus, pthread_t* threads, int* ids) {
    for (int i = 0; i < ue_id_count; ++i) {
        free(pdus[i]);
    }
    free(pdus);

    for (int i = 0; i < MAX_UE_ID; ++i) {
        if (processed_ue_ids[i]) free(ids[i]);
    }
    free(ids);
    free(processed_ue_ids);
    free(duplicates);
}
```

