        rnti[i] = characterSet[rand() % csLength];
    }
    return rnti;
}

void generateNfarandomCRCIndications(int N, size_t rntiLength, char* rntiChars) {
    if (N < 1 || rntiLength == 0 || strlen(rntiChars) < 4 + rntiLength) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    hashCache.count = 0;
    pthread_mutex_init(&hashMutex, NULL);
    sem_init(&cacheSemaphore, 0, HASH_CACHE_SIZE);

    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * N);
    for (int i = 0; i < N; ++i) {
        char* rntiArg = malloc(sizeof(char)*4 + rntiLength + sizeof(size_t)*2); // 3 elements: length, character set length, and character set
        *(size_t*)(rntiArg + sizeof(char)*0) = rntiLength;
        *(size_t*)(rntiArg + sizeof(char)*3) = strlen(rntiChars);
        memcpy(rntiArg + sizeof(char)*4, rntiChars, strlen(rntiChars));

        pthread_create(&threads[i], NULL, generateRNTI, rntiArg);
    }

    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], (void**)&indications[i].rnti);

        indications[i].rxUeInformationTag = rand() % UINT16_MAX;
        indications[i].crcIndicationRel8Tag.crcFlag = rand() % 2 == 0 ? 1 : 0; // Randomly set CRCFLAG to 1 or 0
        hashFunction(indications[i].rnti, indications[i].rntiHash);
    }

    free(threads);
}
