    int log_retention_days;
} Config;

// Thread-safe cache for frequently accessed log templates
struct TemplateCache {
    char** templates;
    size_t template_count;
    pthread_mutex_t mutex;
};

// Function to initialize the TemplateCache
void initTemplateCache(struct TemplateCache* cache, const char** templates, size_t count) {
    cache->templates = malloc(sizeof(char*) * count);
    cache->template_count = count;
    cache->mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < count; ++i)
        cache->templates[i] = malloc(strlen(templates[i]) + 1);
    memcpy(cache->templates, templates, sizeof(char*) * count);
}

// Function to persist event logs to the file system
void generateAndPersistEventLogs(int N, int start_event_id, int end_event_id, const char** severity_levels, Config* config, struct TemplateCache* cache) {
    srandom(time(NULL));

    FILE* log_file = fopen("event_logs.txt", "a"); // Open or create the log file in append mode
    if (!log_file)
        perror("Error opening log file"), exit(1);

    pthread_mutex_t template_mutex = cache->mutex;
    for (int i = 0; i < N; ++i) {
        // Generate timestamp, event ID, severity level, and message
        time_t rawtime;
        struct tm* timeinfo;
        char timestamp[26];
        rawtime = time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), config->format == "machine-readable" ? "%Y-%m-%d %H:%M:%S" : "%F %T", timeinfo);
        int event_id = random() % (end_event_id - start_event_id + 1) + start_event_id;
        const char* severity_level = severity_levels[random() % sizeof(severity_levels) / sizeof(severity_levels[0])];
        const char* message_template = getTemplateFromCache(cache, event_id);

        // Add additional metadata such as user IDs and system information (not shown in this example)

        fprintf(log_file, "%s %d %s\n%s\n", timestamp, event_id, severity_level, message_template);
    }

    fclose(log_file); // Close the log file when done
}

// Function to retrieve a template from the cache
const char* getTemplateFromCache(struct TemplateCache* cache, int id) {
    pthread_mutex_lock(&cache->mutex);
    const char* template = nullptr;
    for (size_t i = 0; i < cache->template_count; ++i) {
        if (sscanf(cache->templates[i], "ID:%d", &id) == 1) {
            template = cache->templates[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);

    return template;
}

// Function to implement log file rotation strategy
void rotateLogFiles() {
    const int log_retention_days = getenv("LOG_RETENTION_DAYS") ? atoi(getenv("LOG_RETENTION_DAYS")) : 7;
    time_t current_time = time(NULL);
    struct dirent** entries;
    int nm = scandir(".", &entries, nullptr, alphasort);
    if (nm < 0)
        perror("Error reading directory"), exit(1);
    for (int i = 0; i < nm; ++i) {
        struct stat file_stat;
        char* path = malloc(strlen(entries[i]->d_name) + 12); // "event_logs.XXXXXX"
        strcpy(path, entries[i]->d_name);
        sprintf(&path[strlen(path) - 6], ".%06o", (unsigned int)getpid());

        if (stat(path, &file_stat) < 0)
            perror("Error stat'ing file"), exit(1);

        if (file_stat.st_mtime + (log_retention_days * 24 * 60 * 60) < current_time && strcmp(entries[i]->d_name, "event_logs") != 0) {
            unlink(path);
            printf("Removed log file: %s\n", path);
        }
    }
    free(path);
    free(entries);
}
