struct whitelist {
    uint32_t rnti;
    struct whitelist *next;
};

struct RNTI_VALIDATION {
    sem_t rnti_mutex;
    bool allowed[UINT32_MAX];
    struct whitelist *whitelist_head;
};

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    time_t creation_timestamp;
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_pdu(struct RNTI_VALIDATION *validation) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pthread_mutex_init(&(pdu->RX_UE_INFORMATION_TAG), NULL);
    pthread_mutex_init(&(pdu->CRC_INDICATION_REL8_TAG), NULL);
    sem_init(&(pdu->RNTI_mutex), 1, 1);

    pdu->creation_timestamp = time(NULL);
    pdu->RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
    pdu->CRC_INDICATION_REL8_TAG = rand() % UINT16_MAX;
    pdu->CRCFLAG = (bool)(rand() % 2);

    sem_wait(&(validation->rnti_mutex));
    if (!validation->allowed[pdu->RNTI]) {
        free(pdu);
        sem_post(&(validation->rnti_mutex));
        return NULL;
    }
    validation->whitelist_head = whitelist_append(validation->whitelist_head, pdu->RNTI);
    sem_post(&(validation->rnti_mutex));

    return pdu;
}

struct whitelist* whitelist_append(struct whitelist *head, uint32_t rnti) {
    if (!head) {
        struct whitelist *new_node = (struct whitelist*) malloc(sizeof(struct whitelist));
        new_node->rnti = rnti;
        new_node->next = NULL;
        return new_node;
    }

    if (head->rnti > rnti) {
        struct whitelist *new_node = (struct whitelist*) malloc(sizeof(struct whitelist));
        new_node->rnti = rnti;
        new_node->next = head;
        return new_node;
    }

    struct whitelist *current = head;
    while (current->next && current->next->rnti < rnti) {
        current = current->next;
    }

    struct whitelist *new_node = (struct whitelist*) malloc(sizeof(struct whitelist));
    new_node->rnti = rnti;
    new_node->next = current->next;
    current->next = new_node;

    return head;
}
```
