    if (json_object_get_type(threshold_obj) != JSON_TYPE_NUMBER || json_object_get_int(threshold_obj) < ALERT_THRESHOLD) {
        fprintf(stderr, "Invalid 'threshold' parameter: must be greater than or equal to %zu\n", ALERT_THRESHOLD);
        exit(1);
    }

    // Implement strategies for reusing memory blocks, performance optimization, load testing, etc. (Not provided)
}
