void initLtePhyResults(struct LtePhyResults* results) {
    results->capacity = 10;
    results->size = 0;
    results->data = malloc(results->capacity * sizeof(LtePhyResult));
}

void resizeLtePhyResults(struct LtePhyResults* results) {
    if (results->size == results->capacity) {
        results->capacity *= 2;
        results->data = realloc(results->data, results->capacity * sizeof(LtePhyResult));
    }
}

void addMeasurement(struct LtePhyResults* results, const LtePhyResult* measurement) {
    if (results->size == results->capacity) {
        resizeLtePhyResults(results);
    }

    memcpy(&results->data[results->size], measurement, sizeof(LtePhyResult));
    results->size++;
}

void updateMeasurement(struct LtePhyResults* results, int cell_id, const LtePhyResult* measurement) {
    for (size_t i = 0; i < results->size; ++i) {
        if (results->data[i].cell_id == cell_id) {
            memcpy(&results->data[i], measurement, sizeof(LtePhyResult));
            return;
        }
    }
}

