```cpp
#include <iostream>
#include <boost/circular_buffer.hpp>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <exception>

// Define Pokemon structure and weaknesses mapping
struct Pokemon {
    std::string name;
    std::string type;
    int health;
};

std::unordered_map<std::string, std::vector<std::string>> weaknesses = {
    {"water", {"grass", "electric"}},
    {"fire", {"water", "grass"} },
    {"grass", {"water", "fire"}}
};

// Define semaphore and queue structures
boost::circular_buffer<Pokemon> pokemonQueue(10000);
std::mutex mtx;
std::condition_variable cv;
int capacity = pokemonQueue.capacity();
int count = 0;

void produce(const std::string& name, const std::string& type) {
    Pokemon p{name, type, 100};
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [this]{ return count < capacity; });
    pokemonQueue.push_back(p);
    ++count;
    lock.unlock();
}

void consume() {
    Pokemon p = pokemonQueue.front();
    std::unique_lock<std::mutex> lock(mtx);
    cv.notify_one();
    --count;
    lock.unlock();

    std::cout << "Processing Pokemon: " << p.name << ", type: " << p.type << "\n";
    for (const auto& w : weaknesses[p.type]) {
        std::cout << "Weakness: " << w << "\n";
    }
}

int main() {
    std::vector<std::thread> producers, consumers;

    // Create producer and consumer threads
    for (int i = 0; i < 10; ++i) {
        producers.emplace_back(produce, "Pokemon" + std::to_string(i), "water");
        consumers.emplace_back(consume);
    }

    for (auto& t : producers) t.join();
    for (auto& t : consumers) t.join();

    return 0;
}
```

