#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    if (initial_capacity == 0) {
        return NULL;
    }

    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void dynamic_array_destroy(DynamicArray* array) {
    if (!array) {
        return;
    }

    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

static void retry_function(void* arg) {
    const size_t MAX_RETRIES = 10;
    const uint64_t BACKOFF_BASE = 100; // microseconds
    const uint64_t BACKOFF_FACTOR = 2;
    size_t retries = 0;

    while (true) {
        if (dynamic_array_push(arg, &retries)) {
            return;
        }

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to allocate memory after %zu retries.\n", MAX_RETRIES);
            return;
        }

        usleep(BACKOFF_BASE * pow(BACKOFF_FACTOR, retries));
        retries++;
    }
}

bool dynamic_array_push(DynamicArray* array, size_t* retries) {
    if (array->length >= array->capacity && array->capacity < 1000) {
        array->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(array->data, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            // Retry logic with exponential backoff
            pthread_t thread;
            pthread_create(&thread, NULL, retry_function, array);
            return false;
        }
        array->data = temp;
    }

    pthread_mutex_lock(&array->mutex);

    // Set random CRCFLAG and initialize new element with valid tags
    NFAPI_CRC_INDICATION_PDU_T* new_element = &array->data[array->length];
    new_element->RX_UE_INFORMATION_TAG = rand();
    new_element->RNTI = rand() % 0xFFFF;
    new_element->CRC_INDICATION_REL8_TAG = rand();
    new_element->CRCFLAG = rand() % 2 == 0;

    array->length++;

    pthread_mutex_unlock(&array->mutex);

    return true;
}
```
