LTE_Ue测量数据_t* get_or_fetch(struct Cache *cache, uint32_t rnti) {
    struct CacheNode *current = cache->head;

    sem_wait(&cache->not_empty);
    while (current != NULL && current->rnti != rnti) {
        current = current->next;
    }

    if (current != NULL) {
        if (time(NULL) > current->expiry_time) {
            // Evict the cache entry and fetch new data
            struct CacheNode *to_delete = current;
            current = current->next;
            free(to_delete);

            // Fetch new data here, using APIs or local files
            // ...
        } else {
            sem_post(&cache->not_empty);
            return &current->data;
        }
    }

    // Cache miss, create a new entry and fetch new data
    struct CacheNode *new_entry = malloc(sizeof(struct CacheNode));
    if (new_entry == NULL) {
        perror("malloc failed");
        return NULL;
    }
    new_entry->rnti = rnti;
    new_entry->next = cache->head;
    new_entry->expiry_time = time(NULL) + 60 * 10; // Expire in 10 minutes
    cache->head = new_entry;
    if (++cache->capacity == cache->head) {
        sem_post(&cache->not_empty);
    }

    // Fetch new data here, using APIs or local files
    // ...

    return &new_entry->data;
}

