typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

Node* create_node() {
    Node *new_node = (Node *) malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    new_node->data.ue_information = get_ue_info();
    if (!new_node->data.ue_information.isValid()) {
        fprintf(stderr, "Error: Invalid RX_UE_INFORMATION_TAG\n");
        free(new_node);
        return NULL;
    }

    new_node->rnti = get_rnti();
    if (new_node->rnti <= 0) {
        fprintf(stderr, "Error: Invalid RNTI\n");
        free(new_node);
        return NULL;
    }

    new_node->data.crc_indication.setCRCFlag((rand() % 2));

    new_node->next = NULL;
    return new_node;
}

Node** create_array(unsigned int size) {
    if (size == 0) {
        fprintf(stderr, "Error: Size cannot be zero\n");
        return NULL;
    }

    Node **array = (Node **) malloc(size * sizeof(Node*));
    if (!array) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    for (unsigned int i = 0; i < size; ++i) {
        array[i] = create_node();
        if (!array[i]) {
            // Free all previously allocated nodes and return NULL to indicate failure
            for (unsigned int j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }

    return array;
}

void cleanup(Node **array, unsigned int size) {
    for (unsigned int i = 0; i < size; ++i) {
        free(array[i]);
    }
    free(array);
}

// Thread-safe version of create_array() using a memory pool
pthread_mutex_t mutex;
Node *memory_pool = NULL;

void* thread_worker(void *arg) {
    while (true) {
        pthread_mutex_lock(&mutex);

        if (!memory_pool) {
            memory_pool = create_node();
        }

        Node *tmp = memory_pool;
        memory_pool = tmp->next;
        pthread_mutex_unlock(&mutex);

        // Use the node and then return it to the pool when done
        ...
    }
}

Node** create_array_threadsafe(unsigned int size) {
    if (size == 0) {
        fprintf(stderr, "Error: Size cannot be zero\n");
        return NULL;
    }

    Node **array = (Node **) malloc(size * sizeof(Node*));
    if (!array) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    pthread_mutex_init(&mutex, NULL);
    pthread_t threads[size];

    for (unsigned int i = 0; i < size; ++i) {
        array[i] = create_node();
        if (!array[i]) {
            // Free all previously allocated nodes and return NULL to indicate failure
            for (unsigned int j = 0; j < i; ++j) {
                free(array[j]);
            }
            cleanup_threads(size);
            free(array);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
    }

    for (unsigned int i = 0; i < size; ++i) {
        pthread_create(&threads[i], NULL, thread_worker, NULL);
    }

    // Wait for all threads to finish and clean up resources
    for (unsigned int i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }
    cleanup_threads(size);

    return array;
}

void cleanup_threads(unsigned int size) {
    pthread_mutex_lock(&mutex);
    for (unsigned int i = 0; i < size; ++i) {
        Node *tmp = memory_pool;
        if (tmp == array[i]) {
            memory_pool = tmp->next;
            free(array[i]);
        }
    }
    pthread_mutex_unlock(&mutex);

    pthread_mutex_destroy(&mutex);
}
