        private readonly IDictionary<string, object> _parameterCache = new Dictionary<string, object>();
        private readonly object _lockObject = new object();
        private readonly int _maxBatchSize;
        private readonly TimeSpan _retryInterval;

        public QueryExecutor(IDbConnection connection, int maxBatchSize = 10, TimeSpan retryInterval = TimeSpan.FromSeconds(5))
        {
            _connection = connection;
            _maxBatchSize = maxBatchSize;
            _retryInterval = retryInterval;
        }

        public async Task<IDataReader> ExecuteQueryAsync(string commandText, IEnumerable<KeyValuePair<string, object>> parameterList)
        {
            if (string.IsNullOrEmpty(commandText))
                throw new ArgumentException("Command text cannot be empty.");

            if (!parameterList?.Any() ?? false)
                throw new ArgumentException("Parameter list must contain at least one entry.");

            commandText = SanitizeSqlInjection(commandText);

            var parameters = parameterList.ToDictionary(k => k.Key, k => GetCachedValueOrDefault(k.Value));
            using (var transaction = _connection.BeginTransaction())
            {
                try
                {
                    IDataReader reader;
                    if (_maxBatchSize > 1)
                        reader = ExecuteBatchQueryAsync(commandText, parameters, transaction).Result;
                    else
                        reader = await ExecuteSingleQueryAsync(commandText, parameters, transaction);

                    return reader;
                }
                catch (Exception ex)
                {
                    LogError(ex);
                    if (!ShouldRetry(ex))
                        throw;

                    await Task.Delay(_retryInterval);
                    return ExecuteQueryAsync(commandText, parameters).Result;
                }
            }
        }

        private async Task<IDataReader> ExecuteSingleQueryAsync(string commandText, IDictionary<string, object> parameters, IDbTransaction transaction)
        {
            var sql = BuildOptimizedQuery(commandText);
            return await _connection.ExecuteReaderAsync(sql, parameters, transaction);
        }

        private async Task<IDataReader> ExecuteBatchQueryAsync(string commandText, IDictionary<string, object> parameters, IDbTransaction transaction)
        {
            var sql = BuildOptimizedQuery(commandText);
            var batchSize = 0;
            var batchParameters = new Dictionary<string, object>();

            using (var reader = await _connection.ExecuteReaderAsync(sql, null, transaction))
            {
                while (await reader.ReadAsync())
                {
                    if (++batchSize == _maxBatchSize)
                    {
                        batchParameters.Clear();
                        await CommitBatchAsync(batchParameters, transaction);
                        batchSize = 0;
                    }

                    AddOrUpdateParameterCache(reader["ParameterName"], reader["ParameterValue"]);
                }
            }

            if (batchSize > 0)
                await CommitBatchAsync(batchParameters, transaction);

            return null;
        }

        private void AddOrUpdateParameterCache(string parameterName, object parameterValue)
        {
            _parameterCache[parameterName] = parameterValue;
        }

        private object GetCachedValueOrDefault(object value)
        {
            if (_parameterCache.TryGetValue(value?.ToString(), out var cachedValue))
                return cachedValue;

            return value;
        }

        // Implement caching, query optimization, transaction management, nested queries support, etc., as needed.
    }
}
