#include <iostream>
#include <vector>
#include <chrono>
#include <random>
#include <cstdint>
#include <time.h>
#include <NFAPI/NFAPI_CRC_INDICATION_PDU_T.h> // Include the required third-party library header

void generateStructures(std::vector<NFAPI_CRC_INDICATION_PDU_T>& list, uint32_t maxSize, uint32_t maxRnti) {
    std::mt19937 rng(time(0)); // Seed random number generator with current time
    std::uniform_int_distribution<uint32_t> distRxUeInformationTag(1, 127); // Valid range for RX_UE_INFORMATION_TAG
    std::uniform_int_distribution<uint32_t> distRnti(1, maxRnti); // Valid range for RNTI
    std::uniform_int_distribution<bool> distCrcFlag; distCrcFlag.reset(); std::fill(distCrcFlag.base(), distCrcFlag.base() + 2, true); // Probability of CRCFLAG=true is 99%

    auto start = std::chrono::high_resolution_clock::now();

    list.resize(0); // Clear the vector if needed

    uint64_t count = 0;
    while (count < maxSize && !list.empty()) {
        NFAPI_CRC_INDICATION_PDU_T structure;
        structure.rx_ue_information_tag = distRxUeInformationTag(rng);
        structure.rnti = distRnti(rng);
        if (list.empty() || list.back().rnti != structure.rnti) { // Ensure no two consecutive structures have the same RNTI
            structure.crc_indication_rel8_tag.crcflag = distCrcFlag(rng);
            list.push_back(structure);
            count++;
