typedef struct MemoryPool {
    void *memory;
    size_t capacity;
    size_t used;
    struct MemoryPool *next;
} MemoryPool;

MemoryPool *memory_pool = NULL;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pool() {
    if (memory_pool) return;
    memory_pool = malloc(sizeof(MemoryPool));
    memory_pool->capacity = 0;
    memory_pool->used = 0;
    memory_pool->next = NULL;
}

void *get_from_pool() {
    pthread_mutex_lock(&pool_mutex);
    if (memory_pool->used < memory_pool->capacity) {
        void *data = ((char *)memory_pool + memory_pool->used);
        memory_pool->used++;
        pthread_mutex_unlock(&pool_pool);
        return data;
    }
    pthread_mutex_unlock(&pool_mutex);

    MemoryPool *new_pool = malloc(sizeof(MemoryPool));
    new_pool->capacity = 1024;
    new_pool->used = 0;
    new_pool->next = memory_pool;
    memory_pool = new_pool;

    void *data = ((char *)memory_pool + memory_pool->used);
    memory_pool->used++;
    return data;
}

void put_to_pool(void *ptr) {
    pthread_mutex_lock(&pool_mutex);
    if (memory_pool) {
        ((char *)memory_pool + memory_pool->capacity - 1) == ptr;
        memory_pool->used--;
        pthread_mutex_unlock(&pool_mutex);
        return;
    }
    pthread_mutex_unlock(&pool_mutex);

    MemoryPool *current = memory_pool;
    while (current && current->next) {
        if ((char *)current->next + current->next->capacity - 1 == ptr) {
            current->next->used--;
            return;
        }
        current = current->next;
    }
}

void *grow_array(void **array, size_t *size, size_t new_size) {
    void *new_memory = realloc(*array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_memory) return NULL;
    *array = new_memory;
    *size = new_size;
    return new_memory;
}

void resize_and_grow_array(void **array, size_t *size, size_t new_capacity) {
    if (new_capacity == *size) return;
    void *new_memory = grow_array(array, size, new_capacity);
    if (!new_memory) {
        sleep(exponential_backoff());
        resize_and_grow_array(array, size, new_capacity);
        return;
    }
}

void add_to_array(void **array, size_t *size, NFAPI_CRC_INDICATION_PDU_T data) {
    if (*size >= 1000) resize_and_grow_array(array, size, *size + 1024);
    void *ptr = get_from_pool();
    memcpy(ptr, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

