    private record PageSectionUpdateRequest(string SectionId, string ElementId, string Content);

    private record PageSectionUpdateResponse(bool RefreshRequired, string Checksum);

    public async Task<PageSectionUpdateResponse> UpdateContentAsync(HttpRequestMessage request)
    {
        var requestBody = await request.Content.ReadAsStringAsync();
        var updateRequest = JsonConvert.DeserializeObject<PageSectionUpdateRequest>(requestBody);

        if (string.IsNullOrEmpty(updateRequest.SectionId) || string.IsNullOrEmpty(updateRequest.ElementId) || string.IsNullOrEmpty(updateRequest.Content))
            return new PageSectionUpdateResponse(true, "Invalid parameters");

        var cachedResponse = _cache.Get(CreateChecksumKey(updateRequest));
        if (cachedResponse != null)
        {
            _logger.LogInformation("Found content update in cache.");
            return JsonConvert.DeserializeObject<PageSectionUpdateResponse>(cachedResponse);
        }

        try
        {
            var response = await _fetchService.FetchUpdate(updateRequest);
            _cache.Set(CreateChecksumKey(updateRequest), JsonConvert.SerializeObject(response), TimeSpan.FromMinutes(5));
            return response;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to fetch update.");
            return new PageSectionUpdateResponse(true, "Failed to fetch update");
        }
    }

    private string CreateChecksumKey(PageSectionUpdateRequest request)
    {
        var checksum = ComputeChecksum(request.Content);
        return $"{request.SectionId}:{request.ElementId}:{checksum}";
    }

