    MD5_CTX md5_ctx;
} HashThreadData;

void* compute_md5(void* data) {
    HashThreadData* thread_data = (HashThreadData*)data;
    FILE* fp = fopen(thread_data->file_path, "rb");
    if (!fp) {
        fprintf(stderr, "Error opening file: %s\n", thread_data->file_path);
        return NULL;
    }

    char buffer[1024];
    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        MD5_Update(&thread_data->md5_ctx, buffer, bytes_read);
    }

    fclose(fp);
    return malloc(MD5_DIGEST_LENGTH);
}

void write_log(const char* file_path, const unsigned char* hash) {
    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s %s\n", file_path, hash);
        fclose(log_file);
    } else {
        fprintf(stderr, "Error writing log: %s\n", "log.txt");
    }
}

