        fprintf(stderr, "Usage: %s <input_directory> <output_directory> <config_file>\n", argv[0]);
        return 1;
    }

    MD5_CTX overall_md5_ctx;
    MD5_Init(&overall_md5_ctx);

    DIR* dir = opendir(argv[1]);
    if (!dir) {
        fprintf(stderr, "Error opening input directory: %s\n", argv[1]);
        return 1;
    }

    struct dirent* entry;
    pthread_t hash_threads[128]; // Adjust as needed for thread limit
    while ((entry = readdir(dir)) != NULL) {
        char file_path[4096];
        snprintf(file_path, sizeof(file_path), "%s/%s", argv[1], entry->d_name);

        struct stat st;
        if (lstat(file_path, &st) < 0) {
            continue; // Skip error and move to the next file
        }

        if (S_ISDIR(st.st_mode)) {
            continue; // Ignore directories, symbolic links pointing to directories, etc.
        }

        if (!S_ISREG(st.st_mode)) {
            fprintf(stderr, "Skipping non-regular file or special file: %s\n", file_path);
            continue;
        }

        HashThreadData thread_data = {file_path, MD5_CTX()};
        pthread_create(&hash_threads[pthread_size], NULL, compute_md5, &thread_data);
    }

    closedir(dir);

    for (size_t i = 0; i < sizeof(hash_threads) / sizeof(pthread_t); ++i) {
        void* hash;
        pthread_join(hash_threads[i], &hash);
        if (!hash) continue; // Skip error and move to the next file

        MD5_Final((unsigned char*)hash, &thread_data.md5_ctx);
        MD5_Update(&overall_md5_ctx, (const unsigned char*)hash, MD5_DIGEST_LENGTH);
        write_log(thread_data.file_path, hash);
        free(hash);
    }

    // Implement transformation and saving logic here
    // ...

    return 0;
}
