        _navigator = _reader.CreateNavigator();
    }

    public XmlElementCollector(Stream stream, string namespaceUri, string localName)
    {
        _ns = XNamespace.Get(namespaceUri);
        _localName = localName;
        var xmlReaderSettings = new XmlReaderSettings();
        xmlReaderSettings.XPathDocumentURIResolver += (Uri uri, XmlName xname) =>
        {
            if (uri.Scheme == Uri.UriSchemeHttp || uri.Scheme == Uri.UriSchemeHttps)
                return null;
            return uri;
        };
        _reader = XmlReader.Create(stream, xmlReaderSettings);
        _navigator = _reader.CreateNavigator();
    }

    public IEnumerable<XElement> Collect()
    {
        if (_nodeIterators.Count > 0)
        {
            foreach (var nodeIterator in _nodeIterators)
            {
                while (nodeIterator.MoveNext())
                {
                    yield return XElement.ReadFrom(_navigator.ReadSubtree());
                }
            }
            _nodeIterators.Clear();
        }
        else
        {
            _nodeIterators.Add(_navigator.Select(_GetXPath()));
        }
    }

    private string _GetXPath()
    {
        var xpath = $"//{_ns}:{_localName}";
        return xpath;
    }

    public void Dispose()
    {
        if (_disposed)
            return;
        _disposed = true;
        _reader.Close();
        GC.SuppressFinalize(this);
    }

    private static ILog Log
    {
        get
        {
            var repository = LogManager.GetRepository();
            repository.Threshold = Level.Debug; // Configurable logging level
            return LogManager.GetLogger(typeof(XmlElementCollector));
        }
    }
}
```

