#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint16_t rxiTag;
    uint32_t rnti;
    uint8_t crcIndicationTag;
    uint8_t crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int minVal;
    int maxVal;

    void* randFloatGen;
    void* randIntGen;
} RAND_GENERATOR_T;

RAND_GENERATOR_T randGenerator = {0, 0, NULL, NULL};

void initRandGenerator(int min, int max) {
    randGenerator.minVal = min;
    randGenerator.maxVal = max;

    randGenerator.randFloatGen = calloc(1, sizeof(float));
    randGenerator.randIntGen = calloc(1, sizeof(unsigned int));
}

void freeRandGenerator() {
    if (randGenerator.randFloatGen) free(randGenerator.randFloatGen);
    if (randGenerator.randIntGen) free(randGenerator.randIntGen);
}

float randFloatInRange(RAND_GENERATOR_T* generator) {
    unsigned int randVal = *(unsigned int*)generator->randIntGen;
    float frac, result;

    if (++randVal >= RAND_MAX / (generator->maxVal - generator->minVal + 1)) {
        randVal = 0;
        srand((unsigned int)time(NULL));
    }

    frac = randVal * (1.f / (RAND_MAX / (generator->maxVal - generator->minVal + 1)));
    result = frac * (generator->maxVal - generator->minVal) + generator->minVal;

    *(unsigned int*)generator->randIntGen = randVal;
    return result;
}

int randIntInRange(RAND_GENERATOR_T* generator) {
    float fltVal = randFloatInRange(generator);
    return (int)fltVal;
}

void NFAPI_CRC_INDICATION_PDU_T::ToString(const char* prefix, FILE* file) const {
    fprintf(file, "%sRxiTag: 0x%04X, Rnti: 0x%08X, "
            "CrcIndicationTag: 0x%02X, CrCFlag: 0x%02X\n", prefix, rxiTag, rnti, crcIndicationTag, crcFlag);
}

NFAPI_CRC_INDICATION_PDU_T* populateNfapiIndications(int numElements, int minRxiTag, int maxRxiTag, int minRnti, int maxRnti) {
    RAND_GENERATOR_T randGen = randGenerator;
    initRandGenerator(minRxiTag, maxRxiTag);

    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)calloc(numElements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        fprintf(stderr, "Failed to allocate memory for PDUs.\n");
        freeRandGenerator();
        return NULL;
    }

    for (int i = 0; i < numElements; ++i) {
        pduArray[i].rxiTag = randIntInRange(&randGen);
        pduArray[i].rnti = (randIntInRange(&randGen) << 16) | randIntInRange(&randGen);
        pduArray[i].crcIndicationTag = i % 2 == 0 ? 0x47 : 0x50; // Alternate between 0x47 and 0x50 for demonstration purposes
        pduArray[i].crcFlag = randIntInRange(&randGen) % 2;
    }

    freeRandGenerator();
    return pduArray;
}
