#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
} DataStructure;

struct rnti_list {
    uint32_t *rntis;
    size_t capacity;
    size_t current;
};

void rnti_list_init(struct rnti_list *list, size_t capacity) {
    list->rntis = calloc(capacity, sizeof(uint32_t));
    if (!list->rntis) {
        perror("Calloc failure");
        exit(1);
    }
    list->current = 0;
    list->capacity = capacity;
}

uint32_t rnti_get() {
    if (list->current >= list->capacity) {
        printf("RNTI exhaustion\n");
        return UINT32_MAX;
    }
    return list->rntis[list->current++];
}

void rnti_put(struct rnti_list *list, uint32_t rnti) {
    if (list->current > 0 && list->current - 1 == list->rntis[list->current - 1]) {
        list->rntis[list->current - 1] = rnti;
    } else {
        while (list->current < list->capacity && list->current != list->rntis[list->current]) {
            list->rntis[list->current++] = rnti;
            break;
        }
    }
}

DataStructure* data_structure_create() {
    DataStructure *data_structure = malloc(sizeof(DataStructure));
    if (!data_structure) {
        perror("Malloc failure");
        exit(1);
    }
    time(&data_structure->timestamp);
    return data_structure;
}

void data_structure_fill(DataStructure *data_structure, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG.tagValue = 0x1234; // Replace with actual tag value
    pdu->RNTI.rnti = rnti_get();
    pdu->CRC_INDICATION_REL8_TAG.crcFlag = (rand() % 2);
}

void data_structure_log(DataStructure *data_structure) {
    printf("Timestamp: %s, RNTI: %u, CRCFlag: %d\n", ctime(&data_structure->timestamp), data_structure->pdu.RNTI.rnti, data_structure->pdu.CRC_INDICATION_REL8_TAG.crcFlag);
}

void *data_generator(void *arg) {
    size_t *capacity = arg;
    struct rnti_list rnti_list;
    DataStructure **data_structures = malloc(*capacity * sizeof(DataStructure*));
    if (!data_structures) {
        perror("Malloc failure");
        exit(1);
    }

    rnti_list_init(&rnti_list, *capacity);

    for (size_t i = 0; i < *capacity; ++i) {
        DataStructure *data_structure = data_structure_create();
        data_structure_fill(data_structure, &data_structure->pdu);
        data_structures[i] = data_structure;
        rnti_put(&rnti_list, data_structure->pdu.RNTI.rnti);
    }

    for (size_t i = 0; i < *capacity; ++i) {
        data_structure_log(data_structures[i]);
    }

    free(data_structures);

    return NULL;
}

int main() {
    pthread_t threads[10];
    size_t capacity = 10000;

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, data_generator, &capacity)) {
            perror("Pthread create failure");
            exit(1);
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Pthread join failure");
            exit(1);
        }
    }

    return 0;
}
```

