#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Third-party MAC layer library dependency
extern void mac_process_frame(MAC_FRAME_PDU_T* frame);

typedef struct {
    uint16_t sap_id;
    uint32_t pdcp_sn;
    uint32_t mac_seq_num;
} MAC_FRAME_PDU_T;

#define BUFFER_GROWTH_FACTOR 1.5
#define MIN_BUFFER_SIZE 1024
#define MAX_BUFFER_SIZE (64 * 1024 * 1024) // 64MB max buffer size

struct buffer {
    MAC_FRAME_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void buffer_init(struct buffer* buf, size_t initial_size) {
    if (initial_size < MIN_BUFFER_SIZE)
        initial_size = MIN_BUFFER_SIZE;
    buf->data = malloc(initial_size * sizeof(MAC_FRAME_PDU_T));
    buf->capacity = initial_size;
    buf->count = 0;
    pthread_mutex_init(&buf->lock, NULL);
}

void buffer_destroy(struct buffer* buf) {
    free(buf->data);
    pthread_mutex_destroy(&buf->lock);
}

void buffer_resize(struct buffer* buf, size_t new_capacity) {
    if (new_capacity > MAX_BUFFER_SIZE)
        return;

    MAC_FRAME_PDU_T* temp = malloc(new_capacity * sizeof(MAC_FRAME_PDU_T));
    memcpy(temp, buf->data, buf->count * sizeof(MAC_FRAME_PDU_T));

    free(buf->data);
    buf->data = temp;
    buf->capacity = new_capacity;
}

void buffer_add(struct buffer* buf, const MAC_FRAME_PDU_T* frame) {
    pthread_mutex_lock(&buf->lock);

    if (buf->count == buf->capacity) {
        size_t new_capacity = buf->capacity * BUFFER_GROWTH_FACTOR;
        buffer_resize(buf, new_capacity);
    }

    // Enforce no two consecutive structures have the same SAP_ID
    if (buf->count > 0 && buf->data[buf->count - 1].sap_id == frame->sap_id) {
        frame->pdcp_sn = buf->data[buf->count - 1].pdcp_sn + 1;
    } else {
        frame->pdcp_sn = 0;
    }

    buf->data[buf->count] = *frame;
    buf->count++;

    pthread_mutex_unlock(&buf->lock);
}

// Custom error handling and logging can be added here
MAC_FRAME_PDU_T* generate_mac_frames(struct buffer* buffer, size_t num_frames, void (*external_data_source)(MAC_FRAME_PDU_T*, int), int log_level) {
    MAC_FRAME_PDU_T frames[num_frames];

    for (size_t i = 0; i < num_frames; ++i) {
        // Fetch data from external source with a timeout, handle errors gracefully
        if (!external_data_source(&frames[i], 100)) {
            frames[i].sap_id = 0;
            frames[i].pdcp_sn = 0;
            frames[i].mac_seq_num = 0;
            continue;
        }
    }

    // Populate structures with unique SAP IDs and PDCP SN, MAC Seq Num incrementing sequentially
    for (size_t i = 1; i < num_frames; ++i) {
        while (i + 1 < num_frames && frames[i].sap_id == frames[i+1].sap_id) {
            frames[i+1].sap_id++;
        }

        if (i > 0) {
            frames[i].pdcp_sn = frames[i-1].pdcp_sn + 1;
            frames[i].mac_seq_num = frames[i-1].mac_seq_num + 1;
