#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    uint32_t TRANSPORT_BLOCK_ID;
    uint16_t RB_ID;
    uint8_t MODULUS_DATA[MAX_MODULUS_DATA_SIZE];
} LTE_TRANSPORTBLOCK_PDU_T;

struct circular_buffer {
    LTE_TRANSPORTBLOCK_PDU_T *data;
    size_t capacity;
    size_t head;
    size_t tail;
    sem_t mutex;
};

void circular_buffer_init(struct circular_buffer *cb, size_t capacity) {
    cb->capacity = capacity;
    cb->data = malloc(capacity * sizeof(LTE_TRANSPORTBLOCK_PDU_T));
    if (!cb->data) {
        perror("malloc failure");
        exit(EXIT_FAILURE);
    }
    cb->head = cb->tail = 0;
    sem_init(&cb->mutex, 0, 1);
}

void circular_buffer_push(struct circular_buffer *cb, LTE_TRANSPORTBLOCK_PDU_T data) {
    pthread_mutex_lock(&cb->mutex);
    size_t next = (cb->head + 1) % cb->capacity;

    // Check if the buffer is full and the new RB_ID does not conflict with existing ones
    while ((next == cb->tail && cb->capacity != 0) || data.RB_ID == cb->data[cb->tail].RB_ID) {
        sem_wait(&cb->mutex);
    }

    if (next == cb->tail) { // Buffer is full, replace the oldest entry
        free(cb->data[(cb->head + cb->capacity - 1) % cb->capacity].MODULUS_DATA);
    }

    cb->data[next] = data;
    cb->tail = next;
    sem_post(&cb->mutex);
}

LTE_TRANSPORTBLOCK_PDU_T circular_buffer_pop(struct circular_buffer *cb) {
    pthread_mutex_lock(&cb->mutex);
    size_t result = cb->head;
    if (cb->head == cb->tail) { // Buffer is empty
        sem_post(&cb->mutex);
        return (LTE_TRANSPORTBLOCK_PDU_T){ 0 };
    }

    cb->head = (cb->head + 1) % cb->capacity;
    LTE_TRANSPORTBLOCK_PDU_T data = cb->data[result];
    sem_post(&cb->mutex);

    return data;
}
