    struct _NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _DLL {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    pthread_mutex_t mutex;
} DLL;

void dll_init(DLL* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_node() {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) return NULL;

    // Initialize members with zero values or default constants

    return newNode;
}

void dll_push_back(DLL* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dll_pop_front(DLL* list) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->head != NULL) {
        result = list->head;
        list->head = list->head->next;
        if (list->head != NULL)
            list->head->prev = NULL;
        else
            list->tail = NULL;
    }

    pthread_mutex_unlock(&list->mutex);

    return result;
}

void dll_destroy(DLL* list) {
    NFAPI_CRC_INDICATION_PDU_T* current, * next;
    pthread_mutex_lock(&list->mutex);

    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_destroy(&list->mutex);
}

// Unit tests
void test_doubly_linked_list() {
    DLL dll;
    dll_init(&dll);

    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* node = create_node();
        if (!node) continue; // Handle memory allocation failures gracefully
        node->tag = i;
        node->rnti = i * 2;
        node->crc_indication.CRCFLAG = rand() % 2;
