} DYNAMIC_ARRAY;

DYNAMIC_ARRAY* dynamic_array_init() {
    DYNAMIC_ARRAY* array = malloc(sizeof(DYNAMIC_ARRAY));
    if (!array) return NULL;

    array->data = calloc(MAX_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = MAX_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void dynamic_array_destroy(DYNAMIC_ARRAY* array) {
    free(array->data);
    free(array);
}

size_t dynamic_array_insert(DYNAMIC_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (array->size + 1 > array->capacity) return 0; // Failed due to memory constraints

    pthread_mutex_lock(&array->mutex);

    size_t i = array->size++;
    memcpy(&array->data[i], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    array->data[i].crc_indication_rel8_tag.crcflag = rand() % 2; // Set CRCFLAG randomly

    pthread_mutex_unlock(&array->mutex);

    return 1; // Successful allocation
}

size_t dynamic_array_delete(DYNAMIC_ARRAY* array, size_t index) {
    if (index >= array->size) return 0; // Failed due to out-of-bounds access

    pthread_mutex_lock(&array->mutex);

    memcpy(&array->data[index], &array->data[--array->size], sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&array->mutex);

    return 1; // Successful deletion
}

void print_metrics(DYNAMIC_ARRAY* array) {
    printf("Total successful allocations: %zu\n", array->size);
    printf("Total failed attempts due to memory constraints: %zu\n", MAX_CAPACITY - array->size);
    printf("Current memory usage: %.2f MB\n", (float)(array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T)) / (1024.0 * 1024.0));
}
