void initNFAPIData(size_t batchSize, size_t* outNumInits, NFAPI_CRC_INDICATION_PDU_T** outData) {
    size_t bufferSize = INITIAL_BUFFER_SIZE;
    NFAPI_CRC_INDICATION_PDU* data = malloc(bufferSize * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!data) {
        LOG("Failed to allocate initial buffer.");
        *outNumInits = 0;
        *outData = NULL;
        return;
    }

    for (size_t i = 0; i < bufferSize; ++i) {
        data[i].tag.present = RX_UE_INFORMATION_TAG_PRS_CRC_INDICATION_REL8;
        data[i].tag.choice.crcIndicationRel8.rnti.length = 16; // Assuming RNTI length is constant here, adjust as necessary
        data[i].tag.choice.crcIndicationRel8.rnti.value = i + 1; // Using index for simplicity, adjust as necessary
        data[i].tag.choice.crcIndicationRel8.crcIndicationRel8Tag.crcFlag = rand() % 2;
    }

    size_t numInits = bufferSize;
    if (batchSize > numInits) {
        size_t newBufferSize = bufferSize * 2;
        while (newBufferSize < batchSize)
            newBufferSize *= 2;

        NFAPI_CRC_INDICATION_PDU* tempData = data;
        data = malloc(newBufferSize * sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!data) {
            LOG("Failed to allocate additional buffer.");
            free(tempData);
            numInits = 0;
            *outData = NULL;
            return;
        }

        memcpy(data, tempData, numInits * sizeof(NFAPI_CRC_INDICATION_PDU));
        free(tempData);

        bufferSize = newBufferSize;
    }

    *outNumInits = batchSize;
    *outData = data;
}
