typedef struct {
    struct NFAPI_CRC_INDICATION_PDU_T data[RING_BUFFER_SIZE];
    size_t head, tail;
    sem_t lock;
} ring_buffer;

ring_buffer* create_ring_buffer() {
    ring_buffer *rb = mmap(NULL, sizeof(ring_buffer), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!rb) return NULL;
    rb->head = 0;
    rb->tail = 0;
    sem_init(&rb->lock, 0, 1);
    return rb;
}

void destroy_ring_buffer(ring_buffer *rb) {
    munmap((void*)rb, sizeof(*rb));
    sem_destroy(&rb->lock);
}

bool validate_pdu(struct NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Perform validation checks here
    // Return true if the PDU is valid; false otherwise
}

void log_event(const char *msg) {
