}

void* pdu_processor(void* data) {
    ring_buffer *rb = (ring_buffer*)data;
    struct NFAPI_CRC_INDICATION_PDU_T pdu;

    while (true) {
        sem_wait(&rb->lock);

        // Obtain RX_UE_INFORMATION_TAG and RNTI from external sources, handle temporary failures gracefully

        pdu.crcflag = rand() % 2;

        if (!validate_pdu(&pdu)) {
            sem_post(&rb->lock);
            continue; // Skip invalid PDUs
        }

        sem_post(&rb->lock);

        sem_wait(&rb->lock);

        if (rb->head == ((rb->tail + 1) % RING_BUFFER_SIZE)) {
            log_event("List full. Dropping PDU.");
            sem_post(&rb->lock);
            continue; // Drop the PDU if the list is full
        }

        rb->data[rb->head] = pdu;
        rb->head = (rb->head + 1) % RING_BUFFER_SIZE;

        sem_post(&rb->lock);
    }
}

void add_pdus_to_list(ring_buffer *rb, size_t num_pdus) {
    pthread_t threads[num_pdus];

    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_create(&threads[i], NULL, &pdu_processor, rb);
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Initialize the list with a given maximum size and start processing incoming PDUs concurrently.
void init_pdu_list(size_t max_list_size, void(*init)(void)) {
    ring_buffer *rb = create_ring_buffer();
    if (!rb) return; // Exit if memory allocation fails

    rb->max_list_size = max_list_size;

    init(rb); // Initialize any additional data structures or settings here

