    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RTNIS 4096 // Maximum number of unique RNTIs allowed
static unsigned int used_rtnis[MAX_RTNIS];
static int num_elements = 0;
static NFAPI_CRC_INDICATION_PDU_T *list;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_and_add_PDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_mutex);
    while (num_elements >= 100000 || num_unique_RTNIs() >= MAX_RTNIS) {
        pthread_mutex_unlock(&list_mutex);
        usleep(1000); // Sleep for a short time before retrying
        pthread_mutex_lock(&list_mutex);
    }

    int rnti = find_available_RNTIs();
    if (rnti == -1) {
        // Handle error case: all available RNTIs have been used
        printf("Error: No more available RNTIs.\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    pdu->RNTI = rnti;
    pdu->CRCFLAG = rand() % 2;
    list[num_elements] = *pdu;
    used_rtnis[rnti]++;
    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

int find_available_RNTIs() {
    for (unsigned int i = 0; i < MAX_RTNIS; ++i) {
        if (!used_rtnis[i])
            return i;
    }
    return -1;
}

int num_unique_RTNIs() {
    int count = 0;
    for (unsigned int i = 0; i < MAX_RTNIS; ++i)
        if (used_rtnis[i])
            count++;
    return count;
}
