    uint64_t crcChecks[MAX_CELL_CONFIGURATION];  // Number of successful CRC checks for each RNTI
} CELL_CONFIGURATION_T;

// Function to dynamically generate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generatePDUs(uint32_t n, const CELL_CONFIGURATION_T* cellConfig) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        // Handle memory allocation failure
        return NULL;
    }

    for (uint32_t i = 0; i < n; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = cellConfig->validRNTIs[rand() % MAX_CELL_CONFIGURATION]; // Generate a valid RNTI within the configuration's range
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0x37 : 0x45; // Randomly set CRCFLAG
    }

    return pdus;
}

// Function to update the number of successful CRC checks per RNTI across multiple calls to generatePDUs()
void updateCRCChecks(const NFAPI_CRC_INDICATION_PDU_T* pdus, uint32_t n, const CELL_CONFIGURATION_T* cellConfig) {
    for (uint32_t i = 0; i < n; ++i) {
        if (pdus[i].CRC_INDICATION_REL8_TAG == 0x37 && // Only update CRC checks when CRCFLAG is set
            cellConfig->validRNTIs[pdus[i].RNTI % MAX_CELL_CONFIGURATION]) {
            ++cellConfig->crcChecks[pdus[i].RNTI % MAX_CELL_CONFIGURATION];
        }
    }
}
