} API_COLLECTION;

API_COLLECTION* api_collection_create(float growth_factor) {
    API_COLLECTION* collection = malloc(sizeof(API_COLLECTION));
    collection->data = NULL;
    collection->size = 0;
    collection->capacity = 0;
    collection->growth_factor = growth_factor;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void api_collection_destroy(API_COLLECTION* collection) {
    for (unsigned int i = 0; i < collection->size; ++i) {
        free(collection->data[i]);
    }
    free(collection->data);
    free(collection);
}

void api_collection_resize(API_COLLECTION* collection) {
    unsigned int new_capacity = (unsigned int)((float)collection->capacity * collection->growth_factor);
    NFAPI_L1_API_STRUCT** new_data = realloc(collection->data, new_capacity * sizeof(NFAPI_L1_API_STRUCT*));
    if (!new_data) {
        return;
    }
    collection->data = new_data;
    collection->capacity = new_capacity;
}

void api_collection_push(API_COLLECTION* collection, NFAPI_L1_API_STRUCT* data) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        api_collection_resize(collection);
    }
    collection->data[collection->size] = data;
    ++collection->size;
    pthread_mutex_unlock(&collection->lock);
}

NFAPI_L1_API_STRUCT* api_collection_pop(API_COLLECTION* collection) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == 0) {
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }
    NFAPI_L1_API_STRUCT* data = collection->data[0];
    memmove(collection->data, collection->data + 1, (collection->size - 1) * sizeof(NFAPI_L1_API_STRUCT*));
    --collection->size;
    pthread_mutex_unlock(&collection->lock);
    return data;
}

void api_collection_iterate(API_COLLECTION* collection, void (*function)(NFAPI_L1_API_STRUCT*)) {
    pthread_mutex_lock(&collection->lock);
    for (unsigned int i = 0; i < collection->size; ++i) {
        function(collection->data[i]);
    }
    pthread_mutex_unlock(&collection->lock);
}
