            auto seed = std::chrono::system_clock::now().time_since_epoch().count();
            m_engine.seed(seed + m_IV);
        }
    }
};

void init() {
    static thread_local RandomGenerator generator{std::hash<std::thread::id>{}(std::this_thread::get_id())};
}

class RandomSystem final {
public:
    static void generate(int num, int min, int max) {
        for (int i = 0; i < num; ++i) {
            init();
            auto value = generator.generateInt(min, max);
            logger->info("[{}] Requested: Range[{}, {}], Generated: {}", m_counter++, min, max, value);
