        private final AtomicDouble totalLength;
        private final int count;

        public LogEntryLengthReducer(AtomicDouble totalLength, int count) {
            this.totalLength = totalLength;
            this.count = count;
        }

        @Override
        public Publisher<Double> reduce(Flowable<String> upstream, FlowableEmitter<Double> emitter) {
            upstream.subscribe(new LogEntrySubscriber(emitter, totalLength, count));
            return Flowable.just(0d);
        }
    }

    private static final class LogEntrySubscriber extends Subscriber<String> {
        private final FlowableEmitter<Double> emitter;
        private final AtomicDouble totalLength;
        private final int count;

        public LogEntrySubscriber(FlowableEmitter<Double> emitter, AtomicDouble totalLength, int count) {
            this.emitter = emitter;
            this.totalLength = totalLength;
            this.count = count;
        }

        @Override
        public void onSubscribe(Subscription s) {
            s.request(Long.MAX_VALUE); // Request unbounded subscription to handle high throughput
        }

        @Override
        public void onNext(String logEntry) {
            try {
                if (isValidLogEntry(logEntry)) {
                    totalLength.addAndGet(logEntry.length());
                    count++;
                }
            } catch (Exception e) {
                // Handle exceptions gracefully, perhaps by logging or caching fallback data
            }
        }

        @Override
        public void onError(Throwable t) {
            emitter.onError(t);
        }

        @Override
        public void onComplete() {
            emitter.onNext(totalLength.get() / count);
            emitter.onComplete();
        }
    }
}
