    $db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);

    $role_id = isset($request['role_id']) ? (int) $request['role_id'] : null;
    $role_name = $request['role_name'];
    $permissions = json_decode($request['permissions'], true);
    $user_id = (int) $request['user_id'];
    $sub_action = $request['sub_action'];

    $logLevel = 'INFO'; // Configure logging level as needed
    function log($level, $message) {
        error_log("[{$level}] {$message}");
    }

    try {
        $db->beginTransaction();

        if ($sub_action === 'assign') {
            $stmt = $db->prepare("INSERT IGNORE INTO roles (role_name, permissions) VALUES (?, ?)");
            $stmt->execute([$role_name, json_encode($permissions)]);
            $role_id = $db->lastInsertId();

            $stmt = $db->prepare("INSERT INTO role_user (role_id, user_id) VALUES (?, ?)");
            $stmt->execute([$role_id, $user_id]);
        } elseif ($sub_action === 'remove') {
            $stmt = $db->prepare("DELETE FROM role_user WHERE role_id = ? AND user_id = ?");
            $stmt->execute([$role_id, $user_id]);

            $stmt = $db->prepare("DELETE FROM roles WHERE id = ?");
            $stmt->execute([$role_id]);
        }

        if ($sub_action === 'assign') {
            validatePermissions($permissions); // Validation for external API calls
        }

        $db->commit();
    } catch (PDOException $e) {
        $db->rollBack();
        log('ERROR', "An error occurred while managing user roles: {$e->getMessage()}");
        throw new Exception($e->getMessage());
    } finally {
        $db = null; // Free up resources
    }
}

