import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import javax.script.*;
import org.w3c.dom.*;

public class ScriptAnalyzer {
    private static final int MAX_THREADS = 4;

    private record Script(String key, String code, Map<String, Future<?>> dependencies) {}

    public String analyze(Script[] scripts) {
        var uf = new UnionFind();
        var scriptToKey = new HashMap<>();
        var htmlBuilder = new StringBuilder();
        var threadPool = Executors.newFixedThreadPool(MAX_THREADS);
        long startTime;

        for (var script : scripts) {
            script.code = wrapScriptInTag(script.code, script.key);
            scriptToKey.put(script.key, script);
        }

        List<Future<Void>> dependencyFutures = new ArrayList<>();

        for (var script : scripts) {
            startTime = System.nanoTime();
            Script currentScript = scriptToKey.get(script.key);
            if (!currentScript.dependencies.isEmpty()) {
                currentScript.dependencies.putAll(loadDependencies(threadPool, currentScript.code));
            }

            int root = uf.find(currentScript.key);
            for (var dep : currentScript.dependencies.keySet()) {
                if (!uf.isConnected(dep, currentScript.key)) {
                    uf.union(dep, currentScript.key);
                }
            }

            dependencyFutures.add(threadPool.submit(() -> {
                try {
                    for (var dep : currentScript.dependencies.keySet()) {
                        currentScript.dependencies.get(dep).get();
                    }
                } catch (Exception e) {
                    System.err.println("Error while loading dependencies for script: " + currentScript.key);
                }
            }));

            if (uf.getRoots().size() == 1) {
                htmlBuilder.append(currentScript.code).append("\n");
            }

            long elapsedTime = TimeUnit.MILLISECONDS.convert(System.nanoTime() - startTime, TimeUnit.NANOSECONDS);
            System.out.printf("Check time for script %s: %.3f ms%n", currentScript.key, elapsedTime);
        }

        threadPool.shutdown();
        try {
            threadPool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            System.err.println("Thread pool interrupted.");
        }

        return "Count: " + uf.getRoots().size() + ", HTML: " + htmlBuilder.toString();
    }

    private Map<String, Future<?>> loadDependencies(ExecutorService executor, String scriptCode) throws ScriptException {
        var dependencies = new HashMap<>();
        Timer timer = new Timer();
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("nashorn");

        Script script = engine.eval(scriptCode);
        for (ScriptContext context : script.getContextList()) {
            if (!(context instanceof Binding binding)) continue;
            for (Map.Entry<String, Object> entry : binding.getReadableAttributes().entrySet()) {
                if (!entry.getValue().getClass().isArray() && entry.getKey().matches("^_d_[0-9]+$")) {
                    String dependencyKey = entry.getKey();
                    dependencies.put(dependencyKey, executor.submit(() -> engine.eval(scriptCode + "\n// <![CDATA[ " + script.getContextList().get(0).getAttribute("code") + " ]]>\n")));
                }
            }
        }

        timer.schedule(new TimerTask() {
            @Override
            public void run() {
                for (var future : dependencies.values()) {
                    future.cancel(true);
                }
            }
        }, 60 * 1000); // Cancel dependencies after a minute

        return dependencies;
    }

    private String wrapScriptInTag(String scriptCode, String key) {
        StringBuilder htmlScript = new StringBuilder("<script id='");
        htmlScript.append(key);
        htmlScript.append("' type='application/javascript'>");
        htmlScript.append(scriptCode);
        htmlScript.append("</script>");
        return htmlScript.toString();
    }
}

class UnionFind {
    private Map<String, Integer> id;
    private Map<Integer, List<String>> roots;

    public UnionFind() {
        this.id = new HashMap<>();
        this.roots = new HashMap<>();
    }

    public int find(String key) {
        if (!id.containsKey(key)) {
            id.put(key, id.size());
            roots.put(id.get(key), Collections.singletonList(key));
        }
        return id.get(key);
    }

    public void union(String a, String b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) return;
        roots.get(rootA).forEach(id::remove);
        id.put(rootA, rootB);
        roots.put(rootB, mergeLists(roots.get(rootA), roots.get(rootB)));
    }

    public List<String> getRoots() {
        return new ArrayList<>(roots.values());
    }
}
```']

