struct state_list {
    size_t num_states;
    int *states;
    FSA* fsa;
    NFAPI_CRC_INDICATION_PDU_T** indications;
    size_t last_state;
};

struct state_list* initializeStateListAndCRCIndications(int *states, size_t num_states, FSA* fsa, size_t last_state) {
    struct state_list *list = malloc(sizeof(struct state_list));
    if (!list) {
        perror("Failed to allocate memory for state list");
        return NULL;
    }

    // Check for valid input parameters
    if (num_states <= 0 || !fsa || last_state < num_states) {
        free(list);
        return NULL;
    }

    list->num_states = num_states;
    list->states = malloc(num_states * sizeof(int));
    if (!list->states) {
        perror("Failed to allocate memory for state array");
        free(list);
        return NULL;
    }

    memcpy(list->states, states, num_states * sizeof(int));

    list->fsa = fsa;

    // Allocate the indications array with a default batch size
    size_t batch_size = num_states / 10; // Adjust this value based on current load and resource availability
    list->indications = calloc(batch_size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->indications) {
        perror("Failed to allocate memory for indications array");
        free(list->states);
        free(list);
        return NULL;
    }

    // Initialize each indication with a valid tag, RNTI, and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    for (size_t i = 0; i < batch_size; ++i) {
        list->indications[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->indications[i]) {
            perror("Failed to allocate memory for an indication");
            free(list->states);
            free(list->indications);
            free(list);
            return NULL;
        }

        list->indications[i]->RX_UE_INFORMATION_TAG = 0xABCD1234; // Set a default tag
        list->indications[i]->RNTI = rand() % 65536;              // Generate a random RNTI value within the allowed range
        list->indications[i]->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
    }

    list->last_state = last_state;

    return list;
}
