#define NFAPI_CRC_INDICATION_PDU_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_nfaapi_crc_indications(unsigned int N) {
    if (N == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(N * NFAPI_CRC_INDICATION_PDU_SIZE);
    if (!indications) {
        fprintf(stderr, "Error: Insufficient resources\n");
        return NULL;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_t *mutex = calloc(N, sizeof(pthread_mutex_t));
    if (!mutex) {
        fprintf(stderr, "Error: Insufficient resources\n");
        free(indications);
        return NULL;
    }

    for (unsigned int i = 0; i < N; ++i) {
        pthread_mutex_init(&mutex[i], &attr);
    }

    log_allocation(N, indications);

    // Populate the structures with random CRC flags
    srand((unsigned int)time(NULL));
    for (unsigned int i = 0; i < N; ++i) {
        indications[i].crc_indication.crcflag = rand() % 256;
        pthread_mutex_lock(&mutex[i]);
        // Perform any additional setup or data flow as needed here
        pthread_mutex_unlock(&mutex[i]);
    }

    return indications;
}
