#define BUF_SIZE (10 * 1024 * 1024) // 10 MB buffer size

// Customizable transformation function
typedef void (*transform_func)(void*, size_t);

int process_file(char* input_file, char* output_file, const char* rules, int lossless, long max_size) {
    struct stat file_stat;
    int fd_in = open(input_file, O_RDONLY);
    if (fd_in == -1) return 1; // error opening input file

    if (fstat(fd_in, &file_stat) == -1) {
        close(fd_in);
        return 2; // error getting file size
    }

    long file_size = file_stat.st_size;
    if (file_size > max_size) {
        close(fd_in);
        return 3; // input file exceeds the specified size limit
    }

    transform_func transform = parse_rules(rules);
    if (!transform) {
        close(fd_in);
        return 4; // error parsing transformation rules
    }

    int fd_out = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd_out == -1) {
        close(fd_in);
        return 5; // error opening output file
    }

    void* map_in = mmap(NULL, BUF_SIZE, PROT_READ, MAP_PRIVATE, fd_in, 0);
    if (map_in == MAP_FAILED) {
        close(fd_out);
        close(fd_in);
        return 6; // error mapping input file
    }

    char* buffer = (char*) map_in;
    size_t bytes_processed = 0;
    clock_t start = clock();

    while (bytes_processed < file_size) {
        size_t to_process = file_size - bytes_processed > BUF_SIZE ? BUF_SIZE : file_size - bytes_processed;
        transform(buffer, to_process);

        if (!lossless && (clock() - start) / CLOCKS_PER_SEC >= 30.0 * (file_size / (1024 * 1024))) {
            break; // exceeded the 30-second threshold
        }

        size_t written = write(fd_out, buffer, to_process);
        if (written != to_process) {
            munmap(map_in, BUF_SIZE);
            close(fd_out);
            close(fd_in);
            return 7; // error writing output file
        }

        bytes_processed += to_process;
    }

    munmap(map_in, BUF_SIZE);
    close(fd_out);
    close(fd_in);

    if (!lossless && (clock() - start) / CLOCKS_PER_SEC >= 30.0 * (file_size / (1024 * 1024))) {
        // exceeded the 30-second threshold when processing large files, but still write output file
        return 0;
    }
    return 0;
}

// Implement transformation rules parsing function here...
