typedef struct _NFAPI_DYNAMIC_LIST {
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t mutex;
    void* (*allocator)(size_t); // Custom allocator function pointer
    void(*deallocator)(void*);  // Custom deallocator function pointer
} NFAPI_DYNAMIC_LIST;

bool validate(const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element->rnti > MAX_RNTI || element->rnti < MIN_RNTI || element->crc_indication > MAX_CRC_INDICATION || element->crc_indication < MIN_CRC_INDICATION)
        return false;

    // Add custom validation checks as needed

    // If a duplicate RNTI is found, return false
    for (size_t i = 0; i < size; ++i) {
        if (element->rnti == elements[i].rnti && i != index)
            return false;
    }

    return true;
}

NFAPI_DYNAMIC_LIST* nfapi_dynamic_list_create(void(*allocator)(size_t), void(*deallocator)(void*), size_t initial_size) {
    NFAPI_DYNAMIC_LIST* list = malloc(sizeof(NFAPI_DYNAMIC_LIST));
    if (!list) return NULL;

    list->allocator = allocator;
    list->deallocator = deallocator;
    list->size = initial_size;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)list->allocator(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void nfapi_dynamic_list_destroy(NFAPI_DYNAMIC_LIST* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->mutex);
    free(list->elements);
    free(list);
}

size_t nfapi_dynamic_list_get_size(const NFAPI_DYNAMIC_LIST* list) {
    return list->size;
}

void nfapi_dynamic_list_add(NFAPI_DYNAMIC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!validate(element)) return;

    pthread_mutex_lock(&list->mutex);

    size_t current_size = list->size;
    if (current_size == list->size) {
        void* new_elements = list->allocator((current_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        memcpy(new_elements, list->elements, current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(list->elements);
        list->elements = new_elements;
    }

    list->elements[current_size] = *element;
    ++(list->size);

    pthread_mutex_unlock(&list->mutex);
}

void nfapi_dynamic_list_remove(NFAPI_DYNAMIC_LIST* list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

