unsigned int get_transaction_age(const struct timespec *current, const struct timespec *timestamp) {
    unsigned long diff = (current->tv_sec - timestamp->tv_sec) * 1000 + (current->tv_nsec - timestamp->tv_nsec) / 1000000;
    return diff;
}

unsigned int get_transaction_frequency(const struct timespec *current, NFAPI_CRC_INDICATION_PDU_T** buffer, unsigned int* count, unsigned int time_interval) {
    unsigned int frequency = 0;
    for (unsigned int i = 0; i < *count - 1; ++i) {
        struct timespec temp_time = *(buffer + i)->timestamp;
        if (get_transaction_age(current, &temp_time) <= time_interval) {
            frequency++;
        }
    }
    return frequency;
}

double calculate_weighted_sum(const NFAPI_CRC_INDICATION_PDU_T** buffer, unsigned int count, double weight) {
    double sum = 0.0;
    for (unsigned int i = 0; i < count; ++i) {
        sum += buffer[i]->crc_indication.value * weight;
    }
    return sum;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_transaction(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** buffer = (NFAPI_CRC_INDICATION_PDU_T**)arg;
    unsigned int count = 0;
    pthread_mutex_lock(&mutex);
