    NFAPI_CRC_INDICATION_PDU_T** new_buffer = (NFAPI_CRC_INDICATION_PDU_T**)realloc(buffer, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (count + 1));
    if (!new_buffer) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    buffer = new_buffer;
    // Generate CRC for the new transaction and store it in the last element of the array
    generate_crc(buffer[count]);
    buffer[count]->timestamp = *((struct timespec *)arg + 1);
    count++;
    pthread_mutex_unlock(&mutex);

    // Evaluate the transaction based on its age, frequency, and weighted sum
    unsigned int age = get_transaction_age(clock_gettime(CLOCK_REALTIME, NULL), buffer[count - 1]->timestamp);
    unsigned int frequency = get_transaction_frequency(clock_gettime(CLOCK_REALTIME, NULL), buffer, &count, 5000);
    double weighted_sum = calculate_weighted_sum(buffer, count, 1.0 / age);

    // Implement a logging mechanism to monitor the function’s performance and stability under various load conditions
    if (frequency > 10 || weighted_sum > 1000) {
        printf("Warning: High transaction frequency or large weighted sum detected.\n");
    }

#ifdef FALLBACK_STRATEGY
    // Implement a fallback strategy for degraded network environments
