    NFAPI_CRC_INDICATION_PDU_T** buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * buffer_size);
    if (!buffer) {
