#include <stdint.h>
#include <time.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    uint64_t id;
    time_t timestamp;
    int value;
} Transaction;

typedef struct {
    size_t size;
    Transaction* transactions;
    uint64_t max_weighted_sum;
    uint64_t max_weighted_sum_id;
} Batch;

Batch process_transaction(Batch* current_batch, const Transaction* new_transaction) {
    time_t current_time = time(NULL);
    double elapsed_since_last = difftime(current_time, current_batch->transactions[current_batch->size - 1].timestamp);

    if (elapsed_since_last > 5) {
        current_batch->size--;
    } else {
        double weighted_sum = 0.0;
        size_t i;

        for (i = current_batch->size - 1; i >= current_batch->size - (current_batch->size % 3); --i) {
            weighted_sum += new_transaction->value + current_batch->transactions[i].value;

            if (weighted_sum > 100.0) {
                break;
            }
        }

        if (i >= current_batch->size - (current_batch->size % 3)) {
            current_batch->transactions[current_batch->size++] = *new_transaction;
        } else {
            current_batch->transactions[current_batch->size - 1].value += new_transaction->value;
        }
    }

    size_t discarded = current_batch->size - (current_batch->size % 3);
    size_t flagged = 0;
    size_t max_index = current_batch->size - 1;

    for (size_t i = 0; i < current_batch->size; ++i) {
        if (current_time - current_batch->transactions[i].timestamp > 86400) { // Daily cumulative value limit check
            flagged++;
        } else if (current_batch->transactions[i].value + current_batch->max_weighted_sum > 1000) {
            flagged++;
            max_index = i;
        }

        current_batch->max_weighted_sum = fmax(current_batch->max_weighted_sum, current_batch->transactions[i].value + current_batch->transactions[(i+3)%current_batch->size].value);
    }

    return (Batch){
        .size = current_batch->size,
        .transactions = current_batch->transactions,
        .max_weighted_sum = current_batch->max_weighted_sum,
        .max_weighted_sum_id = max_index
    };
}
```

