#include <chrono>
#include <thread>
#include <condition_variable>
#include <atomic>
#include <sstream>
#include <queue>
#include <functional>

class AttackCooldown {
public:
    std::mutex mtx;
    std::condition_variable cv;
    std::chrono::steady_clock::time_point lastAttackTime;
    std::chrono::milliseconds cooldownDuration;

    void start() {
        lastAttackTime = std::chrono::steady_clock::now();
        cv.notify_all();
    }

    bool canAttack() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait_until(lock, lastAttackTime + cooldownDuration, [](auto now) { return (now > std::chrono::steady_clock::now()); });
        bool canAttack = true;
        lastAttackTime = std::chrono::steady_clock::now();
        return canAttack;
    }
};

class Attack {
public:
    virtual void execute() = 0;
    virtual std::string logMessage() const = 0;
    std::stringstream log;
};

class BasicAttack : public Attack {
public:
    void execute() override {
        // Implement the basic attack execution logic here
        std::cout << "Basic Attack executed by character" << std::endl;
    }

    std::string logMessage() const override {
        return log.str();
    }
};

