        std::cout << "Magic Attack executed by character" << std::endl;
    }

    std::string logMessage() const override {
        return log.str();
    }
};

class RangedAttack : public Attack {
public:
    void execute() override {
        // Implement the ranged attack execution logic here
        std::cout << "Ranged Attack executed by character" << std::endl;
    }

    std::string logMessage() const override {
        return log.str();
    }
};

class Character {
public:
    std::shared_ptr<AttackCooldown> cooldown;
    std::vector<std::unique_ptr<Attack>> attacks;

    void addAttack(std::unique_ptr<Attack> attack) {
        attacks.push_back(std::move(attack));
    }

    void executeAttack() {
        if (cooldown->canAttack()) {
            auto* currentAttack = attacks[rand() % attacks.size()].get();
            currentAttack->execute();
            cooldown->log << "Attack: " << currentAttack->logMessage() << ", Time: " << std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - cooldown->lastAttackTime).count() << "ms" << std::endl;
            cooldown->start();
        }
    }
};

class CharacterManager {
public:
    void addCharacter(std::shared_ptr<Character> character) {
        characters.emplace_back(character);
    }

    void executeCharactersAttacks() {
        for (auto& character : characters) {
            character->executeAttack();
        }
