MemoryBlock* create_memory_block(size_t capacity) {
    if (capacity <= 0 || capacity > 10000) {
        fprintf(stderr, "Invalid memory block capacity: %zu\n", capacity);
        return NULL;
    }

    MemoryBlock *block = malloc(sizeof(MemoryBlock));
    if (!block) {
        perror("malloc");
        return NULL;
    }

    block->capacity = capacity;
    block->used = 0;
    block->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!block->data) {
        perror("calloc");
        free(block);
        return NULL;
    }

    pthread_mutex_init(&block->mutex, NULL);
    return block;
}

void destroy_memory_block(MemoryBlock *block) {
    if (!block) {
        return;
    }

    free(block->data);
    pthread_mutex_destroy(&block->mutex);
    free(block);
}

