};

class LocalResourceLoader : public ResourceLoader {
private:
    std::unordered_map<fs::path, ResourceBundle> cache_;
    size_t maxCacheSize_{10}; // Adjust as needed
public:
    boost::optional<ResourceBundle> load(const fs::path& path) override {
        if (cache_.count(path))
            return cache_[path];

        ResourceBundle bundle;
        std::ifstream file(path);
        if (!file.is_open())
            return boost::none;

        // Read the resource bundle from the file and set 'bundle' accordingly.
        // The details of this part depend on the specific format of your resource bundles.

        auto it = cache_.upper_bound(path);
        if (cache_.size() > maxCacheSize_) {
            for (auto it = cache_.begin(); it != it; ) {
                cache_.erase(it++);
            }
        }
        cache_[path] = bundle;
        return bundle;
    }
};

class RemoteResourceLoader : public ResourceLoader {
private:
    boost::asio::io_service ioService_;
public:
    boost::optional<ResourceBundle> load(const fs::path& path) override {
        // Implement HTTP request handling here, using boost::asio to connect to the remote server and download the resource bundle.
    }
};

std::shared_ptr<ResourceLoader> createResourceLoader(const std::string& type) {
    if (type == "local")
        return std::make_shared<LocalResourceLoader>();
    else if (type == "remote")
        return std::make_shared<RemoteResourceLoader>();
    throw std::invalid_argument("Invalid resource loader type");
}

std::future<ResourceBundle> loadResourceBundle(const fs::path& path, const std::string& type) {
    auto loader = createResourceLoader(type);
    return loader->load(path).value();
}

int main() {
