        bundles.push_back(loadResourceBundle("local/bundle1.txt", "local"));
        bundles.push_back(loadResourceBundle("http://example.com/bundle2.txt", "remote"));

        boost::asio::io_service ioService;

        for (auto& bundle : bundles) {
