['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char *process_string(const char *input, size_t max_length, bool trim) {
    size_t length = strlen(input);

    // Check if the string exceeds the specified maximum length and needs to be trimmed
    if (length > max_length && trim) {
        // Find the index of the last word space character from the end of the input string
        const char *end_space = input + length - 1;
        while (isspace(*end_space)) {
            --end_space;
        }
        ++end_space; // Move to the next character

        // Check if there's a word to be trimmed and calculate the new length
        size_t new_length = end_space - input;
        if (new_length <= max_length) {
            return strndup(input, new_length);
        }
    }

    // String does not exceed the size limit or does not require trimming
    char *result = malloc(length + 1); // Allocate memory for the result string and a null terminator
    if (!result) {
        // Handle memory allocation failure by returning NULL
        perror("Memory allocation error");
        return NULL;
    }

    // Copy the input string to the result string, ensuring proper handling of whitespace characters
    size_t i = 0;
    for (const char c : input) {
        if (!isspace(c)) {
            result[i++] = c;
        }

        // If the result string exceeds the maximum length, do not copy additional characters from the input string
        if (i >= max_length) {
            break;
        }
    }

    result[i] = '\0'; // Null-terminate the result string
    return result;
}
```

