    char formats[][3] = {"%Y", "%m", "%d", "%H", "%M", "%S"};
    for (size_t i = 0; i < sizeof(formats) / sizeof(formats[0]); ++i) {
        if (!strptime(timestamp, formats[i], NULL))
            return 0;
    }
    return 1;
