bool process_image(const char* input_filename, const ImageProcessingContext* context, FILE* output_file) {
    void* image_data = NULL;
    size_t image_size = 0;
    if (!context->read_func || !context->write_func || !(context->image_convert)) return false;

    if (context->read_func(input_filename, &image_data, &image_size) <= 0) return false;

    IPP_Image converted_image = context->image_convert(image_data, image_size, context->compression_level);
    if (!converted_image) {
        free(image_data);
        return false;
    }

    size_t output_size = get_png_buffer_size(converted_image->width, converted_image->height, context->compression_level);
    unsigned char* output_buffer = malloc(output_size);
    if (!output_buffer) {
