#include <json/json.h>
#include <jansson/jansson.h>
#include <time.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} TokenResponse;

TokenResponse* parse_token(char* json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if (!root) {
        fprintf(stderr, "Error in JSON: %s\n", error.text);
        return NULL;
    }

    TokenResponse* token = (TokenResponse*)malloc(sizeof(TokenResponse));
    json_t *access_token_json = json_object_get(root, "access_token");
    json_t *expires_in_json = json_object_get(root, "expires_in");
    json_t *token_type_json = json_object_get(root, "token_type");
    json_t *refresh_token_json = json_object_get(root, "refresh_token");

    token->access_token = json_string_value(json_object_get(access_token_json));
    token->expires_in = json_integer_value(expires_in_json);
    token->token_type = json_string_value(token_type_json);
    token->refresh_token = refresh_token_json ? json_string_value(refresh_token_json) : "";

    json_decref(root);

    if (!token->access_token || !token->expires_in || strcmp(token->token_type, "Bearer") != 0) {
        free(token);
        return NULL;
    }

    return token;
}

int is_valid_token(TokenResponse* token) {
    time_t current_time = time(NULL);
    struct tm *time_struct = localtime(&current_time);

    if (token->expires_in <= 0 || (time_struct->tm_sec + token->expires_in) > 60) {
        return 0;
    }

    return 1;
}

void process_tokens(char* json, void (*callback)(TokenResponse*)) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if (!root) {
        fprintf(stderr, "Error in JSON: %s\n", error.text);
        return;
    }

    json_t *tokens_array = json_object_get(root, "tokens");
    size_t token_count = json_array_size(tokens_array);
    TokenResponse* tokens = (TokenResponse*)malloc(token_count * sizeof(TokenResponse));

    for (size_t i = 0; i < token_count; ++i) {
        char* token_json = json_string_value(json_array_get(tokens_array, i));
        TokenResponse* token = parse_token(token_json);

        if (!token) continue;
        if (is_valid_token(token)) callback(token);

        free(token);
    }

    json_decref(root);
}
```

