const scriptLoader = (files, callback) => {
  const loadedFiles = [];
  const errors = [];

  const loadScript = (src) => {
    const script = document.createElement('script');
    script.src = src;
    script.onload = () => loadedFiles.push(src);
    script.onerror = () => errors.push(`${src} failed to load`);
