// .php (entry point, initializes environment and loads scripts)
<?php
header("Content-Type: text/html; charset=UTF-8");

$envFile = parse_ini_file('.env');
putenv(implode(", ", array_map(function($key, $val) { return "$key=$val"; }, array_keys($envFile), $envFile)));

require_once __DIR__ . '/vendor/autoload.php'; // Vendor autoloader

$scripts = ['path-to-your-script1.js', 'path-to-your-script2.js'];
