function loadScripts(array $files) {
  $loader = new ScriptLoader();
  $loadedFiles = $loader->loadFiles($files);
  if (empty($loadedFiles)) {
    echo "All required scripts failed to load.";
    exit;
  }
  include __DIR__ . '/index.php';
}

// ScriptLoader.php (for loading JavaScript files)
class ScriptLoader
{
    public function loadFiles(array $files)
    {
        $loadedFiles = [];
        foreach ($files as $script) {
            if (!file_exists($script)) {
                trigger_error("Script '$script' not found", E_USER_WARNING);
                continue;
            }

            try {
                $contents = file_get_contents($script);
            } catch (Exception $e) {
                trigger_error("Error loading script '$script': " . $e->getMessage(), E_USER_ERROR);
                continue;
            }

            if ($contents === false) {
                trigger_error("Script '$script' not readable", E_USER_WARNING);
                continue;
            }

            try {
                ob_start();
                eval($contents);
                $loadedFiles[] = $script;
            } catch (Exception $e) {
                trigger_error("Error executing script '$script': " . $e->getMessage(), E_USER_ERROR);
            }
        }

        return $loadedFiles;
    }
}
