static size_t created_structures = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static bool valid_indicators[] = {/* predefined set of valid indicators */};

size_t create_crc_indication_array(size_t N, NFAPI_CRC_INDICATION_PDU_T** array) {
    if (N == 0 || array == NULL) {
        return 0;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T*) calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*array == NULL) {
        return 0;
    }

    pthread_mutex_lock(&mutex);
    size_t count = 0;

    for (size_t i = 0; i < N && created_structures + count < N; ++i) {
        bool unique_tag = true;
        int tag = 0;
        do {
            tag = rand() % MAX_TAG;
        } while (!unique_tag && (tag == (*array)[count].tag));

        (*array)[count].tag = tag;
        (*array)[count].rnti = rand(); // Replace this with actual RNTI generation logic
        (*array)[count].crcflag = (CRCFLAG)(rand() % NUM_CRCFLAGS);

        unique_tag = true;
        for (size_t j = 0; j < count && valid_indicator[j] != -1; ++j) {
            if ((*array)[count].crcflag == valid_indicators[j]) {
                unique_tag = false;
                break;
            }
        }

        if (unique_tag) {
            created_structures++;
            count++;
        }
    }

    pthread_mutex_unlock(&mutex);

    return count;
}
