typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    time_t creation_time;
} Node;

struct LinkedList {
    unsigned int size;
    Node* head;
    Node* tail;
};

void deleteOlderNodes(struct LinkedList* list) {
    clock_t start = clock();
    Node *current = list->head, *temp;
    while (list->size > 1024 && current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
        if (current == NULL) {
            list->tail = NULL;
        }
        list->size--;
    }
    printf("Time taken for deleting older nodes: %.6fs\n", (clock() - start)/CLOCKS_PER_SEC);
}

struct LinkedList* createLinkedList() {
    struct LinkedList *list = malloc(sizeof(struct LinkedList));
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    return list;
}

bool addToList(struct LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    newNode->creation_time = time(NULL);

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->size++;

    deleteOlderNodes(list);

    return true;
}

