```cpp
#include <openssl/md5.h>
#include <string>
#include <cstddef>

std::string getMD5Hash(const std::string& data) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data.c_str(), data.length());
    MD5_Final(digest, &ctx);

    std::string result;
    for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        char str[3];
        sprintf(str, "%02x", digest[i]);
        result += str;
    }
    return result;
}
