[' Here is a skeleton implementation for the given task in C#. I've used `System.IO`, `System.Security.Cryptography` and `System.Threading.Tasks` namespaces to accomplish the functionalities.

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using log4net;

public class FileIntegrityChecker
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(FileIntegrityChecker));

    private readonly int _maxFileSize;
    private readonly TimeSpan _timeout;
    private readonly int _loggingVerbosity;

    public FileIntegrityChecker(int maxFileSize, TimeSpan timeout, int loggingVerbosity)
    {
        _maxFileSize = maxFileSize;
        _timeout = timeout;
        _loggingVerbosity = loggingVerbosity;
    }

    public async Task<HashCode> ComputeHashAsync(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("File not found", filePath);

        if (File.ReadAllBytes(filePath).Length > _maxFileSize)
            throw new ArgumentException("File size exceeds the maximum allowed file size", nameof(filePath));

        using (var sha256 = SHA256.Create())
        {
            await Task.Run(() =>
            {
                var hashBytes = new byte[sha256.HashSize];
                using (var stream = File.OpenRead(filePath))
                {
                    var buffer = new byte[4096];
                    int bytesRead;

                    while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        sha256.TransformBlock(buffer, 0, bytesRead, hashBytes, 0);
                    }

                    sha256.TransformFinalBlock(hashBytes, 0, hashBytes.Length);
                }
            }, CancellationToken.None);

            return new HashCode(hashBytes);
        }
    }

    public void ConcurrentlyComputeHashes(IEnumerable<string> filePaths)
    {
        var tasks = from filePath in filePaths
                    select ComputeHashAsync(filePath).ContinueWith(_ => _log.DebugFormat("Hash of '{0}': {1}", filePath, _.Result));

        Task.WhenAll(tasks);
    }

    // Add other methods as needed for configuration, resource efficiency, error handling, integration, scalability, usability and testing.
}
```

This code initializes a FileIntegrityChecker object with configurable settings like maxFileSize, timeout and logging verbosity. The ComputeHashAsync method calculates the SHA-256 hash for a given file path asynchronously while handling large files efficiently. The ConcurrentlyComputeHashes method computes hashes for multiple files concurrently.

You can replace the existing log4net implementation with your preferred logging library and adjust the functionalities as per your project requirements.']

