public class ConfigurationLoader {
    private static final Logger LOGGER = Logger.getLogger(ConfigurationLoader.class.getName());

    public <T> T loadConfiguration(byte[] configBytes, Class<T> clazz, T defaultInstance) throws IOException, ClassNotFoundException, InstantiationException, IllegalAccessException, InvocationTargetException, ConfigurationLoadException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(configBytes))) {
            return (T) ois.readObject();
        } catch (ClassCastException e) {
            throw new ConfigurationLoadException("Failed to cast deserialized object to specified class.", e);
        } catch (StreamCorruptedException | ClassNotFoundException e) {
            LOGGER.severe("Deserialization failed: " + e.getMessage());
            throw new ConfigurationLoadException("Deserialization failed: " + e.getMessage(), e);
        }
    }

    public static <T> T loadConfigurationOrDefault(byte[] configBytes, Class<T> clazz, T defaultInstance) {
        try {
            return loadConfiguration(configBytes, clazz, defaultInstance);
        } catch (ConfigurationLoadException e) {
            LOGGER.warning("Failed to load configuration: " + e.getMessage());
            return defaultInstance;
        }
    }
}
