["```javascript
const axios = require('axios'); // Import required libraries
const FormData = require('form-data'); // For handling file uploads
require('dotenv').config(); // For environment variables

const API_URL = 'https://file-storage-api.com'; // Replace with your file storage service API URL
const HEADERS = {
  'Authorization': `Bearer ${process.env.API_KEY}` // Replace with your API key or access token
};

async function uploadFileFromURL(url, destination) {
  try {
    const response = await axios.head(url);
    const fileSize = response.headers['content-length'];
    const chunkSize = Math.max(Math.min(1e6, fileSize), 1e5); // Optimize for 1MB or more chunks
    let totalChunks = Math.ceil(fileSize / chunkSize);
    let currentChunkIndex = 0;
    let uploadAttempt = 0;

    const formData = new FormData();
    formData.append('file', await axios.get(url, { responseType: 'stream' }).then(res => res.data)); // Get the file content as a stream

    const intervalId = setInterval(() => {
      if (uploadAttempt >= 3) {
        clearInterval(intervalId);
        throw new Error('Upload failed');
      }

      axios({
        url: `${API_URL}/upload`,
        method: 'post',
        headers: HEADERS,
        data: formData,
        maxContentLength: Infinity, // For chunked uploads
        maxRedirects: 0,
        onUploadProgress: progressEvent => {
          const uploadSpeed = (progressEvent.loaded / progressEvent.total) * totalChunks;
          const estimatedDuration = (uploadAttempt === 0 ? fileSize : uploadSpeed - (uploadSpeed * currentChunkIndex)) / uploadSpeed;
          console.log(`Attempt ${uploadAttempt + 1}: Uploaded ${(currentChunkIndex / totalChunks) * 100}%, Estimated time remaining: ${estimatedDuration} seconds`);
        }
      })
      .then(() => {
        clearInterval(intervalId);
        console.log(`Upload successful! Final upload URL: ${destination}`);
      })
      .catch((error) => {
        console.error(`Attempt ${uploadAttempt + 1}: Upload failed with error: ${error.message}`);
        uploadAttempt++;
        currentChunkIndex = 0;
      })
      .finally(() => {
        currentChunkIndex++;
      });
    }, 5000); // Retry every 5 seconds if a failure occurs

    return { finalUploadUrl: destination, estimatedDuration: uploadAttempt === 0 ? (fileSize / chunkSize) / (uploadSpeed * totalChunks) : null };
  } catch (error) {
    console.error(`Error while retrieving file metadata from URL: ${error.message}`);
    throw error;
  }
}
```

This JavaScript function takes a source URL and destination for the uploaded file as arguments, and integrates with an existing file storage API to handle the upload of files. It supports chunked uploads for large files, robustly handles network connectivity issues, implements a retry mechanism for failed uploads up to three times, logs detailed status updates for each attempt, and provides users with a progress indicator. The function also accounts for potential discrepancies in file metadata retrieval from the source URL by implementing a fallback mechanism to ensure accurate metadata assignment upon successful upload. Lastly, it returns a summary report including the final upload URL, estimated upload duration, and any encountered errors during the process."]

