const { v4: uuidv4 } = require('uuid');

function executeCommand(command, options) {
  // Validate input parameters
  if (!command || !options) {
    throw new Error('Missing required input: command or options.');
  }

  const commandLineUtilityUrl = 'http://external-utility.com/execute'; // Replace with actual URL of the external command-line utility

  return axios.post(commandLineUtilityUrl, { command }, { params: options })
    .then((response) => {
      // Handle successful response from the external command-line utility
      const result = response.data;
      const output = processOutput(result); // Replace with your own function to process output if needed
      return { result, output };
    })
    .catch((error) => {
      // Handle errors during execution of the external command-line utility
      throw new Error(`Error executing command: ${error.message}`);
    });
}

function hashInput(algorithm, input) {
  // Validate input parameters
  if (!algorithm || !input) {
    throw new Error('Missing required input: algorithm or input.');
  }

  const hashingAlgorithm = crypto[algorithm]; // Use the provided algorithm for hashing

  return new Promise((resolve, reject) => {
    hashingAlgorithm(input, (err, hash) => {
      if (err) {
        // Handle errors during hashing process
        reject(new Error(`Error hashing input: ${err.message}`));
      } else {
        resolve(hash); // Return the hashed input
      }
    });
  });
}

function generateRandomString(length) {
  // Generate a random alphanumeric string of specified length
  return Array.from(crypto.randomBytes(length)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

// Usage example:
executeCommand('ls', { cwd: '/path/to/directory' })
  .then(({ result, output }) => {
    const randomString = generateRandomString(16);
    const hashedResult = hashInput('sha256', result).then((hash) => hash.toString('hex')); // Use your preferred hashing algorithm and format here
    return Promise.all([hashedResult, randomString]).then(([hashedResult, randomString]) => {
      console.log(`Hashed result: ${hashedResult}`);
      console.log(`Random string: ${randomString}`);
      // Return the hashed result and random string for further processing in the application
    });
  })
  .catch((error) => {
    console.error(error.message);
  });
