use std::env;
use std::path::Path;
use std::io::{Read, Write};
use tokio::fs::File;
use tokio::task::spawn;
use regex::Regex;

const CONFIG_FILE: &str = ".config";

async fn process_file(filename: String) {
    let (ext, _) = filename.rsplit('.').collect::<Vec<&str>>().into_iter().last().unwrap_or("");
    let mut new_ext = match ext {
        "txt" | "log" => "json",
        "csv" => "parquet",
        _ => "unknown",
    };
    if filename.contains('-') && (filename.len() - filename[..filename.find('-').unwrap()].rfind('-').unwrap() - 1) as u32 >= 3 {
        new_ext = match &filename[..filename.find('-').unwrap()] {
            "error" => "log",
            _ => "",
        }.to_string();
    }

    let new_filename = format!("{}__{}.{}", filename[..filename.find('-').unwrap()], timestamp(), &new_ext);

    if let Ok(mut file) = File::open(&filename).await {
        let mut content = String::new();
        file.read_to_string(&mut content).await.expect("Failed to read file");

        // Perform I/O operations with the content here

        if let Ok(mut new_file) = File::create(&new_filename).await {
            new_file.write_all(content.as_bytes()).await.expect("Failed to write file");
        }
    }
}

async fn timestamp() -> String {
    use chrono::{Utc, DateTime};
    let dt: DateTime<Utc> = Utc::now();
    format!("{}{}{}", dt.year(), dt.month(), dt.day())
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        println!("Usage: {} FILE", args[0]);
        return;
    }

    let config_file_path = format!("{}/{}", env::current_dir().unwrap().into_os_string().into_string(), CONFIG_FILE);

    if let Ok(mut file) = File::open(&config_file_path).expect("Could not open configuration file") {
        let mut config = String::new();
        file.read_to_string(&mut config).expect("Failed to read configuration file");

        // Parse and adapt the configuration based on your needs

        let tasks: Vec<String> = config.lines().map(|line| line.to_owned()).collect();

        for task in &tasks {
            spawn(process_file(task.clone()));
        }
    } else {
        println!("Configuration file not found");
    }

    // Handle any other command-line arguments or errors here
}
