fn read_config(path: PathBuf) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
    let file = File::open(&path)?;
    let reader = BufReader::new(file);
    let mut map = HashMap::new();
    let mut ns_ctx = NamespaceContext::new();
    let mut reader = EventReader::new(reader, &ns_ctx);
    for event in reader {
        match event? {
            XmlEvent::StartElement { name, .. } if name == TILE_LAYOUT => {
                let mut nested = false;
                for event in reader.into_inner() {
                    match event? {
                        XmlEvent::StartElement { ref name, .. } if name == NFAPI_CRC_INDICATION_PDU_T => {
                            map.insert(name.local_name().to_owned(), String::new());
                            nested = true;
                        },
                        XmlEvent::Text(ref text) => {
                            if let Some(key) = map.get_mut(&TILE_LAYOUT) {
                                key.clear();
                                if nested {
                                    if let Some(val) = text {
                                        map.insert(name.local_name().to_owned(), val.into());
                                    }
                                } else {
                                    key.push_str(text);
                                }
                            }
                        },
                        _ => (),
                    }
                }
            },
            _ => (),
        }
    }

    if map.get(MAX_OVERLAPS).is_none() {
        return Err("Missing MaxOverlaps parameter in the configuration file.".into());
    }

    Ok(map)
}

