['```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Azure.ServiceBus;

public class Character
{
    private readonly Queue<string> _attackCommands;
    private readonly Dictionary<string, TimeSpan> _cooldownStatus;
    private readonly ITopicClient _serviceBusClient;
    private readonly string _sqlCommandTemplate;
    private Timer _cooldownTimer;

    public Character(string connectionToken, List<string> attackCommands, string sqlCommandTemplate, TimeSpan cooldownPeriod, ITopicClient serviceBusClient)
    {
        _attackCommands = new Queue<string>(attackCommands);
        _cooldownStatus = new Dictionary<string, TimeSpan>();
        _sqlCommandTemplate = sqlCommandTemplate;
        _serviceBusClient = serviceBusClient;
        _cooldownPeriod = cooldownPeriod;
    }

    public IDataReader ExecuteRandomAttack()
    {
        var random = new Random();
        var attackIndex = random.Next(_attackCommands.Count);
        var attackCommand = _attackCommands.Dequeue();

        if (_cooldownStatus.ContainsKey(attackCommand))
            throw new InvalidOperationException($"Attack '{attackCommand}' is on cooldown.");

        var uniqueId = Guid.NewGuid().ToString();
        _cooldownStatus[attackCommand] = DateTimeOffset.UtcNow + _cooldownPeriod;

        var sqlCommand = string.Format(_sqlCommandTemplate, attackIndex, uniqueId);

        ExecuteWithRetry(ExecuteSqlCommand, sqlCommand);

        Console.WriteLine($"Selected attack: {attackIndex}, ID: {uniqueId}");

        return ExecuteSqlCommand(sqlCommand);
    }

    private void ExecuteWithRetry(Action action, string command)
    {
        int retryCount = 3;
        TimeSpan delay = TimeSpan.FromMilliseconds(200);

        Action retryAction = () =>
        {
            try
            {
                action();
            }
            catch (Exception ex)
            {
                if (retryCount-- > 0)
                    Task.Delay((int)delay.TotalMilliseconds).ContinueWith(_ => ExecuteWithRetry(action, command));
            }
        };

        retryAction();
    }

    private IDataReader ExecuteSqlCommand(string sqlCommand)
    {
        var connection = _serviceBusClient.CreateConnectionCommand(_connectionToken);
        using (var broker = new BrokeredMessageReceiver(connection))
        {
            var commandText = $"DBContext key='{sqlCommand}'";
            broker.Send(new BrokeredMessage(commandText)
            {
                ContentType = "text/plain",
                TimeToLive = TimeSpan.FromMinutes(1)
            });

            var sqlConnection = new SqlConnection(broker.Receive().GetBody<string>());
            return sqlConnection.CreateCommand().ExecuteReader();
        }
    }
}
```
