public IDataReader insertOrUpdatePduRecords(List<NFAPI_CRC_INDICATION_PDU_T> pdus, SqlConnection connection, string command) {
    using (var transaction = connection.BeginTransaction()) {
        try {
            var parameters = new List<SqlParameter>();
