                parameters.Add(new SqlParameter("@crcIndicationRel8Tag", pdu.crcIndicationRel8Tag));

                command = command.Replace("@param" + index++, string.Format("[{0}]", parameters[index - 1].Value));
            }

            using (var commandObject = new SqlCommand(command, transaction)) {
                commandObject.Parameters.AddRange(parameters.ToArray());
                return commandObject.ExecuteReader();
            }
        } catch (Exception ex) {
            transaction.Rollback();
            throw ex;
