struct array_context *create_array(size_t n) {
    struct array_context *ctx = malloc(sizeof(struct array_context));
    if (!ctx) {
        perror("malloc failed");
        return NULL;
    }

    ctx->data = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ctx->data) {
        perror("calloc failed");
        free(ctx);
        return NULL;
    }

    ctx->capacity = n;
    ctx->size = 0;
    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

void destroy_array(struct array_context *ctx) {
    if (ctx && ctx->data) {
        free(ctx->data);
        pthread_mutex_destroy(&ctx->mutex);
        free(ctx);
    }
}

void add_to_array(struct array_context *ctx, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&ctx->mutex);

    if (ctx->size >= ctx->capacity) {
        printf("Array is full. Increase capacity.\n");
        pthread_mutex_unlock(&ctx->mutex);
        return;
    }

    memcpy(ctx->data + ctx->size, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++ctx->size;

    pthread_mutex_unlock(&ctx->mutex);
}

void serialize(const struct array_context *ctx, FILE *fp) {
    size_t i;
    fwrite(&ctx->capacity, sizeof(size_t), 1, fp);
    for (i = 0; i < ctx->size; ++i) {
        fwrite(ctx->data + i, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
}

struct array_context *deserialize(FILE *fp) {
    size_t n, i;
    struct array_context *ctx = create_array(0);
    if (!ctx) return NULL;

    fread(&n, sizeof(size_t), 1, fp);
    ctx->capacity = n;
    ctx->data = realloc(ctx->data, ctx->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (i = 0; i < n; ++i) {
        fread(ctx->data + i, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
    ctx->size = n;

    return ctx;
}
