int create_dynamic_list(dynamic_list **list, dynamic_cell_id cell_id) {
    *list = malloc(sizeof(dynamic_list));
    if (!*list) return 1;

    (*list)->size = 0;
    (*list)->cell_id = cell_id;
    pthread_mutex_init(&(*list)->lock, NULL);
    (*list)->elements = NULL;

    return 0;
}

void destroy_dynamic_list(dynamic_list *list) {
    if (list->elements) {
        free(list->elements);
        list->elements = NULL;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_dynamic_list(dynamic_list *list, LTE_RRC_CU_MESSAGE_ID id, RRC_STATE_TYPE state) {
    dynamic_list_element *new_element;

    new_element = malloc(sizeof(dynamic_list_element));
    if (!new_element) return 1;

    srand(time(NULL));
    new_element->tag.ue_id = rand();

    pthread_mutex_lock(&list->lock);
    if (list->size >= LIST_CAPACITY) {
        dynamic_list_element *temp = realloc(list->elements, sizeof(dynamic_list_element) * (list->size * 2));
        if (!temp) {
            pthread_mutex_unlock(&list->lock);
            free(new_element);
            return 1;
        }
        list->elements = temp;
    }

    new_element->id = id;
    new_element->state = state;
    new_element->tag.cell_id = list->cell_id;
    list->elements[list->size] = *new_element;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int get_dynamic_list_element(const dynamic_list *list, size_t index, dynamic_list_element *out) {
    if (index >= list->size) return 1;

    pthread_mutex_lock(&list->lock);
    memcpy(out, &list->elements[index], sizeof(dynamic_list_element));
    pthread_mutex_unlock(&list->lock);

    return 0;
}
