from concurrent.futures import ThreadPoolExecutor
import logging
from your_framework import ResourceManager, LoggingAdapter

def get_file_size(file_path):
    try:
        return os.path.getsize(file_path)
    except Exception as e:
        log.error(f"Error while getting file size of {file_path}: {e}")
        return None

def md5_hash(file_path, chunk_size=65536):
    if get_file_size(file_path) is None or get_file_size(file_path) > ResourceManager.get_config('MAX_FILE_SIZE'):
        confirmation = input(f"File '{file_path}' exceeds the specified maximum size of {ResourceManager.get_config('MAX_FILE_SIZE')}. Proceed? (y/n): ")
        if confirmation.lower() != 'y':
            return None

    hasher = hashlib.md5()
    file = open(file_path, "rb")

    def update_hash(chunk):
        hasher.update(chunk)

    with ThreadPoolExecutor(max_workers=ResourceManager.get_config('THREADS')) as executor:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            executor.submit(update_hash, chunk)

    file.close()
    return hasher.hexdigest()

log = LoggingAdapter(logging.getLogger(__name__))

def main():
    # Use your_framework.ResourceManager to get configuration and handle resources
    log.info("Starting MD5 hashing...")
    file_path = sys.argv[1]
    hash = md5_hash(file_path)
    if hash:
        log.info(f"MD5 hash of '{file_path}': {hash}")
    else:
        log.error("Failed to calculate MD5 hash.")

if __name__ == "__main__":
    main()
