import os
import sys
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
from functools import lru_cache
import shutil
import stat
import time
import tqdm

class SafePath:
    def __init__(self, path):
        self.path = os.path.abspath(os.path.expanduser(path))
        if not os.path.exists(self.path) or not os.access(self.path, os.R_OK):
            raise FileNotFoundError(f"Path '{self.path}' is invalid or does not exist.")

    def __str__(self):
        return self.path

@lru_cache(maxsize=None)
def get_md5(filepath):
    with open(filepath, 'rb') as f:
        m = hashlib.md5()
        while True:
            data = f.read(65536)
            if not data:
                break
            m.update(data)
        return m.hexdigest()

def verify_checksum(filepath, checksum):
    computed_checksum = get_md5(filepath)
    return computed_checksum == checksum

def process_file(filepath, checksum, progress_callback):
    file = SafePath(filepath)
    if not verify_checksum(file, checksum):
        print(f"File '{file}' requires rehashing")
        shutil.copy2(file, f"{file}.processing")
        return get_md5(f"{file}.processing"), progress_callback({"status": "Rehashing", "file": file})
    else:
        print(f"File '{file}' is up-to-date")
        return None, progress_callback({"status": "Up-to-date", "file": file})

def process_files(filepaths, checksums, progress_callback, worker_count=None):
    if not worker_count:
        worker_count = min(len(filepaths), os.cpu_count() * 2)
    executor = ThreadPoolExecutor(max_workers=worker_count)
    results = [executor.submit(process_file, filepath, checksum, progress_callback) for filepath, checksum in zip(filepaths, checksums)]
    finished_results = []
    for future in as_completed(results):
        result = future.result()
        finished_results.append(result)
    return finished_results

def main():
    filepaths = [
        "/path/to/largefile1",
        "/path/to/largefile2",
        # Add more paths here
    ]
    checksums = [
        "d41d8cd98f00b204e9800998ecf8427e",  # MD5 hash of empty file for example
        # Add more checksums here
    ]

    progress_callback = lambda data: print(data)

    results = process_files(filepaths, checksums, progress_callback)

if __name__ == "__main__":
    main()
```
