static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_elements = 0;
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;
static LOG_ENTRY_T *log = NULL;
static size_t log_capacity = 0;
static size_t log_index = 0;

void create_and_populate_list(size_t N) {
    if (N > MAX_ELEMENTS || num_elements + N > MEMORY_THRESHOLD / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Requested size exceeds memory threshold or system limitations.\n");
        return;
    }

    // Generate random RNTI and CRCFLAG values
    uint32_t rnti, crcflag;

    // Allocate list and log memory
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, (num_elements + N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) {
        perror("Failed to allocate memory for the list.\n");
        return;
    }
    list = new_list;

    LOG_ENTRY_T *new_log = realloc(log, (log_capacity + N) * sizeof(LOG_ENTRY_T));
    if (!new_log) {
        perror("Failed to allocate memory for the log.\n");
        free(new_list);
        list = NULL;
        return;
    }
    log = new_log;
    log_capacity += N;

    pthread_mutex_lock(&list_mutex);
    num_elements += N;
    pthread_mutex_unlock(&list_mutex);

    for (size_t i = num_elements - 1; i < num_elements; --i) {
        rnti = rand() % ((1 << 24) - 1); // Generate RNTI value within valid range

        bool unique_rnti = true;
        for (size_t j = 0; j < i; ++j) {
            if (list[j].rnti == rnti) {
                unique_rnti = false;
                break;
            }
        }

        if (unique_rnti) {
            crcflag = rand() % 2; // Generate CRCFLAG value, either 0 or 1

            list[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG__UE_ID_RNTI;
            list[i].rnti = rnti;
            list[i].crc_indication.tag = CRC_INDICATION_REL8_TAG__CRCFLAG;
            list[i].crc_indication.crcflag = crcflag;

            pthread_mutex_lock(&log_mutex);
            log[log_index].timestamp = time(NULL);
            log[log_index].index = i;
            ++log_index;
            pthread_mutex_unlock(&log_mutex);
        }
    }
}
