#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <limits.h>

typedef struct {
    char name[256];
    int num_scores;
    int *scores;
    char comment[256];
} StudentRecord;

bool is_valid_score(int score) {
    return (score >= 0 && score <= 100);
}

void add_score(StudentRecord* student, int score) {
    if (!is_valid_score(score)) {
        fprintf(stderr, "Invalid score: %d\n", score);
        return;
    }
    student->scores = realloc(student->scores, (student->num_scores + 1) * sizeof(int));
    student->scores[student->num_scores] = score;
    student->num_scores++;
}

float calculate_average_excluding_min(StudentRecord* student) {
    if (student->num_scores == 0) return 0.0f;

    int min_index, i;
    float avg = 0.0f, temp_avg;

    min_index = 0;
    for (i = 1; i < student->num_scores; ++i) {
        if (student->scores[min_index] > student->scores[i]) {
            min_index = i;
        }
    }

    temp_avg = student->scores[min_index];
    for (i = 0; i < student->num_scores; ++i) {
        if (i == min_index) continue;
        avg += student->scores[i];
    }

    return avg / (student->num_scores - 1);
}

void* process_record(void *data) {
    FILE *file = data;
    StudentRecord *student = malloc(sizeof(StudentRecord));
    memset(student, 0, sizeof(*student));

    char line[4096];
    int score;
    bool in_record = false;

    while (fgets(line, sizeof(line), file)) {
        if (!in_record) {
            sscanf(line, "%[^,],%*c", student->name);
            in_record = true;
            continue;
        }

        sscanf(line, "%d,%255[^\n]", &score, student->comment);

        if (is_valid_score(score)) {
            add_score(student, score);
        } else {
            fprintf(stderr, "Invalid score: %d\n", score);
        }
    }

    free(student->scores);
    student->scores = NULL;
    free(student);
    return NULL;
}

int main() {
    pthread_t threads[4];
    FILE *file = fopen("students.csv", "r");

    if (!file) {
        perror("Error opening file");
        return 1;
    }

    size_t num_threads = sysconf(_SC_NPROCESSORS_CONF);
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    size_t chunk_size = (int)ftell(file)/num_threads;
    fseek(file, 0, SEEK_SET);

    for (size_t i = 0; i < num_threads; ++i) {
        void* start_pos = ftello(file) + i * chunk_size;
        void* end_pos = ftello(file) + ((i == num_threads - 1)? ftell(file) : (i + 1) * chunk_size);
        pthread_create(&threads[i], &attr, process_record, fsetpos(file, (fpos_t*)start_pos));
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);

    return 0;
}
```

