typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct pool {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    void* log_service; // Integration point for external logging service
};

void init_pool(struct pool* pool, size_t capacity, void* log_service) {
    pool->capacity = capacity;
    pool->count = 0;
    pool->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pool->not_empty = PTHREAD_COND_INITIALIZER;
    pool->log_service = log_service;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(struct pool* pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->count == pool->capacity) {
        pthread_cond_wait(&pool->not_empty, &pool->lock);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->data[pool->count];
    // Populate the structure with valid data
    pdu->tag.tag_field1 = 0x1234;
    pdu->tag.tag_field2 = 0x5678;
    pdu->rnti = rand() % MAX_RNTI_VALUE;
    pdu->crc_indication.crci = rand() % MAX_CRC_INDICATION_REL8_TAG_VALUE;
    pdu->crcflag = rand() % 2;

    pool->count++;
    pthread_mutex_unlock(&pool->lock);

    // Report performance and resource utilization metrics
    if (pool->log_service) {
        report_metrics(pool->log_service, pool->count, pool->capacity);
    }

    return pdu;
}

void put_pdu(struct pool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Reset the structure to a known state before reusing
        pool->data[pool->count] = *pdu;
        pool->count++;
    } else {
        pthread_cond_signal(&pool->not_empty);
    }
    pthread_mutex_unlock(&pool->lock);
}
