pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
node_t* head = NULL;
size_t list_length = 0;
size_t memory_usage = 0;

void init_list() {
    if (memory_usage + sizeof(node_t) > MEMORY_THRESHOLD) {
        printf("Memory threshold exceeded, clearing list\n");
        clear_list();
    }
}

void clear_list() {
    node_t *current = head;
    while (head != NULL) {
        current = head;
        head = head->next;
        free(current);
        memory_usage -= sizeof(node_t);
    }
    head = NULL;
    list_length = 0;
}

void push_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
