                    goto cleanup;
                }
            } else if (num_elements > sizeof(LTEPHYTIMER_T) * 1024) {
                log_message("Exceeded maximum allowed timer count (1024).\n");
                goto cleanup;
            }

            memcpy(&phy_timers[num_timers], fetch_result, sizeof(LTEPHYTIMER_T));
            num_timers++;
        } else {
            log_message("Failed to fetch configuration data.\n");
            sleep(1); // Retry after a short delay
            num_timers++;
        }
    }

    if (!phy_timers) {
        log_message("Failed to initialize timers after maximum retries.\n");
        goto cleanup;
    }

    log_message("Successfully initialized %d LTE PHY timers.\n", num_timers);

cleanup:
    if (fetch_result) {
        free(fetch_result);
    }
    if (phy_timers) {
        free(phy_timers);
    }

    return num_timers;
}
```

