    AES_KEY aeskey;
    AES_set_encrypt_key(key, 128, &aeskey);
    AES_DECcrypto_cfb8(pdu->decrypted_data, &ciphertext, ciphertext_len, &aeskey, iv, padding);

    // Validate the decrypted data and CRC checksum
    uint32_t calculated_crc = crc32(0, pdu->decrypted_data, pdu->data_len);
    if (calculated_crc != pdu->crc_indication.crc) {
        // Data integrity check failed, clean up and return NULL
        free(pdu);
        free(ciphertext);
        return NULL;
    }

    // Fetch metadata associated with the CRC indication tag (potentially asynchronous operation)
    bool metadata_fetch_success = false;
    (*metadata_fetcher)(pdu, &metadata_fetch_success);

    if (!metadata_fetch_success) {
        // Temporary failure fetching metadata, handle retries or error propagation
    }

    // Handle the processed PDU and manage memory according to the given bounds and performance considerations
    size_t num_pdu = 1;
    while (num_pdu < 1024 && (ciphertext + ciphertext_len + sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu) <= pdu) {
        num_pdu++;
        // Move the decrypted data and increment the PDU pointer for subsequent elements
        memmove(pdu->decrypted_data, pdu->decrypted_data + pdu->data_len, ciphertext_len);
        pdu->crc_indication.crc = crc32(0, pdu->decrypted_data, pdu->data_len);
        pdu++;

        // Decrypt the next chunk of data and continue the validation process
        ciphertext += AES_BLOCK_SIZE;
        ciphertext_len -= AES_BLOCK_SIZE;
    }

    if (num_pdu > 512) {
        // Allocate a new buffer when exceeding 512 elements to minimize reallocations
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = realloc(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu);

        if (!new_pdu) {
            // Memory allocation failed, clean up and return NULL
            free(ciphertext);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }

        pdu = new_pdu;
    }

    return pdu;
}
