public class StateLoader {
    private static final Logger LOGGER = Logger.getLogger(StateLoader.class.getName());

    public <T extends MoSTState> List<T> loadStateFromFile(String filePath, Map<Class<? extends MoSTState>, ClassLoader> classLoaders) throws IOException, ClassNotFoundException {
        Objects.requireNonNull(filePath);
        Objects.requireNonNull(classLoaders);

        Path path = Path.of(filePath);
        if (!Files.exists(path)) {
            throw new FileNotFoundException("File not found: " + filePath);
        }

        try (LinkOption[] linkOptions = new LinkOption[1];
             Stream<Path> paths = Files.walk(path, 1, linkOptions)) {
            if (!Files.isRegularFile(paths.findAny().orElseThrow(() -> new IllegalStateException("File is not a regular file.")))) {
                throw new IllegalArgumentException("File is not a regular file.");
            }
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            List<T> states = new ArrayList<>();
            while (true) {
                try {
                    T state = (T) ois.readObject();
                    if (!states.contains(state)) {
                        states.add(state);
                    }
                } catch (EOFException e) {
                    break;
                } catch (ClassNotFoundException | ClassCastException e) {
                    LOGGER.warning("Ignoring invalid object in the file: " + e.getMessage());
                }
            }
            return states;
        } catch (IOException e) {
            throw new RuntimeException("I/O error reading from file: " + filePath, e);
        }
    }
}

