char *generateTrafficLogFileName(const char *filename, const char *logLevel, time_t timestamp, int sessionId) {
    static char logDirectory[40];
    static char logFile[256];

    struct tm *currentTime = localtime(&timestamp);

    snprintf(logDirectory, sizeof(logDirectory), "/logs/%04d-%02d-%02d", currentTime->tm_year + 1900, currentTime->tm_mon + 1, currentTime->tm_mday);

    if (mkdir(logDirectory, S_IRWXU | S_IRGRP | S_IROTH | S_IXGRP | S_IXOTH) != 0 && errno != EEXIST) {
        perror("Error creating log directory");
        return NULL;
    }

    snprintf(logFile, sizeof(logFile), "%s/%d-%s-%s.%s%ld", logDirectory, sessionId, logLevel, ctime(&timestamp), logLevel + 1, timestamp);

    // Ensure that the log file name is valid and no buffer overflow occurs
    if (strlen(logFile) >= sizeof(logFile)) {
        perror("Log file name too long");
        return NULL;
    }

    return strdup(logFile);
}
