static unsigned int capacity = 1000; // Default initial capacity
static unsigned int count = 0;       // Total number of structures generated
static unsigned int max_capacity = 1000000; // Maximum capacity for the list

// Thread-safe function to initialize a new node with given data
void create_node(struct node **head, NFAPI_CRC_INDICATION_PDU_T data) {
    struct node *new_node = malloc(sizeof(struct node));
    if (!new_node) return; // Memory allocation failed, bail out gracefully

    pthread_mutex_init(&(new_node->lock), NULL);
    new_node->data = data;
    new_node->next = *head;
    *head = new_node;
}

// Function to query the list's contents, iterating over elements and retrieving specific information
void for_each(void (*fn)(NFAPI_CRC_INDICATION_PDU_T), struct node *head) {
    struct node *current = head;
    pthread_mutex_t lock; // Borrow a mutex from the first node in the list
    pthread_mutex_init(&lock, NULL);

    while (current != NULL) {
        pthread_mutex_lock(&(current->lock));

        if (current != head)
            pthread_mutex_unlock(&lock); // Unlock after acquiring the first mutex if not first node

        (*fn)(current->data);
        current = current->next;

        if (current != NULL)
            pthread_mutex_lock(&(current->lock));
    }

    pthread_mutex_destroy(&lock); // Destroy the borrowed mutex after iterating through the list
}

// Thread-safe function to dynamically resize the linked list based on current capacity and number of structures added
void resize() {
    struct node **head = NULL;
    unsigned int new_capacity = (count + 1) * 2; // Increase by factor of 2 when resizing

    if (new_capacity > max_capacity)
        new_capacity = max_capacity;

    if (new_capacity <= capacity) return; // No need to resize, current capacity is sufficient

    struct node *current = head;
    sem_t lock; // Borrow a mutex from the first node in the list
    pthread_mutex_init(&lock, NULL);

    while (current != NULL) {
        pthread_mutex_lock(&(current->lock));

        struct node *temp = current;
        current = current->next;
        temp->next = head;
        head = temp;

        if (current != NULL)
            pthread_mutex_lock(&(current->lock));
    }

    for (unsigned int i = new_capacity - count - 1; i > 0; --i) {
        create_node(&head, (NFAPI_CRC_INDICATION_PDU_T){
            .RX_UE_INFORMATION_TAG = ++count,
            .RNTI = rand(),
            .CRC_INDICATION_REL8_TAG = rand(),
            .CRCFLAG = rand() % 2 == 0 ? true : false,
        });
    }

    pthread_mutex_destroy(&lock); // Destroy the borrowed mutex after resizing
}

// Thread-safe function to add a new element to the list, ensuring no duplicate RNTIs are added
void push(NFAPI_CRC_INDICATION_PDU_T data) {
    struct node *current = head;
    sem_t lock; // Borrow a mutex from the first node in the list
    pthread_mutex_init(&lock, NULL);

    while (current != NULL && current->data.RNTI == data.RNTI) {
        // If duplicate RNTIs are found during iteration, bail out and skip adding duplicates
        if (current->next != NULL)
            pthread_mutex_lock(&(current->next)->lock);

        pthread_mutex_unlock(&lock);
        current = current->next;
    }

    // Resize the list if needed after adding an element
    if (count == capacity) resize();

    create_node(&head, data);
    count++;

    pthread_mutex_destroy(&lock); // Destroy the borrowed mutex after adding the element
}
