#include "nfapi_crc_list.h"
#include <time.h>

static uint32_t unique_idx = 0;
static const int max_capacity = 10000;

Node* init_list() {
    Node* head = malloc(sizeof(Node));
    if (!head) {
        return NULL;
    }
    head->next = NULL;
    return head;
}

bool add_node(Node** head, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return false;
    }
    if (unique_idx >= max_capacity) {
        free(new_node);
        return false;
    }
    new_node->data = *data;
    new_node->data.RNTI += unique_idx++;
    new_node->next = NULL;

    Node* current = *head;
    if (!current->next) {
        current->next = new_node;
    } else {
        Node* trav = current->next;
        while (trav && trav->next && trav->next->data.RNTI <= data->RNTI) {
            trav = trav->next;
        }
        new_node->next = trav->next;
        trav->next = new_node;
    }

    return true;
}

Node* traverse_list(const Node* head, uint16_t RNTI) {
    const Node* current = head->next;
    while (current && current->data.RNTI != RNTI) {
        current = current->next;
    }
    return (Node*) current;
}

void destroy_list(Node** head) {
    Node* temp;
    while ((*head)) {
        temp = (*head)->next;
        free(*head);
        *head = temp;
    }
}

