            std::cerr << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
            return;
        }

        // Create the results table if it doesn't exist
        char *zErrMsg = nullptr;
        const char *sqlCreateTable =
            "CREATE TABLE IF NOT EXISTS lte_pdsch (" \
            "id INTEGER PRIMARY KEY AUTOINCREMENT," \
            "validDMRSIndicator BOOLEAN," \
            "resourceGridPosition INTEGER," \
            "ri INTEGER," \
            "timestampOffset INTEGER);";
        if (sqlite3_exec(db, sqlCreateTable, nullptr, nullptr, &zErrMsg) != SQLITE_OK) {
            std::cerr << "SQL error: " << zErrMsg << std::endl;
            sqlite3_free(zErrMsg);
        }
    }

    ~LTE_PDSCH_Manager() {
        sqlite3_close(db);
    }

    void addResult(const PDSCH_Result& result) {
        std::lock_guard<std::mutex> lock(dataMutex);
        results.push_back(result);

        // Insert the result into the SQLite database
        char *zErrMsg = nullptr;
        const char *sqlInsert = "INSERT INTO lte_pdsch (validDMRSIndicator, resourceGridPosition, ri, timestampOffset) VALUES (" \
            + std::to_string(result.validDMRSIndicator) + ", " + std::to_string(result.resourceGridPosition) + ", " + std::to_string(result.ri) + ", " + std::to_string(result.timestampOffset) + ");";
        if (sqlite3_exec(db, sqlInsert, nullptr, nullptr, &zErrMsg) != SQLITE_OK) {
            std::cerr << "SQL error: " << zErrMsg << std::endl;
            sqlite3_free(zErrMsg);
        }
    }

    void updateResult(const PDSCH_Result& result, int index) {
        std::lock_guard<std::mutex> lock(dataMutex);

        // Update the SQLite database entry at the specified index
        auto it = results.begin();
        std::advance(it, index);

        if (index >= 0 && index < results.size()) {
            PDSCH_Result& existingResult = *it;
            it->validDMRSIndicator = result.validDMRSIndicator;
            it->resourceGridPosition = result.resourceGridPosition;
            it->ri = result.ri;
            it->timestampOffset = result.timestampOffset;

            char *zErrMsg = nullptr;
            const char *sqlUpdate = "UPDATE lte_pdsch SET validDMRSIndicator=" + std::to_string(result.validDMRSIndicator) + ", resourceGridPosition=" + std::to_string(result.resourceGridPosition) + ", ri=" + std::to_string(result.ri) + ", timestampOffset=" + std::to_string(result.timestampOffset) + " WHERE id=" + std::to_string(it->id) + ";";
            if (sqlite3_exec(db, sqlUpdate, nullptr, nullptr, &zErrMsg) != SQLITE_OK) {
                std::cerr << "SQL error: " << zErrMsg << std::endl;
                sqlite3_free(zErrMsg);
            }
        }
    }

    std::list<PDSCH_Result> getLatestNResults(size_t n) {
        std::list<PDSCH_Result> results;

        // Get the latest N results from the SQLite database and add them to the returned list
        char sql[1024];
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        snprintf(sql, sizeof(sql), "SELECT * FROM lte_pdsch ORDER BY timestampOffset DESC LIMIT %llu;", n);

        sqlite3_stmt* stmt;
        if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) == SQLITE_OK) {
            while (sqlite3_step(stmt) == SQLITE_ROW) {
                const char* colName = sqlite3_column_name(stmt, 0);
                if (!strcmp(colName, "id")) results.front().id = sqlite3_column_int(stmt, 0);
                else if (!strcmp(colName, "validDMRSIndicator")) results.front().validDMRSIndicator = sqlite3_column_int(stmt, 0) != 0;
                else if (!strcmp(colName, "resourceGridPosition")) results.front().resourceGridPosition = sqlite3_column_int(stmt, 0);
                else if (!strcmp(colName, "ri")) results.front().ri = sqlite3_column_int(stmt, 0);
                else if (!strcmp(colName, "timestampOffset")) results.front().timestampOffset = sqlite3_column_int64(stmt, 0);

                results.pop_back(); // Remove the empty result from the front of the list to make room for a new one
            }
        }

        return results;
    }
};
