    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    Node *head;
    size_t num_nodes;
    pthread_mutex_t mutex;
};

void init_list(struct list *list) {
    list->head = NULL;
    list->num_nodes = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(const RX_UE_INFORMATION_TAG tag, const uint32_t rnti) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    new_node->data.tag = tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    return new_node;
}

void add_node(struct list *list, Node* node) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = node;
    } else {
        Node *current = list->head;
        while (current->next != NULL) current = current->next;
        current->next = node;
    }

    list->num_nodes++;
    pthread_mutex_unlock(&list->mutex);
}

void remove_node(struct list *list, const uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (prev == NULL) list->head = current->next;
            else prev->next = current->next;

            free(current);
            list->num_nodes--;
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void clear_list(struct list *list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current != NULL) {
        list->head = current->next;
        free(current);
        current = list->head;
        list->num_nodes--;
    }

    pthread_mutex_unlock(&list->mutex);
}

