static pdsch_list_node *tail = NULL;
static bool is_polling = true;

void enqueue(pdsch_result result) {
    pdsch_list_node* node = malloc(sizeof(pdsch_list_node));
    if (!node) {
        // Handle memory allocation failure
        return;
    }
    node->data = result;
    node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (tail) {
        tail->next = node;
        tail = node;
    } else {
        head = tail = node;
    }
    pthread_mutex_unlock(&list_mutex);
}

pdsch_result dequeue() {
    pdsch_result result;
    pdsch_list_node *temp;

    pthread_mutex_lock(&list_mutex);
    if (head) {
        result = head->data;
        temp = head;
        head = head->next;
        if (!head) tail = NULL;
        free(temp);
    } else {
        result = (pdsch_result){0};
    }
    pthread_mutex_unlock(&list_mutex);

    return result;
}

