[' I will provide you with a high-level C++ design for the dynamic list of TCP_CONNECTION_STATS structures. This implementation uses a combination of thread safety mechanisms such as fine-grained locks, lock-free data structures, and batching to optimize performance under high concurrency and limited resources.

```cpp
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <iostream>
#include <list>
#include <memory>
#include <mutex>
#include <queue>
#include <thread>
#include <vector>

struct TCP_CONNECTION_STATS {
    int connection_id;
    std::string source_ip, destination_ip;
    std::chrono::system_clock::time_point timestamp;
};

class DynamicList {
public:
    explicit DynamicList(size_t initial_capacity = 10000) {
        reclaim_threshold = 0.75f * initial_capacity;
        capacity_multiplier = 2;
        data_multiplier = 4;

        _data.reserve(initial_capacity);
        _lock.reset(new std::mutex());
    }

    void add(const TCP_CONNECTION_STATS& stats) {
        std::unique_lock<std::mutex> lock(*_lock.get());

        // Check for duplicate IP entries
        if (std::find_if(_data.begin(), _data.end(),
                        [&stats](const auto& other) { return other->source_ip == stats.source_ip && other->destination_ip == stats.destination_ip; }) != _data.end())
            throw std::runtime_error("Duplicate IP entry");

        // Add the new structure to the data list
        _data.emplace_back(stats);

        // Check if it's time to reclaim memory
