    if (!ctx->buffer) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    ctx->buffer_size = buffer_size;
    ctx->buffer_lock = PTHREAD_MUTEX_INITIALIZER;
    ctx->resize_sem = SEM_INITIALIZER;
}

BUFFER_POOL_T* create_pool(size_t context_count, size_t buffer_size) {
    BUFFER_POOL_T* pool = malloc(sizeof(BUFFER_POOL_T));
    if (!pool) {
