    sem_wait(&pool->pool_sem);
    pthread_mutex_lock(&pool->pool_lock);

    NFAPI_L1_CONTEXT_T* ctx = &pool->contexts[pool->count];
    ++pool->count;

    pthread_mutex_unlock(&pool->pool_lock);
    sem_post(&pool->pool_sem);
    return ctx;
}

void release_context(BUFFER_POOL_T* pool, NFAPI_L1_CONTEXT_T* ctx) {
    pthread_mutex_lock(&pool->pool_lock);

    // Add proper error handling and memory deallocation logic here

    pool->count--;
    pthread_mutex_unlock(&pool->pool_lock);
    sem_post(&pool->pool_sem);
}
