void* realloc_with_growth(void* ptr, size_t current_capacity, size_t growth) {
    void* new_ptr;

    if (current_capacity * growth <= 1e9) {
        // Use regular realloc with specified growth factor
        new_ptr = realloc(ptr, current_capacity * growth);
    } else {
        // Handle extremely large allocations by doubling the capacity and growing more conservatively
        size_t new_growth = min(current_capacity * 2, growth);
        new_ptr = realloc(ptr, current_capacity * new_growth);
    }

    if (!new_ptr) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }

    return new_ptr;
}
