typedef struct _XPATH_CONTEXT {
    xmlXPathContextPtr xpathCtx;
    char *xpathExpr;
    int timeout;
} XPATH_CONTEXT;

jmp_buf env;

void timeoutHandler(int signum) {
    longjmp(env, 1);
}

NFAPI_CRC_INDICATION_PDU_T* CreateAndPopulateNFAPIListWithXPath(const char *xmlData, const char *elementName, int timeout) {
    xmlDocPtr doc = xmlReadMemory(xmlData, strlen(xmlData), NULL, 0, 0);
    if (!doc) {
        fprintf(stderr, "Error: Failed to parse XML data.\n");
        return NULL;
    }

    XPATH_CONTEXT xpathCtx = {
        .xpathExpr = xmlXPathNewExprChar(elementName),
        .timeout = timeout
    };

    struct timeval startTime, endTime;
    gettimeofday(&startTime, NULL);

    signal(SIGALRM, timeoutHandler);
    alarm(timeout);

    XPATH_OBJECTPtr xpathObj = xmlXPathEvalExpression(xpathCtx.xpathExpr, doc->xmlNode, &xpathCtx.xpathCtx);
    if (xpathObj == NULL || alarm(0)) {
        int errCode = xmlErrno;
        fprintf(stderr, "Error: Failed to find or timeout during XPath evaluation. Error code: %d\n", errCode);

        switch (errCode) {
            case XML_ERR_NO_ERROR:
                if (alarm(0)) {
                    fprintf(stderr, "Timeout error.\n");
                } else {
                    fprintf(stderr, "No matching elements found.\n");
                }
                break;
            case XML_ERR_FILE_NOT_FOUND:
                fprintf(stderr, "Error: XML file not found.\n");
                break;
            case XML_ERR_BAD_FILE:
                fprintf(stderr, "Error: XML file is invalid.\n");
                break;
            default:
                fprintf(stderr, "Unknown error: %d\n", errCode);
        }

        xmlFreeXPathContext(xpathCtx.xpathCtx);
        xmlFree(xpathCtx.xpathExpr);
        xmlFreeDoc(doc);
        return NULL;
    }

    alarm(0);
    gettimeofday(&endTime, NULL);

    int numMatches = xmlXPathNodeSetGetLength(xpathObj->nodeSetVal);
    if (numMatches > 1) {
        fprintf(stderr, "Error: Ambiguous match for specified element.\n");
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numMatches);
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for returned list.\n");
        xmlFreeXPathContext(xpathCtx.xpathCtx);
        xmlFree(xpathCtx.xpathExpr);
        xmlFreeDoc(doc);
        return NULL;
    }

    int i = 0;
    xmlNodeSetIter iter;
    xmlNodeSetIterNext(&iter, xpathObj->nodeSetVal);
    while ((xmlNode *)iter != NULL) {
        xmlNode *currentNode = iter.node;
        strncpy(list[i].rxi, currentNode->properties->name, 3);
        list[i].rnti = atoi((char *)xmlGetProp((xmlNode *)currentNode, BAD_CAST "RNTI"));
        list[i].crcflag = rand() % 2;

        iter.next = NULL;
        iter.node = xmlNodeSetIterNext(&iter, xpathObj->nodeSetVal);
        i++;
    }

    xmlFreeXPathContext(xpathCtx.xpathCtx);
    xmlFree(xpathCtx.xpathExpr);
    xmlFreeDoc(doc);

    fprintf(stderr, "Parsed XML in %ld ms.\n", (endTime.tv_sec - startTime.tv_sec) * 1000 + (endTime.tv_usec - startTime.tv_usec) / 1000);

    return list;
}
