        boost::filesystem::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            std::cerr << "Could not open file: " << filename << std::endl;
            return;
        }

        pool_.pdus.clear();
        boost::serialization::serialize(file, pool_.pdus);

        rntiMap.clear();
