void cleanup(struct dynamic_array* array) {
    for (size_t i = 0; i < array->size - 1; ++i) {
        time_t diff = difftime(time(NULL), array->packets[i].timestamp);
        if (diff > array->cleanup_threshold) {
            free(array->packets + i);
            memmove((array->packets + i), (array->packets + i + 1), sizeof(UdpPacket) * (array->size - i - 1));
            --array->size;
        }
    }
}

void resize_dynamic_array(struct dynamic_array* array, size_t new_capacity) {
    UdpPacket* temp = realloc(array->packets, sizeof(UdpPacket) * new_capacity);
    if (!temp) return;

    array->packets = temp;
    array->capacity = new_capacity;
}

struct dynamic_array* create_dynamic_array(size_t initial_capacity, time_t cleanup_threshold) {
    struct dynamic_array* array = malloc(sizeof(struct dynamic_array));
    if (!array) return NULL;

    array->packets = calloc(initial_capacity, sizeof(UdpPacket));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->cleanup_threshold = cleanup_threshold;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

