void *cleaner(void *arg) {
    struct manager *manager = arg;
    time_t last_active = 0;
    while (true) {
        pthread_mutex_lock(&manager->lock);
        if (time(NULL) - last_active > manager->capacity / 100) { // Clean up inactive elements after given threshold
            size_t i;
            for (i = 0; i < manager->num_elements; ++i) {
