        if (it != configs.end()) {
            it->second->bandwidth = config.bandwidth;
            it->second->frequency = config.frequency;
            it->second->power_level = config.power_level;
        } else {
            configs[config.device_id] = std::make_unique<DeviceConfig>(config);
        }
    }

    void remove(const std::string& device_id) {
        std::scoped_lock lock(mtx);
        auto it = configs.find(device_id);
        if (it != configs.end()) {
            it->second.reset();
            configs.erase(it);
        } else {
            // Handle invalid device ID
        }
    }

private:
    void loadFromArchive(cereal::InputArchive& archive) {
        for (DeviceConfig config; archive(cereal::make_nvp("config", config)); !archive.Eof());
            configs[config.device_id] = std::make_unique<DeviceConfig>(config);
    }

    void saveToArchive(cereal::OutputArchive& archive) const {
        for (const auto& entry : configs)
            archive(cereal::make_nvp("config", *entry.second));
    }
};
