    init_connection(conn);
    manager->connections[manager->count++] = conn;
}

void update_connection(TcpConnection* conn) {
    pthread_mutex_lock(&conn->lock);
    conn->last_active = time(NULL);
    pthread_mutex_unlock(&conn->lock);
}

void clean_inactive_connections(ConnectionManager* manager) {
    time_t now = time(NULL);
    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->connections[i] && (now - manager->connections[i]->last_active) > manager->timeout) {
            free(manager->connections[i]);
            memmove(&manager->connections[i], &manager->connections[i+1], --manager->count * sizeof(TcpConnection*));
        }
    }
}

void connection_manager_destroy(ConnectionManager** manager) {
    if (*manager) {
        free((*manager)->connections);
        free(*manager);
        *manager = NULL;
    }
}
