void append_node(Node **head_ref, Node *new_node) {
    pthread_mutex_lock(&list_mutex);
    if (!*head_ref) {
        *head_ref = new_node;
        *tail = head_ref;
    } else {
        (*tail)->next = new_node;
        *tail = (*tail)->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

