    if (!validate_rnti(&new_node->data)) {
        free(new_node);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    create_node(&new_node);
    append_node(head, new_node);
    total_structures++;

    pthread_mutex_unlock(&list_mutex);
}

void resize_if_necessary() {
    if (total_structures * 2 >= max_nodes) {
        size_t new_max_nodes = max_nodes * 2;
        Node **new_tail = NULL;

        pthread_mutex_lock(&list_mutex);
