        boost::asio::mpsc_queue<char> write_queue(io_service_);
        auto write_task = [&](const NFAPI_CRC_INDICATION_PDU_T& pdu) {
            std::ostringstream ss;
            ss << pdu.rnti << ','
              << (int)(pdu.crc_indication_rel8_tag.crcflag ? 1 : 0) << '\n';
