class MemoryPool {
public:
    MemoryPool(std::size_t nodeCount, std::size_t blockSize) : m_nodes(nodeCount), m_freeList(m_nodes.data(), m_nodes.data() + nodeCount) {}

    NFAPI_CRC_INDICATION_PDU_T* allocateNode() {
        std::unique_lock<std::mutex> lock(m_mutex);
        if (!m_freeList.empty()) {
            auto it = m_freeList.begin();
            m_freeList.erase(it);
            return *it;
        }

        // Allocate new memory block if the free list is empty
        char* mem = static_cast<char*>(::operator new(blockSize));
        NFAPI_CRC_INDICATION_PDU_T* newNodes = reinterpret_cast<NFAPI_CRC_INDICATION_PDU_T*>(mem);

        for (auto node = newNodes; node < newNodes + blockSize / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++node) {
            node->next = newNodes;
            m_nodes.push_back(*node);
        }

        std::shuffle(m_nodes.begin(), m_nodes.end(), std::mt19937{std::random_device{}()}); // Randomize the order for better cache locality

        m_freeList.insert(m_freeList.end(), newNodes, newNodes + blockSize / sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return newNodes;
    }

    void freeNode(NFAPI_CRC_INDICATION_PDU_T* node) {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto it = std::find(m_nodes.begin(), m_nodes.end(), *node);
        if (it != m_nodes.end()) {
            m_freeList.insert(it);
            return;
