#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct FrameBufferEntry {
    time_t timestamp;
    size_t packetLength;
    char* data;
} FrameBufferEntry;

#define BUFFER_CACHE_SIZE 128
FrameBufferEntry bufferCache[BUFFER_CACHE_SIZE];

size_t getCacheIndex(size_t len) {
    return len % BUFFER_CACHE_SIZE;
}

void initBuffer(FrameBufferEntry* entry, time_t timestamp, size_t packetLength) {
    if (packetLength > 0) {
        if (packetLength <= bufferCache[getCacheIndex(packetLength)].packetLength) {
            entry->data = bufferCache[getCacheIndex(packetLength)].data;
            entry->packetLength = packetLength;
            entry->timestamp = timestamp;
            bufferCache[getCacheIndex(packetLength)].packetLength = 0;
        } else {
            entry->data = malloc(packetLength);
            if (!entry->data) {
                fprintf(stderr, "Memory allocation failed.\n");
                exit(EXIT_FAILURE);
            }
            entry->packetLength = packetLength;
            entry->timestamp = timestamp;
        }
    } else {
        fprintf(stderr, "Invalid packet length.\n");
        exit(EXIT_FAILURE);
    }
}

FrameBufferEntry* createFrameBuffer(size_t memoryBudget, size_t initialCapacity) {
    FrameBufferEntry* frameBuffer = malloc(initialCapacity * sizeof(FrameBufferEntry));
    if (!frameBuffer) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    size_t allocatedSize = initialCapacity * sizeof(FrameBufferEntry) + BUFFER_CACHE_SIZE * sizeof(char);

    while (allocatedSize <= memoryBudget && initialCapacity < MEMORY_LIMIT) {
        initialCapacity *= 2;
        frameBuffer = realloc(frameBuffer, initialCapacity * sizeof(FrameBufferEntry));
        if (!frameBuffer) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        allocatedSize += (initialCapacity - initialCapacity / 2) * sizeof(FrameBufferEntry);
    }

    return frameBuffer;
}

void freeFrameBuffer(FrameBufferEntry* buffer, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (buffer[i].data) {
            free(buffer[i].data);
        }
    }
    free(buffer);
}
```

This code defines a `FrameBufferEntry` structure with a timestamp, packet length, and dynamically allocated byte buffer. A cache of 128 pre-allocated buffers is provided to optimize memory usage for frequently used packet lengths. The `createFrameBuffer()` function dynamically allocates a frame buffer based on a given memory budget and initial capacity. When the allocated size exceeds the budget, it gracefully degrades by limiting the growth of the array. The `initBuffer()` function initializes entries with specified timestamps and packet lengths, either reusing buffers from the cache or allocating new ones if needed. Error handling is implemented for buffer overflows and memory exhaustion. Lastly, the `freeFrameBuffer()` function frees all dynamically allocated buffers when the frame buffer is no longer needed.']

