#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>

#define MAX_ENTRIES 1024
#define PAGE_SIZE (getpagesize())

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

struct lru_node {
    struct lru_node *prev, *next;
    NFAPI_CRC_INDICATION_PDU_T data;
};

struct lru_list {
    struct lru_node head, tail;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full, cond_not_empty;
};

void lru_list_init(struct lru_list *list) {
    list->size = 0;
    list->head.prev = &list->tail;
    list->head.next = &list->head;
    list->tail.prev = &list->head;
    list->tail.next = &list->head;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond_not_full, NULL);
    pthread_cond_init(&list->cond_not_empty, NULL);
}

void lru_list_insert(struct lru_list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct lru_node *node = malloc(sizeof(*node));
    if (!node) return;

    node->data = data;
    pthread_mutex_lock(&list->mutex);

    // Insert at head
    node->prev = &list->head;
    node->next = list->head.next;
    list->head.next = node;
    list->head.next->prev = node;

    list->size++;
    if (list->size == MAX_ENTRIES) {
        // LRU eviction: remove least recently used entry
        struct lru_node *lru_node = list->tail.prev;
        pthread_mutex_unlock(&list->mutex);

        pthread_mutex_lock(&lru_node->data.memory_mutex);
        munmap(lru_node->data.memory, PAGE_SIZE);
        free(lru_node->data.memory);
        pthread_mutex_unlock(&lru_node->data.memory_mutex);

        pthread_mutex_lock(&list->mutex);
        node = lru_node;
        list->tail.prev = node->prev;
        node->prev->next = &list->tail;
        node->prev = &list->tail;
        list->size--;
        pthread_mutex_unlock(&list->mutex);
    } else {
        pthread_cond_signal(&list->cond_not_full);
    }
}

void *lru_node_data_alloc(size_t size) {
    void *memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (memory == MAP_FAILED) return NULL;
    pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
    return calloc(1, sizeof(*node) + size + sizeof(pthread_mutex_t));
}

void lru_list_refresh() {
