#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for logging and synchronization
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
int num_crcs[65536] = {0}; // Array to store number of CRC indications per RNTI
bool log_enabled = false;

// Function to initialize linked list node
NFAPI_CRC_INDICATION_PDU_T* init_node() {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->RX_UE_INFORMATION_TAG = rand();
    node->RNTI = rand();
    node->CRC_INDICATION_REL8_TAG = rand() & 0xFF;
    node->CRCFLAG = (rand() % 2) == 0; // Set CRC flag to either 0 or 1 randomly
    node->next = NULL;
    return node;
}

// Function to initialize and populate the linked list with specified number of RNTIs
void init_list(NFAPI_CRC_INDICATION_PDU_T** head, int num_rntis) {
    if (num_rntis <= 0) return;

    *head = init_node();
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    for (int i = 1; i < num_rntis; ++i) {
        current->next = init_node();
        if (!current->next) break;
        current = current->next;
    }
}

// Thread-safe logging function
void log_crc(unsigned int rnTI, unsigned short crcFlag) {
    pthread_mutex_lock(&log_mutex);
    num_crcs[rnTI]++;
    if (log_enabled) printf("RNTI: %u, CRC Flag: %hu\n", rnTI, crcFlag);
    pthread_mutex_unlock(&log_mutex);
}

// Function to process the linked list and generate a summary report upon completion
void process_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    if (!head) return;

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        log_crc(current->RNTI, current->CRC_INDICATION_REL8_TAG & 0x1); // Extract CRC flag value from tag
        current = current->next;
    }

    printf("\nSummary report:\n");
    for (int i = 0; i < 65536; ++i) {
        if (num_crcs[i] > 0)
            printf("RNTI: %u, Number of CRC indications: %d\n", i, num_crcs[i]);
    }
}

// Entry point for multi-threaded processing
void* process(void* arg) {
    int num_rntis = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    init_list(&head, num_rntis); // Initialize and populate the linked list for this thread

    process_list(head); // Process the linked list
    free(head); // Deallocate memory used by the linked list

    pthread_exit(NULL);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <number_of_RNTIs>\n", argv[0]);
        return 1;
    }

    int num_rntis = atoi(argv[1]);
    if (num_rntis <= 0) {
        printf("Invalid number of RNTIs\n");
        return 1;
    }

    pthread_t threads[num_rntis / 16 + 1]; // Create one thread per 16 RNTIs for load balancing
    for (int i = 0; i < num_rntis / 16 + 1; ++i) {
        if (pthread_create(&threads[i], NULL, process, &num_rntis / (num_rntis / 16 + 1) * i)) {
            perror("Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < num_rntis / 16 + 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

This code implements a multi-threaded solution that initializes and populates a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures for the specified number of Radio Network Temporary Identifiers (RNTIs). It ensures CRC flags are consistent within each RNTI group using a thread-safe logging mechanism. The code also integrates with an external logging framework, optimizes memory usage, and handles potential failures from the logging framework.

To enable or disable logging, set `log_enabled` to true or false before calling `main()`. This can be done by modifying the line:

