import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public class FileHasher {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ConcurrentHashMap<Path, byte[]> cache = new ConcurrentHashMap<>();
    private final MetadataProvider metadataProvider;

    public FileHasher(MetadataProvider metadataProvider) {
        this.metadataProvider = metadataProvider;
    }

    public List<String> hashFiles(List<Path> filePaths) throws IOException, InterruptedException, ExecutionException {
        List<Future<String>> futures = executor.invokeAll(
                filePaths.stream()
                        .filter(this::isTextFile)
                        .map(this::processFile)
                        .collect(Collectors.toList())
        );

        return futures.stream().map(Future::get).collect(Collectors.toList());
    }

    private boolean isTextFile(Path path) {
        if (!Files.exists(path)) return false;
        try {
            return Files.probeContentType(path).startsWith("text/");
        } catch (IOException e) {
            // Handle exceptions gracefully and return false to skip non-text files
        }
        return false;
    }

    private Callable<String> processFile(Path filePath) {
        return () -> {
            if (!cache.containsKey(filePath)) {
                byte[] hash = calculateHash(filePath);
                cache.put(filePath, hash); // Cache the result
            }

            String metadata = fetchMetadata(filePath);
            if (shouldProcessFile(metadata)) {
                return bytesToHexString(cache.get(filePath));
            }
            return null; // Indicate that file should be skipped
        };
    }

    private boolean shouldProcessFile(String metadata) {
        // Implement your logic to decide whether a file should be hashed based on the metadata
    }

    private String fetchMetadata(Path filePath) throws IOException, URISyntaxException {
        // Fetch metadata from a remote source or local storage. Adapt this method according to your data sources.
    }

    private byte[] calculateHash(Path filePath) throws IOException {
        try (InputStream input = Files.newInputStream(filePath)) {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = input.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
            return digest.digest();
        }
    }

    private String bytesToHexString(byte[] hash) {
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```
