#include <sys/types.h>
#include <sys/timeb.h>

typedef struct UEState {
    uint32_t ue_id;
    struct MeasurementReport* reports;
    pthread_mutex_t state_mutex;
    bool active;
} UEState;

typedef struct MeasurementReport {
    time_t timestamp;
    int cell_id;
    float signal_strength;
    struct ListNode* neighbors;
} MeasurementReport;

typedef struct ListNode {
    struct MeasurementReport data;
    struct ListNode* next;
} ListNode;

UEState* create_ue(uint32_t ue_id) {
    UEState* new_ue = (UEState*) malloc(sizeof(UEState));
    if (!new_ue) return NULL;

    new_ue->ue_id = ue_id;
    new_ue->reports = NULL;
    new_ue->active = true;

    pthread_mutex_init(&new_ue->state_mutex, NULL);
    return new_ue;
}

ListNode* create_report(time_t timestamp, int cell_id, float signal_strength) {
    ListNode* new_report = (ListNode*) malloc(sizeof(ListNode));
    if (!new_report) return NULL;

    new_report->data.timestamp = timestamp;
    new_report->data.cell_id = cell_id;
    new_report->data.signal_strength = signal_strength;
    new_report->next = NULL;

    return new_report;
}

UEState* add_ue(UEState** ue_list, uint32_t ue_id) {
    for (UEState* current = *ue_list; current != NULL; current = current->next) {
        if (current->ue_id == ue_id) return current;
    }

    UEState* new_ue = create_ue(ue_id);
    if (!new_ue) return NULL;

    new_ue->next = *ue_list;
    *ue_list = new_ue;
    return new_ue;
}

void insert_report(UEState* ue, ListNode* report) {
    pthread_mutex_lock(&ue->state_mutex);

    if (!ue->reports) {
        ue->reports = report;
    } else {
        ListNode* current = ue->reports;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = report;
    }

    pthread_mutex_unlock(&ue->state_mutex);
}

// ... Implement other functions for updating, finding, and removing UEState entries as needed.
```

