#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    unsigned int UE_ID;
    void *downlink_buf;
    time_t last_pkt_ts;
} UE_session;

struct network_interface {
    size_t mem_budget;
    pthread_mutex_t mem_lock;
    UE_session **sessions;
    size_t num_sessions;
    void (*log_func)(UE_session*, const char*);
};

void log_usage(UE_session *ue, const char* msg) {
    if (ue && ue->downlink_buf && ue->log_func)
        ue->log_func(ue, msg);
}

void* allocate_buffer(size_t size, pthread_mutex_t *lock) {
    void *ptr;
    if ((ptr = malloc(size)) == NULL) {
        log_usage((UE_session*)lock, "Memory allocation failed");
        return NULL;
    }
    log_usage((UE_session*)lock, "Allocated buffer of size: ...");
    return ptr;
}

void free_buffer(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
        log_usage((UE_session) {0, ptr, 0}, "Freed buffer");
    }
}

UE_session* create_ue_session(unsigned int id) {
    UE_session *ue = malloc(sizeof(UE_session));
    if (!ue) {
        log_usage((UE_session){0, NULL, 0}, "Memory allocation for UE session failed");
        return NULL;
    }
    ue->UE_ID = id;
    ue->downlink_buf = allocate_buffer(BUFF_SIZE, (UE_session*)ue);
    if (!ue->downlink_buf) {
        free(ue);
        log_usage((UE_session){0, NULL, 0}, "Failed to allocate buffer for UE session");
        return NULL;
    }
    return ue;
}

void network_interface_init(struct network_interface *ni, size_t mem_budget) {
    ni->mem_budget = mem_budget;
    pthread_mutex_init(&(ni->mem_lock), NULL);
    ni->sessions = NULL;
    ni->num_sessions = 0;
}

void* add_ue_session(struct network_interface *ni, unsigned int id) {
    UE_session *ue = create_ue_session(id);
    if (!ue) return NULL;

    pthread_mutex_lock(&(ni->mem_lock));
    if (ni->num_sessions + 1 > ni->mem_budget / sizeof(UE_session)) {
        free(ue);
        log_usage((UE_session*)&ni->mem_lock, "Memory budget exceeded");
        pthread_mutex_unlock(&(ni->mem_lock));
        return NULL;
    }

    if (ni->sessions) {
        size_t i = ni->num_sessions - 1;
        while (i > 0 && ni->sessions[i]->UE_ID < id) i--;
        memmove(ni->sessions + i + 1, ni->sessions + i, sizeof(UE_session) * (ni->num_sessions - i));
    }
    ni->sessions = realloc(ni->sessions, sizeof(UE_session) * (ni->num_sessions + 1));
    if (!ni->sessions) {
        free(ue);
        log_usage((UE_session*)&ni->mem_lock, "Memory allocation for sessions array failed");
        pthread_mutex_unlock(&(ni->mem_lock));
        return NULL;
    }

    ni->sessions[i] = ue;
    ni->num_sessions++;
    pthread_mutex_unlock(&(ni->mem_lock));
    log_usage((UE_session*)&ni->mem_lock, "Added UE session with ID: ...");
    return ue;
}

void network_interface_shutdown(struct network_interface *ni) {
    pthread_mutex_lock(&(ni->mem_lock));
    for (size_t i = 0; i < ni->num_sessions; i++) {
        UE_session* ue = ni->sessions[i];
        if (ue && ue->downlink_buf) free_buffer(ue->downlink_buf);
    }
    free(ni->sessions);
    pthread_mutex_unlock(&(ni->mem_lock));
    pthread_mutex_destroy(&(ni->mem_lock));
}
```

This implementation creates a network interface structure that supports adding UE sessions with unique IDs, handles potential memory allocation failures gracefully, and maintains a log of usage statistics for each session. The memory budget is enforced using a mutex lock to ensure safe access to the allocated memory. The function can be easily integrated with an existing network management framework by passing a logging function as a parameter.']

