struct addrinfo hints, *res;
int status;
char ip_buf[INET6_ADDRSTRLEN];
u_char ip_address[16];

int dns_resolve(const char *hostname) {
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return status;
    }

    void *address;
    int address_len = res->ai_addrlen;
    if (res->ai_family == AF_INET) {
        struct sockaddr_in *sa = (struct sockaddr_in *)res->ai_addr;
        memcpy(ip_address, &sa->sin_addr, sizeof(sa->sin_addr));
    } else if (res->ai_family == AF_INET6) {
        struct sockaddr_in6 *sa = (struct sockaddr_in6 *)res->ai_addr;
        memcpy(ip_address, &sa->sin6_addr, sizeof(sa->sin6_addr));
    }

    freeaddrinfo(res); // Always free the result

    inet_ntop(res->ai_family, res->ai_addr, ip_buf, sizeof(ip_buf));

    return 0;
}
