#define MAX_LIST_SIZE 1024

static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t num_elements = 0;
static size_t capacity = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void create_list(size_t n) {
    if (n > MAX_LIST_SIZE) {
        fprintf(stderr, "Error: List size exceeds maximum allowed limit.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_list = NULL;

    pthread_mutex_lock(&list_mutex);

    if (num_elements + n > capacity) {
        size_t new_capacity = (capacity * 3) / 2 + n;

        new_list = realloc(list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            perror("Error: Failed to allocate memory for the list.\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        capacity = new_capacity;
        list = new_list;
    }

    for (size_t i = num_elements; i < num_elements + n; ++i) {
        list[i].timestamp = time(NULL);
        list[i].tag.tagClass = RNTI_TAG_CLASS;
        list[i].tag.tagValue = rand() % 256;
        list[i].rnti = rand() % 65536;
        list[i].crc_indication.crcFlag = (rand() % 2) == 0 ? 1 : 0;
    }

    num_elements += n;

    pthread_mutex_unlock(&list_mutex);
}

void validate_list() {
    for (size_t i = 0; i < num_elements; ++i) {
        if (!(list[i].tag.tagClass == RNTI_TAG_CLASS && list[i].rnti <= 65535)) {
            fprintf(stderr, "Error: Invalid structure at index %lu.\n", i);
            return;
        }
    }
}
