typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define UE_MAX 1024
static unsigned int cached_ues[UE_MAX] = {0};
static NFAPI_CRC_INDICATION_PDU_T* ue_data = NULL;
static size_t num_ue_allocated = 0;
static size_t num_ue_used = 0;

void log_error(const char* msg) {
    fprintf(stderr, "%s\n", msg);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_ue_data() {
    NFAPI_CRC_INDICATION_PDU_T* temp_ue_data;

    if (num_ue_allocated == num_ue_used) {
        size_t new_capacity = num_ue_allocated ? (num_ue_allocated * 2) : UE_MAX;
        temp_ue_data = realloc(ue_data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_ue_data) {
            log_error("Failed to allocate memory for ue data!");
            free(ue_data);
            return NULL;
        }
        ue_data = temp_ue_data;
    }

    return &ue_data[num_ue_used++];
}

bool is_cached(size_t index) {
    if (index >= UE_MAX || index >= num_ue_allocated) return false;
    return cached_ues[index] != 0;
}

void cache_ue(size_t index) {
