#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_node {
    time_t last_access_time;
    size_t data_size;
    uintptr_t data_ptr;
};

typedef struct cache_node CACHE_NODE;

struct cache {
    CACHE_NODE *cache;
    size_t capacity;
    size_t size;
};

void cache_init(struct cache *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->cache = calloc(capacity, sizeof(CACHE_NODE));
}

void cache_insert(struct cache *cache, uintptr_t data_ptr, size_t data_size) {
    size_t index = cache->size % cache->capacity;

    if (cache->size == cache->capacity) return;

    CACHE_NODE *node = &cache->cache[index];
    node->last_access_time = time(NULL);
    node->data_ptr = data_ptr;
    node->data_size = data_size;
    cache->size++;
}

uintptr_t cache_get(struct cache *cache, size_t data_size) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        CACHE_NODE *node = &cache->cache[i];

        if (time(NULL) - node->last_access_time > 60 && node->data_ptr) {
            // Remove infrequently accessed data from the cache to free up space.
            node->data_ptr = NULL;
        }

        if (!node->data_ptr || node->data_size < data_size) continue;

        void *aligned_ptr = (uintptr_t)node->data_ptr & ~0xF; // Align to 16-byte cache line.
        memmove(aligned_ptr, node->data_ptr, data_size);
        return aligned_ptr;
    }

    return NULL;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *managed_data = NULL;
size_t managed_data_capacity = 0;
size_t managed_data_size = 0;
struct cache managed_cache;

void _allocate_managed_data(size_t capacity) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *temp_ptr = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp_ptr) break;

        // Retry with reduced memory requests when allocation fails due to resource constraints.
        capacity *= 0.9;
    }

    managed_data = temp_ptr;
    managed_data_capacity = capacity;
}

void managed_data_init(size_t initial_capacity) {
    pthread_mutex_lock(&mutex);
    if (!managed_data || managed_data_capacity < initial_capacity) _allocate_managed_data(initial_capacity);
    cache_init(&managed_cache, 1024);
    pthread_mutex_unlock(&mutex);
}

void *get_managed_data(size_t index) {
    pthread_mutex_lock(&mutex);
    void *data = NULL;

    if (index >= managed_data_size || index < 0) {
        // Handle out-of-bounds requests.
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    data = cache_get(&managed_cache, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        // If the data is not found in the cache, fetch it and store it in the cache.
        memcpy(data, managed_data + index, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        cache_insert(&managed_cache, (uintptr_t)data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&mutex);
    return data;
}

void set_managed_data(size_t index, RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&mutex);

    if (index >= managed_data_size || index < 0) {
        // Handle out-of-bounds requests.
        pthread_mutex_unlock(&mutex);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = get_managed_data(index);
    if (!pdus) {
        // If the data is not found in the managed data, allocate new space.
        if (managed_data_size == managed_data_capacity) _allocate_managed_data(managed_data_capacity * 2);

        memcpy(pdus, managed_data + index, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdus->tag = tag;
        pdus->rnti = rnti;
        pdus->crc_indication.crcflag = (time(NULL) & 0xFFFF); // Set CRCFLAG with current time for testing purposes.
        cache_insert(&managed_cache, (uintptr_t)pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        pdus->tag = tag;
        pdus->rnti = rnti;
        pdus->crc_indication.crcflag = (time(NULL) & 0xFFFF); // Set CRCFLAG with current time for testing purposes.
    }

    pthread_mutex_unlock(&mutex);
}
