} RX_UE_INFORMATION_TAG_T;

typedef struct list_node {
    CRC_INDICATION_REL8_TAG_T data;
    struct list_node *prev;
    struct list_node *next;
} LIST_NODE_T;

#define MAX_LIST_SIZE 1000

void log_operation(const char *operation, uint16_t rnti, CRC_INDICATION_REL8_TAG_T *tag) {
    FILE *log_file = stdout; // User-specified log file
    if (log_file != stdout) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);
        fprintf(log_file, "%s RNTI: %u CRC_INDICATION_REL8_TAG: {.crCflag = %u .timestamp = %ld}\n", operation, rnti, tag->crcflag, (long)tag->timestamp);
    }
}

RX_UE_INFORMATION_TAG_T *list_head;
pthread_mutex_t list_mutex;
size_t list_size = 0;
FILE *log_file;

void init_list(FILE *log_file_) {
    log_file = log_file_;
    pthread_mutex_init(&list_mutex, NULL);
    list_head = malloc(sizeof(RX_UE_INFORMATION_TAG_T));
    if (!list_head) {
        fprintf(stderr, "Failed to allocate memory for list head\n");
        exit(EXIT_FAILURE);
    }
    list_head->mutex = PTHREAD_MUTEX_INITIALIZER;
    list_head->head = NULL;
}

void merge_entries(RX_UE_INFORMATION_TAG_T *current, RX_UE_INFORMATION_TAG_T *new_entry) {
    if (!current->head) {
        current->head = new_entry;
        current->head->prev = NULL;
        current->head->next = NULL;
    } else {
        LIST_NODE_T *last = current->head;
        while (last->next) last = last->next;
        last->next = new_entry;
        new_entry->prev = last;
        new_entry->next = NULL;
    }
}

void free_list_node(LIST_NODE_T *node) {
    free(node);
}

void free_list(RX_UE_INFORMATION_TAG_T *ue_info) {
    pthread_mutex_destroy(&ue_info->mutex);
    LIST_NODE_T *node = ue_info->head;
    while (node) {
        LIST_NODE_T *next = node->next;
        free_list_node(node);
        node = next;
    }
    free(ue_info);
}

void generate_report(uint16_t rnti, CRC_INDICATION_REL8_TAG_T *tag) {
    pthread_mutex_lock(&list_mutex);
    RX_UE_INFORMATION_TAG_T *ue_info = list_head;
    while (ue_info) {
        if (ue_info->rnti == rnti) {
            log_operation("Reported", rnti, tag);
            LIST_NODE_T *node = ue_info->head;
            while (node) {
                log_operation("CRC Indication", rnti, &node->data);
                node = node->next;
            }
        }
        ue_info = ue_info->head;
    }
    pthread_mutex_unlock(&list_mutex);
}

void manage_indication(CRC_INDICATION_REL8_TAG_T *tag) {
    time_t now = time(NULL);
    tag->timestamp = now;

    pthread_mutex_lock(&list_mutex);
    RX_UE_INFORMATION_TAG_T *ue_info = list_head;
    if (list_size >= MAX_LIST_SIZE) {
        RX_UE_INFORMATION_TAG_T *least_recent = NULL;
        while (ue_info && list_size > MAX_LIST_SIZE) {
            least_recent = ue_info;
            ue_info = ue_info->head;
            if (!ue_info) break;
        }
        if (least_recent) {
            RX_UE_INFORMATION_TAG_T *prev = least_recent->head->prev;
            LIST_NODE_T *node = least_recent->head;
            free_list_node(node);
            if (!prev) list_head = NULL;
            else prev->next = NULL;
            list_size--;
        }
    }

    RX_UE_INFORMATION_TAG_T *entry = NULL;
    LIST_NODE_T *new_node = malloc(sizeof(LIST_NODE_T));
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        fprintf(stderr, "Failed to allocate memory for new node\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = *tag;
    list_size++;

    RX_UE_INFORMATION_TAG_T *ue_info_to_merge = NULL;
    ue_info = list_head;
    while (ue_info) {
        if (ue_info->rnti == rnti) {
            ue_info_to_merge = ue_info;
            break;
        }
        ue_info = ue_info->head;
    }

    if (!ue_info_to_merge) {
        merge_entries(list_head, new_node);
    } else {
        merge_entries(ue_info_to_merge, new_node);
    }

    pthread_mutex_unlock(&list_mutex);
}

void destroy_list() {
    free_list(list_head);
    fclose(log_file);
}

int main() {
    init_list(stdin);
    CRC_INDICATION_REL8_TAG_T tag = { .timestamp = 0 };

    // Example usage:
    manage_indication(&tag);
    generate_report(1, &tag);

    destroy_list();
    return 0;
}

