NFAPI_CRC_INDICATION_PDU_T* populateNfademo(size_t num_elements, const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Error opening configuration file");
        return NULL;
    }

    char *contents = readFileSync(config_file);
    if (!contents) {
        perror("Error reading configuration file");
        fclose(file);
        return NULL;
    }

    size_t line_len, num_lines = 0, i = 0;
    sscanf(contents, "%s\n", contents);
    while (contents[0] != '\0') {
        sscanf(contents, "%d", &line_len);
        num_elements += line_len;
        sscanf(contents + strlen(contents), "%*c"); // consume newline character
        sscanf(contents, "%s\n", contents);
    }

    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *) malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        perror("Error allocating memory");
        free(contents);
        fclose(file);
        return NULL;
    }

    rewind(file);
    for (i = 0; i < num_elements; ++i) {
        size_t read = fread(&data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (read != 1) {
            perror("Error reading from configuration file");
            free(contents);
            free(data);
            fclose(file);
            return NULL;
        }
    }

    free(contents);
    fclose(file);
    return data;
}

