const fs = require('fs');

function readFileSync(filePath) {
    const validDirPathRegex = /^(\/|[a-zA-Z]:\\)/; // Directory path format validation

    if (!validDirPathRegex.test(filePath)) {
        throw new Error(`Invalid directory path format: "${filePath}"`);
    }

    try {
        const contents = fs.readFileSync(filePath, 'utf8');
        return contents;
    } catch (error) {
        if (error.code === 'ENOENT') {
            throw new Error(`Error reading file: "${filePath}" does not exist`);
        } else if (error.code === 'EACCES') {
            throw new Error(`Error reading file: Access denied to "${filePath}"`);
        } else {
            throw error;
        }
    }
}
