typedef struct _CRC_LIST_MANAGER {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    unsigned int size;
    unsigned int max_allowed_crc_indications;
} CRC_LIST_MANAGER;

void init_crc_list_manager(CRC_LIST_MANAGER* manager, unsigned int max_allowed_crc_indications) {
    pthread_mutex_init(&(manager->lock), NULL);
    manager->head = NULL;
    manager->tail = NULL;
    manager->size = 0;
    manager->max_allowed_crc_indications = max_allowed_crc_indications;
}

NFAPI_CRC_INDICATION_PDU_T* acquire_crc_pdu(CRC_LIST_MANAGER* manager) {
    pthread_mutex_lock(&(manager->lock));
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = NULL;
    if (manager->size < manager->max_allowed_crc_indications && !new_pdu) {
        new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            pthread_mutex_unlock(&(manager->lock));
            return NULL;
        }
    }
    if (manager->tail) {
        manager->tail->next = new_pdu;
        manager->tail = new_pdu;
    } else {
        manager->head = new_pdu;
    }
    manager->size++;
    pthread_mutex_unlock(&(manager->lock));
    return new_pdu;
}

void release_crc_pdu(CRC_LIST_MANAGER* manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&(manager->lock));
    if (pdu && manager->size > 0) {
        if (pdu == manager->head) {
            manager->head = pdu->next;
        } else if (pdu->next) {
            NFAPI_CRC_INDICATION_PDU_T *temp = manager->head;
            while (temp->next != pdu) {
                temp = temp->next;
            }
            temp->next = pdu->next;
        } else {
            manager->tail = NULL;
        }
        free(pdu);
        manager->size--;
    }
    pthread_mutex_unlock(&(manager->lock));
}

void cleanup_crc_list(CRC_LIST_MANAGER* manager) {
    pthread_mutex_lock(&(manager->lock));
    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    manager->tail = NULL;
    manager->size = 0;
    pthread_mutex_unlock(&(manager->lock));
}
