// Function to validate network traffic event
int validateTrafficEvent(const TrafficEvent* event, const unsigned long maxPayloadSize) {
    if (event->payloadSize > maxPayloadSize) {
        fprintf(stderr, "Error: Payload size exceeds maximum allowed.\n");
        return 0;
    }
    // Add additional validation checks as needed
    return 1;
}

// Function to check for duplicate IP combinations
int isUniqueIPCombination(const TrafficEvent* event, const TrafficEvent* existingEvents, size_t numExistingEvents) {
    for (size_t i = 0; i < numExistingEvents; ++i) {
        if ((strcmp(event->sourceIP, existingEvents[i].sourceIP) == 0 && strcmp(event->destinationIP, existingEvents[i].destinationIP) == 0) ||
            (strcmp(event->sourceIP, existingEvents[i].destinationIP) == 0 && strcmp(event->destinationIP, existingEvents[i].sourceIP) == 0)) {
            return 0;
        }
    }
    return 1;
}

// Function to dynamically allocate memory for network traffic events
TrafficEvent* allocateNetworkTrafficEvents(size_t numEvents, const char* sourceIP, const char* destinationIP, int protocolType, unsigned long maxPayloadSize) {
    TrafficEvent* events = (TrafficEvent*) malloc(numEvents * sizeof(TrafficEvent));
    if (!events) {
        fprintf(stderr, "Error: Failed to allocate memory for network traffic events.\n");
        return NULL;
    }

    // Initialize event structures and validate input parameters
    for (size_t i = 0; i < numEvents; ++i) {
        events[i].timestamp = time(NULL);
        strcpy(events[i].sourceIP, sourceIP);
        strcpy(events[i].destinationIP, destinationIP);
        events[i].protocolType = protocolType;
        events[i].payloadSize = 0;

        if (!validateTrafficEvent(&events[i], maxPayloadSize)) {
            free(events);
            return NULL;
        }
    }

    // Check for duplicate IP combinations and handle memory reallocation as needed
    size_t numUniqueEvents = 0;
    TrafficEvent* uniqueEvents = NULL;
    for (size_t i = 0; i < numEvents; ++i) {
        if (isUniqueIPCombination(&events[i], uniqueEvents, numUniqueEvents)) {
            uniqueEvents = realloc(uniqueEvents, sizeof(TrafficEvent) * (++numUniqueEvents));
            if (!uniqueEvents) {
                fprintf(stderr, "Error: Failed to allocate memory for unique network traffic events.\n");
                free(events);
                return NULL;
            }
            uniqueEvents[numUniqueEvents - 1] = events[i];
        }
    }

    free(events);
    events = uniqueEvents;
    return events;
}
