struct lockfree_list {
    hash_node_t **nodes;
    unsigned long size;
    pthread_mutex_t mutex; // For logging and configuration changes
};

void init_lockfree_list(struct lockfree_list *lf, unsigned long size) {
    lf->size = size;
    lf->nodes = calloc(size, sizeof(hash_node_t*));
    pthread_mutex_init(&lf->mutex, NULL);
}

unsigned long hash(const char *key, unsigned long size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % size;
}

NFAPI_CRC_INDICATION_PDU_T* get_or_create(struct lockfree_list *lf, const char *key) {
    unsigned long index = hash(key, lf->size);
    pthread_mutex_lock(&lf->mutex);
    hash_node_t *current = lf->nodes[index];
    pthread_mutex_unlock(&lf->mutex);

    while (current) {
        if (strcmp(current->data.crc, key) == 0)
            return &current->data;
        current = current->next;
    }

    pthread_mutex_lock(&lf->mutex);
    hash_node_t *new_node = malloc(sizeof(hash_node_t));
    if (new_node == NULL) {
        printf("Error: Out of memory\n");
        pthread_mutex_unlock(&lf->mutex);
        return NULL;
    }
    memcpy(&new_node->data, key, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = lf->nodes[index];
    lf->nodes[index] = new_node;
    pthread_mutex_unlock(&lf->mutex);

    return &new_node->data;
}

