void* memory_pool_alloc(size_t size) {
    static void* pool = NULL;
    static size_t capacity = 0;
    static size_t count = 0;

    if (!pool || capacity <= count + size) {
        if (capacity == 0) {
            capacity = size;
            pool = malloc(capacity);
        } else {
            void* temp = realloc(pool, capacity * 2);
            if (!temp) {
                perror("Error resizing memory pool");
                return NULL;
            }
            pool = temp;
            capacity *= 2;
        }
    }

    void* result = &((char*)pool)[count * sizeof(NFAPI_CRC_INDICATION_PDU_T)];
    count += size;
    return result;
}

