struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

void nfapi_crc_indication_pdu_t_init(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->rnti = rand();
    pdu->crc_indication.crcflag = (rand() % 2);
}

struct list_node* create_list_node(NFAPI_CRC_INDICATION_PDU_T data) {
    struct list_node* new_node = (struct list_node*)malloc(sizeof(struct list_node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_list_node(struct list_node** head, struct list_node* node) {
    if (*head == NULL) {
        *head = node;
    } else {
        struct list_node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

void delete_list_node(struct list_node** head, struct list_node* node) {
    if (*head == node) {
        *head = node->next;
    } else {
        struct list_node* current = *head;
        while (current->next != node && current->next != NULL) {
            current = current->next;
        }
        if (current->next == NULL) {
            printf("Error: Node not found\n");
            return;
        }
        current->next = node->next;
    }
}

void manage_list(int max_capacity, int throughput) {
    struct list_node* head = NULL;
    int num_elements = 0;
    clock_t start_time = clock();

    for (int i = 0; i < throughput; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        nfapi_crc_indication_pdu_t_init(&pdu);

        // Check if the list is full and remove the oldest entry if necessary.
        if (num_elements >= max_capacity) {
            clock_t elapsed_time = clock() - start_time;
            if ((clock() - start_time) / CLOCKS_PER_SEC > 10.0) { // Adjust the time limit as per requirements.
                printf("Exceeded specified time limit for large input sizes.\n");
                break;
            }
            struct list_node* oldest = head;
            while (oldest->next != NULL) {
                oldest = oldest->next;
            }
            delete_list_node(&head, oldest);
        }

        // Insert the new data into the list.
        struct list_node* new_node = create_list_node(pdu);
        insert_list_node(&head, new_node);
        ++num_elements;
    }
}

void log_performance(int throughput) {
    double operations_per_second = (double)throughput / ((clock() - start_time) / CLOCKS_PER_SEC);
    printf("Performed %d operations at a rate of approximately %f operations per second\n", throughput, operations_per_second);
}
```

