static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
static size_t num_entries = 0, capacity = 0;

void manage_dynamic_array(enum operation op, const RX_UE_INFORMATION_TAG* rx_ue, uint32_t rnti, CRC_INDICATION_REL8_TAG crc_indication, bool* crcflag) {
    pthread_mutex_lock(&mutex);

    if (op == INSERT) {
        // Handle memory allocation and capacity expansion here
        array[num_entries] = (NFAPI_CRC_INDICATION_PDU_T){ *rx_ue, rnti, crc_indication, *crcflag };
        num_entries++;
    } else if (op == REMOVE) {
        // Search for the specified RNTI and remove it
        for (size_t i = 0; i < num_entries; ++i) {
            if (array[i].rnti == rnti) {
                memmove(&array[i], &array[i + 1], --num_entries - i);
                break;
            }
        }
    } else if (op == UPDATE) {
