    NFAPI_CRC_INDICATION_PDU_T** indications = (NFAPI_CRC_INDICATION_PDU_T**)args;
    size_t* size = (size_t*)(*indications + 1);
    size_t max = *size;

    for (size_t i = 0; i < max; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* indication = &(*indications)[i];

        if (!indication->rx_ue_information_tag.is_initialized ||
            !indication->rnti.is_initialized ||
            !indication->crc_indication_rel8_tag.is_initialized) {
            LOG("Invalid structure: skipping.");
            continue;
        }

        if (!realloc((*indications), sizeof(NFAPI_CRC_INDICATION_PDU_T) * (max + 1))) {
            perror("Reallocation failed");
            exit(EXIT_FAILURE);
        }
        *size += 1;

        // Initialize the structure with valid data and a randomly generated CRCFLAG
        indication->rx_ue_information_tag.value = RX_UE_INFORMATION_TAG_VALUE;
        indication->rnti.value = RNTI_VALUE;
        indication->crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    return NULL;
}

void populateNfapiIndications(NFAPI_CRC_INDICATION_PDU_T** indications, size_t capacity) {
    if (!indications || !capacity) {
        LOG("Invalid input: no structures or invalid capacity.");
        return;
    }

    pthread_t threads[CPU_COUNT];

    *indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!*indications) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    size_t chunkSize = capacity / CPU_COUNT;
    for (size_t i = 0; i < CPU_COUNT; ++i) {
        size_t startIndex = i * chunkSize;
        size_t endIndex = (i == CPU_COUNT - 1) ? capacity : startIndex + chunkSize;
        pthread_create(&threads[i], NULL, populateNfapiIndications, &(*indications + startIndex));
    }

    for (size_t i = 0; i < CPU_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }
}
