char* get_crc_dir(const char* parent_dir) {
    const char *crc_dir = getenv("CRC_DIR");
    if (crc_dir) {
        return crc_dir;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));
    char* dir = malloc(strlen(parent_dir) + strlen(timestamp) + 1);
    if (!dir) {
        perror("malloc failed");
        pthread_mutex_destroy(&mutex);
        return NULL;
    }

    snprintf(dir, sizeof(dir), "%s/%s", parent_dir, timestamp);

    mode_t mode = S_IRWXU | S_IRGRP | S_IROTH;
    int ret = mkdir(dir, mode);
    if (ret && errno != EEXIST) {
        perror("mkdir failed");
        free(dir);
        pthread_mutex_destroy(&mutex);
        return NULL;
    }

    setenv("CRC_DIR", dir, 1);
    pthread_mutex_destroy(&mutex);

    return dir;
}

void save_pdus(const char* dir, NFAPI_CRC_INDICATION_PDU_T *pdu, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        FILE *file = fopen(dir "/pdu_" i ".bin", "wb");
        if (!file) {
            perror("fopen failed");
            continue;
        }

        fwrite(&pdu[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        fclose(file);

        if (ferror(file)) {
            perror("fwrite/fclose failed");
        }
    }
}

void* save_pdus_thread(void *arg) {
    const char* dir = arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdus(N);
    if (!pdu) return NULL;

    save_pdus(dir, pdu, N);

    free(pdu);
    return NULL;
}

int main() {
    const char* parent_dir = "/path/to/parent/directory";
    char* crc_dir = get_crc_dir(parent_dir);
    if (!crc_dir) {
        perror("Failed to create CRC directory");
        return 1;
    }

    pthread_t thread;
    int ret = pthread_create(&thread, NULL, save_pdus_thread, crc_dir);
    if (ret) {
        perror("pthread_create failed");
        free(crc_dir);
        return 1;
    }

    pthread_join(thread, NULL);

    free(crc_dir);
    return 0;
}
