typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuthToken;

bool validate_oauth_token(const char *json, size_t len) {
    if (!json || len == 0) return false;

    const char *iter = json;
    bool access_token_present = false, token_type_found = false, refresh_token_present = false;
    OAuthToken token;

    // Iterate through the JSON string, skipping key-value pairs and whitespace.
    while (*iter) {
        if (*iter++ == ':') continue;  // Advance to value
        if (!isspace((unsigned char)*iter)) break;  // Found non-whitespace character
    }

    if (!*iter || iter + 1 >= json + len) return false;  // Invalid JSON format

    memset(&token, 0, sizeof(token));

    const char *key_start = iter - 1, *key_end;
    for (key_end = iter; *iter++; ) {
        if (*iter == ',' || *iter == '}') break;
    }

    size_t key_len = key_end - key_start;

    // Check for required fields and validate their values.
    if (!strcmp(key_start, "access_token")) {
        access_token_present = true;
        token.access_token = malloc(key_len + 1);
        memcpy(token.access_token, key_start, key_len);
        token.access_token[key_len] = '\0';
        if (strlen(token.access_token) == 0) goto error;
    }

    if (!strcmp(key_start, "expires_in")) {
        if (sscanf(key_end, "%d", &token.expires_in) != 1 || token.expires_in <= 0) goto error;
    }

    if (!strcmp(key_start, "token_type")) {
        token_type_found = true;
        size_t len = strlen(key_end);
        if (len < 2 || strncmp(key_end + len - 7, "Bearer", 6) != 0 || (len > 14 && strncmp(key_end + len - 13, "BearerWithScope", 12))) goto error;
        if (len == 7) {
            token.token_type = malloc(7);
            memcpy(token.token_type, key_end, 7);
        } else if (len > 14) {
            token.token_type = malloc(13);
            memcpy(token.token_type, key_end + len - 13, 13);
        }
    }

    if (!strcmp(key_start, "refresh_token")) {
        refresh_token_present = true;
        token.refresh_token = malloc(129);  // Max length of 128 characters + null terminator
        memcpy(token.refresh_token, key_end, strlen(key_end));
        if (strlen(token.refresh_token) < 32 || strlen(token.refresh_token) > 128) goto error;
    }

    // Iterate through the JSON string again to check for additional fields and ignore them.
    iter = json;
    while (*iter) {
        if (strcmp(iter, key_start)) continue;  // Skip current field
        if (!*++iter) goto error;  // Found non-key character after key
        if (!isspace((unsigned char)*iter)) break;  // Found non-whitespace character
    }

    if (access_token_present && token_type_found && (!refresh_token_present || refresh_token_valid(token.refresh_token))) return true;
error:
    free(token.access_token);
    free(token.refresh_token);
    return false;
}

bool refresh_token_valid(const char *refresh_token) {
    // Implement custom validation for the refresh token if needed here.
    return strlen(refresh_token) >= 32 && strlen(refresh_token) <= 128;
}
