#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct UserSession {
    int id;
    struct activityLog* logs;
    time_t lastSeen;
    int refCount;
    pthread_mutex_t lock;
} UserSession;

struct activityLog {
    time_t timestamp;
    char* activity;
};

typedef struct Node {
    UserSession userSession;
    struct Node *prev, *next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int idleThreshold = 600; // in seconds
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t listCond = PTHREAD_COND_INITIALIZER;
int numActiveSessions = 0;

void initUserSession(UserSession* session, int id) {
    session->id = id;
    session->logs = malloc(sizeof(struct activityLog));
    session->lastSeen = time(NULL);
    session->refCount = 1;
    pthread_mutex_init(&session->lock, NULL);
}

UserSession* createNewUserSession() {
    UserSession* newSession = malloc(sizeof(UserSession));
    initUserSession(newSession, rand());
    return newSession;
}

void addToList(UserSession* session) {
    pthread_mutex_lock(&listLock);
    Node* newNode = malloc(sizeof(Node));
    initNode(newNode);
    newNode->userSession = *session;

    if (!head) {
        head = tail = newNode;
    } else {
        newNode->next = head;
        head->prev = newNode;
        head = newNode;
    }

    pthread_mutex_unlock(&listLock);
}

void removeFromList(UserSession* session) {
    pthread_mutex_lock(&listLock);
    Node* current = head;
    while (current != NULL) {
        if (&current->userSession == session) {
            if (current == head) {
                head = current->next;
                if (head) head->prev = NULL;
            } else if (current == tail) {
                tail = current->prev;
                tail->next = NULL;
            } else {
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }
            free(current);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&listLock);
}

void updateLastSeen(UserSession* session) {
    pthread_mutex_lock(&session->lock);
    session->lastSeen = time(NULL);
    pthread_mutex_unlock(&session->lock);
}

int incrementRefCount(UserSession* session) {
    pthread_mutex_lock(&session->lock);
    int oldRefCount = session->refCount++;
    pthread_mutex_unlock(&session->lock);
    return oldRefCount;
}

void decrementRefCount(UserSession* session) {
    pthread_mutex_lock(&session->lock);
    if (--session->refCount == 0) {
        removeFromList(session);
    }
    pthread_mutex_unlock(&session->lock);
}

void purgeInactiveSessions() {
    time_t now = time(NULL);
    pthread_mutex_lock(&listLock);
    Node* current = head;
    while (current != NULL) {
        if (difftime(now, current->userSession.lastSeen) > idleThreshold) {
            removeFromList(&current->userSession);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&listLock);
}

void reportActiveSessionCount() {
    pthread_mutex_lock(&listLock);
    numActiveSessions = 0;
    Node* current = head;
    while (current != NULL) {
        if (current->userSession.refCount > 0) numActiveSessions++;
        current = current->next;
    }
    pthread_mutex_unlock(&listLock);
}
```

