#define MAX_ELEMENTS 10000

static NFAPI_CRC_INDICATION_PDU_T* elements = NULL;
static size_t num_elements = 0;
static pthread_mutex_t mutex;
static bool logging_enabled = true;

void init_array() {
    if (MAX_ELEMENTS > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Max elements exceeds maximum supported size.\n");
        exit(1);
    }

    elements = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elements) {
        if (logging_enabled) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
        }
        exit(1);
    }
    num_elements = 0;
    pthread_mutex_init(&mutex, NULL);
}

bool validate_tag(uint32_t tag) {
    return (tag >= 1 && tag <= INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void insert_element(const NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);
    while (num_elements >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&mutex);
        usleep(1000);
        pthread_mutex_lock(&mutex);
    }

    if (!validate_tag(element->RX_UE_INFORMATION_TAG)) {
        fprintf(stderr, "Error: Invalid RX_UE_INFORMATION_TAG value.\n");
        exit(1);
    }

    for (size_t i = 0; i < num_elements; ++i) {
        if (elements[i].RX_UE_INFORMATION_TAG == element->RX_UE_INFORMATION_TAG) {
            fprintf(stderr, "Error: TAG already exists in the array.\n");
            exit(1);
        }
    }

    elements[num_elements] = *element;
    num_elements++;
    pthread_mutex_unlock(&mutex);
}

void log_allocation_failures() {
    if (!logging_enabled) return;

    fprintf(stderr, "Error: Memory allocation failed.\n");
}
