void nfapi_queue_init(struct queue* queue, uint32_t max_entries) {
    queue->head = NULL;
    queue->tail = NULL;
    sem_init(&queue->empty, 0, max_entries);
    sem_init(&queue->size_limit, 0, ULONG_MAX - max_entries);
}

void nfapi_queue_push(struct queue* queue, NFAPI_RLC_PDU_T data) {
    queue_node_t* node = (queue_node_t*) malloc(sizeof(queue_node_t));

    if (!node) return;

    node->data = data;
    node->next = NULL;

    sem_wait(&queue->size_limit);

    if (queue->tail == NULL) {
        queue->head = node;
        queue->tail = node;
    } else {
        queue->tail->next = node;
        queue->tail = node;
    }

    sem_post(&queue->empty);
}

NFAPI_RLC_PDU_T nfapi_queue_pop(struct queue* queue) {
    queue_node_t* node = queue->head;

    if (node == NULL) return (NFAPI_RLC_PDU_T){0};

    NFAPI_RLC_PDU_T data = node->data;

    queue->head = node->next;

    if (queue->head == NULL) queue->tail = NULL;

    free(node);

    sem_post(&queue->empty);

