        pthread_mutex_unlock(&list_mutex);
        return NULL; // RNTI already exists
    }
    if (!head) {
        head = tail = node;
    } else {
        while (cur && cur->next) {
            cur = cur->next;
        }
        cur->next = node;
        tail = node;
    }
    pthread_mutex_unlock(&list_mutex);
    return head;
}

void free_list() {
    NFAPI_CRC_INDICATION_PDU_T *cur, *next;
    pthread_mutex_lock(&list_mutex);
    cur = list_head;
    while (cur) {
        next = cur->next;
        free(cur);
        cur = next;
    }
    list_head = NULL;
    pthread_mutex_unlock(&list_mutex);
}
```

This code provides a basic implementation of a thread-safe linked list in C. It initializes the list with up to 1000 nodes, ensures each node has a unique RNTI value, and handles memory allocation errors gracefully. The `add_node()` function adds new nodes to the list while ensuring no duplicate RNTIs are added. The `free_list()` function deallocates all nodes in the list when no longer needed.

However, this solution does not optimize for concurrency or memory management strategies beyond basic thread synchronization using a mutex. You may consider implementing more advanced data structures and concurrency mechanisms such as buddy allocators, slab allocators, or other lock-free solutions to improve performance under heavy load conditions.']

