class NetworkSimulationFramework {
public:
    // Constructor, initializing containers and setting up logging configuration
    NetworkSimulationFramework(size_t numThreads) : _numThreads(numThreads), _log("NetworkLogger") {
        _dataQueue.reserve(NUM_DATA * numThreads);
    }

    // Function to create and populate the list of structures with random values
    void generateData() {
        std::uniform_int_distribution<uint32_t> rxiDist(0, UINT32_MAX);
        std::uniform_int_distribution<uint16_t> rntiDist(0, UINT16_MAX);
        std::uniform_int_distribution<uint16_t> crcIndDist(0, UINT16_MAX);
        std::uniform_int_distribution<bool> crcFlagDist(false, true);

        for (size_t i = 0; i < NUM_DATA; ++i) {
            NFAPI_CRC_INDICATION_PDU_T data;
            data.RX_UE_INFORMATION_TAG = rxiDist(generator);
            data.RNTI = rntiDist(generator);
            data.CRC_INDICATION_REL8_TAG = crcIndDist(generator);
            data.CRCFLAG = crcFlagDist(generator) & CRF_FLAGS_BITMASK;
            _dataQueue.emplace_back(data);
        }
    }

    // Function to process the data concurrently using threads
    void runSimulation() {
        std::vector<std::thread> threads;

        for (size_t i = 0; i < _numThreads; ++i) {
            threads.emplace_back(std::thread(&NetworkSimulationFramework::processData, this));
        }

        for (auto& t : threads) {
            t.join();
        }
    }

private:
