    void processData() {
        while (!_dataQueue.empty()) {
            auto data = _dataQueue.front();
            _dataQueue.pop_front();
            // Simulate transmission and logging here, adapting to network conditions
            std::this_thread::sleep_for(std::chrono::milliseconds(getRandomDuration()));
            bplog::info("Processed data with RX_UE_INFORMATION_TAG: {} and CRCFLAG: {}", data.RX_UE_INFORMATION_TAG, data.CRCFLAG);
        }
    }

    // Helper function to generate a random duration for the simulated transmission time
    std::chrono::milliseconds getRandomDuration() const {
        std::uniform_int_distribution<int> dist(MIN_DURATION, MAX_DURATION);
        return std::chrono::milliseconds(dist(generator));
    }

    // Logging system with adjustable log levels and easy configuration
    boost::log::sources::severity_logger_mt<spdlog::source_attr> _log;

    // Thread-safe queue for data storage and processing
    std::queue<NFAPI_CRC_INDICATION_PDU_T> _dataQueue;

    // Number of threads to use for data processing
    size_t _numThreads;

    // Random number generator for creating random values
    static std::mt19937 generator;
};

std::mt19937 NetworkSimulationFramework::generator(std::random_device{}());

