    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t num_elements;
    size_t max_elements;
    sem_t list_mutex;
};

void init_list_manager(struct list_manager* manager, size_t max_elements) {
    // Initialize mutex and other fields
    manager->head = NULL;
    manager->tail = NULL;
    manager->num_elements = 0;
    manager->max_elements = max_elements;
    sem_init(&manager->list_mutex, 0, 1);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->crcflag = rand() % 2;
    pdu->next = NULL;
    return pdu;
}

bool insert_pdu(struct list_manager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_wait(&manager->list_mutex);
    if (manager->num_elements >= manager->max_elements) {
        sem_post(&manager->list_mutex);
        return false; // Reach max elements, return false to indicate failure
    }

    if (!manager->head) {
        manager->head = pdu;
        manager->tail = pdu;
    } else {
        manager->tail->next = pdu;
        manager->tail = pdu;
    }
    manager->num_elements++;
    sem_post(&manager->list_mutex);
    return true; // Insertion successful
}

NFAPI_CRC_INDICATION_PDU_T* find_pdu(struct list_manager* manager, RX_UE_INFORMATION_TAG tag) {
    NFAPI_CRC_INDICATION_PDU_T* current = manager->head;
    while (current) {
        if (current->tag == tag) return current;
        current = current->next;
    }
    return NULL; // PDU not found
}

void cleanup(struct list_manager* manager, time_t expiration) {
    sem_wait(&manager->list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    NFAPI_CRC_INDICATION_PDU_T *temp;
    time_t now = time(NULL);

    while (current) {
        if (!current->next && now - current->crc_indication.time > expiration) {
            manager->head = current->next;
            if (!manager->head) manager->tail = NULL;
            free(current);
            current = manager->head;
            manager->num_elements--;
        } else if (now - current->crc_indication.time > expiration) {
            temp = current->next;
            free(current);
            current = temp;
            manager->num_elements--;
        } else {
            current = current->next;
        }
    }
    sem_post(&manager->list_mutex);
}
