void *dns_resolve(void *arg) {
    struct dns_query *query = arg;
    in_addr_t resolved_ip;
    int status = getaddrinfo(query->hostname, NULL, NULL, &resolved_ip);
    if (status != 0) {
        fprintf(stderr, "Failed to resolve %s: %s\n", query->hostname, gai_strerror(status));
        return NULL;
    }
    query->ip_addr = malloc(sizeof(u_char) * INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &resolved_ip, query->ip_addr, sizeof(query->ip_addr));
    return query->ip_addr;
}

void dns_throttle() {
    usleep(100000); // Sleep for 100ms to throttle DNS requests
}

void init_data(struct data *data) {
    size_t entries = 1 + (rand() % 10000);
    data->list = malloc(entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->size = 0;
    data->capacity = entries;

    for (size_t i = 0; i < entries; ++i) {
        data->list[data->size].tag.tag_value = rand() % 256;
        data->list[data->size].rnti.rnti_value = rand() % 1024;
        data->list[data->size].crc_indication.crcflag = rand() % 2;
        ++data->size;
    }
}

u_char **resolve_hostnames(struct data *data) {
    FILE *config = fopen(data->config_file, "r");
    if (!config) {
        fprintf(stderr, "Failed to open config file\n");
        return NULL;
    }

    char line[256];
    size_t num_queries = 0;
    while (fgets(line, sizeof(line), config)) {
        ++num_queries;
    }
    rewind(config);

    u_char **resolved_ips = malloc(num_queries * sizeof(u_char*));
    size_t resolved_count = 0;
    struct dns_query *queries = malloc(num_queries * sizeof(struct dns_query));

    for (size_t i = 0; i < num_queries; ++i) {
        if (!fgets(queries[i].hostname, sizeof(queries[i].hostname), config)) {
            fprintf(stderr, "Failed to read hostname from config file\n");
            break;
        }
        queries[i].index = i;
        queries[i].ip_addr = NULL;
        pthread_create(&queries[i].thread_id, NULL, dns_resolve, &queries[i]);
    }

    for (size_t i = 0; i < num_queries; ++i) {
        pthread_join(queries[i].thread_id, &queries[i].ip_addr);
        if (queries[i].ip_addr) {
            resolved_ips[resolved_count] = queries[i].ip_addr;
            ++resolved_count;
        }
    }

    free(queries);

    u_char **result = malloc(resolved_count * sizeof(u_char*));
    memcpy(result, resolved_ips, resolved_count * sizeof(u_char*));
    free(resolved_ips);

    return result;
}
