}

// Function to add a message to the dynamic array, handling concurrent access safely
void add_message(NFAPI_RRC_MSG_T* message) {
    pthread_mutex_lock(&lock);

    if (num_messages >= max_messages) {
        // Periodically clean up unused messages when necessary
        if ((time(NULL) - message->timestamp) > 60 * 60) {
            free(message->pdcp_sdu);
            free(message);
            num_messages--;
        } else {
            free(message);
        }
    } else {
        messages[num_messages] = message;
        num_messages++;
    }

    pthread_mutex_unlock(&lock);
}

// Function to initialize the dynamic array with at least N messages
void init_messages(unsigned int n) {
    for (int i = 0; i < n; ++i) {
        add_message(create_message());
    }
}
