#include <iostream>
#include <functional>
#include <memory>
#include <unordered_map>
#include <chrono>
#include <mutex>

struct NetworkInterfaceConfig {
    int bandwidth = 0;
    double latencyTolerance = 0.0;
    unsigned priorityLevel = 0;
};

class DynamicArray {
private:
    std::unordered_map<int, std::unique_ptr<NetworkInterfaceConfig>> data;
    mutex mtx;
    time_point lastUpdateTime = clock::now();

public:
    void add(const NetworkInterfaceConfig& config) {
        lock_guard<mutex> lock(mtx);
        data.emplace(config.priorityLevel, std::make_unique<NetworkInterfaceConfig>(config));
    }

    bool update(unsigned priorityLevel, const NetworkInterfaceConfig& config) {
        auto it = data.find(priorityLevel);
        if (it != data.end()) {
            it->second->bandwidth = config.bandwidth;
            it->second->latencyTolerance = config.latencyTolerance;
            return true;
        }
        return false;
    }

    int getTotalBandwidth() const {
        int totalBandwidth = 0;
        for (const auto& entry : data) {
            totalBandwidth += entry.second->bandwidth;
        }
        return totalBandwidth;
    }

    void updateConfigurations(const std::function<NetworkInterfaceConfig(unsigned priorityLevel)>& updater) {
        lock_guard<mutex> lock(mtx);
        auto now = clock::now();
        if (duration_cast<hours>(now - lastUpdateTime).count() < 1) return;

        for (auto& entry : data) {
            entry.second->bandwidth = updater(entry.first).bandwidth;
            entry.second->latencyTolerance = updater(entry.first).latencyTolerance;
        }
        lastUpdateTime = now;
    }
};
