```cpp
#include <functional>
#include <queue>
#include <mutex>
#include <memory>
#include <random>
#include <iostream>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcFlag; // randomly set CRCFLAG
};

class MemoryPool {
public:
    MemoryPool(size_t maxSize) : maxSize_(maxSize), currentSize_(0) {}

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        if (currentSize_ + sizeof(NFAPI_CRC_INDICATION_PDU_T) > maxSize_) {
            std::cerr << "Error: Memory pool exceeded the maximum size limit." << std::endl;
            return nullptr;
        }

        NFAPI_CRC_INDICATION_PDU_T* data = reinterpret_cast<NFAPI_CRC_INDICATION_PDU_T*>(malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)));
        if (!data) {
            std::cerr << "Error: Memory allocation failure." << std::endl;
            return nullptr;
        }
        currentSize_ += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        std::random_device rd;
        std::uniform_int_distribution<> distr(0, 1);
        data->crcFlag = static_cast<CRC_INDICATION_REL8_TAG>(distr(rd));
        return data;
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* data) {
        if (data) {
            free(data);
            currentSize_ -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
    }

private:
    const size_t maxSize_;
    size_t currentSize_;
};

class Task {
public:
    Task(MemoryPool& memoryPool, int priority) : memoryPool_(memoryPool), priority_(priority) {}

    void run() {
        NFAPI_CRC_INDICATION_PDU_T* data = memoryPool_.allocate();
        if (data) {
            // Process and log the total number of elements created
            ++totalElementsCreated_;
            // Verify that the CRC flag is set correctly after population
            if (data->crcFlag != 1) {
                std::cerr << "Error: CRC flag not set correctly." << std::endl;
            }
            // Add the task to the priority queue for processing
            addToQueue(std::move(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(data)));
        }
    }

private:
    MemoryPool& memoryPool_;
    int priority_;
    static std::mutex mtx; // for thread-safety in the priority queue
    static std::priority_queue<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>, std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>>, std::greater<>> taskQueue_;
    size_t totalElementsCreated_ = 0;

    static void addToQueue(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> task) {
        std::unique_lock<std::mutex> lock(mtx);
        taskQueue_.push(std::move(task));
    }
};
std::mutex Task::mtx;
std::priority_queue<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>, std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>>, std::greater<>> Task::taskQueue_;
