} NFAPI_CRC_INDICATION_PDU;

sem_t log_mutex; // Mutex for logging to prevent race conditions

NFAPI_CRCI_INDICATION_PDU* create_list(size_t N) {
    if (N > NFAPI_MAX_CHESS_PDU) {
        fprintf(stderr, "Error: Request size exceeds NFAPI_MAX_CHESS_PDU\n");
        return NULL;
    }

    sem_init(&log_mutex, 0, 1); // Initialize mutex for logging

    NFAPI_CRCI_INDICATION_PDU* list = malloc(N * sizeof(NFAPI_CRCI_INDICATION_PDU));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        sem_destroy(&log_mutex); // Cleanup log mutex on failure
        return NULL;
    }

    size_t i = 0;
    uint16_t current_RNTI = 0;
    for (; i < N - 1; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand(); // Populate structures with random data
        do {
            list[i].RNTI = rand();
        } while ((i == 0 || list[i - 1].RNTI + 1 != list[i].RNTI)); // Ensure no two consecutive structures have the same RNTI value
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
        log_event("PDU creation", i, list[i].RNTI); // Log event using pthread_mutex_lock and pthread_mutex_unlock for locking log_mutex
    }

    list[i].RX_UE_INFORMATION_TAG = rand(); // Populate last structure with random data
    list[i].RNTI = current_RNTI + 1; // Last RNTI value should be one more than the previous one to avoid duplicate values in consecutive structures
    list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    log_event("PDU creation", i, list[i].RNTI); // Log event using pthread_mutex_lock and pthread_mutex_unlock for locking log_mutex

    // Verify integrity of the populated list using a checksum function
    uint32_t checksum = 0;
    for (size_t j = 0; j < N; ++j) {
        checksum += list[j].RX_UE_INFORMATION_TAG + list[j].RNTI + list[j].CRC_INDICATION_REL8_TAG;
    }

    // Optimized verification logic to avoid introducing latency in real-time processing tasks
    if (checksum != rand()) {
        fprintf(stderr, "Error: List integrity check failed\n");
        free(list);
        sem_destroy(&log_mutex); // Cleanup log mutex on failure
        return NULL;
    }

    return list;
}

void log_event(const char* event_type, size_t index, uint16_t rnti) {
    pthread_t tid = pthread_self(); // Get current thread ID
    struct timespec time;
    clock_gettime(CLOCK_REALTIME, &time);

    sem_wait(&log_mutex); // Acquire log mutex before logging events

    printf("[%lu] [%s] [%zu] [%u]: Event occurred\n", tid, event_type, index, rnti);

    sem_post(&log_mutex); // Release log mutex after logging the event
}
