typedef struct {
    sem_t whitelist_mutex;
    uint32_t* whitelist;
    size_t whitelist_size;
    void (*refresh)(void); // External callback for refreshing the whitelist
} WhitelistManager;

void create_whitelist_manager(WhitelistManager* manager, size_t capacity) {
    manager->whitelist = malloc(capacity * sizeof(uint32_t));
    if (!manager->whitelist) {
        perror("malloc failure");
        return;
    }
    manager->whitelist_size = capacity;
    sem_init(&manager->whitelist_mutex, 0, 1);
}

void destroy_whitelist_manager(WhitelistManager* manager) {
    if (manager->whitelist) {
        free(manager->whitelist);
        manager->whitelist = NULL;
    }
    sem_destroy(&manager->whitelist_mutex);
}

void refresh_whitelist(WhitelistManager* manager) {
    if (manager->refresh) {
        manager->refresh();
    }
}

// Function for generating NFAPI_CRC_INDICATION_PDU_T structures
void* generate_pdu(void* arg) {
    WhitelistManager* manager = arg;
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("malloc failure");
        return NULL;
    }

    sem_wait(&manager->whitelist_mutex);
    // Validate RNTI against whitelist and update it as needed
    bool valid = false;
    size_t i;
    for (i = 0; i < manager->whitelist_size && !valid; ++i) {
        if (manager->whitelist[i] == ((uint32_t)pdu->rnti & 0xFFFFFFFF)) {
            valid = true;
        }
    }
    sem_post(&manager->whitelist_mutex);

    if (!valid) {
        // Handle RNTI validation failure, e.g., log the event or drop the packet
        free(pdu);
        return NULL;
    }

    pdu->timestamp = time(NULL);
    pdu->rnti = rand() % (1 << 30); // Generate a valid RNTI according to network policy
    pdu->crc_indication.crcFlag = rand() % 2;

    return pdu;
}

// Function for dynamically generating and populating a list of NFAPI_CRC_INDICATION_PDU_T structures
void* create_pdu_list(WhitelistManager* manager, size_t num_ues) {
    void** pdu_list = malloc(num_ues * sizeof(void*));
    if (!pdu_list) {
        perror("malloc failure");
        return NULL;
    }

    pthread_t* threads = malloc(num_ues * sizeof(pthread_t));
    if (!threads) {
        free(pdu_list);
        perror("malloc failure");
        return NULL;
    }

    size_t i;
    for (i = 0; i < num_ues; ++i) {
        pthread_create(&threads[i], NULL, generate_pdu, manager);
    }

    // Wait for all threads to finish executing
    for (i = 0; i < num_ues; ++i) {
        pthread_join(threads[i], &pdu_list[i]);
        if (!pdu_list[i]) {
            // Handle failed thread execution, e.g., log the event or skip the UE
            continue;
        }
    }

    free(threads);
    return pdu_list;
}
