    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define LOG_BUF_SIZE 4096
static char log_buf[LOG_BUF_SIZE];
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsnprintf(log_buf, LOG_BUF_SIZE, format, args);
    va_end(args);

    pthread_mutex_lock(&log_mutex);
    printf("%s", log_buf);
    pthread_mutex_unlock(&log_mutex);
}

void* alloc_pdus(size_t num_elements, size_t *pnum_allocated) {
    void *mem = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mem) {
        log("Error: Out of memory");
        return NULL;
    }

    *pnum_allocated = num_elements;
    return mem;
}

void free_pdus(void *ptr, size_t num_elements) {
    if (ptr) {
        free(ptr);
        log("Freed PDU memory");
    }
}

NFAPI_CRC_INDICATION_PDU_T* init_pdu(size_t index, void *pdus) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)((uint8_t *)pdus + index * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = index;
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG = rand();
    pdu->CRCFLAG = (rand() % 2) == 0;
    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T* populate_pdus(size_t num_elements, void *pdus) {
    size_t allocated;
    void *mem = alloc_pdus(num_elements, &allocated);
    if (!mem) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* first_pdu = init_pdu(0, mem);
    for (size_t i = 1; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* next_pdu = init_pdu(i, mem);
        first_pdu->next = next_pdu;
        first_pdu = next_pdu;
    }
    first_pdu->next = NULL;

    log("Populated %zu PDUs", allocated);
    return first_pdu;
}

void cleanup_pdus(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *next = pdu->next;
        free_pdus(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu = next;
    }
}
```

