fn populateNfaapiCRCIndications(n: usize) -> NFAPI_CRC_INDICATION_PDU_T_VEC {
    let mut indications = Vec::with_capacity(n);

    // Initialize iterator variable i for looping through the number of structures.
    let n = Arc::new(Mutex::new(n));
    let i = Arc::new(Mutex::new(0));

