    CRC_INDICATION_REL8_TAG crc_indication;
    uint64_t session_id;
    UserActivityLogs logs;
    time_t last_seen;
    atomic_int ref_count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU;

typedef struct _POOL_T {
    NFAPI_CRC_INDICATION_PDU **pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} POOL_T;

void init_session(NFAPI_CRC_INDICATION_PDU *session) {
    session->ref_count = 1;
    session->last_seen = time(NULL);
    atomic_init(&session->ref_count, 1);
    pthread_mutex_init(&session->mutex, NULL);
}

void increment_ref(NFAPI_CRC_INDICATION_PDU *session) {
    atomic_add(1, &session->ref_count);
}

bool decrement_and_check_ref(NFAPI_CRC_INDICATION_PDU *session) {
    int val = atomic_dec(&session->ref_count);
    return !val;
}

void free_session(NFAPI_CRC_INDICATION_PDU *session) {
    if (decrement_and_check_ref(session)) {
        pthread_mutex_destroy(&session->mutex);
        free(session);
    }
}

POOL_T* create_pool() {
    POOL_T *pool = malloc(sizeof(POOL_T));
    pool->capacity = MAX_SESSIONS;
    pool->count = 0;
    pool->pool = calloc(MAX_SESSIONS, sizeof(NFAPI_CRC_INDICATION_PDU*));
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

NFAPI_CRC_INDICATION_PDU* acquire_session(POOL_T *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->pool[i]) {
            pool->pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
            init_session(pool->pool[i]);
            ++pool->count;
            return pool->pool[i];
        }
    }
    return NULL;
}

void release_session(POOL_T *pool, NFAPI_CRC_INDICATION_PDU *session) {
    if (session) {
        increment_ref(session);
        pthread_mutex_lock(&pool->mutex);
        pool->pool[--pool->count] = session;
        pthread_mutex_unlock(&pool->mutex);
    }
}

void purge_inactive_sessions(POOL_T *pool) {
    struct timeval now;
    gettimeofday(&now, NULL);
    long timestamp = now.tv_sec - IDLE_THRESHOLD;

    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->count; ++i) {
        if (time(NULL) > pool->pool[i]->last_seen + timestamp) {
            free_session(pool->pool[i]);
            pool->pool[i] = NULL;
            --pool->count;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

void report_active_sessions(POOL_T *pool, extern void (*report)(size_t)) {
    pthread_mutex_lock(&pool->mutex);
    size_t count = pool->count;
    pthread_mutex_unlock(&pool->mutex);

    if (count) report(count);
}
