        fprintf(stderr, "Failed to allocate memory for data.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&(*data)->mutex, NULL);
}

void destroyThreadData(struct thread_data* data) {
    free(data->data);
    free(data);
}

NFAPI_CRC_INDICATION_PDU_T* getData(struct thread_data* data, size_t index) {
