    initThreadData(&data, N, batch_limit);
    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, threadFunc, data);
    }
    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }
    destroyThreadData(data);
}
