import subprocess, os, threading, time, sys, traceback, queue, gc, psutil, datetime

def init_threads(memory_budget):
    threads = []
    for _ in range(os.cpu_count()):
        t = threading.Thread(target=network_stats_thread, args=(queue, memory_budget))
        t.start()
        threads.append(t)
    return threads

def network_stats_thread(q, memory_budget):
    connections = []
    slab = SlabAllocator(memory_budget)

    while True:
        try:
            record = q.get(block=True, timeout=1)
            if record is None:  # signifies end of work
                break

            # Process network record and update statistics
            connections.append(slab.allocate())
            connections[-1].update_record(record)

            # Memory pressure detection
            if slab.memory_used() > memory_budget * 0.9:
                print("Memory usage is critical, alerting!")
                send_alert()

            gc.collect()
        except Exception as e:
            print(f"Error in thread: {e}, retrying in {2**q.qsize()} seconds")
            time.sleep(2 ** q.qsize())

    # Free all connections upon completion
    for connection in connections:
        slab.free(connection)

class SlabAllocator:
    def __init__(self, memory_budget):
        self.memory_budget = memory_budget
        self.slabs = [Pool() for _ in range(10)]  # Custom memory pools with 10 blocks each

    def allocate(self):
        for slab in self.slabs:
            if len(slab) < 1:
                return slab.pop()
        # If all slabs are full, create a new one and add it to the list
        new_slab = Pool()
        self.slabs.append(new_slab)
        return new_slab.pop()

    def free(self, connection):
        for slab in reversed(self.slabs):
            if len(slab) < 10:
                slab.append(connection)
                break

class Pool:
    def __init__(self):
        self._connections = []

    def pop(self):
        if self._connections:
            return self._connections.pop()
        # If empty, allocate a new connection object
        new_connection = Connection()
        self._connections.append(new_connection)
        return new_connection

class Connection:
    def __init__(self):
        self.record = None

    def update_record(self, record):
        self.record = record  # Update the network record in this connection object

