    config = ""
    for key, value in params.items():
        config += template.replace("{{{ %s }}}" % key, str(value))

    # Add network statistics section
    current_time = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    stats_section = """
[Network_Stats]
Timestamp={{ Timestamp }}
SignalStrength={{ SignalStrength }}
ActiveConnections={{ ActiveConnections }}
PacketLoss={{ PacketLoss }}
Latency={{ Latency }}
"""
    config += stats_section.replace("{{{ %s }}}" % key, str(key))

    subprocess.run(["touch", output_file])
    with open(output_file, "w") as f:
        f.write(config)

def main():
    params = {  # Define your parameters here
        "SSID": "my_network",
        "PASSWORD": "mypassword"
    }

    generate_config(params)

    threads = init_threads(memory_budget=1024 * 1024 * 50)  # Initialize memory budget (e.g., 50MB)

