void resize(size_t newSize) {
    if (newSize > 1024 && allocatedSize < newSize) {
        size_t blockSize = allocatedSize ? aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), currentSize * sizeof(NFAPI_CRC_INDICATION_PDU_T)) : aligned_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), newSize);
        if (!blockSize) {
            // Handle error
            return;
        }

        dataBuffer = (NFAPI_CRC_INDICATION_PDU_T*) blockSize;
        currentSize = newSize;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate(size_t size) {
    pthread_mutex_lock(&mutex);
    if (currentSize < size) {
        resize(size);
    }
    NFAPI_CRC_INDICATION_PDU_T* result = &dataBuffer[currentSize - size];
    currentSize -= size;
