#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} List;

List *create_list(size_t max) {
    List *list = mmap(NULL, sizeof(List), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list == MAP_FAILED) {
        perror("mmap error");
        exit(EXIT_FAILURE);
    }
    list->capacity = max;
    list->count = 0;
    list->data = calloc(max, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        perror("calloc error");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void read_csv(const char *filename, List *list, size_t max, int crcflag_default) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen error");
        exit(EXIT_FAILURE);
    }
    char line[256];
    size_t counter = 0;
    while (fgets(line, sizeof(line), file)) {
        if (counter >= max) break;

        NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[counter];
        sscanf(line, "%llu,%lld,%hu,%hhu", &(entry->tag), &(entry->rnti.value), &(entry->crc_indication.present), &(entry->crc_indication.bitmask));

        // Skip duplicates
        for (size_t i = 0; i < counter; ++i) {
            if (list->data[i].rnti.value == entry->rnti.value) {
                goto next_line;
            }
        }

        // Override default CRCFLAG if specified in the CSV file
        if (sscanf(strchr(line, ',') + 1, "%hhu", &(entry->crc_indication.bitmask)) != 1) {
            entry->crc_indication.bitmask = crcflag_default;
        }

        ++counter;
    next_line: {}
    }
    fclose(file);
}

void process_entry(NFAPI_CRC_INDICATION_PDU_T *entry, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&entry->list->mutex);
    callback(entry);
    pthread_mutex_unlock(&entry->list->mutex);
}

void free_list(List *list) {
    munmap(list, sizeof(List));
}
