struct LTEMeasurementResult {
    int cellID;
    std::chrono::system_clock::time_point timestamp;
    float downlinkPower, uplinkPower;
};

struct NFCRCIndication {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
};

class DataManager {
private:
    std::vector<std::unique_ptr<LTEMeasurementResult>> measurementResults;
    std::unordered_map<int, std::unique_ptr<NFCRCIndication>> crcIndications;
    mutable std::mutex dataMutex;
    int failedUpdatesCount = 0;
    int malformedDataCount = 0;

public:
    void addMeasurement(const LTEMeasurementResult& measurement) {
        // Validate the incoming measurement result and handle inconsistencies gracefully.
        // ...
        std::unique_ptr<LTEMeasurementResult> measurementPtr(new LTEMeasurementResult(measurement));
        measurementResults.emplace_back(std::move(measurementPtr));
    }

    void addCRCIndication(const NFCRCIndication& indication) {
        // Validate the incoming CRC indication and handle inconsistencies gracefully.
        // ...
        std::unique_ptr<NFCRCIndication> indicationPtr(new NFCRCIndication(indication));
        crcIndications[indication.RNTI] = std::move(indicationPtr);
    }

    LTEMeasurementResult* getLatestMeasurement(int cellID) {
        // Lock the data mutex to ensure thread-safety during access.
        std::unique_lock<std::mutex> lock(dataMutex);

        for (auto& measurement : measurementResults) {
            if (measurement->cellID == cellID) {
                LTEMeasurementResult* result = measurement.get();
                return result;
            }
        }
