NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.crcflag = (rand() % 2);
    Node *temp = malloc(sizeof(Node));
    if (!temp) return NULL;
    temp->data = *new_node;
    temp->next = NULL;
    return &temp->data;
}

