    Node *new_node = create_node(data.tag, data.rnti, data.crc_indication);
    if (!new_node) return;
    Node *temp = *head;
    while (temp->next) temp = temp->next;
    temp->next = new_node;
}

void remove_node(Node **head, uint16_t rnti) {
