        qsort(list, list_len, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_timestamps);
        size_t i;
        for (i = list_len - RECENT_ENTRIES_COUNT; i < list_len; ++i) {
            free(list + i);
        }
        list_len -= RECENT_ENTRIES_COUNT;
    }
}

