    TCP_NODE_DIAGNOSTICS_DATA data;
    struct list_node* next;
};

struct list_metadata {
    size_t count;
    struct list_node* head;
    pthread_mutex_t mutex;
};

void trim_list(struct list_metadata* metadata) {
    struct list_node *current, *temp;
    unsigned long lfu[MAX_LIST_SIZE] = {0};

    pthread_mutex_lock(&metadata->mutex);
    current = metadata->head;
    for (size_t i = 0; i < metadata->count && i < MAX_LIST_SIZE; ++i) {
        lfu[i]++;
        if (current == NULL) break;
        current = current->next;
    }
    pthread_mutex_unlock(&metadata->mutex);

    size_t remove_index = 0;
    for (size_t i = 1; i < metadata->count && i < MAX_LIST_SIZE; ++i) {
        if (lfu[remove_index] > lfu[i]) {
            remove_index = i;
        }
    }

    pthread_mutex_lock(&metadata->mutex);
    current = metadata->head;
    for (size_t i = 0; i < remove_index && current != NULL; ++i) {
        temp = current;
        current = current->next;
        free(temp);
    }
    metadata->count--;
    pthread_mutex_unlock(&metadata->mutex);
}

void add_entry(struct list_metadata* metadata, const TCP_NODE_DIAGNOSTICS_DATA* data) {
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (!new_node) {
        // Log error and return, handle out-of-memory gracefully
        return;
    }
    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&metadata->mutex);
    if (metadata->count >= MAX_LIST_SIZE) {
        trim_list(metadata);
    }
    if (metadata->head == NULL) {
        metadata->head = new_node;
    } else {
        struct list_node *last = metadata->head;
        while (last->next != NULL) last = last->next;
        last->next = new_node;
    }
    metadata->count++;
    pthread_mutex_unlock(&metadata->mutex);
}

void external_update(struct list_metadata* metadata) {
