List* create_list(size_t capacity) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->capacity = capacity;
    list->size = 0;
    return list;
}

void add_node(List* list, const NFAPI_L2_PDU* data) {
    ListNode* node = malloc(sizeof(ListNode));
    if (!node) return;

    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        // Handle out-of-memory scenario gracefully.
        free(node);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    node->data = *data;
    node->next = list->head;
    list->head = node;
    ++list->size;
    pthread_mutex_unlock(&list->mutex);
}

void update_node(List* list, size_t index, const NFAPI_L2_PDU* data) {
    ListNode* current = list->head;
    size_t i = 0;

    pthread_mutex_lock(&list->mutex);
    if (index >= list->size || !current) {
        // Handle invalid index or empty list.
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    while (i < index) {
        current = current->next;
        ++i;
    }

    current->data = *data;
    pthread_mutex_unlock(&list->mutex);
}

const NFAPI_L2_PDU* iterate(List* list) {
    ListNode* current = list->head;
    if (!current) return NULL;

    pthread_mutex_lock(&list->mutex);
    ListNode* temp = current;
    list->head = current->next;
    --list->size;
    pthread_mutex_unlock(&list->mutex);

    const NFAPI_L2_PDU* data = &temp->data;
    free(temp);
    return data;
}

