bool push(const NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);

    // Check if array is full and wait for space to become available if necessary
    while (count == MAX_ELEMENTS) {
        pthread_cond_wait(&empty_cond, &mutex);
    }

    data[count] = *element;
    count++;
    pthread_cond_signal(&full_cond);
    pthread_mutex_unlock(&mutex);

    return true;
}

bool pop(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);

    // Check if array is empty and wait for an element to become available if necessary
    while (count == 0) {
        pthread_cond_wait(&full_cond, &mutex);
    }

    *element = data[--count];
    pthread_cond_signal(&empty_cond);
    pthread_mutex_unlock(&mutex);

    return true;
