    MAC_CONTEXT_T& getContext(uint64_t transaction_id) {
        uint64_t index = current_index % max_contexts;
        while (contexts[index].transaction_id != transaction_id) {
            std::unique_lock<std::mutex> lock(mtx);
            if (index == current_index) {
                mtx.unlock();
                usleep(1000); // Yield CPU to other threads
                mtx.lock();
            }
            index = (index + 1) % max_contexts;
