    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DYNAMIC_ARRAY;

DYNAMIC_ARRAY *create_dynamic_array(size_t initial_capacity) {
    DYNAMIC_ARRAY *array = malloc(sizeof(DYNAMIC_ARRAY));
    array->messages = calloc((initial_capacity), sizeof(NFAPI_UL_CCCH_MESSAGE_T*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DYNAMIC_ARRAY *array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i]) {
            free(array->messages[i]->NAS_MESSAGE);
            free(array->messages[i]);
        }
    }
    free(array->messages);
    free(array);
}

size_t find_empty_slot(DYNAMIC_ARRAY *array) {
    for (size_t i = 0; i < array->capacity; ++i) {
        if (!array->messages[i]) {
            return i;
        }
    }
    return -1; // array is full
}

NFAPI_UL_CCCH_MESSAGE_T *find_message_by_tag(DYNAMIC_ARRAY *array, uint16_t tag) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i] && array->messages[i]->CCCH_MESSAGE_TAG == tag) {
            return array->messages[i];
        }
    }
    return NULL;
}

void add_message(DYNAMIC_ARRAY *array, const NFAPI_UL_CCCH_MESSAGE_T *msg) {
    pthread_mutex_lock(&array->lock);
    size_t empty_slot = find_empty_slot(array);
    if (empty_slot != -1) {
        array->messages[empty_slot] = malloc(sizeof(NFAPI_UL_CCCH_MESSAGE_T));
        memcpy(array->messages[empty_slot], msg, sizeof(NFAPI_UL_CCCH_MESSAGE_T));
        array->size++;
    }
    pthread_mutex_unlock(&array->lock);
}

void update_message(DYNAMIC_ARRAY *array, const NFAPI_UL_CCCH_MESSAGE_T *msg) {
    pthread_mutex_lock(&array->lock);
    NFAPI_UL_CCCH_MESSAGE_T *existing_msg = find_message_by_tag(array, msg->CCCH_MESSAGE_TAG);
    if (existing_msg) {
        free(existing_msg->NAS_MESSAGE);
        existing_msg->NAS_MESSAGE = malloc(msg->NAS_MESSAGE_LEN);
        memcpy(existing_msg->NAS_MESSAGE, msg->NAS_MESSAGE, msg->NAS_MESSAGE_LEN);
    }
    pthread_mutex_unlock(&array->lock);
}
