    }
}

NFAPI_CRC_INDICATION_PDU_T** init_list() {
    InitData data;
    NFAPI_CRC_INDICATION_PDU_T** result = NULL;
    size_t allocated, used;

    data.data = NULL;
    data.allocated = &allocated;
    data.used = &used;
    data.lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        if ((result = malloc((allocated + 1024)*sizeof(NFAPI_CRC_INDICATION_PDU_T*))) != NULL) {
            void* temp = reallocarray(result, allocated + 1024, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            if (temp == NULL) {
                free(result);
                continue;
            }
            result = temp;
        } else {
            pthread_mutex_lock(&data.lock);
            if (allocated > 0 && --MAX_RETRIES == 0) {
                perror("Failed to allocate memory after max retries");
                destroy_lock(&data.lock);
                return NULL;
            }
            allocated *= 2;
            pthread_mutex_unlock(&data.lock);
        }

        if (result != NULL) {
            data.allocated = &allocated;
            *data.allocated = allocated;
            *data.used = used = 0;
            break;
        }
    }

    return data.data;
}

