Node* createNode(NFAPI_RX_UE_INFORMATION_TAG_t tag, uint32_t rnti, uint8_t* subframes, size_t numSubframes) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->data = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    newNode->prev = NULL;
    newNode->next = NULL;

    // Populate the structure with random data (or actual data if available)
    memset(newNode->data, 0, sizeof(NFAPI_RX_FRAME_PDU_T));
    newNode->data->rnti = rnti;
    newNode->data->ueInformationTag = tag;
    for (size_t i = 0; i < numSubframes; ++i) {
        newNode->data->subframe[i] = rand() % 256;
    }

    return newNode;
}

void insertNode(Node** head, Node* newNode) {
    if (*head == NULL) {
        *head = newNode;
        return;
    }

    newNode->next = *head;
    (*head)->prev = newNode;
    *head = newNode;
}

void deleteNode(Node** head, Node* nodeToRemove) {
    if (nodeToRemove == NULL || *head == NULL) return;

    if (nodeToRemove == *head) {
        *head = (*head)->next;
        if (*head != NULL) (*head)->prev = NULL;
        free(nodeToRemove);
        return;
    }

    Node* current = *head;
    while (current != NULL && current != nodeToRemove) {
        current = current->next;
    }

    if (current == NULL) return;

    if (current->next == NULL) { // last element in the list
        current->prev->next = NULL;
        free(current);
    } else {
        current->prev->next = current->next;
        current->next->prev = current->prev;
        free(current);
    }
}

void initDoublyLinkedList(Node** head, size_t numNodes) {
    *head = NULL;
    srand(time(NULL)); // seed for random data generation

    for (size_t i = 0; i < numNodes; ++i) {
        Node* newNode = createNode((NFAPI_RX_UE_INFORMATION_TAG_t)i, (uint32_t)(rand() % 0x7FF), (uint8_t*)malloc(sizeof(uint8_t) * 10), 10);
        insertNode(head, newNode);
    }
}
