        pthread_create(&thread_ids[i], NULL, enqueueThread, &list);
    }

    // Wait for threads to finish and destroy the linked list
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    destroyLinkedList(&list);

    return 0;
}

void* enqueueThread(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    for (int i = 0; i < NUM_ENQUEUES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        initCRCFlag(node);
        enqueue(list, node);
    }
}
```

