typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct node* next;
} node;

struct pdu_list {
    size_t size;
    size_t capacity;
    node** data;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

void pdu_list_init(struct pdu_list* plist, size_t initial_capacity) {
    plist->size = 0;
    plist->capacity = initial_capacity;
    plist->data = calloc(initial_capacity, sizeof(node*));
}

void pdu_list_push(struct pdu_list* plist, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&plist->mutex);
    if (plist->size == plist->capacity) {
        size_t new_capacity = (plist->capacity * 2 > MAX_PDU_COUNT) ? MAX_PDU_COUNT : plist->capacity * 2;
        node** tmp = realloc(plist->data, new_capacity * sizeof(node*));
        if (!tmp) {
            pthread_mutex_unlock(&plist->mutex);
            return;
        }
        plist->data = tmp;
        plist->capacity = new_capacity;
    }
    node* new_node = malloc(sizeof(node));
    if (!new_node) {
        pthread_mutex_unlock(&plist->mutex);
        return;
    }
    new_node->pdu = *pdu;
    new_node->next = plist->data[plist->size];
    plist->data[plist->size++] = new_node;
    pthread_mutex_unlock(&plist->mutex);
}

void pdu_list_cleanup(struct pdu_list* plist) {
    pthread_mutex_lock(&plist->mutex);
    size_t cur_capacity = plist->capacity;
    if (cur_capacity > MIN_PDU_COUNT && plist->size < (cur_capacity / 2)) {
        size_t new_capacity = (cur_capacity * 2 < MAX_PDU_COUNT) ? cur_capacity * 2 : MAX_PDU_COUNT;
        node** tmp = realloc(plist->data, new_capacity * sizeof(node*));
        if (!tmp) {
            pthread_mutex_unlock(&plist->mutex);
            return;
        }
        plist->data = tmp;
        plist->capacity = new_capacity;
    }

    node* current = NULL, * temp;
    for (size_t i = 0; i < plist->size; ++i) {
        current = plist->data[i];
        while (current != NULL) {
            temp = current;
            current = current->next;
            free(temp);
        }
    }
    plist->size = 0;
    pthread_mutex_unlock(&plist->mutex);
}
