function generateJWT(header, payload) {
  return jwt.sign({ header, payload }, process.env.PRIVATE_KEY, {
    algorithm: 'RS256',
    expiresIn: '3600' // JWT is valid for 1 hour
  });
}

async function verifyJWT(token) {
  try {
    const header = jwt.verify(token, await jwksRSA.getPublicKey(process.env.JWKS_URI), { algorithms: ['RS256'] }).header;
    return jwt.verify(token, process.env.PUBLIC_KEY, { audience: header.aud });
  } catch (err) {
    console.error('Invalid or expired JWT', err);
    throw new Error('Invalid or expired JWT');
  }
}
