        auto node = memoryPool.allocate();
        node->data = data;
        node->prev = head.get();
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
        ++size;
    }

    void reverse() {
        std::lock_guard lock(listMutex);
        auto current = tail->prev;
        tail->prev = head;
        head->next = tail;
        while (current != head) {
            auto next = current->next;
            current->next = current->prev->prev;
            current->prev = next->prev;
            next->prev = current;
            next->next = current->next;
        }
    }

    void clear() {
        std::lock_guard lock(listMutex);
        while (head->next != tail.get()) {
            auto nodeToDelete = head->next;
            head->next = nodeToDelete->next;
            nodeToDelete->prev->next = nodeToDelete->next;
            memoryPool.deallocate(nodeToDelete);
        }
        size = 0;
    }

    void iterate(std::function<void(const NFAPI_CRC_INDICATION_PDU_T&)> callback) const {
        std::lock_guard lock(listMutex);
        auto current = head->next;
        while (current != tail.get()) {
            callback(current->data);
            current = current->next;
        }
    }

