class DynamicLinkedList {
public:
    explicit DynamicLinkedList(size_t initialCapacity = 1024) : m_dataList(initialCapacity), m_mutex(), m_ioService() {}

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
        unique_lock<mutex> lock(m_mutex);
        if (data.tag.value != RX_UE_INFORMATION_TAG{}) {
            m_dataList.emplace_back(data);
            if (m_dataList.size() > 2 * m_dataList.max_size()) {
                resize();
            }
        } else {
            cerr << "Invalid data pushed to the list" << endl;
        }
    }

    size_t size() const {
        unique_lock<mutex> lock(m_mutex);
        return m_dataList.size();
    }

    bool empty() const {
        unique_lock<mutex> lock(m_mutex);
        return m_dataList.empty();
    }

    void logElements(const string& filePath) {
