        list<NFAPI_CRC_INDICATION_PDU_T> newList(m_dataList.begin(), m_dataList.end());
        m_dataList.swap(newList);
        m_dataList.reserve(2 * m_dataList.max_size());
    }

private:
    list<NFAPI_CRC_INDICATION_PDU_T> m_dataList;
    mutex m_mutex;
    boost::asio::io_service m_ioService;
};
