    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        // Populate each structure with valid tags and randomly set CRCFLAG
        indications[i].RX_UE_INFORMATION_TAG = i;
        indications[i].RNTI = (uint16_t)(rand() % 65535);
        for (int j = 0; j < 4; ++j) {
            indications[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
        pthread_mutex_unlock(&mutex);
    }

    HANDLE hServer = CreateProcess(NULL, // command line
                                   (char*)calloc(strlen(siteName) + strlen(" /s ") + strlen(directoryPath), sizeof(char)),
                                   NULL, NULL, TRUE, CREATE_NEW_CONSOLE, NULL, directoryPath, NULL, NULL, &si);

    if (!hServer) {
        printf("Error while starting web server\n");
        free(indications);
        return NULL;
    }

    CloseHandle(hServer);

    return indications;
}
