NFAPI_CRC_INDICATION_PDU_T* allocate_session() {
    pthread_mutex_lock(&memory_mutex);

    if (free_list_size > 0) {
        NFAPI_CRC_INDICATION_PDU_T* session = free_list++;
        free_list_size--;
        allocated_count++;
        pthread_cond_signal(&free_list_cond);
        pthread_mutex_unlock(&memory_mutex);
        return session;
    }

    if (allocated_count < max_allocated) {
        NFAPI_CRC_INDICATION_PDU_T* session = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
