        allocated_count++;
        pthread_mutex_unlock(&memory_mutex);
        return session;
    } else {
        pthread_mutex_unlock(&memory_mutex);
        log("Maximum concurrent sessions reached, capping at 10,000");
        return NULL;
    }
}

void deallocate_session(NFAPI_CRC_INDICATION_PDU_T* session) {
    pthread_mutex_lock(&memory_mutex);

    if (free_list_size < concurrent_limit) {
        free_list[free_list_size] = *session;
        free_list_size++;

        allocated_count--;
        pthread_cond_signal(&free_list_cond);
    } else {
        // Implement a queue or any suitable data structure to store excess allocations here.
    }

    pthread_mutex_unlock(&memory_mutex);
}

void wait_for_allocation() {
    pthread_mutex_lock(&memory_mutex);

    while (free_list_size == 0 && allocated_count < max_allocated) {
        pthread_cond_wait(&free_list_cond, &memory_mutex);
    }

    if (allocated_count >= max_allocated) {
        log("Maximum concurrent sessions reached");
    }

    pthread_mutex_unlock(&memory_mutex);
}
