const fs = require('fs');
const path = require('path');
const { default: chalk } = require('chalk');
const blueSlip = require('blueslip');

function loadModules(modules, callback) {
  let executedModules = [];
  const logError = (moduleName, error) => {
    console.error(`${chalk.red(moduleName)}:`, error);
  };

  modules.forEach((moduleName) => {
    try {
      const modulePath = path.join(__dirname, moduleName);
      const module = require(modulePath);

      // Add the executed module to the executedModules array
      executedModules.push(module);

      // Execute tests on each module
      if (module.tests) {
        blueSlip.reset();
        module.tests.forEach((testName) => {
          try {
            console.log(`${chalk.green(moduleName)}: Running test ${testName}`);
            const result = module[testName]();
            if (result) {
              console.log(`${chalk.green(moduleName)}: Test ${testName} passed`);
            } else {
              console.error(`${chalk.red(moduleName)}: Test ${testName} failed`);
            }
          } catch (error) {
            logError(moduleName, error);
          }
        });
      }
    } catch (error) {
      logError(moduleName, error);
    }
  });

  callback(executedModules);
}
