    if (!*head) {
        *head = new_node;
        *tail = new_node;
        return new_node;
    }

    new_node->next = *head;
    (*head)->prev = new_node;
    *head = new_node;

    if (new_node->next) {
        new_node->next->prev = new_node;
        *tail = new_node->next;
    }

    return new_node;
}

void doubly_linked_list_free(Node** head) {
    Node* current = *head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = nullptr;
}

// Thread-safe doubly linked list implementation using pthread_mutex_t for synchronization
Node* create_and_populate_doubly_linked_list(const RX_UE_INFORMATION_TAG*, const RNTI, pthread_mutex_t* mutex) {
    Node* head = nullptr;
    Node* tail = nullptr;

    pthread_mutex_lock(mutex);
    if (head == nullptr) {
        head = create_node(rx_ue_information_tag, rnti);
        if (!head) {
            pthread_mutex_unlock(mutex);
            return nullptr;
        }
        tail = head;
    } else {
        Node* new_node = create_node(rx_ue_information_tag, rnti);
        if (!new_node) {
            pthread_mutex_unlock(mutex);
            return nullptr;
        }
        doubly_linked_list_insert(&head, &tail, new_node);
    }
    pthread_mutex_unlock(mutex);

    return head;
}
```

This code defines a `Node` structure representing the nodes in the doubly linked list. The `create_and_populate_doubly_linked_list` function creates and populates the doubly linked list, while ensuring thread safety through the use of a `pthread_mutex_t`. The function also integrates with an external logging framework by calling the provided `log_event` function to log creation events. The function dynamically scales based on the input load and manages memory efficiently using standard dynamic allocation strategies and a custom `calculate_checksum` function for generating the CRC flag.']

