2. Calculating the MD5 hash of a file:

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <openssl/md5.h>

ssize_t read_chunk(int fd, void *buf, size_t count) {
    return read(fd, buf, count);
}

size_t file_to_md5(const char *path, unsigned char digest[MD5_DIGEST_LENGTH], size_t chunk_size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open failed");
        return 0;
    }

    unsigned char buffer[chunk_size];
    size_t total_bytes = 0;

    while (1) {
        ssize_t nread = read_chunk(fd, buffer, chunk_size);
        if (nread == -1 && errno != EINTR) break; // If error not due to interrupt, break the loop
        if (nread <= 0) break; // End of file or error

        total_bytes += nread;
        if (nread > 0) {
            MD5_CTX ctx;
            MD5_Init(&ctx);
            MD5_Update(&ctx, buffer, nread);
        }
    }

    close(fd);
    MD5_Final(digest, &ctx);

    return total_bytes;
}
```']

