std::vector<CRC_INDICATION_PDU_T> generateCRCPDU(int n) {
    std::vector<CRC_INDICATION_PDU_T> v(n);
    for (size_t i = 0; i < v.size(); ++i) {
        v[i].rx_ue_information_tag = i + 1;
        v[i].rnti = rand() % 65536;
        v[i].crcflag = rand() % 2 == 0;
    }
    return v;
}

std::string calculateMD5(const std::string& path, size_t chunkSize = 4 * 1024 * 1024) {
    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error: Could not open file: " << path << std::endl;
        return "";
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);

    size_t totalBytes = 0;
    double startTime = clock();

    std::string currentChunk;
    while (file) {
        currentChunk.clear();
        currentChunk.resize(chunkSize, '\0');
        file.read(&currentChunk[0], chunkSize);
        totalBytes += currentChunk.size();
        if (!file.gcount()) break; // EOF reached

        MD5_Update(&ctx, &currentChunk[0], currentChunk.size());
    }

    file.close();
    MD5_Final(digest, &ctx);

    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ss << std::hex << static_cast<unsigned int>(digest[i]);
    }
    std::string hash = ss.str();

    double endTime = clock();
    double elapsedTime = (endTime - startTime) / CLOCKS_PER_SEC;

    std::cout << "File: \"" << path << "\"\n"
              << "Size: " << totalBytes << " bytes\n"
              << "Hash: " << hash << "\n"
              << "Processing time: " << elapsedTime << " seconds" << std::endl;

    return hash;
}

