    for (int i = 0; i < numThreads; ++i) {
        auto idx = static_cast<decltype(crcPdus.size())>(i * crcPdus.size() / numThreads);
        data[i] = std::make_pair(&(crcPdus.substr(idx, crcPdus.size() / numThreads)), filePath);
    }

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], nullptr, parallelProcess, &data[i]) != 0) {
            std::cerr << "Error: Failed to create thread" << std::endl;
            return -1;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_join(threads[i], nullptr)) {
            std::cerr << "Error: Failed to join thread" << std::endl;
            return -1;
        }
    }

    delete[] threads;
}
