#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_UE_COUNT 1000 // Maximum number of UE entries in the list

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t add_time; // Time when this entry was added
    struct node *next;
} Node;

typedef struct {
    int count;
    pthread_mutex_t lock;
    Node *head;
} List;

List *list_init() {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void list_destroy(List *list) {
    Node *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node *create_node(RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication = crc_indication;
    new_node->add_time = time(NULL);
    new_node->next = NULL;

    return new_node;
}

int list_add(List *list, Node *new_node) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_UE_COUNT) { // List is full, evict the least recently added entry.
        Node *oldest = list->head;
        time_t oldest_time = oldest->add_time;
        Node *current = list->head->next;
        while (current != NULL) {
            if (current->add_time < oldest_time) {
                oldest = current;
                oldest_time = current->add_time;
            }
            current = current->next;
        }
        Node *temp = oldest;
        list->head = list->head->next;
        free(temp);
    }

    new_node->next = list->head;
    list->head = new_node;
    ++list->count;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

Node *list_find(List *list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) break;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current;
}

int main() {
    List *list = list_init();

    // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures and add them to the list.

    list_destroy(list);
    return 0;
}
