// Define the struct representing a frame
typedef struct RX_FRAME_PDU_T {
    NFAPI_RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    int num_subframes; // number of subframes in this frame
    void** subframes; // array to store received subframes
    struct RX_FRAME_PDU_T* prev; // pointer to the previous node
    struct RX_FRAME_PDU_T* next; // pointer to the next node
} RX_FRAME_PDU;

// Define the function prototype for logging
void log_frame(RX_FRAME_PDU* frame, const char* file);

// Initialize doubly linked list
RX_FRAME_PDU* init_doubly_linked_list() {
    RX_FRAME_PDU* head = NULL;
    return head;
}

// Allocate memory for a new frame node and populate it with random subframe data
RX_FRAME_PDU* create_new_frame(int num_subframes) {
    RX_FRAME_PDU* new_frame = (RX_FRAME_PDU*)malloc(sizeof(RX_FRAME_PDU));

    if (!new_frame) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    // Initialize the frame fields
    new_frame->tag = (NFAPI_RX_UE_INFORMATION_TAG)rand();
    new_frame->rnti = rand();
    new_frame->num_subframes = num_subframes;
    new_frame->subframes = malloc(new_frame->num_subframes * sizeof(void*));

    if (!new_frame->subframes) {
        perror("Memory allocation failure");
        free(new_frame);
        exit(EXIT_FAILURE);
    }

    // Populate the subframe array with random values using standard library functions
    for (int i = 0; i < new_frame->num_subframes; ++i) {
        new_frame->subframes[i] = malloc(sizeof(void));

        if (!new_frame->subframes[i]) {
            perror("Memory allocation failure");
            free(new_frame);
            exit(EXIT_FAILURE);
        }
    }

    new_frame->prev = NULL;
    new_frame->next = NULL;
    return new_frame;
}

// Insert a frame node into the doubly linked list
void insert_frame(RX_FRAME_PDU** head, RX_FRAME_PDU* new_frame) {
    if (!*head) { // If the list is empty, the new frame becomes the head
        *head = new_frame;
    } else {
        RX_FRAME_PDU* current = *head;

        while (current->next) {
            current = current->next;
        }

        current->next = new_frame;
        new_frame->prev = current;
    }
}

// Remove a frame node from the doubly linked list
void remove_frame(RX_FRAME_PDU** head, RX_FRAME_PDU* frame) {
    if (frame->prev) { // If the frame is not the head, update its predecessor's next pointer
        frame->prev->next = frame->next;
    } else {            // Otherwise, set the head to the next node
        *head = frame->next;
    }

    if (frame->next) { // If the frame is not the last node, update its successor's prev pointer
        frame->next->prev = frame->prev;
    }
}

// Concurrent insertions and deletions without race conditions using pthread_mutex_t
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Log a frame for debugging purposes
void log_frame(RX_FRAME_PDU* frame, const char* file) {
    FILE* log_file;
    time_t current_time;
    struct tm* time_info;
    char log_filename[256];

    if (!(log_file = fopen("log.txt", "a"))) {
        perror("Error opening log file");
        return;
    }

    current_time = time(NULL);
    time_info = localtime(&current_time);
    strftime(log_filename, sizeof(log_filename), "%Y-%m-%d %H:%M:%S.log", time_info);

    if (!(log_file = fopen(log_filename, "w"))) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "[%s] Frame:\n", ctime(&current_time));
    fprintf(log_file, "Tag: %u\n", frame->tag);
    fprintf(log_file, "RNTI: %u\n", frame->rnti);
    fprintf(log_file, "Number of subframes: %d\n", frame->num_subframes);

    for (int i = 0; i < frame->num_subframes; ++i) {
        fprintf(log_file, "Subframe %d: %p\n", i, frame->subframes[i]);
    }

    fclose(log_file);
}
```

