    size_t capacity;
    size_t count;
    LTE_PDCP_PDU* data;
    pthread_mutex_t mutex;
};

void LTE_PDCP_PDU_init(struct LTE_PDCP_PDU_manager* manager, size_t capacity) {
    manager->capacity = capacity;
    manager->count = 0;
    manager->data = malloc(capacity * sizeof(LTE_PDCP_PDU));
    if (!manager->data) {
        perror("Out of memory");
        return;
    }
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void LTE_PDCP_PDU_deinit(struct LTE_PDCP_PDU_manager* manager) {
    free(manager->data);
    manager->capacity = 0;
    manager->count = 0;
}

void* generate_pdus(void* arg) {
    struct LTE_PDCP_PDU_manager* manager = arg;
    for (size_t i = 0; i < manager->capacity; ++i) {
        pthread_mutex_lock(&manager->mutex);
        if (manager->count >= manager->capacity) {
            pthread_mutex_unlock(&manager->mutex);
            break;
        }
        LTE_PDCP_PDU* pdus = &manager->data[manager->count];
        pdus->PDCP_SN = i + 1;
        pdus->PDCP_RB_ID = rand() % 128 + 1; // Range: [1, 128]
        pdus->PDCP_SAP_ID = 0x1ABC; // Valid SAP ID
        ++manager->count;
        pthread_mutex_unlock(&manager->mutex);
    }
    return NULL;
}

bool LTE_PDCP_PDU_batch_init(struct LTE_PDCP_PDU_manager* manager, size_t count, uint32_t start_sn) {
    if (count > manager->capacity - manager->count) {
        return false;
    }

    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < count; ++i) {
        LTE_PDCP_PDU* pdus = &manager->data[manager->count + i];
        pdus->PDCP_SN = start_sn + i;
        pdus->PDCP_RB_ID = rand() % 128 + 1; // Range: [1, 128]
        pdus->PDCP_SAP_ID = 0x1ABC; // Valid SAP ID
    }
    manager->count += count;
    pthread_mutex_unlock(&manager->mutex);

    return true;
}
