        perror("semaphore post failed");
    }

    pthread_mutex_unlock(&arr->lock);

    return true;
}

struct LTE_Packet* packet_array_pop(PacketArray* arr) {
    struct LTE_Packet* packet = NULL;

    pthread_mutex_lock(&arr->lock);

    while (sem_wait(&arr->sem_cons) != 0 && arr->count > 0) {
        // Handle contention gracefully, e.g., log or retry
        perror("semaphore wait failed");
    }

    if (arr->count > 0) {
        packet = arr->packets[--arr->count];
        arr->packets[arr->count] = NULL; // Optimization: Fill hole for efficient memory management
