#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint16_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateCRCIndications(int N) {
    if (N <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; ++i) {
        indications[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_DEFAULT;
        indications[i].rnti = i + 1;
        indications[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_INITIAL;
        indications[i].crcflag = rand() % 65536;
    }

    pthread_t threads[N];

    for (int i = 0; i < N; ++i) {
        int tid = i;
        if (pthread_create(&threads[i], NULL, updateCrcFlag, &indications[tid])) {
            perror("pthread_create");
            return NULL;
        }
    }

    for (int i = 0; i < N; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join");
            return NULL;
        }
    }

    free(threads);
    pthread_mutex_destroy(&mutex);
    return indications;
}

void* updateCrcFlag(void *arg) {
    int index = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *indications = allocateAndPopulateCRCIndications(1);

    pthread_mutex_lock(&((allocateAndPopulateCRCIndications)(NULL))->mutex);

    indications[0].crcflag ^= ((NFAPI_CRC_INDICATION_PDU_T*)arg)[index].crcflag;

    pthread_mutex_unlock(&((allocateAndPopulateCRCIndications)(NULL))->mutex);

    free(indications);
    return NULL;
}
```
