void sort_linked_list(NFAPI_CRC_INDICATION_PDU_T **head) {
    if ((*head) == NULL || (*head)->next == NULL) return;

    NFAPI_CRC_INDICATION_PDU_T *cur = *head, *next, *min;

    while (cur != NULL) {
        min = cur;
        next = cur->next;

        while (next != NULL) {
            if (next->rnti < min->rnti) {
                min = next;
            }
            next = next->next;
        }

        if (cur != min) {
            next = min->next;
            min->next = cur->next;
            cur->next = next;

            if (min == *head) {
                *head = cur;
            }
        }
        cur = cur->next;
    }
}

