            current = current->next;
            if (!current) break; // Reached end of list without finding node
        }

        if (current == node) {
            if (node->prev != NULL) node->prev->next = node->next;
            if (node->next != NULL) node->next->prev = node->prev;
        }
    }
}

void initialize_list(NFAPI_CRC_INDICATION_PDU_T ***list, size_t capacity) {
    *list = (NFAPI_CRC_INDICATION_PDU_T **)memory_allocator(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    (*list)[0] = NULL;
    for (size_t i = 1; i < capacity; ++i) {
        (*list)[i] = NULL;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t length) {
    if (!length || !list) return;

    for (size_t i = 0; i < length; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *current = (*list)[i];
        while (current != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *next = current->next;
            free(current);
            current = next;
        }
    }
}

void resize_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t old_capacity, size_t new_capacity) {
    if (old_capacity >= new_capacity) return;

    NFAPI_CRC_INDICATION_PDU_T **new_list = (NFAPI_CRC_INDICATION_PDU_T **)memory_allocator((new_capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (size_t i = 0; i < old_capacity && i < new_capacity; ++i) {
        if ((*list)[i] != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *current = (*list)[i];
            while (current != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *next = current->next;
                free_and_reuse(&current);
                current = next;
            }
        }
        new_list[i] = (*list)[i];
    }
    for (size_t i = old_capacity; i < new_capacity; ++i) {
        new_list[i] = NULL;
    }
    free(*list);
    *list = new_list;
}

// Thread-safe version of the linked list functions using pthread mutexes

