void sort_and_insert(Node* node) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    Node* prev = NULL;

    while (current && current->data.RNTI < node->data.RNTI) {
        prev = current;
        current = current->next;
    }

    if (prev) {
        prev->next = node;
        node->prev = prev;
        node->next = current;
        if (current) current->prev = node;
    } else {
        node->next = head;
        head->prev = node;
        head = node;
    }

    pthread_mutex_unlock(&list_mutex);
}

