#include <stdio.h>
#include <arpa/inet.h>
#include <netinet/ip_icmp.h>
#include <stdint.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    uint16_t src_port;
    uint16_t dest_port;
    uint32_t seq_num;
    uint32_t ack_num;
    uint16_t checksum;
    uint16_t window;
    time_t timestamp;
    unsigned char payload[40]; // Adjust size as needed
} tcp_packet;

#define PACKET_COUNT 10000

void initialize_tcp_packets(tcp_packet **array) {
    *array = (tcp_packet *) mmap(NULL, sizeof(tcp_packet) * PACKET_COUNT, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);

    // Set default values for each packet
    for (size_t i = 0; i < PACKET_COUNT; ++i) {
        tcp_packet *packet = array + i;
        memset(packet, 0, sizeof(*packet));
    }
}

void populate_tcp_packets(tcp_packet *array, uint16_t src_port, uint16_t dest_port) {
    for (size_t i = 0; i < PACKET_COUNT; ++i) {
        tcp_packet *packet = array + i;

        // Set standard TCP header fields according to specifications
        packet->src_port = src_port;
        packet->dest_port = dest_port;
        packet->seq_num = htonl(i); // Incrementing sequence number for each packet
        packet->ack_num = 0;

        // Calculate initial checksum and store it in the header
        uint16_t *header = (uint16_t *)packet->payload;
        header[0] = htons(src_port);
        header[1] = htons(dest_port);
        header[2] = htonl(i); // Sequence number
        header[3] = 0; // Acknowledgment number
        packet->checksum = calculate_tcp_checksum(packet->payload, sizeof(*packet) - sizeof(packet->payload));
    }
}

uint16_t calculate_tcp_checksum(const void *data, size_t length) {
    uint32_t sum = 0;
    for (size_t i = 0; i < length; i += sizeof(uint16_t)) {
        const uint16_t *word = data + i;
        sum += ntohs(*word);
        if ((i + sizeof(uint16_t)) < length) {
            sum += (sum >> 16);
        }
    }

    // One's complement
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return ~sum;
}
```

