```cpp
#include <vector>
#include <atomic>
#include <mutex>
#include <boost/asio/ip/tcp.hpp>
#include <boost/asio/checksum.hpp>
#include <iostream>
#include <sstream>
#include <fstream>
#include <optional>
#include <filesystem>

namespace b = boost;

struct Packet {
    b::asio::ip::tcp::header header;
    std::vector<char> payload;
    std::uint32_t timestamp;
    std::atomic<bool> validated{false};

    bool validate() const {
        if (validated) return true;
        auto checksum = boost::asio::checksum(header, payload.data(), payload.size());
        validated = header.checksum == checksum;
        return validated;
    }
};

class TCPPacketManager {
public:
    // Configurable logging levels and storage options (e.g., file path)
    enum class LogLevel { INFO, DEBUG };
    std::string logFilePath{"log.txt"};
    LogLevel logLevel{LogLevel::INFO};

    void setLogLevel(LogLevel level) noexcept { logLevel = level; }
    void setLogFile(const std::string& path) noexcept { logFilePath = path; }

    TCPPacketManager(std::size_t initialCapacity, LogLevel logLevel)
        : logLevel{logLevel}, capacity{initialCapacity}, data(), packetsMutex() {}

    ~TCPPacketManager() { clear(); }

    // Resize dynamically if needed
    void push_back(const Packet& packet) {
        if (data.size() >= capacity) resize();
        std::unique_lock<std::mutex> lock{packetsMutex};
        data.push_back(packet);
        if (logLevel == LogLevel::DEBUG) logPacketInsertion(packet);
    }

private:
    void resize() {
        auto newCapacity = capacity * 2;
        std::vector<Packet> temp(newCapacity);
        std::unique_lock<std::mutex> lock{packetsMutex};
        for (const auto& packet : data) temp.push_back(packet);
        data.swap(temp);
        capacity = newCapacity;
    }

    void logPacketInsertion(const Packet& packet) const {
        if (logLevel != LogLevel::DEBUG) return;
        std::stringstream ss;
        auto timestampStr = std::to_string(packet.timestamp);
        auto validationResultStr = packet.validate() ? "valid" : "invalid";
        ss << "Packet inserted at timestamp: " << timestampStr
          << ", Validation result: " << validationResultStr << "\n";
        logToFile(ss.str());
    }

    void logToFile(const std::string& message) const {
        auto file = std::ofstream{logFilePath, std::ios_base::app};
        if (file.is_open()) file << message;
    }

    std::vector<Packet> data;
    std::atomic_size_t capacity;
    std::mutex packetsMutex;
};
```

