// Thread-safe enqueue operation using GCC's atomic operations.
void enqueue(struct cdeq* q, NFAPI_CRC_INDICATION_PDU_T* data) {
    size_t head = atomic_load((atomic_uintptr_t*)q->head);
    size_t tail = atomic_load((atomic_uintptr_t*)q->tail);

    // Circular queue overflow condition.
    if ((head + 1) % q->capacity == tail) {
        return;
    }

    // Set the head pointer to the next position, then store the data at that location.
    atomic_store((atomic_uintptr_t*)q->head, (head + 1) % q->capacity);
    memcpy(static_cast<char*>(q->head[head]), data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Thread-safe dequeue operation using GCC's atomic operations.
void* dequeue(struct cdeq* q) {
    size_t head = atomic_load((atomic_uintptr_t*)q->head);
    size_t tail = atomic_load((atomic_uintptr_t*)q->tail);

    // Circular queue underflow condition.
    if (head == tail) {
        return nullptr;
    }

    // Store the data from the current head position, then set the tail pointer to the next position.
    NFAPI_CRC_INDICATION_PDU_T* data = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(q->head[head]);
    atomic_store((atomic_uintptr_t*)q->tail, head);

    return data;
}

// Logging helper function to record the number of elements processed and the timestamp.
void logOperation(const char* operation, size_t count) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static pthread_mutex_t loggerMutex = PTHREAD_MUTEX_INITIALIZER;
    time_t now;
