    // Logging synchronization for efficiency.
    pthread_mutex_lock(&loggerMutex);

    char logBuffer[256];
    strftime(logBuffer, sizeof(logBuffer), "%Y-%m-%d %H:%M:%S ", localTime = localtime(&now));
    printf("%s%s: [%ld] %s\n", logBuffer, operation, count, ctime(&now));

    pthread_mutex_unlock(&loggerMutex);
}

// Main function managing the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures.
void manageList(struct cdeq* q, int maxSize) {
    // Assume you have a maximum of 10 threads accessing this list concurrently.
    pthread_t tid[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&tid[i], nullptr, [q]() {
            while (true) {
                NFAPI_CRC_INDICATION_PDU_T* data = createEntry();
                if (!data) break; // Exit the loop when out of memory.
                enqueue(q, data);
                logOperation("enqueue", 1);
                usleep(50000); // Simulate high throughput and low latency requirements.
            }
            return nullptr;
        }, (void*)i);
    }

    for (int i = 0; i < 10; ++i) {
