```python
import hashlib
import os

def md5_hash(filepath, chunk_size=64*1024):
    with open(filepath, 'rb') as f:
        block = f.read(chunk_size)
        hasher = hashlib.md5()
        while len(block) > 0:
            hasher.update(block)
            block = f.read(chunk_size)
        return hasher.hexdigest()
