#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>
#include <sys/syscall.h>

typedef struct session {
    char* session_id;
    char* user_agent;
    time_t last_activity;
    pthread_mutex_t mutex;
} Session;

struct hash_table {
    unsigned int size;
    Session** table;
    double load_factor;
};

unsigned long long get_hash(const char* key, const unsigned int table_size) {
    unsigned long long hash = 5381;
    for (int i = 0; *key; ++i)
        hash = ((hash << 5) + hash) + (*key);
    return hash % table_size;
}

Session* new_session(const char* session_id, const char* user_agent) {
    Session* session = malloc(sizeof(Session));
    if (!session)
        return NULL;

    session->session_id = strdup(session_id);
    session->user_agent = strdup(user_agent);
    session->last_activity = time(NULL);
    pthread_mutex_init(&session->mutex, NULL);

    return session;
}

void free_session(Session* session) {
    if (session->session_id)
        free(session->session_id);
    if (session->user_agent)
        free(session->user_agent);
    pthread_mutex_destroy(&session->mutex);
    free(session);
}

Session* find_or_add_session(struct hash_table* table, const char* session_id) {
    unsigned int hash = get_hash(session_id, table->size);
    for (int i = hash; i < table->size; ++i) {
        if (!table->table[i]) {
            table->table[i] = new_session(session_id, "");
            return table->table[i];
        }
        pthread_mutex_lock(&table->table[i]->mutex);
        if (!strcmp(table->table[i]->session_id, session_id)) {
            pthread_mutex_unlock(&table->table[i]->mutex);
            return table->table[i];
        }
        pthread_mutex_unlock(&table->table[i]->mutex);
    }

    for (int i = 0; i <= hash; ++i) {
        if (!table->table[i]) {
            table->table[i] = new_session(session_id, "");
            return table->table[i];
        }
        pthread_mutex_lock(&table->table[i]->mutex);
        if (!strcmp(table->table[i]->session_id, session_id)) {
            pthread_mutex_unlock(&table->table[i]->mutex);
            return table->table[i];
        }
        pthread_mutex_unlock(&table->table[i]->mutex);
    }

    // Handle overflow case
    unsigned int new_size = (table->size * 2) + 1;
    Session** new_table = realloc(table->table, new_size * sizeof(Session*));
    if (!new_table)
        return NULL;

    table->size = new_size;
    for (int i = table->size - 1; i >= hash; --i) {
        if (!table->table[i]) {
            table->table[i] = new_session(session_id, "");
            return table->table[i];
        }
        pthread_mutex_lock(&table->table[i]->mutex);
        if (!strcmp(table->table[i]->session_id, session_id)) {
            pthread_mutex_unlock(&table->table[i]->mutex);
            return table->table[i];
        }
        pthread_mutex_unlock(&table->table[i]->mutex);
    }

    // Copy and resize the old table
    for (int i = 0; i < table->size; ++i) {
        if (table->table[i]) {
            Session* session = table->table[i];
            int new_index = get_hash(session->session_id, new_size);
            new_table[new_index] = session;
        }
    }
    table->table = new_table;
    return find_or_add_session(table, session_id);
}

void flush_table(struct hash_table* table) {
    time_t current_time = time(NULL);
    for (int i = 0; i < table->size; ++i) {
        if (!table->table[i])
            continue;
        pthread_mutex_lock(&table->table[i]->mutex);
        if (difftime(current_time, table->table[i]->last_activity) > 60) { // Adjust threshold as needed
            free_session(table->table[i]);
            table->table[i] = NULL;
        }
        pthread_mutex_unlock(&table->table[i]->mutex);
    }
}
