void* malloc_aligned(size_t size, size_t alignment) {
    void *ptr = mmap(NULL, size + alignment - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    size_t aligned_size = ((uintptr_t)ptr + alignment - 1) & ~(alignment - 1);
    void *aligned_ptr = realloc(ptr, aligned_size - size + size);
    if (aligned_ptr == NULL) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }
    return aligned_ptr;
}

void init_list(struct list *list, size_t initial_capacity) {
    list->length = 0;
    list->capacity = initial_capacity;
    list->data = malloc_aligned(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), alignof(pthread_mutex_t));
    pthread_mutex_init(&list->mutex, NULL);
}

size_t find_next_power_of_two(size_t n) {
    size_t result = 1;
    while (result < n) {
        result *= 2;
    }
    return result;
}

void resize_list(struct list *list, size_t new_capacity) {
    if (new_capacity == list->capacity) return;
    void *new_data = malloc_aligned(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), alignof(pthread_mutex_t));
    if (!new_data) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list->mutex);
    memcpy(new_data, list->data, list->length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(list->data);
    list->data = new_data;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->mutex);
}

void log_operation(struct list *list, const char *operation) {
    if (!list->log_file) return;
    time_t current_time = time(NULL);
    struct tm *timeinfo = localtime(&current_time);
    fprintf(list->log_file, "%s %d-%02d-%02d %02d:%02d:%02d: List operation (%s)\n", asctime(timeinfo), (int)timeinfo->tm_year + 1900,
            (int)timeinfo->tm_mon + 1, (int)timeinfo->tm_mday, (int)timeinfo->tm_hour, (int)timeinfo->tm_min, (int)timeinfo->tm_sec, operation);
}

void serialize(struct list *list, FILE *output_file) {
    gzFile file = gzopen(output_file, "wb");
    if (!file) {
        perror("gzopen failed");
        exit(EXIT_FAILURE);
    }

    log_operation(list, "serialization started");
    size_t compressed_size;
    char *compressed_data = gzcompress((Bytef*)list->data, list->length * sizeof(NFAPI_CRC_INDICATION_PDU_T), &compressed_size);
    if (!compressed_data) {
        perror("gzcompress failed");
        exit(EXIT_FAILURE);
    }
    fwrite(compressed_data, 1, compressed_size, file);
    free(compressed_data);

    log_operation(list, "serialization completed");
    gzclose(file);
}

void* deserialize_thread(void *arg) {
    struct list *list = arg;
    void *buffer;
    size_t buffer_size;
    FILE *input_file = fopen((char*)arg, "rb");
    if (!input_file) {
        perror("fopen failed");
        exit(EXIT_FAILURE);
    }

    log_operation(list, "deserialization started");
    gzFile file = gzopen(input_file, "rb");
    if (!file) {
        perror("gzopen failed");
        exit(EXIT_FAILURE);
    }

    char *buffer_data = malloc_aligned(1 + GZIP_MAX_WBITS, alignof(pthread_mutex_t));
    size_t data_size;
    buffer = gzread(file, buffer_data, 1 + GZIP_MAX_WBITS);
    while (buffer != NULL && !feof(input_file)) {
        data_size = WMOFF(buffer_data[0]);
        if (gzdecompress(buffer_data, 1 + data_size, &buffer, &data_size) == Z_OK) {
            NFAPI_CRC_INDICATION_PDU_T *pdus = buffer;
            pthread_mutex_lock(&list->mutex);
            for (size_t i = 0; i < data_size / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
                list->data[list->length++] = pdus[i];
            }
            pthread_mutex_unlock(&list->mutex);
        } else {
            perror("gzdecompress failed");
            exit(EXIT_FAILURE);
        }
        buffer = gzread(file, buffer_data, 1 + GZIP_MAX_WBITS);
    }

    free(buffer_data);
    fclose(input_file);
    gzclose(file);

    log_operation(list, "deserialization completed");
    return NULL;
}

void deserialize(struct list *list, const char *input_file) {
    if (!list->log_file) return;
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, &deserialize_thread, input_file) != 0) {
        perror("pthread_create failed");
        exit(EXIT_FAILURE);
    }
    pthread_detach(thread_id);
}
