#include <chrono>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueTag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

struct CRC_INDICATION_REL8_TAG {
    bool crcFlag;
};

class DataSource {
public:
    virtual RX_UE_INFORMATION_TAG getUEInfoTag() = 0;
    virtual int getRNTI() = 0;
};

class DataProvider : public DataSource {
private:
    std::mutex mtx;
    std::vector<RX_UE_INFORMATION_TAG> ueTags;
    std::vector<int> rntis;
    std::default_random_device rd;
    std::mt19937 gen;

public:
    DataProvider() : gen(rd()) {
        for (int i = 0; i < 100; ++i) {
            ueTags.push_back((RX_UE_INFORMATION_TAG)i);
            rntis.push_back(i + 100);
        }
    }

    RX_UE_INFORMATION_TAG getUEInfoTag() override {
        std::unique_lock<std::mutex> lock(mtx);
        if (!ueTags.empty()) {
            auto ueTag = ueTags.back();
            ueTags.pop_back();
            return ueTag;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        return getUEInfoTag();
    }

    int getRNTI() override {
        std::unique_lock<std::mutex> lock(mtx);
        if (!rntis.empty()) {
            auto rnti = rntis.back();
            rntis.pop_back();
            return rnti;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        return getRNTI();
    }
};

class PDUAllocator {
private:
    DataSource& dataSource;
    std::atomic<int> totalSuccessfullyInitialized{ 0 };
    std::mutex mtx;

public:
    explicit PDUAllocator(DataSource& dataSource) : dataSource(dataSource) {}

    NFAPI_CRC_INDICATION_PDU_T* allocate(size_t batchSize) {
        if (batchSize == 0) return nullptr;

        auto pduArray = new NFAPI_CRC_INDICATION_PDU_T[batchSize];
        if (!pduArray) return nullptr;

        std::unique_lock<std::mutex> lock(mtx);
        for (size_t i = 0; i < batchSize; ++i) {
            auto ueInfoTag = dataSource.getUEInfoTag();
            auto rnti = dataSource.getRNTI();

            pduArray[i].ueTag = ueInfoTag;
            pduArray[i].rnti = rnti;
            pduArray[i].crcIndication.crcFlag = (rd() % 2 == 0) ? true : false;
        }

        totalSuccessfullyInitialized += batchSize;
        return pduArray;
    }
};
```

