    size_t array_size = 0;
    pthread_mutex_t lock;
    sem_t mem_semaphore;

    pthread_mutex_init(&lock, NULL);
    sem_init(&mem_semaphore, 0, 1);

    config_array = calloc(num_threads, sizeof(LTE_RRC_SRB_CONFIG));
    if (!config_array) {
