import os
import hashlib
import stat
import sys
import mmap
from functools import lru_cache

def md5(file):
    if not os.path.isfile(file):
        raise FileNotFoundError(f'File {file} does not exist')

    with open(file, 'rb') as f:
        statbuf = os.stat(file)
        chunksize = 4096
        buffer = mmap.mmap(-1, statbuf.st_size, filedes=f.fileno(), access=mmap.ACCESS_READ)

    md5obj = hashlib.md5()
    while len(buffer) > 0:
        md5obj.update(buffer[:chunksize])
        buffer.seek(0)
        buffer = buffer[chunksize:]

    return md5obj.digest()
