['```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <stdio.h>

typedef struct {
    uint64_t ueId;
    time_t rachRequestTime;
    enum RrcState { RRC_IDLE, RRC_CONNECTED, RRC_INACTIVE } currentRrcState;
} UEContextInfo;

#define MAX_CONTEXTS 10000

struct ContextManager {
    UEContextInfo contexts[MAX_CONTEXTS];
    int numContexts;
    pthread_mutex_t lock;
    time_t lastCleanupTime;
    time_t cleanupInterval;
};

void initContextManager(struct ContextManager *manager, time_t cleanupInterval) {
    manager->numContexts = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->lastCleanupTime = 0;
    manager->cleanupInterval = cleanupInterval;
}

UEContextInfo* findContextByUeId(struct ContextManager *manager, uint64_t ueId) {
    for (int i = 0; i < manager->numContexts; ++i) {
        if (manager->contexts[i].ueId == ueId)
            return &manager->contexts[i];
    }
    return NULL;
}

bool addContext(struct ContextManager *manager, UEContextInfo context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->numContexts >= MAX_CONTEXTS) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }
    manager->contexts[manager->numContexts] = context;
    ++manager->numContexts;
    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool updateContext(struct ContextManager *manager, UEContextInfo updatedContext) {
    UEContextInfo* foundContext = findContextByUeId(manager, updatedContext.ueId);
    if (!foundContext)
        return false;

    pthread_mutex_lock(&manager->lock);
    if (updatedContext.currentRrcState == RRC_INACTIVE &&
        time(NULL) - updatedContext.rachRequestTime > 60) { // Clean up inactive contexts older than 1 minute
        --manager->numContexts;
        memmove(&manager->contexts[foundContext - manager->contexts],
                &manager->contexts[manager->numContexts],
                (manager->numContexts - 1) * sizeof(UEContextInfo));
    } else {
        foundContext->rachRequestTime = updatedContext.rachRequestTime;
        foundContext->currentRrcState = updatedContext.currentRrcState;
    }
    pthread_mutex_unlock(&manager->lock);
    return true;
}

void cleanupInactiveContexts(struct ContextManager *manager) {
    time_t currentTime = time(NULL);
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->numContexts; ++i) {
        if (manager->contexts[i].currentRrcState == RRC_INACTIVE &&
            currentTime - manager->contexts[i].rachRequestTime > manager->cleanupInterval) {
            --manager->numContexts;
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->numContexts - i) * sizeof(UEContextInfo));
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void contextManagerPeriodicCheck(struct ContextManager *manager, time_t currentTime) {
    if (currentTime - manager->lastCleanupTime >= manager->cleanupInterval) {
        cleanupInactiveContexts(manager);
        manager->lastCleanupTime = currentTime;
    }
}
```

