```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>

struct std::hash<std::thread::id> {
    std::size_t operator()(const std::thread::id& id) const {
        return static_cast<std::size_t>(id.native_handle());
    }
};

struct LTE_ECGI_T {
    std::atomic<uint64_t> GUTI;
    std::atomic<uint16_t> CI;
    std::vector<MeasurementReportItem_T> MeasurementReports;
    std::mutex mtx;
};

struct MeasurementReportItem_T {
    int ServingCellRSRP;
    int ServingCellRSRQ;
};

class LTE_ECGI_Manager_T {
public:
    LTE_ECGI_Manager_T(size_t initialCapacity) : data_(initialCapacity), id_(std::this_thread::get_id()) {}

    void AddEntry(const LTE_ECGI_T& entry);
    LTE_ECGI_T* GetEntryByGUTI(uint64_t GUTI);
    LTE_ECGI_T* UpdateEntryByGUTI(uint64_t GUTI, const LTE_ECGI_T& newData);

private:
    std::vector<LTE_ECGI_T> data_;
    std::unordered_map<std::thread::id, size_t> threadsToIndex_;
    std::mutex mtx;
    std::mt19937 rng_;
    std::uniform_int_distribution<> rsrpDist_(0, 85); // range: 0-85 dBm (realistic RSRP values)
    std::uniform_int_distribution<> rsqrDist_(0, 100); // range: 0-100% (realistic RSRQ values)

    size_t GetIndexForThread() {
        auto it = threadsToIndex_.find(std::this_thread::get_id());
        if (it != threadsToIndex_.end())
            return it->second;
        auto newIndex = data_.size();
        threadsToIndex_[std::this_thread::get_id()] = newIndex;
        data_.resize(newIndex + 1);
        return newIndex;
    }
};

void LTE_ECGI_Manager_T::AddEntry(const LTE_ECGI_T& entry) {
    size_t index = GetIndexForThread();
    data_[index] = entry;
}

LTE_ECGI_T* LTE_ECGI_Manager_T::GetEntryByGUTI(uint64_t GUTI) {
    std::scoped_lock lock(mtx);
    auto it = data_.begin();
    while (it != data_.end()) {
        if (it->GUTI.load() == GUTI)
            return &*it;
        ++it;
    }
    return nullptr;
}

LTE_ECGI_T* LTE_ECGI_Manager_T::UpdateEntryByGUTI(uint64_t GUTI, const LTE_ECGI_T& newData) {
    std::scoped_lock lock(mtx);
    auto it = data_.begin();
    while (it != data_.end()) {
        if (it->GUTI.load() == GUTI) {
            it->CI.store(newData.CI.load());
            it->MeasurementReports = newData.MeasurementReports;
            return &*it;
        }
        ++it;
    }
    return nullptr;
}
```

