NFAPI_CRC_INDICATION_PDU_T* allocate_and_shuffle(size_t N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        data[i].crc_indication_rel8.CRCFLAG = rand() % 2;
    }

    shuffle(data, N);

    return data;
}

void print_and_verify(const NFAPI_CRC_INDICATION_PDU_T *data, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        printf("Index: %lu\n", i);
