    }
}

void shuffle(NFAPI_CRC_INDICATION_PDU_T *data, size_t N) {
    if (N <= 1) return;

    for (size_t i = 0; i < N - 1; ++i) {
        size_t j = rand() % (i + 1);
        if (i != j) {
            swap(&data[i], &data[j]);
        }
    }
}

void swap(NFAPI_CRC_INDICATION_PDU_T *a, NFAPI_CRC_INDICATION_PDU_T *b) {
    NFAPI_CRC_INDICATION_PDU_T temp = *a;
    *a = *b;
    *b = temp;
}
