#include <pthread.h>
#include <time.h>
#include <atomic>
#include <list>
#include <unordered_map>
#include <chrono>
#include <mutex>

struct UEContextInfo {
    uint64_t ueId;
    time_t rachRequestTime;
    int currentRrcState;
};

typedef std::list<UEContextInfo> UEContextList;
typedef std::unordered_map<uint64_t, UEContextInfo*> UEContextMap;

std::atomic<bool> g_running{true};
std::mutex g_mutex;
std::condition_variable g_cv;

void cleanupThread(UEContextMap& contexts) {
    while (g_running) {
        std::unique_lock<std::mutex> lock(g_mutex);
        g_cv.wait(lock, []{ return (contexts.size() > 100) || !g_running; }); // Adjust threshold as needed

        auto now = time(NULL);
        UEContextList toRemove;
        for (auto it = contexts.begin(); it != contexts.end(); ) {
            if ((now - it->second->rachRequestTime) > 60) // Adjust time in seconds as needed
                toRemove.push_back(*it);
            ++it;
        }

        for (auto ctx : toRemove) {
            delete ctx.second;
            contexts.erase(ctx.first);
        }

        lock.unlock();
    }
}

UEContextInfo* addOrUpdateUEContext(UEContextMap& contexts, uint64_t ueId, time_t rachRequestTime, int currentRrcState) {
    auto it = contexts.find(ueId);
    UEContextInfo* ctx;

    std::unique_lock<std::mutex> lock(g_mutex);
    g_cv.notify_one(); // Notify cleanup thread to check for cleanups

    if (it == contexts.end()) {
        ctx = new UEContextInfo{ueId, rachRequestTime, currentRrcState};
        contexts[ueId] = ctx;
    } else {
        ctx = it->second;
        ctx->rachRequestTime = rachRequestTime;
        ctx->currentRrcState = currentRrcState;
    }

    return ctx;
}

void removeUEContext(UEContextMap& contexts, uint64_t ueId) {
    auto it = contexts.find(ueId);

    std::unique_lock<std::mutex> lock(g_mutex);
    if (it != contexts.end()) {
        delete it->second;
        contexts.erase(it);
    }
}

void initUEContextManager(UEContextMap& contexts, pthread_t* cleanupThreadId) {
    *cleanupThreadId = std::thread(cleanupThread, std::ref(contexts));
}
