#include <pthread.h>
#include <time.h>

typedef struct {
    uint8_t mac_addr[6];
    uint16_t length;
    uint8_t data[500]; // Adjust size according to your needs
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    void* (*parser)(const uint8_t*, size_t); // Function pointers for custom parsing logic
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;
    arr->capacity = 0;
    arr->size = 0;
    arr->parser = NULL;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_dynamic_array(DynamicArray *arr) {
    free(arr->data);
    free(arr);
}

MAC_PDU_T* grow_dynamic_array(DynamicArray *arr, size_t new_capacity) {
    if (new_capacity > 5000) return NULL; // Limit to 5000 elements
    MAC_PDU_T *new_data = realloc(arr->data, new_capacity * sizeof(MAC_PDU_T));
    if (!new_data) return NULL;
    arr->data = new_data;
    arr->capacity = new_capacity;
    return &arr->data[arr->size];
}

void push_to_dynamic_array(DynamicArray *arr, const uint8_t* pdu, size_t length, void* (*parser)(const uint8_t*, size_t)) {
    MAC_PDU_T* entry = grow_dynamic_array(arr, arr->size + 1);
    if (!entry) return; // Handle memory allocation failure

    memcpy(entry, pdu, length);
    entry->length = length;
    arr->parser = parser; // Update parsing function for future entries

    // Process the parsed data here
    if (arr->parser) {
        uint8_t* parsed_data = arr->parser(pdu, length);
        if (parsed_data) memcpy(&entry->data[0], parsed_data, parsed_data - pdu);
    }

    arr->size++;
}

// Concurrent access functions, each with its own mutex for thread safety
void enqueue_to_dynamic_array(DynamicArray *arr, const uint8_t* pdu, size_t length) {
    pthread_mutex_lock(&arr->lock);
    push_to_dynamic_array(arr, pdu, length, arr->parser);
    pthread_mutex_unlock(&arr->lock);
}

// Use this function if you need to iterate through the array in a thread-safe manner
void for_each_in_dynamic_array(DynamicArray *arr, void(*fn)(MAC_PDU_T*)) {
    pthread_mutex_lock(&arr->lock);
    MAC_PDU_T* current = arr->data;
    MAC_PDU_T* end = arr->data + arr->size;

    for (; current < end; ++current) {
        fn(current);
    }
    pthread_mutex_unlock(&arr->lock);
}
```

