#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    uint32_t field1;
    uint32_t field2;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t list_lock;
    bool logging_enabled;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (!list) {
        perror("Memory allocation failure");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

void destroy_list(List* list) {
    if (!list) return;
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!data) return NULL;
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("Memory allocation failure");
        return NULL;
    }
    node->data = *data;
    node->next = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void add_to_list(List* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!list || !data) return;
    Node* new_node = create_node(data);
    if (!new_node) return;
    pthread_mutex_lock(&list->list_lock);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->list_lock);
}

void iterate_over_list(List* list, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) return;
    pthread_mutex_lock(&list->list_lock);
    Node* current = list->head;
    while (current != NULL) {
        callback(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->list_lock);
}

void set_logging(List* list, bool enable) {
    if (!list) return;
    list->logging_enabled = enable;
}

void log(const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list && list->logging_enabled) {
        printf("Data:\nfield1: %u\nfield2: %u\n", data->field1, data->field2);
    }
}
```

