        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    sem_init(&manager->cache, 0, initial_capacity); // Initialize cache semaphore to allow all buffers initially

    return manager;
}

PHY_RX_BUFFER* allocate_buffer(struct buffer_manager* manager) {
    pthread_mutex_lock(&manager->lock);

    size_t index = manager->count;
    if (index < manager->capacity && manager->buffers[index]) { // Buffer is available
        PHY_RX_BUFFER* buffer = manager->buffers[index];
        manager->buffers[index] = NULL;
        manager->count++;
        pthread_mutex_unlock(&manager->lock);
        return buffer;
    } else { // No available buffer, extend capacity if necessary and allocate new one
        if (index == manager->capacity) {
            PHY_RX_BUFFER** new_buffers = realloc(manager->buffers, manager->capacity * 2 * sizeof(PHY_RX_BUFFER*));
            if (!new_buffers) {
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            manager->capacity *= 2;
            manager->buffers = new_buffers;
        }

        PHY_RX_BUFFER* buffer = calloc(1, sizeof(PHY_RX_BUFFER));
        if (!buffer) {
            pthread_mutex_unlock(&manager->lock);
            return NULL;
        }

        manager->buffers[index] = buffer;
        manager->count++;
        pthread_mutex_unlock(&manager->lock);
        sem_post(&manager->cache); // Make new buffer available for caching strategy

        return buffer;
    }
}

void free_buffer(struct buffer_manager* manager, PHY_RX_BUFFER* buffer) {
    pthread_mutex_lock(&manager->lock);

    if (sem_wait(&manager->cache)) { // Wait for a released buffer slot in the caching strategy
        pthread_mutex_unlock(&manager->lock);
        free(buffer);
        return;
    }

    size_t index = manager->count - 1;
    manager->buffers[index] = buffer;
    manager->count--;
    pthread_mutex_unlock(&manager->lock);
}

void iterate_buffers(const struct buffer_manager* manager, void(*action)(PHY_RX_BUFFER*)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->buffers[i]) action(manager->buffers[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void shutdown_buffer_manager(struct buffer_manager* manager) {
    pthread_mutex_destroy(&manager->lock);
    sem_destroy(&manager->cache);
    free(manager->buffers);
    free(manager);
}
```

This code creates a `buffer_manager` struct that manages a list of `PHY_RX_BUFFER` elements dynamically allocated using `calloc`. The manager implements functions for allocating, releasing, and iterating through the buffers as well as shutting down the system.

The caching strategy is implemented using a semaphore to control access to free buffer slots, allowing for efficient memory operations while minimizing fragmentation. The code also incorporates error handling for null pointers and out-of-memory conditions.

For easy scalability, the memory allocation strategy doubles the capacity when necessary. However, it's important to note that this implementation does not include data integrity checks or synchronization mechanisms to prevent race conditions during concurrent access. You may consider implementing these features depending on your specific application requirements."]

