int processNfaPduList(NFAPI_CRC_INDICATION_PDU_T** pduList, size_t listSize) {
    char* serializedPayload;
    NFAPI_CRC_INDICATION_PDU_T* currentPdu;
    size_t batchCount = 0;
    bool isNetworkConnected = true;

    for (size_t i = 0; i < listSize; ++i) {
        currentPdu = pduList[i];

        // Randomly set CRCFLAG and assign unique transaction ID
        currentPdu->CRCFLAG = rand() % 2;
        currentPdu->transactionID = time(NULL);

        // Set CRC_INDICATION_REL8_TAG based on RSSI values
        currentPdu->CRC_INDICATION_REL8_TAG = (uint16_t)(-currentPdu->RSSI * 0.01);

        // Batch multiple structures into a single serialized payload
        if ((i + 1) % BATCH_SIZE == 0 || i == listSize - 1) {
            serializePDU(&pduList[batchCount], &serializedPayload);
            isNetworkConnected = transmitData(serializedPayload);

            if (isNetworkConnected) {
                ++batchCount;
                serializedPayload = NULL;
            }
        }
    }

    // Handle any remaining serialized payloads before exiting the function
    while (batchCount > 0) {
        isNetworkConnected = transmitData(serializedPayload);

        if (isNetworkConnected) {
            --batchCount;
            serializedPayload = NULL;
        }
    }

    // Start message broker thread if not already started
    if (pthread_self() != messageBrokerThread) {
        pthread_create(&messageBrokerThread, NULL, messageBrokerHandle, NULL);
    }

    // Log transaction details and any errors encountered during processing
    for (size_t i = 0; i < listSize; ++i) {
        pthread_mutex_lock(&logMutex);
        logEvent(pduList[i]->transactionID == currentPdu->transactionID ?
                 "Processed PDU with transaction ID" :
                 "Skipped corrupted or incomplete PDU");
        pthread_mutex_unlock(&logMutex);
    }

    return 0;
}
