#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_QUEUE_SIZE 100000
#define TIMESTAMP_TICKS_PER_SECOND 1000000000L

typedef struct LTE_TRANSPORT_CONTEXT_T {
    int E_UTRAN_CELL_ID;
    int TRANSPORT_CHANNEL;
    uint32_t TRANSPORT_CONTEXT_VALIDATION_TAG;
    uint16_t QoS_PROFILE_ID;
    uint64_t sequence_number;
    struct timespec timestamp;
} LTE_TRANSPORT_CONTEXT;

struct queue_node {
    LTE_TRANSPORT_CONTEXT context;
    struct queue_node *next;
};

struct queue {
    struct queue_node *head;
    struct queue_node *tail;
    size_t length;
    pthread_mutex_t lock;
    pthread_cond_t full_cond;
    pthread_cond_t empty_cond;
};

void init_queue(struct queue *q) {
    q->head = NULL;
    q->tail = NULL;
    q->length = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->full_cond, NULL);
    pthread_cond_init(&q->empty_cond, NULL);
}

void enqueue(struct queue *q, const LTE_TRANSPORT_CONTEXT *context) {
    struct queue_node* node = malloc(sizeof(struct queue_node));
    if (!node) {
        perror("malloc failed");
        return;
    }

    memcpy(&node->context, context, sizeof(LTE_TRANSPORT_CONTEXT));
    node->next = NULL;

    pthread_mutex_lock(&q->lock);

    if (q->length == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&q->empty_cond, &q->lock);
    }

    if (q->head) {
        q->head = node;
    } else {
        q->tail = node;
    }
    q->head->next = q->head; // circular list
    q->length++;

    pthread_mutex_unlock(&q->lock);
}

void dequeue(struct queue *q, LTE_TRANSPORT_CONTEXT* context) {
    pthread_mutex_lock(&q->lock);

    if (q->length == 0) {
        pthread_cond_wait(&q->full_cond, &q->lock);
    }

    if (q->length == 1) {
        *context = q->head->context;
        free(q->head);
        q->tail = NULL;
        q->head = NULL;
    } else {
        struct queue_node* temp = q->head;
        *context = q->head->context;
        q->head = q->head->next;
        free(temp);
        q->length--;
    }

    pthread_mutex_unlock(&q->lock);

    pthread_cond_signal(&q->empty_cond);
}

