#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
size_t size = 0;
pthread_mutex_t list_lock;

void init_list() {
    pthread_mutex_init(&list_lock, NULL);
}

bool is_empty() {
    pthread_mutex_lock(&list_lock);
    bool empty = size == 0;
    pthread_mutex_unlock(&list_lock);
    return empty;
}

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    pthread_mutex_init(&new_node->lock, NULL);
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    size++;
    pthread_mutex_unlock(&list_lock);
}

void remove_by_rnti(uint32_t rnti) {
    Node* current = head;
    Node* previous = NULL;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            size--;
            pthread_mutex_unlock(&list_lock);
            return;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

void update_crcflag(uint32_t rnti, bool new_crcflag) {
    Node* current = head;
    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data.crcflag = new_crcflag;
            pthread_mutex_unlock(&list_lock);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

bool list_integrity() {
    Node* current = head;
    bool integrity = true;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (size > 1 && current->data.rnti == current->next->data.rnti) {
            integrity = false;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
    return integrity;
}

void serialize(FILE* fp) {
    // Implement serialization logic here
}

void deserialize(FILE* fp) {
    // Implement deserialization logic here
}
