void generate_unique_rnti(NFAPI_CRC_INDICATION_PDU* pdu, int attempts) {
    pthread_mutex_lock(&rnti_mutex);
    while (RTNIs.count(pdu->rnti) && attempts > 0) {
        // Reset RNTI and attempt to insert again if already in use
        pdu->rnti = rand();
        attempts--;
    }
