        pdus[i].crc_indication_rel8_tag.crcflag = (rand() % 2) == 1;
    }
    return pdus;
}

NFAPI_CRC_INDICATION_PDU* create_pdus_list(int N) {
    pthread_t threads[N];
    void** results = malloc(N * sizeof(void*));

    for (int i = 0; i < N; ++i) {
        if (pthread_create(&threads[i], NULL, create_pdus, &N) != 0) {
