#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T_CRCFLAG CRC_INDICATION_REL8_TAG;
} UE_INFO;

typedef struct node {
    UE_INFO data;
    struct node* next;
} Node;

static Node* head = NULL;
static size_t capacity = 0;
static double growth_factor = 1.5;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    if (capacity) return;
    capacity = 8;
    head = malloc(capacity * sizeof(Node));
    for (size_t i = 0; i < capacity - 1; ++i)
        head[i].next = &head[i + 1];
    head[capacity - 1].next = NULL;
}

void resize_list() {
    Node* new_nodes = malloc((size_t)(growth_factor * capacity) * sizeof(Node));
    for (size_t i = 0; i < capacity; ++i) {
        Node* current = &head[i];
        new_nodes[i].data = current->data;
        if (!current->next) break;
        new_nodes[i].next = &new_nodes[i + 1];
        current->next = (Node*)((size_t)(growth_factor * capacity) + (size_t)current);
    }
    free(head);
    head = new_nodes;
    capacity *= growth_factor;
}

void add_ue_info(UE_INFO* ue_info) {
    pthread_mutex_lock(&mutex);
    if (!head) init_list();
    Node* current = head;
    while (current->next && current->next->data.RNTI == ue_info->RNTI + 1)
        current = current->next;
    if (capacity <= head - current) resize_list();
    current->next = malloc(sizeof(Node));
    current = current->next;
    memcpy(&current->data, ue_info, sizeof(UE_INFO));
    current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    pthread_mutex_unlock(&mutex);
}

UE_INFO* get_ue_info(uint32_t rnti) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current) {
        if (current->data.RNTI == rnti) {
            UE_INFO* ue_info = malloc(sizeof(UE_INFO));
            memcpy(ue_info, &current->data, sizeof(UE_INFO));
            pthread_mutex_unlock(&mutex);
            return ue_info;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}
```

This code defines a doubly-linked list to store UE information and provides functions for initializing the list, adding new elements, and retrieving existing ones. The list dynamically resizes itself when necessary and ensures thread safety using a mutex. Error handling is minimal, but you can add more extensive checks as needed. Keep in mind that this is a simplified implementation, and optimizations should be made according to your specific requirements and constraints.']

