    pool->capacity = capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    srand(seed);
    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_structure(DataPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->data[pool->count];

    pthread_mutex_lock(&pool->mutex);
    if (pool->count >= pool->capacity) {
        log_message("Error: Data pool is full.");
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
