    sockaddr_in source;
    sockaddr_in destination;
} TrafficEvent;

void generate_ip(sockaddr_in* ip) {
    memset(ip, 0, sizeof(*ip));
    ip->sin_family = AF_INET;
    ip->sin_port = htons(rand() % 65535);
    ip->sin_addr.s_addr = htonl(rand() | (RAND_MAX >> 16));
}

void init_traffic_events(TrafficEvent* events, size_t size) {
    if (size == 0) {
        perror("Invalid array size");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t now = tv.tv_sec;

    for (size_t i = 0; i < size; ++i) {
        generate_ip(&events[i].source);
        generate_ip(&events[i].destination);

        // Adjust timestamp to avoid consecutive events with the same IP addresses
        while ((i > 0 && (events[i].source.sin_addr.s_addr == events[i - 1].source.sin_addr.s_addr ||
                          events[i].destination.sin_addr.s_addr == events[i - 1].destination.sin_addr.s_addr)) ||
               (i > 1 && memcmp(&events[i], &events[i - 2], sizeof(TrafficEvent)) == 0)) {
            generate_ip(&events[i].source);
            generate_ip(&events[i].destination);
        }

        events[i].timestamp = now + i * 10; // Adjust the timestamp to increase with every event for simplicity
    }
}
