static sem_t queue_not_full = SEM_INITIALIZER_NP;
static sem_t queue_not_empty = SEM_INITIALIZER_NP;

void enqueue(PHY_LAYER_TRANSACTION transaction) {
    sem_wait(&mutex);
    if (head == NULL || head->next == NULL) {
        sem_post(&queue_not_full);
    } else if (max_size <= head->next - &head->transaction) {
        free(head->next);
        while (max_size <= head->next - &head->transaction) {
            head = head->next;
