pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned int successful_allocations = 0;
unsigned int failed_allocations = 0;
unsigned int total_entities = 0;

LTE_MAC_ENTITY* initialize_lte_mac_list(int N) {
    LTE_MAC_ENTITY* head = NULL;
    LTE_MAC_ENTITY* current = NULL;
    for (int i = 0; i < N; ++i) {
        LTE_MAC_ENTITY* new_entity = (LTE_MAC_ENTITY*)mempool_alloc();
        if (!new_entity) {
            ++failed_allocations;
            continue;
        }
        total_entities++;
        new_entity->mac_entity_id = i + 1;
        new_entity->sequence_number = rand() % 65536;
        MAC_PDU* pdu = (MAC_PDU*)mempool_alloc();
        if (!pdu) {
            free(new_entity);
            --total_entities;
            ++failed_allocations;
            continue;
        }
        pdu->header = new_entity->mac_entity_id << 12 | (new_entity->sequence_number & 0xFFF);
        pdu->payload = NULL;
        new_entity->pdu = pdu;
        new_entity->next = head;
        head = new_entity;
    }
    return head;
}

void log_allocation_status() {
    pthread_mutex_lock(&log_mutex);
    printf("Successful allocations: %u\n", successful_allocations);
    printf("Failed allocations: %u\n", failed_allocations);
    printf("Total entities managed: %u\n", total_entities);
    pthread_mutex_unlock(&log_mutex);
}
