// Custom logger API
typedef enum { INFO, WARNING, ERROR } LogLevel;

typedef struct _LogEntry {
    char *message;
    LogLevel level;
    struct _LogEntry *next;
} LogEntry;

void log(LogLevel level, const char *msg, void(*logger)(LogEntry*)) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->message = strdup(msg);
    entry->level = level;
    entry->next = NULL;

    // Thread safety and null pointer handling
    if (!entry || !entry->message) {
        free(entry);
        return;
    }

    // Dynamic memory allocation for log entries, minimizing fragmentation
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    LogEntry *log_list = NULL;
    pthread_mutex_lock(&lock);
        log_list = malloc(sizeof(LogEntry));
        if (!log_list) {
            free(entry->message);
            free(entry);
            pthread_mutex_unlock(&lock);
            return;
        }
        log_list->next = entry;
    pthread_mutex_unlock(&lock);

    // External logging service integration (synchronous)
    if (logger) {
        logger(entry);
    }
}

// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int num) {
    int rnti;
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        log(ERROR, "Insufficient memory", NULL);
        return NULL;
    }

    for (int i = 0; i < num && scanf("%d", &rnti) == 1; ++i) {
        if (rnti < 0 || rnti > 65535) {
            log(WARNING, "Invalid RNTI value:", NULL);
            continue;
        }

        list[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_REL8;
        list[i].rnti = rnti;
        list[i].crc_indication_rel8_tag.crcflag = (rand() % 2) ? true : false;
    }

    return num > 0 && i == num ? list : free_and_log(list, num, ERROR, "Out of memory");
}

void free_and_log(NFAPI_CRC_INDICATION_PDU_T *list, int len, LogLevel level, const char *msg) {
    log(level, msg, NULL);
    for (int i = 0; i < len; ++i) {
        free(list[i].rnti);
    }
    free(list);
    return;
}
