typedef struct RadioPacket {
    ReceiverInfo receiver;
    time_t transmissionTime;
    int channelQuality;
    size_t packetsLost;
    uint64_t bandwidthConsumed;
    pthread_mutex_t packetDataMutex;
} RadioPacket;

typedef struct {
    RadioPacket* packets;
    size_t capacity;
    size_t currentSize;
    pthread_mutex_t listMutex;
} RadioNetwork;

RadioNetwork* initializeRadioNetwork(size_t expectedPackets, int networkBandwidth) {
    size_t packetSize = sizeof(RadioPacket);
    RadioNetwork *network = malloc(sizeof(RadioNetwork));

    if (network == NULL) {
        perror("Memory allocation failed");
        exit(-1);
    }

    network->capacity = expectedPackets > 10000 ? 10000 : expectedPackets;
    network->currentSize = 0;

    network->packets = malloc(network->capacity * packetSize);

    if (network->packets == NULL) {
        perror("Memory allocation failed");
        exit(-1);
    }

    for (size_t i = 0; i < network->capacity; ++i) {
        RadioPacket* packet = &network->packets[i];
        packet->transmissionTime = 0;
        packet->channelQuality = 0;
        packet->packetsLost = 0;
        packet->bandwidthConsumed = 0;
        pthread_mutex_init(&packet->packetDataMutex, NULL);
    }

    pthread_mutex_init(&network->listMutex, NULL);

    // Track total bandwidth consumption across packets
    network->totalBandwidth = networkBandwidth * 8ULL * 1024 * 1024; // assuming network bandwidth in Mbps and packet size in bytes

    return network;
}
```

