void ltephy_rxueinfo_list_add(RX_UE_INFORMATION_TAG info, unsigned char rnti[], LTEPHY_RX_CQI_TAG cqi) {
    struct node *new_node = (struct node*) malloc(sizeof(struct node));
    new_node->info = info;
    memcpy(new_node->rnti, rnti, 4);
    new_node->cqi = cqi;
    new_node->next = head;
    head = new_node;
}

void ltephy_rxueinfo_list_remove(unsigned char rnti[]) {
    struct node *current, *prev;

    prev = NULL;
    current = head;

    while (current != NULL) {
        if (!memcmp(current->rnti, rnti, 4)) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void ltephy_rxueinfo_list_iterate(void (*func)(RX_UE_INFORMATION_TAG, unsigned char[], LTEPHY_RX_CQI_TAG)) {
    struct node *current;

    pthread_mutex_lock(&list_mutex);
    current = head;
    head = NULL;
    while (current != NULL) {
        func(current->info, current->rnti, current->cqi);
        current = current->next;
        free(head);
        head = current;
    }
    pthread_mutex_unlock(&list_mutex);
}

