#include <stdbool.h>

typedef struct LTEPHY_RXUEINFO_TAG {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
    LTEPHY_RX_CQI_TAG cqi;
} LTEPHY_RXUEINFO_TAG;

typedef struct node {
    LTEPHY_RXUEINFO_TAG info;
    struct node* next;
} Node;

Node* create_node(LTEPHY_RXUEINFO_TAG info) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->info = info;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void remove_node(Node** head, uint32_t rnti) {
    if (*head == NULL) {
        return;
    }

    Node* current = *head;
    if (current->rnti == rnti) {
        *head = current->next;
        free(current);
        return;
    }

    Node* previous = current;
    while (current != NULL && current->rnti != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return;
    }

    previous->next = current->next;
    free(current);
}

Node* find_node(const Node* head, uint32_t rnti) {
    for (Node* current = (Node*)head; current != NULL; current = current->next) {
        if (current->rnti == rnti) {
            return (Node*)current;
        }
    }
    return NULL;
}
