// Custom types for simplicity
typedef struct Frame {
    NFAPI_MESSAGE_T msg;
    void* userData;
} Frame;

typedef struct FrameList {
    size_t capacity;
    size_t length;
    Frame** frames;
} FrameList;

FrameList* createFrameList(size_t capacity) {
    FrameList* list = malloc(sizeof(FrameList));
    if (!list) {
        perror("Failed to allocate memory for FrameList");
        return NULL;
    }
    list->capacity = capacity;
    list->length = 0;
    list->frames = calloc(capacity, sizeof(Frame*));
    if (!list->frames) {
        free(list);
        perror("Failed to allocate memory for frames array");
        return NULL;
    }
    return list;
}

void resizeFrameList(FrameList* list) {
    Frame** newFrames = realloc(list->frames, (list->capacity * 2) * sizeof(Frame*));
    if (!newFrames) {
        perror("Failed to allocate memory for frames array");
        return;
    }
    list->frames = newFrames;
    list->capacity *= 2;
}

Frame* createFrame(void* userData, NFAPI_DL_FRAMEINFO dlInfo, NFAPI_UL_FRAMEINFO ulInfo) {
    Frame* frame = malloc(sizeof(Frame));
    if (!frame) {
        perror("Failed to allocate memory for Frame");
        return NULL;
    }
    frame->msg.dlInfo = dlInfo;
    frame->msg.ulInfo = ulInfo;
    frame->userData = userData;
    return frame;
}

void addFrameToList(FrameList* list, Frame* frame) {
    if (list->length >= list->capacity)
        resizeFrameList(list);
    list->frames[list->length++] = frame;
}

Frame* getFrameByID(const FrameList* list, uint32_t id) {
    for (size_t i = 0; i < list->length; ++i) {
        if (list->frames[i]->msg.id == id)
            return list->frames[i];
    }
    return NULL;
}

void freeFrameList(FrameList* list) {
    for (size_t i = 0; i < list->length; ++i) {
        free(list->frames[i]);
    }
    free(list->frames);
    free(list);
}
