        temp = head;
        head = head->next;
        free(temp);
    }
    head = NULL;
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = malloc(sizeof(Node));
    memset(new_node, 0, sizeof(Node));
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return new_node;
}

void insert_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = create_node(data);
    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T* remove_node() {
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        pthread_mutex_unlock(&list_lock);
        return NULL;
    }
    data = &head->data;
    Node* temp = head;
    head = head->next;
    free(temp);
    pthread_mutex_unlock(&list_lock);
    return data;
}

void serialize(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;
    while (head != NULL) {
        remove_node();
    }
    Node* new_node;
    while (!feof(file)) {
        new_node = malloc(sizeof(Node));
        fread(new_node, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        insert_node(&new_node->data);
    }
    fclose(file);
}
```

