    int sum = 0;
    char *extension;
    char newFilename[MAX_FILENAME_LENGTH];
    int i, j, k = 0;

    // Calculate character frequency and check edge cases
    for (i = 0; filename[i] != '\0'; ++i) {
        if (!isalnum(filename[i])) continue;
        ++charFrequency[(tolower(filename[i]) - 'a')];
    }

    // Construct extension
    for (i = 0; i < 3; ++i) sum += filename[i];
    extensionLength = sum > 255 ? MAX_EXTENSION_LENGTH : sum > 96 ? sum : 3;
    extension = malloc(extensionLength + 1);

    for (i = 0, j = 0; i < extensionLength; ++i) {
        if (j >= 26) extension[i] = 'a' + (rand() % 26);
        else extension[i] = 'a' + (charFrequency[(j++ < 26 ? j : j - 26)] > 0 ? charFrequency[(j++ < 26 ? j : j - 26)] : 'z');
    }
    extension[extensionLength] = '\0';

    // Construct new filename with unique identifier and extension
    for (i = 0; filename[i] != '\0' || extension[j] != '\0'; ++i, ++j) {
        if (k >= MAX_FILENAME_LENGTH - 1) break;
        if (i < strlen(filename)) newFilename[k++] = filename[i];
        if (j < extensionLength) newFilename[k++] = extension[j];
    }
    newFilename[k] = '\0'; // Ensure null terminator

    // Error handling for unexpected cases
    if ((int)strlen(newFilename) > MAX_FILENAME_LENGTH - 1 || (int)strlen(extension) > MAX_EXTENSION_LENGTH - 1) {
        fprintf(stderr, "Error: Generated filename exceeds the maximum allowed length.\n");
        free(extension);
        return;
    }

    // Replace original filename with new one
    sprintf(filename, "%s", newFilename);
}
