#include <iostream>
#include <vector>
#include <boost/circular_buffer.hpp>
#include <mutex>

struct NetworkNode {
    int NodeID;
    std::string Location;
    // BandwidthMetrics structure representing the network device attributes
};

class NodeManager {
private:
    const int maxNodes = 10000;
    boost::circular_buffer<NetworkNode> nodesBuffer(maxNodes);
    std::vector<NetworkNode> nodes;
    std::mutex mutex;

public:
    void addNode(const NetworkNode& node) {
        // Add node to the circular buffer and vector using lock-free data structure first
        if (nodesBuffer.push_back(node)) {
            // If the operation was successful, perform synchronization by adding the node to the vector using a mutex
            std::lock_guard<std::mutex> lock(mutex);
            nodes.push_back(node);
        }
    }

    void removeNode(int NodeID) {
        // Remove node from both structures using lock-free data structure first
        if (nodesBuffer.erase(nodesBuffer.begin(), std::find(nodesBuffer.begin(), nodesBuffer.end(), NodeID))) {
            // If the operation was successful, perform synchronization by removing the node from the vector using a mutex
            std::lock_guard<std::mutex> lock(mutex);
            auto it = std::remove_if(nodes.begin(), nodes.end(), [NodeID](const NetworkNode& n) { return n.NodeID == NodeID; });
            nodes.erase(it, nodes.end());
        }
    }

    const NetworkNode* getNodeByID(int NodeID) const {
        // Try to find the node in the circular buffer using lock-free data structure first
        auto it = std::find_if(nodesBuffer.begin(), nodesBuffer.end(), [NodeID](const NetworkNode& n) { return n.NodeID == NodeID; });

        if (it != nodesBuffer.end()) {
            // If found, return the node directly
            return &(*it);
        } else {
            // Otherwise, perform synchronization by searching the vector using a mutex
            std::lock_guard<std::mutex> lock(mutex);

            it = std::find_if(nodes.begin(), nodes.end(), [NodeID](const NetworkNode& n) { return n.NodeID == NodeID; });

            if (it != nodes.end()) {
                // If found, return the node directly
                return &(*it);
            } else {
                // Otherwise, indicate that the node was not found
                return nullptr;
            }
        }
    }
};
```

