#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t allocator_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_allocated = 0;
static size_t failed_allocations = 0;

void* randomize_crc(void *p_crc) {
    CRC_INDICATION_REL8_TAG *crc = static_cast<CRC_INDICATION_REL8_TAG*>(p_crc);
    crc->crcflag = (uint32_t)(rand() % 2);
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t n) {
    if (n == 0) return nullptr;

    pthread_mutex_lock(&allocator_mutex);

    NFAPI_CRC_INDICATION_PDU_T *pdus = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    if (!pdus) {
        failed_allocations++;
        pthread_mutex_unlock(&allocator_mutex);
        return nullptr;
    }

    total_allocated += n;
    for (size_t i = 0; i < n; ++i) {
        pdus[i].tag.fieldValue = i;
        pdus[i].rnti.fieldValue = i + 1000;
        pthread_mutex_lock(&allocator_mutex);
        void *crc_ptr = &pdus[i].crc_indication;
        pthread_mutex_unlock(&allocator_mutex);
        pthread_mutex_init(static_cast<pthread_t*>(crc_ptr), nullptr);
        pthread_create(static_cast<pthread_t*>(crc_ptr), nullptr, &randomize_crc, crc_ptr);
    }

    if (pthread_mutex_unlock(&allocator_mutex)) {
        fprintf(stderr, "Failed to unlock allocator mutex during pdu allocation\n");
        free(pdus);
        return nullptr;
    }

    return pdus;
}
