['```cpp
#include <iostream>
#include <unordered_map>
#include <set>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include <boost/circular_buffer.hpp>
#include <boost/optional.hpp>

class EnvironmentalMetadata {
public:
    double temperature;
    int humidity;
    int aqi;
};

struct LocationVersion {
    double latitude;
    double longitude;
    double altitude;
    EnvironmentalMetadata metadata;
    std::int64_t timestamp;
};

class VersionedLocation {
public:
    std::vector<LocationVersion> versions;
    std::mutex mutex;
};

struct GeoHashNode {
    int geohash;
    std::unordered_map<double, VersionedLocation> locations;
    std::set<GeoHashNode*> children;
    EnvironmentalMetadata metadata;
};

class GeoTree {
public:
    void insert(const LocationVersion& locationVersion) {
        auto currentNode = root;
        boost::optional<GeoHashNode*> parent;

        for (int bit = 63; bit >= 0; --bit) {
            int geohashBit = (locationVersion.latitude >> bit) & 1;
            if (!parent || parent->get()->children.count(geohashNodeForGeohash(currentNode->geohash ^ (1 << bit))) == 0) {
                parent = createChild(currentNode, geohashBit);
            }
            currentNode = *parent;
        }

        currentNode->locations[locationVersion.latitude] = LocationVersion{locationVersion};
    }

    void remove(const double& latitude) {
        auto currentNode = root;
        boost::optional<GeoHashNode*> parent;

        for (int bit = 63; bit >= 0; --bit) {
            int geohashBit = (currentNode->geohash >> bit) & 1;
            if (parent && geohashBit != (latitude >> bit) & 1) {
                currentNode = *parent;
            }
            else {
                parent = getChild(currentNode, !geohashBit);
                if (!parent) break;
            }
        }

        if (parent && currentNode->locations.count(latitude)) {
            currentNode->locations.erase(latitude);
            if (currentNode->locations.empty()) {
                auto it = currentNode->children.find(GeoHashNode*());
                if (it != currentNode->children.end()) {
                    currentNode->children.erase(it);
                }
            }
        }
    }

    VersionedLocation getLatestVersion(const double& latitude) const {
        auto currentNode = root;
        boost::optional<GeoHashNode*> parent;

        for (int bit = 63; bit >= 0; --bit) {
            int geohashBit = (currentNode->geohash >> bit) & 1;
            if (parent && geohashBit != (latitude >> bit) & 1) {
                currentNode = *parent;
            }
            else {
                parent = getChild(currentNode, !geohashBit);
                if (!parent) break;
            }
        }

        auto it = currentNode->locations.find(latitude);
        if (it != currentNode->locations.end()) {
            return it->second;
        }
        return VersionedLocation{};
    }

    std::vector<VersionedLocation> queryVersionsByLatitude(const double& latitude, const int fromIndex, const int toIndex) const {
        auto currentNode = root;
        boost::optional<GeoHashNode*> parent;

        for (int bit = 63; bit >= 0; --bit) {
            int geohashBit = (currentNode->geohash >> bit) & 1;
            if (parent && geohashBit != (latitude >> bit) & 1) {
                currentNode = *parent;
            }
            else {
                parent = getChild(currentNode, !geohashBit);
                if (!parent) break;
            }
        }

        std::vector<VersionedLocation> result;
        for (auto& it : currentNode->locations) {
            if (it.second.versions.size() > toIndex) continue;
            if (fromIndex <= it.second.versions.size()) {
                result.push_back(it.second);
            }
        }
        return result;
    }

private:
    GeoHashNode* createChild(GeoHashNode* parent, int geohashBit) {
        auto newNode = new GeoHashNode();
        newNode->geohash = parent->geohash | (geohashBit << 1);
        parent->children.insert(newNode);
        return newNode;
    }

    boost::optional<GeoHashNode*> getChild(GeoHashNode* node, bool geohashBit) {
        for (auto& child : node->children) {
            if ((child->geohash >> 1) == geohashBit) {
                return child;
            }
        }
        return boost::none;
    }

    GeoHashNode* geohashNodeForGeohash(int geohash) {
        return new GeoHashNode() {};
    }

    GeoHashNode* root = new GeoHashNode();
};
