    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_element {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct list_element* next;
};

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
struct list_element* head = NULL;
size_t list_size = 0;
static size_t max_elements = 16; // initial capacity

void grow_list() {
    max_elements *= 2;
    struct list_element** current = &head;
    while (*current) current = &(*current)->next;
    while (max_elements > list_size) {
        *current = malloc(sizeof(struct list_element));
        (*current)->pdu = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*current)->next = NULL;
        current = &(*current)->next;
    }
}

void insert_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list_mutex);
    if (list_size >= max_elements) grow_list();
    struct list_element* current = head;
    while (current->next != NULL) current = current->next;
    current->next = malloc(sizeof(struct list_element));
    current = current->next;
    current->pdu = pdu;
    current->next = NULL;
    list_size++;
    pthread_mutex_unlock(&list_mutex);
}

void clean_list() {
    pthread_mutex_lock(&list_mutex);
    struct list_element* current = head, * temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
    head = NULL;
    list_size = 0;
    pthread_mutex_unlock(&list_mutex);
}

