#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <checksum.h> // Assuming checksum library for data validation

typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    uint8_t data[MAX_DATA_SIZE]; // Assume MAX_DATA_SIZE is a constant defined elsewhere
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct dynamic_list {
    size_t length;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
    void (*destroy)(NFAPI_CRC_INDICATION_PDU_T*); // Callback for destroying elements
    checksum_t (*checksum)(const NFAPI_CRC_INDICATION_PDU_T*); // Checksum function
} dynamic_list_t;

void dynamic_list_init(dynamic_list_t* list, size_t initial_capacity, void (*destroy)(NFAPI_CRC_INDICATION_PDU_T*), checksum_t (*checksum)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    list->length = 0;
    list->capacity = initial_capacity;
    list->destroy = destroy;
    list->checksum = checksum;
}

void dynamic_list_add(dynamic_list_t* list, const NFAPI_CRC_INDICATION_PDU_T* item) {
    if (list->length == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            fprintf(stderr, "Memory allocation failure\n");
            exit(EXIT_FAILURE);
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->length] = *item;
    list->length++;
}

void dynamic_list_remove(dynamic_list_t* list, size_t index) {
    if (index >= list->length) {
        fprintf(stderr, "Invalid index\n");
        return;
    }

    // Call the destroy callback if provided
    if (list->destroy) {
        list->destroy(&list->data[index]);
    }

    memmove(&list->data[index], &list->data[index + 1], --list->length - index);
    list->length--;
}

void dynamic_list_update(dynamic_list_t* list, size_t index, const NFAPI_CRC_INDICATION_PDU_T* new_item) {
    if (index >= list->length) {
        fprintf(stderr, "Invalid index\n");
        return;
    }

    // Validate CRC flag before updating the item
    bool is_valid = list->checksum && list->checksum(&list->data[index]) == list->data[index].crc_tag.value;
    if (!is_valid) {
        fprintf(stderr, "Invalid data: CRC check failed\n");
        return;
    }

    // Call the destroy callback if provided for the old item
    if (list->destroy) {
        list->destroy(&list->data[index]);
    }

    list->data[index] = *new_item;
}

void dynamic_list_cleanup(dynamic_list_t* list) {
    free(list->data);
    list->data = NULL;
    list->length = 0;
    list->capacity = 0;
}
```

