```csharp
using System;
using System.Xml;
using System.Xml.XPath;
using System.Threading;
using System.Linq;

public class XmlUtil {
    public static string FindFirstMatchingElement(string xml, string xpathExpression, string expectedElementName, int timeoutMs) {
        var watch = new System.Diagnostics.Stopwatch();
        watch.Start();

        using (var reader = new XmlTextReader(new StringReader(xml))) {
            var document = new XmlDocument();
            document.Load(reader);
            var navigator = document.CreateNavigator();
            var xpathNavigator = navigator.Evaluate(xpathExpression) as XPathNavigator;

            if (xpathNavigator == null) {
                throw new ArgumentException("Invalid XPath expression");
            }

            if (!xpathNavigator.MoveToFirst()) {
                throw new TimeoutException($"No matching element found within {timeoutMs}ms.");
            }

            var matchedElement = xpathNavigator.Name;
            if (matchedElement != expectedElementName) {
                throw new AmbiguousMatchException("More than one element with the specified name found.");
            }

            watch.Stop();
            if (watch.ElapsedMilliseconds > timeoutMs) {
                Console.WriteLine($"Warning: Timeout exceeded while searching for '{expectedElementName}'");
            }

            return xpathNavigator.ReadValueAsString();
        }
    }
}
