#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    size_t buffer_size;
    char *buffer;
} NFAPI_RX_FRAME_PDU_T;

struct dynamic_array {
    NFAPI_RX_FRAME_PDU_T **data;
    size_t capacity;
    size_t count;
    sem_t mutex;
};

void da_init(struct dynamic_array *da, size_t initial_capacity) {
    da->data = malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_PDU_T*));
    da->capacity = initial_capacity;
    da->count = 0;
    sem_init(&(da->mutex), 0, 1);
}

void da_push(struct dynamic_array *da, NFAPI_RX_FRAME_PDU_T *pdu) {
    sem_wait(&(da->mutex));

    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_RX_FRAME_PDU_T **new_data = realloc(da->data, new_capacity * sizeof(NFAPI_RX_FRAME_PDU_T*));
        if (!new_data) {
            // Handle out-of-memory condition (e.g., discard least recently used data or pause new stream initialization)
            sem_post(&(da->mutex));
            return;
        }
        da->capacity = new_capacity;
        da->data = new_data;
    }

    da->data[da->count] = pdu;
    ++(da->count);
    sem_post(&(da->mutex));
}

NFAPI_RX_FRAME_PDU_T* da_pop(struct dynamic_array *da) {
    NFAPI_RX_FRAME_PDU_T *pdu;
    size_t i;

    sem_wait(&(da->mutex));

    if (da->count > 0) {
        pdu = da->data[0];
        for (i = 1; i < da->count; ++i) {
            da->data[i - 1] = da->data[i];
        }
        --(da->count);
        da->data[da->count] = NULL;
        sem_post(&(da->mutex));
        return pdu;
    } else {
        sem_post(&(da->mutex));
        return NULL;
    }
}
