static NFAPI_RX_FRAME_PDU_T* dynamic_array = NULL;
static size_t current_size = 0;
static size_t max_size = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_element(RX_UE_INFORMATION_TAG ue_tag, RNTI rnti, const void* frame_data, size_t data_size) {
    pthread_mutex_lock(&mutex);

    if (current_size + 1 >= max_size) {
        if ((max_size * 2) > MAX_ELEMENTS || current_size + 1 > BUFFER_THRESHOLD / sizeof(NFAPI_RX_FRAME_PDU_T))
            return; // Return without adding if memory limit exceeded or array size too large
        max_size *= 2;
    }

    dynamic_array = realloc(dynamic_array, max_size * sizeof(NFAPI_RX_FRAME_PDU_T));

    NFAPI_RX_FRAME_PDU_T* element = &dynamic_array[current_size];
    element->ue_tag = ue_tag;
    element->rnti = rnti;
    element->frame_data = malloc(data_size);
    memcpy(element->frame_data, frame_data, data_size);
    element->crc_indication.CRCFLAG = rand() % 2; // Set CRCFLAG randomly
    current_size++;

    pthread_mutex_unlock(&mutex);
}

