    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    struct _NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _LIST_NODE {
    pthread_mutex_t mutex;
    struct _NFAPI_CRC_INDICATION_PDU_T *head;
    struct _NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
} LIST_NODE;

static NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, uint32_t rnti, CRC_INDICATION_REL8_TAG crc_indication, bool crcflag) {
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->tag     = tag;
    node->rnti    = rnti;
    node->crc_indication = crc_indication;
    node->crcflag   = crcflag;
    node->prev      = NULL;
    node->next      = NULL;

    return node;
}

static void add_node(LIST_NODE *list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    ++(list->size);
}

static void remove_node(LIST_NODE *list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (node == list->head) {
        list->head = node->next;
        if (list->head)
            list->head->prev = NULL;
        else
            list->tail = NULL;
    } else if (node == list->tail) {
        list->tail = node->prev;
        list->tail->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    free(node);
    --(list->size);
}

static NFAPI_CRC_INDICATION_PDU_T* find_matching_node(LIST_NODE *list, RX_UE_INFORMATION_TAG tag) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        if (current->tag == tag) return current;
        current = current->next;
    }

    return NULL;
}

static void clear_list(LIST_NODE *list) {
    while (list->head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* nodeToFree = list->head;
        list->head = list->head->next;
        free(nodeToFree);
    }

    list->size = 0;
}

static void evict_least_recently_used(LIST_NODE *list, size_t threshold) {
    if (list->size > threshold) {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        NFAPI_CRC_INDICATION_PDU_T* nodeToFree;
        size_t evictions = list->size - threshold;

        while (evictions--) {
            if (current == list->tail) {
                nodeToFree = list->tail;
                list->tail = current->prev;
                if (list->tail) list->tail->next = NULL;
            } else {
                nodeToFree = current;
                current = current->next;
            }

            remove_node(list, nodeToFree);
        }
    }
}

