void initList(List *list) {
    list->head = (Node**)malloc(sizeof(Node*)*2);
    list->tail = list->head + 1;
    list->length = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroyList(List *list) {
    Node *current = *list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

Node* createNode(const NFAPI_CRC_INDICATION_PDU_T *data, uint64_t RNTI) {
