    Node* newNode = createNode(data, RNTI);

    if (newNode == NULL) {
        printf("Failed to allocate memory for new node.\n");
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    if (*list->head == NULL) {
        *list->head = newNode;
        *list->tail = newNode;
    } else {
        newNode->next = *list->head;
        (*list->head)->prev = newNode;
        *list->head = newNode;
    }
    list->length++;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

