    uint32_t RX_UE_INFORMATION_TAG;
    bool CRCIndicationTag;
};

template<typename T, size_t bufferSize>
class CustomAllocator : public std::allocator<T> {
public:
    using value_type = T;
    using pointer = typename std::allocator<T>::pointer;
    using const_pointer = typename std::allocator<T>::const_pointer;
    using size_type = typename std::allocator<T>::size_type;
    using difference_type = typename std::allocator<T>::difference_type;

    pointer allocate(size_type n, const void* hint) {
        // Custom allocation logic based on LRU eviction policy and memory mapping
        // ...

        return static_cast<pointer>(mmap(NULL, n * sizeof(value_type), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0));
    }

    void deallocate(pointer p, size_type) {
        // Custom deallocation logic based on LRU eviction policy and memory unmapping
        munmap(static_cast<void*>(p), sizeof(*p));
    }
};

class UEContextManager {
private:
    std::vector<UEContextInfo, CustomAllocator<UEContextInfo, 1024>> contexts;
    boost::circular_buffer<UEContextInfo> cache;
    pthread_mutex_t mutex;
    atomic<size_t> cacheSize{0};

public:
    UEContextManager() {
        pthread_mutex_init(&mutex, nullptr);
    }

    ~UEContextManager() {
        // Cache cleanup logic goes here
        pthread_mutex_destroy(&mutex);
    }

    void add(const UEContextInfo& context) {
        pthread_mutex_lock(&mutex);
        contexts.push_back(context);
        if (cacheSize < cache.capacity()) {
            cache.push_back(context);
            ++cacheSize;
        } else {
            // LRU eviction logic goes here
            cache[0] = contexts.back();
            contexts.pop_back();
        }
        pthread_mutex_unlock(&mutex);
    }

    void update(uint64_t rnti, const UEContextInfo& context) {
        pthread_mutex_lock(&mutex);
        auto it = std::find_if(contexts.begin(), contexts.end(), [rnti](const UEContextInfo& ueContext) { return ueContext.RNTI == rnti; });

        if (it != contexts.end()) {
            *it = context;

            // Check cache and update if necessary
            auto cacheIt = std::find_if(cache.begin(), cache.end(), [rnti](const UEContextInfo& ueContext) { return ueContext.RNTI == rnti; });
            if (cacheIt != cache.end()) {
                *cacheIt = context;
            }
        }

        pthread_mutex_unlock(&mutex);
    }
};
```

This implementation uses a custom allocator for `std::vector`, which implements an LRU eviction policy to minimize memory fragmentation and efficiently deallocate unused resources. The `UEContextManager` class manages the dynamic array of `UEContextInfo` structures, providing functions for adding and updating entries with fine-grained locking using `pthread_mutex`.

To handle high concurrency, this implementation uses a circular buffer `boost::circular_buffer` for caching read-heavy operations from the main data structure. The cache size is dynamically managed based on the available resources and LRU eviction policy.

