#include <boost/intrusive_ptr.hpp>
#include <pthread.h>
#include <glog/logging.h>
#include <vector>
#include <cstdlib>
#include <cstring>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag; // randomly set
} NFAPI_CRC_INDICATION_PDU_T;

const int MAX_ELEMENTS = 10000;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
std::vector<boost::intrusive_ptr<NFAPI_CRC_INDICATION_PDU_T>> list;

void init() {
    if (list.size()) return; // initialization is done once at program start
    for (int i = 0; i < MAX_ELEMENTS; ++i)
        list.emplace_back(new NFAPI_CRC_INDICATION_PDU_T);
}

boost::intrusive_ptr<NFAPI_CRC_INDICATION_PDU_T> add(const RX_UE_INFORMATION_TAG& rx_ue_info, const RNTI& rnti) {
    boost::intrusive_ptr<NFAPI_CRC_INDICATION_PDU_T> pdu;
    pthread_mutex_lock(&list_mutex);
    if (list.size() >= MAX_ELEMENTS) {
        LOG(WARNING) << "List is full, unable to add element.";
        pthread_mutex_unlock(&list_mutex);
        return nullptr;
    }

    pdu = list[list.size() - 1];
    memset(pdu.get(), 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->rx_ue_information_tag = rx_ue_info;
    pdu->rnti = rnti;
    pdu->crcflag = rand() % 2;
    pthread_mutex_unlock(&list_mutex);
    return pdu;
}

void remove(boost::intrusive_ptr<NFAPI_CRC_INDICATION_PDU_T> pdu) {
    pthread_mutex_lock(&list_mutex);
    auto it = std::find(list.begin(), list.end(), pdu);
    if (it == list.end()) {
        LOG(WARNING) << "Unable to find element to remove.";
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    list.erase(it);
    delete it->get();
    pthread_mutex_unlock(&list_mutex);
}
```

The `init()`, `add()`, and `remove()` functions handle the dynamic list management, ensuring efficient memory usage and thread safety through the use of a mutex. The `add()` function creates new elements on-the-fly when necessary, while the `remove()` function deletes elements efficiently using `boost::intrusive_ptr`.

