        UserSession session;
        session.user_id = it->second;
        session.start_time = std::chrono::steady_clock::now();
        session.last_active = session.start_time;
        session.recent_requests.insert(session.recent_requests.end(), requests.begin(), requests.end());
        sessions_[user] = session;
