    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_pdus(size_t N) {
    if (N > 10000) {
        fprintf(stderr, "Error: Maximum supported size is 10,000.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    pthread_t threads[N];
    pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
    unsigned int unique_rntis[10000] = { 0 };
    bool all_initialized = false;

    for (size_t i = 0; i < N && !all_initialized; ++i) {
        pthread_create(&threads[i], NULL, generate_pdu_worker, &pdus[i]);
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);

        if (pdus[i].RNTI >= 1 << 15) {
            fprintf(stderr, "Error: RNTI value out of range.\n");
            all_initialized = true;
            break;
        }

        if (unique_rntis[pdus[i].RNTI]) {
            fprintf(stderr, "Error: Duplicate RNTI value encountered.\n");
            all_initialized = true;
            break;
        }

        unique_rntis[pdus[i].RNTI] = 1;
    }

    if (all_initialized) {
        free(pdus);
        return NULL;
    }

    return pdus;
}

void* generate_pdu_worker(void *data) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = data;

    pthread_mutex_lock(&rnti_lock);

    do {
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand() & 0x7FFF;
        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG = (rand() % 2) == 0;
    } while (!unique_rnti_check(pdu));

    pthread_mutex_unlock(&rnti_lock);

    return NULL;
}

bool unique_rnti_check(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return !unique_rntis[pdu->RNTI];
}
```

