// Thread-safe hash map for CRC verification. Key is RNTI, value is expected CRC value.
typedef struct hash_map {
    uint16_t* keys; // RNTIs
    uint16_t* values; // CRC values
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashMap;

HashMap* create_hash_map(size_t capacity) {
    HashMap* hash_map = malloc(sizeof(HashMap));
    hash_map->capacity = capacity;
    hash_map->size = 0;
    hash_map->keys = calloc(capacity, sizeof(uint16_t));
    hash_map->values = calloc(capacity, sizeof(uint16_t));
    hash_map->lock = PTHREAD_MUTEX_INITIALIZER;
    return hash_map;
}

void put_in_hash_map(HashMap* map, uint16_t key, uint16_t value) {
    pthread_mutex_lock(&map->lock);
    if (map->size == map->capacity) {
        // Handle overflow by resizing the hash map and rehashing.
    }
    map->keys[map->size] = key;
    map->values[map->size++] = value;
    pthread_mutex_unlock(&map->lock);
}

uint16_t get_from_hash_map(HashMap* map, uint16_t key) {
    pthread_mutex_lock(&map->lock);
    size_t i = 0;
    for (; i < map->size; ++i) {
        if (map->keys[i] == key) {
            uint16_t value = map->values[i];
            memmove(map->keys + i, map->keys + i + 1, (map->size - i - 1) * sizeof(uint16_t));
            memmove(map->values + i, map->values + i + 1, (map->size - i - 1) * sizeof(uint16_t));
            --map->size;
            pthread_mutex_unlock(&map->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&map->lock);
    return 0;
}

