    pool->pool = malloc(capacity * sizeof(Node*));
    memset(pool->pool, 0, capacity * sizeof(Node*));
    pthread_mutex_init(&pool->mutex, NULL);
}

Node* acquire_from_memory_pool(struct MemoryPool* pool) {
    Node *node;
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->pool[i]) {
            node = &pool->pool[i];
            pool->pool[i] = node;
            node->next = NULL;
            pthread_mutex_unlock(&pool->mutex);
            return node;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

void release_to_memory_pool(struct MemoryPool* pool, Node *node) {
