    }
}

void create_and_populate_list(size_t n, size_t m, void (*log_fn)(const char*)) {
    NFAPI_CRC_INDICATION_PDU_T** list = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
