    struct thread_data td = { list, NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER };
    create_cache(&td, m);

    pthread_t threads[MAX_THREADS];
    for (size_t i = 0; i < MAX_THREADS && n > td.count; ++i) {
        if (pthread_create(threads + i, NULL, &populate_list, &td)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    free(td.list);
    free_cache(&td);
}
