class DataSourceValidator {
public:
    virtual bool validateCRC(const NFAPI_CRC_INDICATION_PDU_T& pdu) = 0;
};

struct CRCIndicationPDU {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    // ... Additional fields, if any
};

class DynamicList {
private:
    std::vector<CRCIndicationPDU> list_;
    std::mutex mtx_;
    const size_t maxSize_;
    DataSourceValidator* validator_;
    std::atomic<size_t> batchSize_{1};
    std::atomic<unsigned long> validationInterval_{100}; // in milliseconds
    std::atomic<bool> running_{true};

public:
    DynamicList(DataSourceValidator* validator, size_t maxSize)
        : maxSize_(maxSize), validator_(validator) {}

    ~DynamicList() { running_.store(false); }

    void addPDU(const CRCIndicationPDU& pdu) {
        std::unique_lock<std::mutex> lock(mtx_);
        if (list_.size() >= maxSize_) {
            list_.erase(list_.begin());
        }
        list_.push_back(pdu);
    }

    void process() {
        // Batch processing using atomic variables for concurrent thread-safe access.
        std::unique_lock<std::mutex> lock(mtx_);
        auto start = std::chrono::steady_clock::now();
        size_t processedCount = 0;
        while (processedCount < batchSize_ && running_) {
            if (list_.empty()) break;
            auto it = list_.begin();
            auto end = it; ++end;
            std::rotate(it, end, list_.end());
            list_.pop_back();
            const CRCIndicationPDU& pdu = *it;
            if (!validator_->validateCRC(pdu)) {
                logError(it->tag, it->rnti, it->crc_indication.crcFlag, std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count());
            }
            processedCount++;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(validationInterval_));
    }

    void logError(const RX_UE_INFORMATION_TAG& tag, const RNTI& rnti, const CRC_INDICATION_REL8_TAG& crc_indication, unsigned long timestamp) {
        std::cout << "Timestamp: " << timestamp << ", Tag: " << tag << ", RNTI: " << rnti << ", CRC Mismatch: " << crc_indication.crcFlag << std::endl;
    }
};
