typedef struct LTE_PHY_RX_FRAME {
    L1PHY_RX_FRAME_HEADER header;
    L1PHY_RX_FRAME_PAYLOAD payload;
    struct LTE_PHY_RX_FRAME *next;
} LTE_PHY_RX_FRAME;

typedef struct FrameQueueNode {
    uint64_t id;
    struct LTE_PHY_RX_FRAME* frame;
    struct FrameQueueNode *next;
    pthread_mutex_t mutex;
} FrameQueueNode;

void create_frame_queue(FrameQueue **head) {
    *head = malloc(sizeof(FrameQueueNode));
    (*head)->id = 0;
    (*head)->frame = NULL;
    (*head)->next = NULL;
    pthread_mutex_init(&(*head)->mutex, NULL);
}

bool frame_queue_empty(const FrameQueue *node) {
    return node->next == NULL;
}

FrameQueue* find_frame_queue(FrameQueue **head, uint64_t id) {
    FrameQueue *current = *head;
    while (current != NULL) {
        if (current->id == id)
            return current;
        current = current->next;
    }
    return NULL;
}

void insert_frame(FrameQueue **head, uint64_t id, LTE_PHY_RX_FRAME *frame) {
    FrameQueue *new_node = malloc(sizeof(FrameQueueNode));
    new_node->id = id;
    new_node->frame = frame;
    new_node->next = NULL;
    pthread_mutex_init(&(new_node->mutex), NULL);

    FrameQueue *current = find_frame_queue(head, id);

    if (current == NULL) {
        // Insert at the end of the list.
        pthread_mutex_lock(&((*head)->mutex));
        new_node->next = *head;
        *head = new_node;
        pthread_mutex_unlock(&((*head)->mutex));
    } else {
        // Duplicate ID detected, handle gracefully (e.g., drop the frame or queue it).
        printf("Duplicate frame ID encountered: %lu\n", id);
    }
}

LTE_PHY_RX_FRAME* delete_frame(FrameQueue **head, uint64_t id) {
    FrameQueue *current = *head;

    if (current->id == id) {
        // Head of the list has the desired ID.
        LTE_PHY_RX_FRAME *frame_to_free = current->frame;
        *head = current->next;
        free(current);
        return frame_to_free;
    }

    while (current != NULL && current->next != NULL) {
        if (current->next->id == id) {
            LTE_PHY_RX_FRAME *frame_to_free = current->next->frame;
            FrameQueueNode *node_to_free = current->next;
            current->next = current->next->next;
            free(node_to_free);
            return frame_to_free;
        }
        current = current->next;
    }

    // ID not found in the list.
    return NULL;
}
