    unsigned int NR_SI;
    unsigned short NR_SFI;
};

pthread_mutex_t messages_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct NR_CMAC_MESSAGE *messages = NULL;
static size_t capacity = 0;
static size_t size = 0;

void init_messages(size_t initial_capacity) {
    if (initial_capacity > capacity) {
        while (capacity < initial_capacity)
            capacity *= 2;

        messages = realloc(messages, capacity * sizeof(struct NR_CMAC_MESSAGE));
        if (!messages)
