// Memory pool structure
typedef struct memory_pool {
    void* base;
    size_t cap;
    size_t sz;
    size_t avail;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_mem_pool(size_t item_sz, size_t num_items) {
    void *base = mmap(NULL, num_items * item_sz, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (base == MAP_FAILED) {
        return NULL;
    }

    memory_pool* pool = (memory_pool*)base;
    pool->cap = num_items;
    pool->sz = item_sz;
    pool->avail = num_items;
    pthread_mutex_init(&(pool->lock), NULL);
    return pool;
}

void* mem_pool_alloc(memory_pool* pool) {
    pthread_mutex_lock(&(pool->lock));

    if (pool->avail > 0) {
        void *item = ((char*)pool->base) + (pool->sz * (--pool->avail));
        pthread_mutex_unlock(&(pool->lock));
        return item;
    } else {
        pthread_mutex_unlock(&(pool->lock));
        return NULL;
    }
}

void mem_pool_free(memory_pool* pool, void *item) {
    pthread_mutex_lock(&(pool->lock));
    ((char*)pool->base)[(size_t)(item - pool->base)] = 0;
    ++(pool->avail);
    pthread_mutex_unlock(&(pool->lock));
}

// Dynamic list structure
typedef struct dynamic_list {
    memory_pool* mem_pool;
    void** data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} dynamic_list;

dynamic_list* create_dynamic_list(size_t item_sz, size_t init_cap) {
    memory_pool* mem_pool = create_mem_pool(item_sz, init_cap);
    if (!mem_pool) return NULL;

    dynamic_list* list = (dynamic_list*)malloc(sizeof(dynamic_list));
    if (!list) {
        free(mem_pool->base);
        return NULL;
    }

    list->mem_pool = mem_pool;
    list->data = (void**)calloc(init_cap, sizeof(void*));
    if (!list->data) {
        free(mem_pool->base);
        free(list);
        return NULL;
    }

    list->capacity = init_cap;
    list->count = 0;
    pthread_mutex_init(&(list->lock), NULL);
    return list;
}

void insert_to_dynamic_list(dynamic_list* list, struct NR_TRANSPORT_LAYER_MESSAGE* msg) {
    void* item = mem_pool_alloc(list->mem_pool);
    if (!item) return;

    pthread_mutex_lock(&(list->lock));

    if (list->count < list->capacity) {
        list->data[list->count] = item;
        ++(list->count);
    } else {
        // Resize array and reallocate memory pool as needed
    }

    pthread_mutex_unlock(&(list->lock));
}

void* get_from_dynamic_list(dynamic_list* list) {
    if (list->count == 0) return NULL;

    pthread_mutex_lock(&(list->lock));
    void* item = list->data[0];
    memmove(list->data, list->data + 1, --list->count * sizeof(void*));
    --(list->count);
    pthread_mutex_unlock(&(list->lock));

    return item;
}
