static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* buffer = NULL;

void error_log(const char *msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
