NFAPI_CRC_INDICATION_PDU_T* create_buffer() {
    if (buffer != NULL) return buffer;

    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ENTRIES;
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        error_log("mmap failed");
        return NULL;
    }

    buffer = ptr;
    pthread_mutex_init(&mem_lock, NULL);
    return buffer;
}

NFAPI_CRC_INDICATION_PDU_T* alloc_entry(uint16_t rnti) {
    if (rnti >= RNTI_RANGE || rnti >= MAX_ENTRIES) {
        error_log("Invalid RNTI");
        return NULL;
    }

    pthread_mutex_lock(&mem_lock);
    NFAPI_CRC_INDICATION_PDU_T* entry = &buffer[rnti];
    memset(entry, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry->rnti = rnti;
    entry->crc_indication.crcflag = rand() % 2;
    pthread_mutex_unlock(&mem_lock);

    return entry;
}

void dealloc_buffer() {
