    Node_T* current = NULL;
    pthread_mutex_lock(&list->mutex);

    for (Node_T** node = list->head; *node != NULL; node = &(*node)->next) {
        current = *node;
        if (current->data.rnti == rnti)
            break;
    }

    pthread_mutex_unlock(&list->mutex);

    return current;
}

void remove_entry_by_rnti(List_T* list, uint32_t rnti) {
    Node_T** prev = NULL;
    Node_T* current = NULL;

    pthread_mutex_lock(&list->mutex);

    for (Node_T** node = list->head; *node != NULL; node = &(*node)->next) {
        current = *node;
        if (current->data.rnti == rnti) {
            if (prev == NULL)
                *list->head = current->next;
            else
                prev->next = current->next;

            free(current);
            list->size--;
            break;
        }
        prev = node;
    }

    pthread_mutex_unlock(&list->mutex);
}

