// Custom structures
typedef struct {
    LTE_PHY_RX UE_INFO;
    uint32_t CRC_INDICATION_REL15_TAG;
    timestamp_t timestamp;
} dynamic_ue_info;

typedef struct queue_node {
    dynamic_ue_info* data;
    struct queue_node* next;
} queue_node;

// Queue operations (add, remove, iterate)
queue_node* create_node(dynamic_ue_info* data) {
    queue_node* new_node = (queue_node*)malloc(sizeof(queue_node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void enqueue(queue_node** head, dynamic_ue_info* data) {
    queue_node* new_node = create_node(data);

    if (*head == NULL) {
        *head = new_node;
    } else {
        queue_node* last = *head;

        while (last->next != NULL) {
            last = last->next;
        }

        last->next = new_node;
    }
}

dynamic_ue_info* dequeue(queue_node** head) {
    if (*head == NULL) return NULL;

    dynamic_ue_info* temp = (*head)->data;
    queue_node* toFree = *head;
    *head = (*head)->next;

    free(toFree);
    return temp;
}

void print_queue(const char* title, queue_node* head) {
    printf("%s:\n", title);
    for (queue_node* node = head; node != NULL; node = node->next) {
        printf("  [%p]: %d\n", &node->data->UE_INFO.RX_UE_INFORMATION_TAG, node->data->RNTI);
    }
}

// Thread safety and memory management
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t queue_capacity = 0;
size_t queue_length = 0;
queue_node* queue_head = NULL;

// Functions for adding, removing, and iterating over elements in the array
void add_ue_info(LTE_PHY_RX new_ue_info, uint32_t rnti, uint32_t crc) {
    dynamic_ue_info* new_data = malloc(sizeof(dynamic_ue_info));
    pthread_mutex_lock(&queue_mutex);

    if (queue_length + 1 >= queue_capacity) {
        // Resize the array if necessary
        queue_node** new_head = realloc(queue_head, sizeof(queue_node) * (2 * queue_capacity));

        if (!new_head) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&queue_mutex);
            return;
        }

        queue_head = new_head;
        queue_capacity *= 2;
    }

    new_data->UE_INFO = new_ue_info;
    new_data->RNTI = rnti;
    new_data->CRC_INDICATION_REL15_TAG = crc;

    enqueue(&queue_head, new_data);
    queue_length++;

    pthread_mutex_unlock(&queue_mutex);
}

void remove_ue_info(uint32_t rnti) {
    pthread_mutex_lock(&queue_mutex);

    queue_node* current = queue_head;
    queue_node* previous = NULL;

    while (current != NULL) {
        if (current->data->RNTI == rnti) {
            if (previous != NULL) {
                previous->next = current->next;
            } else {
                queue_head = current->next;
            }

            free(current);
            queue_length--;
            break;
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&queue_mutex);
}

// Additional functionality (error handling, logging, etc.)
