#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_UE 10000
#define MAX_PDU_RATE 1000000

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t last_update;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

node_t **pool;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init() {
    // Initialize the pool with MAX_UE empty nodes
    pool = malloc(MAX_UE * sizeof(node_t*));
    for (int i = 0; i < MAX_UE; ++i)
        pool[i] = NULL;
}

void destroy() {
    // Deallocate memory for the pool
    for (int i = 0; i < MAX_UE; ++i) {
        node_t *tmp, *cur = pool[i];
        while (cur != NULL) {
            tmp = cur;
            cur = cur->next;
            free(tmp);
        }
    }
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu() {
    // Search for an empty slot in the pool
    for (int i = 0; i < MAX_UE; ++i) {
        if (pool[i] == NULL) {
            pool[i] = malloc(sizeof(node_t));
            if (pool[i] == NULL) {
                fprintf(stderr, "Out of memory\n");
                exit(1);
            }
            pool[i]->data = (NFAPI_CRC_INDICATION_PDU_T){0};
            pool[i]->next = NULL;
            return &pool[i]->data;
        }
    }
    // If no empty slot is found, allocate a new node from the heap
    node_t *new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    new_node->data = (NFAPI_CRC_INDICATION_PDU_T){0};
    new_node->next = pool[hash(new_node->data.rnti) % MAX_UE];
    pool[hash(new_node->data.rnti) % MAX_UE] = new_node;
    return &new_node->data;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Set the PDU as empty and link it back to the pool
    pthread_mutex_lock(&mutex);
    pdu->rnti = 0;
    pdu->last_update = 0;
    pdu->crc_indication.crcflag = rand() % 2;
    pthread_mutex_unlock(&mutex);

    node_t *cur = pool[hash(pdu->rnti) % MAX_UE];
    while (cur != NULL && cur->next != pdu) {
        cur = cur->next;
    }
    if (cur == NULL || cur->next == NULL) {
        fprintf(stderr, "Failed to free PDU\n");
        exit(1);
    }
    cur->next = pdu->next;
}

int hash(uint32_t key) {
    // Implement your chosen hashing function here
    return key % MAX_UE;
}

// Incorporate the get_pdu and free_pdu functions into the existing UE management system, ensuring thread safety
