    std::vector<NFAPI_CRC_INDICATION_PDU_T> temp = dynamicList;
    std::sort(temp.begin(), temp.end(), customSort);
    dynamicList.clear();
    std::merge(temp.begin(), temp.end(), dynamicList.begin(), dynamicList.end(), customSort);
}
