struct NetworkLogEntry {
    std::int64_t timestamp;
    int eventId;
    std::string message;

    friend std::ostream& operator<<(std::ostream& os, const NetworkLogEntry& entry);
};

std::ostream& operator<<(std::ostream& os, const NetworkLogEntry& entry) {
    os << "Timestamp: " << entry.timestamp << ", Event ID: " << entry.eventId << ", Message: \"" << entry.message << "\"";
    return os;
}

class DynamicNetworkLog {
private:
    static constexpr int minValue = 0;
    static constexpr int maxValue = 100;

    struct DataStore {
        virtual void save(const std::vector<NetworkLogEntry>& logs) = 0;
        virtual std::vector<NetworkLogEntry> load() = 0;
    };

    std::unique_ptr<DataStore> dataStore;
    std::mutex mutex;
    std::vector<NetworkLogEntry> logBuffer;
    std::atomic_int bufferSize{ 0 };
    std::condition_variable cv;

public:
    DynamicNetworkLog(std::unique_ptr<DataStore> dataStore) : dataStore(std::move(dataStore)) {}

    void addEntry(const NetworkLogEntry& entry) {
        std::scoped_lock lock(mutex);
        logBuffer.push_back(entry);
        ++bufferSize;
        cv.notify_one();
    }

    NetworkLogEntry getEntry(size_t index) {
        std::scoped_lock lock(mutex);
        if (index >= bufferSize) {
            throw std::out_of_range("Index out of range.");
        }
        return logBuffer[index];
    }

    void clear() {
        std::scoped_lock lock(mutex);
        logBuffer.clear();
        bufferSize = 0;
    }

    float getRandomFloat(float min, float max) {
        std::uniform_real_distribution<float> distribution(min, max);
        return distribution(UnityEngine::Random::getSystemRandom());
    }

    int getRandomInt(int min, int max, bool exclusive) {
        if (exclusive) {
            std::uniform_int_distribution<int> distribution(min, max - 1);
            return distribution(UnityEngine::Random::getSystemRandom());
        } else {
            std::uniform_int_distribution<int> distribution(min, max);
            return distribution(UnityEngine::Random::getSystemRandom());
        }
