from concurrent.futures import ThreadPoolExecutor

def md5(file_path, chunk_size=8192):
    """Calculate the MD5 hash of a file given its path."""
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_files(directory, chunk_size=8192, max_workers=None):
    """Read files from a directory synchronously and return their contents as strings."""
    results = []
    for file in os.listdir(directory):
        if not file.endswith('.txt'): continue  # Assume .txt files only for simplicity
        file_path = os.path.join(directory, file)
        with open(file_path, 'r', encoding='utf-8') as f:
            results.append(f.read())

    if max_workers:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            results = list(executor.map(lambda file: process_files([file]), [os.path.join(directory, f) for f in os.listdir(directory) if f.endswith('.txt')]))

    return results

def init_config():
