const fs = require('fs');
const path = require('path');
const config = require('./config');

function calculateMD5(filePath) {
  let file = fs.createReadStream(filePath, { highWaterMark: config.chunkSize });
  const md5sum = crypto.createHash('md5');
  file.on('data', chunk => md5sum.update(chunk));
  return new Promise((resolve) => {
    file.on('end', () => resolve(md5sum.digest('hex')));
  });
}

function readFileSync(directory) {
  let results = [];
  const files = fs.readdirSync(directory);
  files.forEach((file) => {
    if (!/text$/.test(path.extname(file))) return; // Assume .txt files only for simplicity
    filePath = path.join(directory, file);
    results.push(fs.readFileSync(filePath, 'utf8'));
  });
  return results;
}

module.exports = {
  calculateMD5,
  readFileSync
};
