    new_array->capacity *= 2;
    new_array->length = (*array)->length;
    new_array->next = NULL;
    new_array->measurements = realloc((*array)->measurements, new_array->capacity * sizeof(LTEMeasurement));
    memcpy(new_array->measurements, (*array)->measurements, (*array)->length * sizeof(LTEMeasurement));
    free(*array);
    *array = new_array;
}

void add_measurement(MeasurementArray* array, LTEMeasurement measurement) {
    if (array->length == array->capacity) resize_measurement_array(&array);
    memcpy(array->measurements + array->length, &measurement, sizeof(LTEMeasurement));
    array->length++;
}

void update_measurement(MeasurementArray* array, int cell_id, LTEMeasurement new_data) {
    for (size_t i = 0; i < array->length; ++i) {
        if (array->measurements[i].cell_id == cell_id) {
            array->measurements[i] = new_data;
            return;
        }
    }
}

