    time_t max_timestamp = 0;
    for (size_t i = 0; i < array->length; ++i) {
        if (array->measurements[i].cell_id == cell_id && array->measurements[i].timestamp > max_timestamp) {
            latest = &array->measurements[i];
            max_timestamp = latest->timestamp;
