#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include "crc_library.h" // Include your external CRC library here

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    timestamp_t last_access_time;
} node_t;

struct LRUList {
    unsigned int capacity;
    unsigned int size;
    node_t* head;
    node_t* tail;
    node_t* eviction_candidate;
    pthread_mutex_t list_lock;
    pthread_rwlock_t cache_lock;
    node_t** cache; // LRU cache array
};

LRUList* lru_list_create(unsigned int capacity) {
    LRUList* list = malloc(sizeof(LRUList));
    if (!list) return NULL;

    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    list->eviction_candidate = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
    pthread_rwlock_init(&list->cache_lock, NULL);

    list->cache = calloc(capacity, sizeof(node_t*));
    if (!list->cache) {
        free(list);
        return NULL;
    }

    return list;
}

bool lru_list_insert(LRUList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list->size >= list->capacity) {
        // Evict least recently used entry and adjust list pointers
        node_t* temp = list->eviction_candidate;
        list->size--;
        if (list->head == temp) {
            list->head = temp->next;
        } else if (list->tail == temp) {
            list->tail = list->tail->prev;
            free(temp);
        } else {
            node_t* current = list->head;
            while (current->next != temp) {
                current = current->next;
            }
            current->next = temp->next;
            if (temp->next) {
                temp->next->prev = current;
            } else {
                list->tail = current;
            }
            free(temp);
        }
    }

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) return false;

    new_node->data = *data;
    new_node->next = NULL;
    new_node->last_access_time = get_timestamp();

    // Insert new node at the beginning of the list and update eviction candidate if necessary
    pthread_mutex_lock(&list->list_lock);
    if (list->head) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        list->head = new_node;
        list->tail = new_node;
    }
    list->eviction_candidate = list->tail;

    unsigned int index = data->RX_UE_INFORMATION_TAG % list->capacity;
    pthread_rwlock_wrlock(&list->cache_lock);
    if (list->cache[index]) {
        // Cache hit, update last access time and CRCFLAG
        node_t* cached = list->cache[index];
        cached->last_access_time = get_timestamp();
        cached->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand();
    } else {
        // Cache miss, allocate new cache entry and store the new node
        list->cache[index] = malloc(sizeof(node_t));
        if (!list->cache[index]) {
            pthread_rwlock_unlock(&list->cache_lock);
            free(new_node);
            return false;
        }
        *list->cache[index] = *new_node;
    }
    list->size++;
    pthread_rwlock_unlock(&list->cache_lock);

    return true;
}

// Enable or disable logging with LOGGING_ENABLED macro before function definition
