#endif

// The following function should be optimized for performance and usability
void* lru_list_iterate(LRUList* list, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*, void* userdata), void* userdata) {
    node_t* current = list->head;

    pthread_mutex_lock(&list->list_lock);
    while (current != NULL) {
        node_t* next = current->next;
        (*callback)(&current->data, userdata); // Pass the CRC indication data to the callback function
        current->last_access_time = get_timestamp();
        current = next;
    }
    pthread_mutex_unlock(&list->list_lock);
}
