        except Exception as e:
            self.log_service.log_error(f"Error while computing hash for {filepath}: {str(e)}")
            return None

class FileHasher:
    def __init__(self, directory_path, num_workers=4, log_service):
        self.directory_path = directory_path
        self.num_workers = num_workers
        self.log_service = log_service
        self.task_queue = SimpleQueue()
        self.results = {}

    def run(self):
        with concurrent.futures.ThreadPoolExecutor(max_workers=self.num_workers) as executor:
            for root, dirs, files in os.walk(self.directory_path):
                for file in files:
                    self.task_queue.put((root + "/" + file, HashWorker(self.log_service)))

            futures = [executor.submit(self.process_file, self.task_queue.get, timeout=60) for _ in range(self.num_workers)]

            for f in concurrent.futures.as_completed(futures):
                filepath, worker = f.result()
                if worker.success:
                    self.results[filepath] = worker.result
                else:
                    self.log_service.log_error(f"Failed to compute hash for {filepath}")

def setup_logging(log_level='INFO'):
    logging.basicConfig(format='%(asctime)s - %(name)s - %(levelname)s - %(message)s', level=log_level)

if __name__ == "__main__":
    setup_logging()
    log_service = logging.getLogger(__name__)
    file_hasher = FileHasher("/path/to/directory", num_workers=4, log_service=log_service)
    file_hasher.run()
```
This code provides a `FileHasher` class that calculates the MD5 hash of multiple files given a directory path using parallel processing and handles exceptions during the hashing operation. The hashing operation is performed in chunks to manage memory usage efficiently, especially for large files. The function integrates with an external logging service, log_service, to monitor progress and handle errors. In case of temporary network failures during logging integration, the primary hashing operation will not be affected. The code uses a thread-safe queue to manage file processing tasks and can be easily extended to support additional hashing algorithms in the future.']

