typedef struct FrameHeader {
    time_t timestamp;
    uint32_t sequenceNumber;
    size_t payloadSize;
    uint8_t* payload; // Checksum is calculated based on this data
} FrameHeader;

FrameHeader* initializeFrames(size_t framesCount, size_t payloadSize) {
    FrameHeader* frames = (FrameHeader*)calloc(framesCount, sizeof(FrameHeader));
    if (!frames) {
        perror("Memory allocation failure");
        return NULL;
    }

    for (size_t i = 0; i < framesCount; ++i) {
        frames[i].timestamp = time(NULL);
        frames[i].sequenceNumber = i;
        frames[i].payloadSize = payloadSize;
        frames[i].payload = calloc(payloadSize, sizeof(uint8_t));
        if (!frames[i].payload) {
            perror("Memory allocation failure");
            for (size_t j = 0; j < i; ++j) free(frames[j].payload);
            free(frames);
            return NULL;
        }
    }

    // Add a checksum calculation method here. This can be a separate function.
    // For simplicity, let's use XOR for now:

    uint32_t checksum = 0;
    for (size_t i = 0; i < framesCount; ++i) {
        for (size_t j = 0; j < payloadSize; ++j) {
            checksum ^= frames[i].payload[j];
        }
        frames[i].checksum = checksum;
        checksum = 0;
    }

    return frames;
}
```

