bool verify_sequence(LTE_DL_FRAME_SETUP *frame, size_t index, const size_t *expected_seq) {
    return (frame[index].FRAME_NUMBER == expected_seq[index]);
}

void print_discrepancies(const LTE_DL_FRAME_SETUP *frames, size_t array_size, const size_t *expected_seq) {
    for (size_t i = 0; i < array_size; ++i) {
        if (!verify_sequence(&frames[i], i, expected_seq)) {
            printf("Sequence number discrepancy at index %zu\n", i);
        }
    }
}

void load_frame_setup(LTE_DL_FRAME_SETUP **frames, size_t *array_size, json_object *json) {
    json_object *config;
    json_object_object_foreach (json, key, value) {
        if (json_object_get_type(value) == json_type_array) {
            config = value;
            break;
        }
    }

    if (!config) {
        fprintf(stderr, "JSON configuration file lacks frame setup array.\n");
        exit(1);
    }

    *array_size = json_array_length(config);
    *frames = malloc(*array_size * sizeof(LTE_DL_FRAME_SETUP));

    for (size_t i = 0; i < *array_size; ++i) {
        json_object *frame_obj = json_array_get_idx(config, i);

        if (!json_object_get_type(frame_obj) == json_type_object) {
            fprintf(stderr, "Invalid frame setup object at index %zu.\n", i);
            exit(1);
        }

        LTE_DL_FRAME_SETUP *frame = &(*frames)[i];

        frame->DL_FRAME_TAG = json_object_get_uint32(json_object_get_named(frame_obj, "DL_FRAME_TAG"));
        frame->CELL_ID = json_object_get_uint16(json_object_get_named(frame_obj, "CELL_ID"));
        frame->FRAME_NUMBER = json_object_get_uint16(json_object_get_named(frame_obj, "FRAME_NUMBER"));
    }
}

int main() {
    LTE_DL_FRAME_SETUP *frame_setup;
    size_t frame_count;
    json_object *config = json_object_from_file("config.json");

    if (!config) {
        fprintf(stderr, "Failed to load configuration file.\n");
        return 1;
    }

    load_frame_setup(&frame_setup, &frame_count, config);

    const size_t expected_seq[] = {/* provide expected sequence number array here */};
    print_discrepancies(frame_setup, frame_count, expected_seq);

    free_json_object(config);
    free(frame_setup);

    return 0;
}
