    size_t count;
    UEContext **data;
    pthread_mutex_t lock;
} UeContextManager;

UeContextManager *ue_context_manager_create(size_t initial_capacity) {
    UeContextManager *manager = malloc(sizeof(UeContextManager));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->data = calloc(initial_capacity, sizeof(UEContext*));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    return manager;
}

void ue_context_manager_add(UeContextManager *manager, UEContext *ue_context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        // Handle reallocation here to accommodate increased capacity when necessary.
    }

    manager->data[manager->count] = ue_context;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

UEContext *ue_context_manager_get(UeContextManager *manager, size_t index) {
    if (index >= manager->count) return NULL;
    pthread_mutex_lock(&manager->lock);
    UEContext *ue_context = manager->data[index];
    pthread_mutex_unlock(&manager->lock);
    return ue_context;
}

void ue_context_manager_update(UeContextManager *manager, size_t index, UEContext *new_ue_context) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->count) return;

    manager->data[index] = new_ue_context;

    pthread_mutex_unlock(&manager->lock);
}

void ue_context_manager_destroy(UeContextManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->data);
    free(manager);
}
