#define MAX_PACKETS 10000
#define PACKET_BUFFER_SIZE 1024
#define TIME_WINDOW_MS 100

typedef struct {
    in_addr_t srcIP;
    in_addr_t dstIP;
    uint16_t protocol;
    size_t payloadSize;
    uint32_t sequenceNumber;
} PacketHeader;

struct LogEntry {
    time_t timestamp;
    PacketHeader header;
    double processingTime;
    int errorCode;
};

void initLog(struct LogEntry** log, size_t* capacity) {
    *log = malloc(*capacity * sizeof(struct LogEntry));
    (*log)[0].timestamp = time(NULL);
}

void logPacket(struct LogEntry* log, PacketHeader header, double processingTime, int errorCode) {
    log[(log - *log) % *((*log) / sizeof(struct LogEntry)) + 1]->timestamp = time(NULL);
    log[(log - *log) % *((*log) / sizeof(struct LogEntry)) + 1]->header = header;
    log[(log - *log) % *((*log) / sizeof(struct LogEntry)) + 1]->processingTime = processingTime;
    log[(log - *log) % *((*log) / sizeof(struct LogEntry)) + 1]->errorCode = errorCode;
}

void packetQueue(PacketHeader** packets, size_t* capacity, size_t* count, PacketHeader newPacket) {
    if (*count >= *capacity) {
        *capacity *= 2;
        *packets = realloc(*packets, *capacity * sizeof(PacketHeader));
    }
    (*packets)[*count] = newPacket;
    (*count)++;
}

void generatePackets(PacketHeader** packets, size_t* capacity, size_t* count) {
    for (size_t i = 0; i < *count; ++i) {
        (*packets)[i].srcIP = htonl(random() >> (32 - 4)); // IPv4 address
        (*packets)[i].dstIP = htonl(random() >> (32 - 8)); // IPv4 address
        while ((*packets + i + 1)->srcIP == (*packets)[i].srcIP || (*packets + i + 1)->dstIP == (*packets)[i].dstIP) {
            if (i > 0) --i;
            (*packets)[i].srcIP = htonl(random() >> (32 - 4)); // IPv4 address
            (*packets)[i].dstIP = htonl(random() >> (32 - 8)); // IPv4 address
        }
        (*packets)[i].protocol = htons((uint16_t)random() % 256);
        (*packets)[i].payloadSize = random() % PACKET_BUFFER_SIZE;
        (*packets)[i].sequenceNumber = htonl(time(NULL) * (i + 1));
    }
}

void processPackets(PacketHeader** packets, size_t count, struct LogEntry* log) {
    double startTime = time(NULL);
    for (size_t i = 0; i < count && (time(NULL) - startTime) <= TIME_WINDOW_MS / 1000.0; ++i) {
        logPacket(log, (*packets)[i], (time(NULL) - startTime), 0); // Log processing time and error code (0 if no error)
        // Process packet here
    }
}
