void populate_packet_array(PacketHeader** packets, size_t num_packets, const char* srcIP_range, const char* dstIP_range, size_t min_protocol, size_t max_protocol) {
    size_t ipv4_address_size = sizeof(in_addr_t);
    in_addr_t src_start, src_end, dst_start, dst_end;
    inet_pton(AF_INET, srcIP_range, &src_start);
    inet_pton(AF_INET, srcIP_range + strlen(srcIP_range) + 2, &src_end);
    inet_pton(AF_INET, dstIP_range, &dst_start);
    inet_pton(AF_INET, dstIP_range + strlen(dstIP_range) + 2, &dst_end);

    *packets = malloc(num_packets * sizeof(PacketHeader));
