int congestionLevel; // Feedback from congestion control algorithm
pthread_mutex_t logMutex; // Mutex for concurrent logging access

// Function to initialize global variables and resources
void initResources() {
    sem_init(&bufferSemaphore, 0, MAX_BUFFER_SIZE);
    pthread_mutex_init(&logMutex, NULL);
}

// Function to create a new PacketHeader with unique IPs and sequence number
PacketHeader* createNewPacket(struct sockaddr_in srcIP, struct sockaddr_in dstIP) {
    // Implement logic for ensuring no two consecutive packets share the same srcIP or dstIP
    static uint32_t lastSequenceNumber = 0;
    lastSequenceNumber++;

    PacketHeader* newPacket = malloc(sizeof(PacketHeader));
    if (!newPacket) {
        perror("Failed to allocate memory for packet header");
        return NULL;
    }

    newPacket->srcIP = srcIP;
    newPacket->dstIP = dstIP;
    newPacket->protocol = 0; // Set protocol value as required
    newPacket->payloadSize = 0; // Set payloadSize value as required
    newPacket->sequenceNumber = lastSequenceNumber;

    return newPacket;
}

// Function to handle individual packet processing
void processPacket(PacketHeader* packet, int* logCount) {
    struct timespec currentTime;
    clock_gettime(CLOCK_MONOTONIC, &currentTime);

    if (currentTime.tv_sec - logTimeWindow.tv_sec > 1) { // Logging time window is 1 second
        pthread_mutex_lock(&logMutex);
        printf("Processed %d packets in the last second.\n", *logCount);
        (*logCount) = 0;
        logTimeWindow = currentTime;
        pthread_mutex_unlock(&logMutex);
    }

    // Implement packet processing logic and congestion control feedback here

    sem_post(&bufferSemaphore); // Release buffer after processing packet

    (*logCount)++;
}

// Function to process packets in a concurrent manner, handling potential errors and resource contention issues
void* handlePackets(void* arg) {
    int logCount = 0;

    while (true) {
        PacketHeader* packet = receivePacket(); // Replace this line with your packet reception logic
        if (!packet) continue;

        sem_wait(&bufferSemaphore); // Wait for buffer availability before processing packets

        processPacket(packet, &logCount);
    }
}
