typedef struct {
    PHICH_DEMODULATION_CONTEXT phich;
    SRS_DEMODULATION_CONTEXT srs;
    PDSCH_DEMODULATION_CONTEXT pdsch;
} LTE_PHY_RX_FRAME;

typedef struct {
    LTE_PHY_RX_FRAME* frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LTE_PHY_RX_BUFFER;

void lte_phy_rx_buffer_init(LTE_PHY_RX_BUFFER* buffer, size_t initial_size) {
    if (initial_size == 0) {
        initial_size = 16;
    }

    buffer->frames = malloc(initial_size * sizeof(LTE_PHY_RX_FRAME));

    if (!buffer->frames) {
        fprintf(stderr, "Failed to allocate memory for LTE_PHY_RX_BUFFER.\n");
        return;
    }

    buffer->capacity = initial_size;
    buffer->size = 0;
    pthread_mutex_init(&buffer->lock, NULL);
}

void lte_phy_rx_buffer_destroy(LTE_PHY_RX_BUFFER* buffer) {
    if (buffer->frames) {
        free(buffer->frames);
        buffer->frames = NULL;
        pthread_mutex_destroy(&buffer->lock);
    }
}

void lte_phy_rx_buffer_resize(LTE_PHY_RX_BUFFER* buffer, size_t new_capacity) {
    if (new_capacity <= buffer->size || !new_capacity) {
        return;
    }

    LTE_PHY_RX_FRAME* new_frames = realloc(buffer->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME));

    if (!new_frames) {
        fprintf(stderr, "Failed to resize LTE_PHY_RX_BUFFER.\n");
        return;
    }

    buffer->frames = new_frames;
    buffer->capacity = new_capacity;
}

void lte_phy_rx_buffer_push(LTE_PHY_RX_BUFFER* buffer, LTE_PHY_RX_FRAME frame) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->size == buffer->capacity) {
        lte_phy_rx_buffer_resize(buffer, buffer->capacity * 2);
    }

    buffer->frames[buffer->size] = frame;
    buffer->size++;
    pthread_mutex_unlock(&buffer->lock);
}

LTE_PHY_RX_FRAME* lte_phy_rx_buffer_pop(LTE_PHY_RX_BUFFER* buffer) {
    LTE_PHY_RX_FRAME* frame;
    pthread_mutex_lock(&buffer->lock);

    if (buffer->size == 0) {
        frame = NULL;
    } else {
        frame = &buffer->frames[0];
        memmove(&buffer->frames[0], &buffer->frames[1], sizeof(LTE_PHY_RX_FRAME) * (--buffer->size));
    }

    pthread_mutex_unlock(&buffer->lock);
    return frame;
}
```

