#include <boost/circular_buffer.hpp>
#include <boost/lockfree/spsc_queue.hpp>
#include <cstdlib> // rand()
#include <atomic>
#include <vector>

struct LTE_PDCP_PDU_T {
    std::atomic<uint32_t> LTE_PDCP_SN;
    std::atomic<uint32_t> LTE_PDCP_SN_MASK;
    std::atomic<uint16_t> LTE_PDCP_NC_SN;
    std::atomic<uint16_t> LTE_PDCP_NC_SN_MASK;
};

// Memory pooling using boost::circular_buffer
constexpr size_t bufferSize = 4096; // Adjust based on your needs
boost::circular_buffer<LTE_PDCP_PDU_T> buffer(bufferSize);

// Lock-free queue for thread-safe access
boost::lockfree::spsc_queue<LTE_PDCP_PDU_T*, std::memory_order_relaxed> queue;

void init() {
    LTE_PDCP_PDU_T* first = buffer.data();
    LTE_PDCP_PDU_T* last = first + bufferSize - 1;

    // Fill the buffer with random values
    for (LTE_PDCP_PDU_T* p = first; p != last; ++p) {
        p->LTE_PDCP_SN.store(rand(), std::memory_order_relaxed);
        p->LTE_PDCP_SN_MASK.store(rand(), std::memory_order_relaxed);
        p->LTE_PDCP_NC_SN.store(rand(), std::memory_order_relaxed);
        p->LTE_PDCP_NC_SN_MASK.store(rand(), std::memory_order_relaxed);
    }
}

// Function to get an element from the buffer, updating its sequence number atomically
LTE_PDCP_PDU_T* get() {
    LTE_PDCP_PDU_T* p = queue.pop(); // Lock-free pop
    if (!p) {
        // Buffer is empty, find a non-empty slot
        for (LTE_PDCP_PDU_T* b = buffer.data(); b != buffer.end(); ++b) {
            if (!b->LTE_PDCP_SN.load(std::memory_order_relaxed)) {
                p = b;
                break;
            }
        }
    }

    // Atomically increment sequence number and set it to non-zero
    p->LTE_PDCP_SN.store(1, std::memory_order_relaxed);
    return p;
}
