    ds->count = 0;
    pthread_mutex_init(&ds->mutex, NULL);
    sem_init(&ds->not_full, 0, n);
    sem_init(&ds->not_empty, 0, 0);
}

void add_data(struct data_struct* ds, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&ds->mutex);
    while (sem_trywait(&ds->not_full) != 0) {
        pthread_cond_wait(&ds->not_empty, &ds->mutex);
    }

    memcpy(ds->array + ds->count, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ds->count++;
    sem_post(&ds->not_full);
    pthread_mutex_unlock(&ds->mutex);
}

void remove_data(struct data_struct* ds) {
    pthread_mutex_lock(&ds->mutex);
    while (sem_trywait(&ds->not_empty) != 0) {
        pthread_cond_wait(&ds->not_full, &ds->mutex);
    }

    if (ds->count > 0) {
        ds->count--;
        sem_post(&ds->not_empty);
    }
    pthread_mutex_unlock(&ds->mutex);
}

