from io import BytesIO
from collections import defaultdict
import logging
import codecs

logger = logging.getLogger(__name__)

def normalize_line(line):
    line = line.strip()
    line = line.encode('utf-8', 'ignore').decode('utf-8')
    return line

def analyze_document(filepath, encoding='utf-8'):
    try:
        if filepath.lower().endswith(('.gz', '.tar.gz')):
            with gzip.open(filepath, 'rt', encoding=encoding) as f:
                for line in f:
                    yield from (normalize_line(line),)

        elif filepath.lower().endswith('.tar.gz'):
            with tarfile.open(filepath, 'r:gz') as tar:
                for member in tar:
                    if member.isfile():
                        with tar.open(member) as f:
                            for line in f:
                                yield from (normalize_line(line),)

        else:
            with open(filepath, encoding=encoding, errors='ignore') as f:
                for line in f:
                    yield from (normalize_line(line),)

    except Exception as e:
        logger.error(f"Error while processing {filepath}: {e}")
        return None

def get_document_metadata(filepath):
    try:
        if os.path.islink(filepath):
            return {"type": "symbolic link", "target": filepath}

        stat = os.stat(filepath)
        timestamp = stat.st_mtime
        size = stat.st_size
        return {"size": size, "timestamp": timestamp, "type": "file"}
    except Exception as e:
        logger.error(f"Error while getting metadata for {filepath}: {e}")
        return None

def average_word_length(words):
    word_count = len(words) if words else 0
    total_chars = sum(len(word) for word in words) if words else 0
    return total_chars / word_count if word_count > 0 else None

def analyze_text_data(directory, encoding='utf-8'):
    report = defaultdict(lambda: {"average_word_length": None, "size": None, "timestamp": None})

    for root, _, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            metadata = get_document_metadata(filepath)
            if metadata:
                document_data = analyze_document(filepath, encoding)
                if document_data:
                    words = [re.sub(r'\W+', ' ', word).strip() for word in document_data]
                    average_length = average_word_length(words)
                    report[metadata['type']].update({"average_word_length": average_length, **metadata})

    return dict(report)

# Configure logging
logging.basicConfig(filename='text_analysis.log', level=logging.INFO, format='%(asctime)s - %(levelname)s: %(message)s')
