#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 1024
#define RNTI_SIZE 8
#define CRCFLAG_SIZE 1

typedef struct {
    uint64_t rnti;
    uint8_t crc_indication_rel8_tag[CRCFLAG_SIZE];
} NFAPI_CRC_INDICATION_PDU_T;

enum overflow_strategy { QUEUE, DISCARD, LOG };

typedef struct queue_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct queue_node* next;
} queue_node_t;

queue_node_t* head = NULL;
queue_node_t* tail = NULL;
enum overflow_strategy overflow_strategy = QUEUE;

int add_structure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (head == NULL) {
        head = malloc(sizeof(queue_node_t));
        if (!head) return -1; // memory allocation failure
        tail = head;
        memcpy(&tail->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        queue_node_t* current = head;
        while (current->next) {
            if (current->next->data.rnti == pdu->rnti) return -2; // duplicate RNTI entry
            current = current->next;
        }

        queue_node_t* new_node = malloc(sizeof(queue_node_t));
        if (!new_node) {
            if (overflow_strategy == LOG) printf("Overflow detected.\n");
            free(pdu);
            return -3; // memory allocation failure on overflow
        }
        memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        current->next = new_node;
        tail = current->next;
    }

    if (tail - head + 1 > MAX_STRUCTURES) {
        queue_node_t* temp = head;
        switch (overflow_strategy) {
            case QUEUE:
                while (tail->next) {
                    tail = tail->next;
                }
                free(temp);
                break;
            case DISCARD:
                free(pdu);
                while (tail != head) {
                    temp = head;
                    head = head->next;
                    free(temp);
                }
                tail = head;
                break;
        }
    }

    return 0; // successful allocation
}

void clear_queue() {
    queue_node_t* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    head = tail = NULL;
}
