#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

struct list {
    struct list_node* head;
    size_t size;
    pthread_mutex_t mutex;
};

static inline void* align(size_t value, size_t alignment) {
    return (void*)(((uintptr_t)value + (alignment - 1)) & ~(alignment - 1));
}

struct list* create_list() {
    struct list* list = malloc(sizeof(struct list));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_list(struct list* list) {
    struct list_node *current, *next;
    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}

struct list_node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->next = NULL;

    return new_node;
}

void add_to_list(struct list* list, struct list_node* node) {
    pthread_mutex_lock(&list->mutex);

    struct list_node* head = list->head;
    if (head == NULL) {
        list->head = node;
    } else {
        while (head->next != NULL) head = head->next;
        head->next = node;
    }

    ++list->size;
    pthread_mutex_unlock(&list->mutex);
}

void remove_from_list(struct list* list, struct list_node* node) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == node) {
        list->head = node->next;
    } else {
        struct list_node *current = list->head;
        while (current->next != node) current = current->next;
        if (current->next == NULL) return; // Node not found
        current->next = node->next;
    }

    --list->size;
    pthread_mutex_unlock(&list->mutex);
}

void serialize(const struct list* list, const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) return; // Error handling...

    size_t alignment = align(sizeof(NFAPI_CRC_INDICATION_PDU_T), getpagesize()) - sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void *buf = mmap(NULL, list->size * alignment + list->size, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buf == MAP_FAILED) { // Error handling...
        close(fd);
        return;
    }

    pthread_mutex_lock(&list->mutex);
    struct list_node *current = list->head;
    size_t index = 0;
    while (current != NULL) {
        memcpy((char*)buf + index, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        index += alignment;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    msync(buf, list->size * alignment + list->size, MS_SYNC | MS_ASYNC);
    close(fd);
}
```

