} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(unsigned int size, unsigned int *available_RNTIs, size_t RNTI_count) {
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (unsigned int i = 0; i < size; ++i) {
        unsigned int rnti;
        do {
            rnti = available_RNTIs[rand() % RNTI_count];
        } while (i < size && list[i] != NULL && rnti == list[i]->RNTI);
        if (rnti >= available_RNTIs[RNTI_count]) {
            // Handle the case where no more valid RNTIs are available, such as generating a new one or returning an error
            fprintf(stderr, "Out of valid RNTIs\n");
            exit(EXIT_FAILURE);
        }
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list[i]->RX_UE_INFORMATION_TAG = i;
        list[i]->RNTI = rnti;
        list[i]->CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    return list;
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_T **list, unsigned int size) {
    for (unsigned int i = 0; i < size; ++i) {
        free(list[i]);
    }
    free(list);
}

void iterate_and_remove(NFAPI_CRC_INDICATION_PDU_T **list, unsigned int size, unsigned int rnti_to_remove) {
    unsigned int index = 0;
    for (unsigned int i = 0; i < size; ++i) {
        if (list[i] != NULL && list[i]->RNTI == rnti_to_remove) {
            NFAPI_CRC_INDICATION_PDU_T *temp = list[index];
            list[index] = list[i];
            list[i] = temp;
            ++index;
        }
    }
    while (index < size) {
        free(list[index]);
        memmove(list + index, list + index + 1, (size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        --size;
    }
}
