    init_mutex(new_node);
    new_node->next = NULL;
    return new_node;
}

static void insert_node(Node **head, Node *new_node) {
    pthread_mutex_lock(&list_mutex);
    if (!*head) {
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
    node_count++;
    pthread_mutex_unlock(&list_mutex);
