#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

static struct node* head = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    // Generate a random CRCFLAG value without consecutive duplicate values
    static unsigned char prev_crcflag = 0;
    do {
        tag->crcflag = rand() & 0x0F;
    } while (tag->crcflag == prev_crcflag);
    prev_crcflag = tag->crcflag;
}

void add_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation error\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    new_node->data = *data;
    generate_crcflag(&new_node->data.crc_indication_rel8_tag);

    if (head == NULL) {
        head = new_node;
    } else {
        struct node* current = head;
        while (current->next != NULL) {
            if (current->next->data.rnti == new_node->data.rnti) {
                // Report duplicate RNTI value
                fprintf(stderr, "Duplicate RNTI value detected: %d\n", new_node->data.rnti);
                free(new_node);
                pthread_mutex_unlock(&list_mutex);
                return;
            }
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

void remove_node(int rnti) {
    pthread_mutex_lock(&list_mutex);
    struct node* current = head;
    struct node* previous = NULL;

    while (current != NULL && current->data.rnti == rnti) {
        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
        current = previous->next;
    }

    if (current != NULL) {
        struct node* temp;
        while (current != NULL && current->data.rnti != rnti) {
            temp = current;
            current = current->next;
        }

        if (current == NULL) {
            // RNTI not found in the list
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        previous = temp;

        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }

        free(current);
    }
    pthread_mutex_unlock(&list_mutex);
}
