        return;
    }

    Node* current = head_;
    size_t i = 0;

    while (i < index) {
        if (!current) {
            // Handle list traversal failure
            return;
        }

        current = current->next.load();
        ++i;
    }

    if (current) {
        if (index == 0) {
            head_.exchange(current->next.load());
            if (head_ == nullptr) {
