        NFAPI_CRC_INDICATION_PDU_T *pdu = &((*pdus)[*count]);
        pdu->RX_UE_INFORMATION_TAG = rand() % 256;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = (rand() >> 1) & 0xFFFF;
        pdu->CRCFLAG = rand() % 2 == 0;
        (*count)++;
        pthread_mutex_unlock(lock);

        usleep(1000); // Sleep to avoid creating too many PDUs in a short time
