    pool_index += (size_t)(sizeof(PDU_DATA) + sizeof(NFAPI_CRC_INDICATION_PDU_T) * array_length(pdu_arr));
    pool_size += array_length(pdu_arr);
    pool = realloc(pool, (pool_size + 1) * sizeof(PDU_DATA));
    if (!pool) {
        free(pdu_arr);
        pthread_mutex_unlock(&mutex);
        return;
    }

    PDU_DATA* pdus = pool + pool_index--;
    pdus->rnti = 0;
    pdus->pdu = pdu_arr;

    pthread_mutex_unlock(&mutex);
    free(pdu_arr);
}
