        dynamic_array_resize(array, array->capacity * 2);
    }

    memcpy(&array->frames[array->count], frame, sizeof(NFAPI_RX_FRAME_PDU));
    ++array->count;
}

void dynamic_array_remove_at(dynamic_array* array, size_t index) {
    if (index >= array->capacity || index >= array->count) {
