typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

static node_t* head = NULL;
static size_t count = 0;
static const size_t MAX_ENTRIES = 1000;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void create_list(size_t num_entries) {
    if (num_entries > MAX_ENTRIES || num_entries == 0)
        return;

    if (count + num_entries > MAX_ENTRIES) {
        // Resize array and reallocate memory
        node_t** old_list = &head;
        size_t new_size = count + num_entries < MAX_ENTRIES ? num_entries : MAX_ENTRIES - count;
        node_t* new_list = malloc(new_size * sizeof(node_t));
        if (!new_list)
            return;

        for (size_t i = 0; i < count; ++i)
            new_list[i] = old_list[i];

        free(old_list);
        head = new_list;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = count; i < count + num_entries; ++i) {
        node_t* new_node = malloc(sizeof(node_t));
        if (!new_node) {
            pthread_mutex_unlock(&mutex);
            return;
        }

        new_node->data.rx_ue_info.tag = (RX_UE_INFORMATION_TAG)(i % NUM_RX_UE_INFO_TAGS);
        new_node->data.rnti = (RNTI)i;
        new_node->data.crc_indication.crcflag = (CRCFLAG)(rand() % 2);

        // Check for duplicate RNTIs and update the RNTI if a duplicate is found
        node_t* current = head;
        size_t j;
        for (j = 0; j < i && current != NULL; ++j, current = current->next) {
            if (current->data.rnti == new_node->data.rnti) {
                current->data.rnti += 1 + (new_node->data.rnti - current->data.rnti);
                break;
            }
        }

        if (current != NULL) {
            new_node->next = current->next;
            current->next = new_node;
        } else {
            head = new_node;
        }
        ++count;
    }
    pthread_mutex_unlock(&mutex);
}
