int manage_list_and_execute_command(NFAPI_CRCMD_CMD cmd) {
    pid_t child_pid;
    int status;
    FILE *log_file;
    NFAPI_CRCMD_PDU_T *pdu;

    // Allocate memory for the PDU structure and initialize it
    pdu = malloc(sizeof(NFAPI_CRCMD_PDU_T));
    if (!pdu) {
        err(1, "Failed to allocate memory for the PDU");
    }

    // Set the required fields in the PDU
    pdu->cmd = cmd;
    pdu->crc_indication.crcflag = rand() % 2;

    // Lock the list mutex before adding the PDU to the list
    pthread_mutex_lock(&list_mutex);

    // Add the PDU to the list and increment the number of elements
    list = realloc(list, sizeof(NFAPI_CRCMD_PDU_T) * (num_elements + 1));
    if (!list) {
        err(1, "Failed to allocate memory for the list");
    }

    list[num_elements++] = *pdu;

    // Unlock the list mutex after adding the PDU to the list
    pthread_mutex_unlock(&list_mutex);

    // Create a new process and execute the command asynchronously, logging its output
    if ((child_pid = fork()) < 0) {
        err(1, "Failed to create a new process");
    } else if (child_pid == 0) {
        // Child process: execute the command and log its output
        dup2(open("/dev/null", O_RDWR), STDIN_FILENO);
        dup2(open("/dev/null", O_RDWR), STDOUT_FILENO);
        dup2(open("/dev/null", O_RDWR), STDERR_FILENO);
        close(open("/proc/self/fd/0", O_RDONLY)); // Redirect command input to /dev/null
        close(open("/proc/self/fd/1", O_WRONLY)); // Redirect command output to /dev/null
        log_file = fopen("command_output.log", "w");
        if (!log_file) {
            err(1, "Failed to open the log file for writing");
        }
        close(STDOUT_FILENO); // Redirect command output to the log file
        close(STDERR_FILENO); // Redirect command error output to the log file
        execlp("/bin/sh", "/bin/sh", "-c", cmd, NULL);
        err(1, "Failed to execute the command");
    } else {
        // Parent process: wait for the child process to finish and release its resources
        if (waitpid(child_pid, &status, 0) < 0) {
            err(1, "Failed to wait for the child process");
        }
    }

    // Free the memory allocated for the PDU structure
    free(pdu);

    // Return 1 if the command was executed successfully, 0 otherwise
    return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
}
