// A thread-safe wrapper for std::multiset to allow concurrent insertions and erasures.
template <typename KeyType>
class ThreadSafeMultiset {
public:
    void insert(KeyType key) {
        std::unique_lock<std::mutex> lock(_mutex);
        _multiset.insert(key);
    }

    bool remove(KeyType key) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = _multiset.find(key);
        if (it != _multiset.end()) {
            _multiset.erase(it);
            return true;
        }
        return false;
    }

    bool contains(KeyType key) const {
        std::unique_lock<std::mutex> lock(_mutex);
        return _multiset.find(key) != _multiset.end();
    }

private:
    std::multiset<KeyType> _multiset;
    mutable std::mutex _mutex;
};

std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> initializeLinkedList(int N) {
    if (N <= 0) {
