    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

struct list_node {
    NFAPI_CRC_INDICATION_PDU data;
    struct list_node *next;
};

struct dynamic_list {
    struct list_node* head;
    size_t size;
    pthread_mutex_t mutex;
};

void init_dynamic_list(struct dynamic_list* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool add_to_dynamic_list(struct dynamic_list* list, const NFAPI_CRC_INDICATION_PDU* data) {
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (!new_node) return false;
    new_node->data = *data;

    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_LIST_SIZE || find_duplicate_rnti(list, new_node->data.rnti)) {
        free(new_node);
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    new_node->next = list->head;
    list->head = new_node;
    ++list->size;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool update_dynamic_list(struct dynamic_list* list, const NFAPI_CRC_INDICATION_PDU* data) {
    struct list_node *current = list->head;
    pthread_mutex_lock(&list->mutex);

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    while (current != NULL && current->data.rnti != data->rnti) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    current->data = *data;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool remove_from_dynamic_list(struct dynamic_list* list, uint32_t rnti) {
    struct list_node **current = &list->head;
    struct list_node *temp;

    pthread_mutex_lock(&list->mutex);

    while (*current != NULL && (*current)->data.rnti != rnti) {
        current = &(*current)->next;
    }

    if (*current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    temp = *current;
    *current = temp->next;
    free(temp);
    --list->size;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool find_duplicate_rnti(const struct dynamic_list* list, uint32_t rnti) {
    const struct list_node *current = list->head;
    while (current != NULL && current->data.rnti == rnti) {
        current = current->next;
    }
    return current != NULL && current->data.rnti == rnti;
}

void periodic_update(struct dynamic_list* list, ...) {
