UE_CONTEXT_POOL* ue_context_pool_init(size_t capacity) {
    UE_CONTEXT_POOL* pool = (UE_CONTEXT_POOL*)malloc(sizeof(UE_CONTEXT_POOL));
    pool->capacity = capacity;
    pool->count = 0;
    pool->pool = (UE_CONTEXT*)calloc(capacity, sizeof(UE_CONTEXT));
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

UE_CONTEXT* ue_context_pool_get(UE_CONTEXT_POOL* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->capacity) {
        UE_CONTEXT* context = &pool->pool[pool->count];
        memset(context, 0, sizeof(UE_CONTEXT));
        context->crc_indication_rel8_tag.crcFlag = rand();
        ++pool->count;
        pthread_mutex_unlock(&pool->mutex);
        return context;
    } else {
        pthread_mutex_unlock(&pool->mutex);
        // Handle overflow situation
    }
}

void ue_context_pool_put(UE_CONTEXT_POOL* pool, UE_CONTEXT* context) {
    pthread_mutex_lock(&pool->mutex);
    if (0 < pool->count) {
        --pool->count;
        *context = pool->pool[pool->count];
