void serializeNfarpcPduList(NFAPI_CRC_INDICATION_PDU_T** pList, size_t* size) {
    size_t listSize = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    // Allocate memory for the list and its elements
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Generate RNTI and CRCFLAG for the first element
    list[0].RX_UE_INFORMATION_TAG = 1;
    list[0].RNTI = rand() % 65536;
    list[0].CRC_INDICATION_REL8_TAG = rand() % 256;
    list[0].CRCFLAG = rand() % 2;
    listSize++;

    // Allocate memory for the rest of the elements if needed
    while (listSize < *size) {
        NFAPI_CRC_INDICATION_PDU_T* newList = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (listSize + 1));
        if (!newList) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        list = newList;

        // Generate RNTI and CRCFLAG for the next element
        list[listSize].RX_UE_INFORMATION_TAG = listSize + 1;
        list[listSize].RNTI = rand() % 65536;
        list[listSize].CRC_INDICATION_REL8_TAG = rand() % 256;
        list[listSize].CRCFLAG = rand() % 2;
        listSize++;
    }

    // Null-terminate the list
    list[listSize] = NULL;

    // Serialize the list into a byte array
    size_t byteArraySize = (listSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    uint8_t* byteArray = malloc(byteArraySize);
    if (!byteArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    memcpy(byteArray, list, byteArraySize);

    *pList = list;
    *size = listSize + 1;
}
