    struct http_parser_url url;
    struct http_message msg;
    time_t timestamp;
    pthread_mutex_t lock;
};

struct Cache {
    struct CacheEntry **entries;
    size_t capacity, count;
    sem_t mutex;
    void *shm_config; // Shared memory for configuration management
};

struct Cache* create_cache(size_t initial_capacity) {
    struct Cache *cache = malloc(sizeof(struct Cache));
    if (!cache) return NULL;

    cache->capacity = initial_capacity;
    cache->count = 0;
    cache->entries = calloc(initial_capacity, sizeof(struct CacheEntry*));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }

    pthread_mutex_init(&cache->mutex, NULL);
    sem_init(&cache->mutex, 0, 1);

    get_config(&cache->capacity); // Initialize cache size from external configuration

    void *shm = shmat(shmget(IPC_PRIVATE, sizeof(size_t), 0600), NULL, 0);
    if (shm == (void *)-1) {
        perror("shmat");
        goto error;
    }
    cache->shm_config = shm;

    return cache;
error:
    cleanup(cache);
    return NULL;
}

void cleanup(struct Cache *cache) {
    if (cache && cache->entries) {
        for (size_t i = 0; i < cache->capacity; ++i) {
            free(cache->entries[i]);
        }
        free(cache->entries);
    }

    if (cache && cache->shm_config) {
        shmdt(cache->shm_config);
    }

    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

struct CacheEntry* get_entry(struct Cache *cache, const char *url) {
    sem_wait(&cache->mutex);

    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->entries[i]->url.field_data.host, url) == 0 &&
            strcmp(cache->entries[i]->url.field_data.path, url + strlen(url + url + strchr(url, '/') - url)) == 0) {
            pthread_mutex_unlock(&cache->entries[i]->lock);
            sem_post(&cache->mutex);
            return cache->entries[i];
        }
    }

    if (cache->count < cache->capacity) {
        struct CacheEntry *entry = &cache->entries[cache->count++];
        memset(entry, 0, sizeof(struct CacheEntry));
        entry->lock = PTHREAD_MUTEX_INITIALIZER;
        sem_post(&cache->mutex);
        return entry;
    }

    struct CacheEntry *oldest = cache->entries[0];
    for (size_t i = 1, j = 0; i < cache->count; ++i) {
        if (oldest->timestamp > cache->entries[i]->timestamp) {
            oldest = cache->entries[i];
            j = i;
        }
    }
    sem_post(&cache->mutex);

    pthread_mutex_lock(&oldest->lock);
    memset(oldest, 0, sizeof(struct CacheEntry));
    oldest->timestamp = time(NULL);
    pthread_mutex_unlock(&oldest->lock);

    return oldest;
}

void insert_entry(struct Cache *cache, struct CacheEntry *entry) {
    sem_wait(&cache->mutex);

    for (size_t i = 0; i < cache->count; ++i) {
        if (!strcmp(entry->url.field_data.host, cache->entries[i]->url.field_data.host) &&
            !strcmp(entry->url.field_data.path, cache->entries[i]->url.field_data.path)) {
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }

    if (cache->count < cache->capacity) {
        memcpy(cache->entries[cache->count], entry, sizeof(struct CacheEntry));
        sem_post(&cache->mutex);
    } else {
        size_t evicted = 0;
        for (size_t i = 1, j = 0; i < cache->count; ++i) {
            if ((time(NULL) - entry->timestamp) > (time(NULL) - cache->entries[i]->timestamp)) {
                evicted = i;
                break;
            }
        }
        memcpy(cache->entries[evicted], entry, sizeof(struct CacheEntry));
        sem_post(&cache->mutex);
    }
