const int MAX_INTEGERS = 10000;
const int INT_MAX = 2147483647;
std::deque<int> integers;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
time_t nextFetchTime;

void fetchData() {
    char buffer[MAX_RESPONSE_SIZE];
    FILE *file = fopen("https://example.com/data.csv", "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    size_t bytesRead = 0;
    int lineCount = 0;
    while ((bytesRead = fread(buffer, sizeof(char), MAX_RESPONSE_SIZE - bytesRead, file)) > 0) {
        if (lineCount == 0) { // Skip header row
            continue;
        }

        std::istringstream iss(buffer);
        int number;
        if (!(iss >> number)) {
            continue; // Skip invalid lines
        }

        pthread_mutex_lock(&mutex);
        while (integers.size() == MAX_INTEGERS || static_cast<long>(integers.back()) > INT_MAX - number) {
            nextFetchTime = time(NULL) + 300; // Set next fetch in 5 minutes
            pthread_mutex_unlock(&mutex);
            sleep(1);
            pthread_mutex_lock(&mutex);
        }
        integers.push_back(number);
        pthread_mutex_unlock(&mutex);
    }
    fclose(file);

    nextFetchTime = time(NULL) + 300; // Set next fetch in 5 minutes
}

void* createPDUs() {
    srand(time(NULL));
    while (true) {
        pthread_mutex_lock(&mutex);
        if (integers.empty()) {
            pthread_mutex_unlock(&mutex);
            usleep(100000); // Sleep for 0.1 seconds before checking again
            continue;
        }
        int numPDUs = std::min(static_cast<int>(integers.size()), MAX_INTEGERS / 10);
        auto start = integers.begin();
        std::advance(start, numPDUs);
        integers.erase(start, integers.end());
        pthread_mutex_unlock(&mutex);

        for (int i = 0; i < numPDUs; ++i) {
            NFAPI_CRCI_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = rand() % 65535 + 1; // RX_UE_INFORMATION_TAG should be within the valid range
            pdu.RNTI = rand() % 2 ** 32; // RNTI should not overflow
            pdu.CRC_INDICATION_REL8_TAG = rand() % 65535 + 1;
            pdu.CRCFLAG = rand() % 2 == 0;

            // Assuming RX_UE_INFORMATION_TAG and RNTI are already defined in some header file
        }
    }
}

int main() {
    signal(SIGINT, [](int) { exit(0); });

    while (true) {
        time_t currentTime = time(NULL);
        if (currentTime >= nextFetchTime) {
            fetchData();
        }

        usleep(100000); // Sleep for 0.1 seconds to minimize CPU usage
    }

    return 0;
}
