#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    union {
        uint16_t CRC_INDICATION_REL8_TAG;
        struct {
            bool CRCFLAG : 1;
            uint15_t checksum : 15;
        };
    };
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemPoolNode {
    void* data;
    struct MemPoolNode *next;
} MemPoolNode;

MemPoolNode* memPool = NULL;
size_t memPoolSize = 0;
size_t memPoolCapacity = 4096;

void* memPool_malloc(size_t size) {
    if (memPoolSize + size > memPoolCapacity) {
        MemPoolNode* newPool = malloc(memPoolCapacity * 2);
        if (!newPool) return NULL;
        memPoolCapacity *= 2;
        for (MemPoolNode* current = memPool; current; current = current->next)
            newPool[current - memPool] = *current;
        free(memPool);
        memPool = newPool;
    }

    MemPoolNode* node = &memPool[memPoolSize];
    void* data = node->data;
    node->data = NULL;
    memPoolSize++;

    return data;
}

void memPool_free(void* ptr) {
    if (!ptr || !memPool) return;

    MemPoolNode* current = memPool;
    for (MemPoolNode** previous = &memPool; *previous; previous = &((*previous)->next)) {
        if ((*previous)->data == ptr) {
            (*previous)->data = (*current).data;
            current->data = NULL;
            current = *previous;
            memPoolSize--;
            break;
        }
        current = *previous;
    }
}

void serialize(NFAPI_CRC_INDICATION_PDU_T* data, size_t N, uint8_t* buffer) {
    for (size_t i = 0; i < N; ++i) {
        union {
            uint16_t word;
            struct {
                bool CRCFLAG : 1;
                uint15_t checksum : 15;
            };
        } flags;
        flags.CRCFLAG = rand() % 2;
        data[i].CRC_INDICATION_REL8_TAG = flags.word;
        data[i].checksum = (data[i].RX_UE_INFORMATION_TAG + data[i].RNTI) & 0x7FFF;

        uint16_t tag = data[i].RX_UE_INFORMATION_TAG;
        buffer[2 * i] = tag >> 8;
        buffer[2 * i + 1] = tag & 0xFF;
        buffer[2 * i + 2] = data[i].RNTI >> 24;
        buffer[2 * i + 3] = (data[i].RNTI & 0x00FFFFFF) >> 16;
        buffer[2 * i + 4] = (data[i].RNTI & 0x00FFFF) >> 8;
        buffer[2 * i + 5] = data[i].RNTI & 0xFF;
        buffer[2 * i + 6] = flags.CRCFLAG ? (buffer[2 * i + 7] ^ data[i].checksum) : buffer[2 * i + 7];
    }
}

void* deserialize(uint8_t* buffer, size_t N) {
    if (!buffer || !N) return NULL;

    try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(buffer))) {
        Class<?> clazz = Class.forName("YourClass"); // Replace with the specific class you're deserializing to
        for (int i = 0; i < N; ++i) {
            try {
                Object obj = ois.readObject();
                if (!clazz.isInstance(obj)) {
                    System.err.printf("Unexpected object class: %s%n", obj.getClass().getName());
                    return null;
                }
                // Update your code to handle the deserialized objects as needed
            } catch (ClassNotFoundException | IOException e) {
                System.err.println("Error during deserialization: " + e.getMessage());
                return null;
            }
        }
