typedef struct MemoryBlock {
    size_t capacity;
    size_t allocated;
    NFAPI_CRC_INDICATION_PDU* data;
    struct MemoryBlock* next;
} MemoryBlock;

MemoryBlock* head = NULL;
size_t successful_allocations = 0;
size_t reallocations = 0;
size_t failures = 0;

void custom_malloc(size_t size) {
    if (!head || size > head->capacity) {
        MemoryBlock* new_block = (MemoryBlock*) malloc(sizeof(MemoryBlock));
        new_block->capacity = size;
        new_block->allocated = 0;
        new_block->data = (NFAPI_CRC_INDICATION_PDU*) malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!new_block || !new_block->data) {
            failures++;
            return;
        }
        new_block->next = head;
        head = new_block;
        reallocations++;
    }
    MemoryBlock* current = head;
    while (current->allocated >= current->capacity) {
        current = current->next;
    }

    successful_allocations++;
    NFAPI_CRC_INDICATION_PDU* pdu = &current->data[current->allocated];
    pdu->tag = generateTag(); // Implement generation of RX_UE_INFORMATION_TAG here
    pdu->RNTI = generateRNTI(); // Implement generation of RNTI here
    pdu->crc_indication.CRCFLAG = rand() % 2; // Implement CRC_INDICATION_REL8_TAG with randomly set CRCFLAG here
    current->allocated++;
}

