    const size_t estimatedSize = 10000;
    for (size_t i = 0; i < estimatedSize * 2; ++i) {
        custom_malloc(estimatedSize);
        handleExternalSource();
    }
    printf("Successful allocations: %zu\n", successful_allocations);
    printf("Reallocations: %zu\n", reallocations);
    printf("Failures: %zu\n", failures);

    // Free the memory and print statistics
    MemoryBlock* current = head;
    while (current) {
        MemoryBlock* temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    return 0;
}
