NFAPI_CRC_INDICATION_PDU* allocate_and_populate_crc_indications(size_t N, bool log) {
    if (N <= 0) {
        if (log) {
            printf("Error: Invalid input value. N must be greater than 0.\n");
        }
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!array) {
        if (log) {
            printf("Error: Memory allocation failure.\n");
        }
        return NULL;
    }

    time_t now = time(NULL);
    struct timespec resolution;
    clock_getres(CLOCK_REALTIME, &resolution);
    uint64_t rnti_seed = (uint64_t)now * resolution.tv_nsec;

    for (size_t i = 0; i < N; ++i) {
        array[i].tag = RX_UE_INFORMATION_TAG_INVALID;
        array[i].rnti = rnti_seed + i * resolution.tv_nsec;
        array[i].crcFlag = (CRC_INDICATION_REL8_TAG)((rand_r(rnti_seed + i) & 1) == 0 ? true : false);
        array[i].timestamp = now;
    }

    if (log) {
        printf("Successfully allocated and populated %zu elements.\n", N);
    }

    return verify_integrity(array, N, log) ? array : NULL;
}

bool verify_integrity(NFAPI_CRC_INDICATION_PDU *array, size_t N, bool log) {
    if (!array || N <= 0) {
        return false;
    }

    uint64_t rntis[N];
    memset(rntis, 0, sizeof(rntis));

    for (size_t i = 0; i < N; ++i) {
        if (array[i].tag != RX_UE_INFORMATION_TAG_INVALID || array[i].timestamp <= 0) {
            return false;
        }

        size_t rnti_index = rntis[(size_t)(array[i].rnti) % N];
        if (rnti_index != SIZE_MAX && array[i].rnti == array[rnti_index].rnti) {
            return false;
        }

        rntis[(size_t)(array[i].rnti) % N] = i;
    }

    if (log) {
        printf("Array integrity verified successfully.\n");
    }

    return true;
}

void rand_r(uint32_t* seed) {
    *seed = (*seed * 16807) % 2147483647;
}
