#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <xmlparser/libxml/xmlreader.h>
#include <NFAPI_CRC_INDICATION_PDU_T.h>

void parse_config(const char *filename, NFAPI_CRC_INDICATION_PDU_T **tiles, int *num_tiles) {
    xmlDocPtr doc = xmlReadFile(filename, NULL, 0);

    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file: %s\n", xmlErrMsg);
        exit(1);
    }

    xmlNodePtr root = xmlDocGetRootElement(doc);
    if (root == NULL) {
        fprintf(stderr, "Invalid XML structure\n");
        xmlFreeDoc(doc);
        exit(1);
    }

    xmlNodeSetPtr tile_nodes;
    int num_tiles_found = 0;

    for (xmlNodePtr cur = root->xmlChildrenNode; cur != NULL; cur = cur->xmlNextNode) {
        if (xmlStrcmp(cur->name, BAD_CAST "tile")) {
            continue;
        }
        num_tiles_found++;
    }

    tile_nodes = xmlSelectNodes(root, "tile");

    if (num_tiles_found <= 0 || tile_nodes == NULL) {
        fprintf(stderr, "Missing or incorrectly formatted tile definitions\n");
        xmlFreeDoc(doc);
        exit(1);
    }

    *tiles = malloc(num_tiles_found * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*tiles == NULL) {
        fprintf(stderr, "Out of memory\n");
        xmlFreeDoc(doc);
        exit(1);
    }

    int i = 0;
    for (xmlNodePtr cur = tile_nodes->nodeTab; cur != NULL; cur = cur->xmlNextNode) {
        NFAPI_CRC_INDICATION_PDU_T *tile = &((*tiles)[i++]);

        xmlChar *x, *y, *width, *height;
        int x_coord, y_coord, width_val, height_val;

        x = xmlGetProp(cur, BAD_CAST "x");
        y = xmlGetProp(cur, BAD_CAST "y");
        width = xmlGetProp(cur, BAD_CAST "width");
        height = xmlGetProp(cur, BAD_CAST "height");

        if (x == NULL || y == NULL || width == NULL || height == NULL) {
            fprintf(stderr, "Missing tile attribute(s)\n");
            continue;
        }

        sscanf(XMLSTR2CHAR(x), "%d", &x_coord);
        sscanf(XMLSTR2CHAR(y), "%d", &y_coord);
        sscanf(XMLSTR2CHAR(width), "%d", &width_val);
        sscanf(XMLSTR2CHAR(height), "%d", &height_val);

        tile->x = x_coord;
        tile->y = y_coord;
        tile->width = width_val;
        tile->height = height_val;
    }

    xmlFreeDoc(doc);
    *num_tiles = num_tiles_found;
}
