public:
    void log(const std::string& message, int level) {
        // Your logging implementation here
    }
};

class NFAPIList {
private:
    static constexpr size_t INITIAL_CAPACITY = 1024;
    static constexpr float GROWTH_FACTOR = 1.5f;
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> buffer;
    boost::circular_buffer<NFAPI_CRC_INDICATION_PDU_T> safeBuffer;
    pthread_mutex_t mutex;
    LoggingFunction logFn;

public:
    NFAPIList() {
        pthread_mutex_init(&mutex, nullptr);
        buffer.resize(INITIAL_CAPACITY);
    }

    ~NFAPIList() {
        for (auto& ptr : buffer) {
            if (ptr != nullptr) {
                delete ptr.get();
            }
        }
        pthread_mutex_destroy(&mutex);
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& data) {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> newData = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(data);
        newData->CRCFLAG = (std::rand() % 2) == 0; // set CRC flag randomly

        pthread_mutex_lock(&mutex);
        if (buffer.size() >= buffer.capacity()) {
            resize();
        }
        buffer[buffer.size()] = std::move(newData);
        safeBuffer.push_back(std::move(*newData)); // copy data to circular buffer for thread-safe access
        pthread_mutex_unlock(&mutex);
    }

    const NFAPI_CRC_INDICATION_PDU_T* get() {
        pthread_mutex_lock(&mutex);
        if (!safeBuffer.empty()) {
            auto data = safeBuffer.pop_front();
            buffer[buffer.size() - 1] = std::move(data); // move data back to dynamic array
            pthread_mutex_unlock(&mutex);
            return buffer[buffer.size() - 1].get();
        } else {
            pthread_mutex_unlock(&mutex);
            return nullptr;
        }
    }

private:
    void resize() {
        size_t newCapacity = static_cast<size_t>(buffer.size() * GROWTH_FACTOR);
        buffer.resize(newCapacity);
        logFn.log("Resizing the NFAPI list to " + std::to_string(newCapacity), 1);
    }
};
