typedef struct ConnectionInfo {
    int connectionID;
    time_t timestamp, lastActivityTime;
    enum Status { ACTIVE, INACTIVE } status;
} ConnectionInfo;

typedef struct CacheNode {
    ConnectionInfo info;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    unsigned long capacity;
    CacheNode **table;
    sem_t lock;
    pthread_mutex_t lru_lock;
    CacheNode *lru, *lru_tail;
    size_t size;
} CustomCache;

CustomCache* createCache(unsigned long capacity) {
    CustomCache *cache = mmap(NULL, sizeof(CustomCache), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!cache) return NULL;

    cache->capacity = capacity;
    sem_init(&cache->lock, 0, 1);
    pthread_mutex_init(&cache->lru_lock, NULL);
    cache->lru = cache->lru_tail = NULL;
    cache->size = 0;

    cache->table = calloc(capacity, sizeof(CacheNode*));
    if (!cache->table) {
        free(cache);
        return NULL;
    }

    return cache;
}

ConnectionInfo* findOrAddConnection(CustomCache *cache, int connectionID) {
    unsigned long index = hashFunction(connectionID);
    CacheNode *node, **table = cache->table;

    sem_wait(&cache->lock);

    for (node = table[index]; node != NULL; node = node->next) {
        if (node->info.connectionID == connectionID) {
            sem_post(&cache->lock);
            return &node->info;
        }
    }

    node = malloc(sizeof(CacheNode));
    if (!node) {
        sem_post(&cache->lock);
        return NULL;
    }

    memcpy(&node->info, &ConnectionInfo{connectionID, time(NULL), ACTIVE, time(NULL)}, sizeof(ConnectionInfo));

    sem_post(&cache->lock);

    node->next = table[index];
    table[index] = node;
    cache->size++;

    if (cache->size > cache->capacity) {
        sem_wait(&cache->lru_lock);
        removeLRUEntry(cache);
        sem_post(&cache->lru_lock);
    }

    return &node->info;
}

// Implement hashFunction, removeLRUEntry, and other necessary functions...
