#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct list {
    pthread_mutex_t lock;
    unsigned int size;
    unsigned int capacity;
    Node* head;
    Node* tail;
};

void initList(struct list* list, unsigned int capacity) {
    list->size = 0;
    list->capacity = capacity;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data = data;
    newNode->next = NULL;

    return newNode;
}

bool listIsFull(struct list* list) {
    return list->size == list->capacity;
}

bool pushBack(struct list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (listIsFull(list)) return false;

    Node* newNode = createNode(data);
    if (!newNode) return false;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T popFront(struct list* list) {
    if (isEmpty(list)) return (NFAPI_CRC_INDICATION_PDU_T){0, 0, 0, false};

    pthread_mutex_lock(&list->lock);
    Node* temp = list->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    list->head = temp->next;
    free(temp);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return data;
}

bool isEmpty(struct list* list) {
    return list->size == 0;
}

void clearList(struct list* list) {
    pthread_mutex_lock(&list->lock);
    Node* temp;
    while (list->head != NULL) {
        temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}
```

