    pthread_mutex_lock(&map->mutex);
    for (size_t i = 0; i < map->capacity && map->data[i] != NULL; ++i) {
        if (map->data[i]->icv == icv) {
            pthread_mutex_unlock(&map->mutex);
            return map->data[i];
        }
    }
    pthread_mutex_unlock(&map->mutex);
    return NULL;
