#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <atomic>
#include <map>
#include <vector>
#include <mutex>
#include <queue>

// Define MAC Entity structure
struct MACEntity {
    std::atomic<uint32_t> id;       // Unique identifier
    std::map<uint16_t, std::atomic<uint64_t>> logicalChannels;  // Map from channel ID to error frame and retransmission counters
    std::mutex mtx;                  // Mutex for thread safety
};

// Define statistical counter update function
void updateStatisticalCounters(struct MACEntity* entity, uint16_t channelId, bool isError, bool isRetransmission) {
    if (!entity || channelId >= entity->logicalChannels.size()) return;

    std::unique_lock<std::mutex> lock(entity->mtx);
    if (isError) entity->logicalChannels[channelId]++;
    if (isRetransmission && !isError) entity->logicalChannels[channelId]++;
}

// Define thread-safe MAC Entity management system
class MACEntityManager {
public:
    std::atomic<uint32_t> entityCount;       // Atomic counter for MAC entities
    std::map<uint32_t, struct MACEntity> entities;   // Map from entity ID to the actual entity
    pthread_mutex_t mtx;                     // Mutex for thread safety
    std::queue<struct MACEntity> queue;     // Queue for adding/removing MAC entities

public:
    void addMACEntity(const struct MACEntity& entity) {
        struct MACEntity newEntity = entity;
        newEntity.id.store(entityCount++);
        std::unique_lock<std::mutex> lock(mtx);
        queue.push(newEntity);
    }

    void removeMACEntity(uint32_t id) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = entities.find(id);
        if (it != entities.end()) {
            queue.push(it->second);
            entities.erase(it);
        }
    }

    const struct MACEntity* getMACEntity(uint32_t id) const {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = entities.find(id);
        return (it != entities.end()) ? &it->second : nullptr;
    }
};
```
